    ["{{PlayerName}}，看来你也有当美食评论家的天分。"] = "{{PlayerName}}, кажется, у тебя еще есть талант кулинарного критика.",
    ["{{他|她}}拿着什么，天呐，是风车长出的头发！"] = "{{He| She}} что-то держит, боже мой, это волосы, растущие из ветряной мельницы!",
    ["{{先生|女士}}你可以随意逛逛问问，我敢担保，莴苣与肉类市场再也没有比我家更好的牛排了。"] = "{{Mr.|Ms.}}, ты можешь осмотреться и спрашивать, что хочешь. Я гарантирую, что на рынке салата и мяса нет лучшего стейка, чем мой.",
    ["{{先生|女士}}您好，欢迎来到街角咖啡店。"] = "Привет, {{Mr.|Ms.}}, добро пожаловать в Corner Cafe.",
    ["{{先生|女士}}您好，请问您知道康妮夫人家的位置吗？"] = "{{ Mr. | Ms. }}, здравствуйте. Вы случайно не знаете, где дом миссис Конни?",
    ["{{先生|女士}}要买点什么吗？我们家的东西最便宜实惠了。有些蔬菜摊主说着是菜都是产自霍伊河上游，殊不知是哪块不要的工业废地呢。"] = "{{Mr.|Ms.}} Хотите что-нибудь купить? Наши товары самые дешевые и доступные. Некоторые продавцы овощей утверждают, что их овощи из верховьев реки Хой, не зная, из каких заброшенных промышленных пустошей они на самом деле прибыли.",
    ["{{先生|女士}}要买花吗？红宝石一样的鲜花，刚从树上摘下来，廷根市最新鲜的玫瑰。"] = "{{ Mr.| Ms.}}, хочешь купить цветов? Цветы, похожие на рубины, только что сорванные с дерева, самые свежие розы в Тингене.",
    ["{{先生|女士}}！相信我，真的有鬼魂！"] = "{{sir|madam}}! Поверьте, призраки действительно существуют!",
    ["{{先生|女士}}，一共是3苏勒。"] = "{{Сэр|Мэм}}, с вас всего 3 сули.",
    ["{{先生|女士}}，一盒火柴？"] = "{{Mr.|Ms.}}, коробок спичек?",
    ["{{先生|女士}}，不要和朱莉提起你问我的这些问题……"] = "{{Mr.|Ms.}}, не упоминай эти вопросы, которые ты мне задал Джули...",
    ["{{先生|女士}}，不论您买了什么，本店都将利润的百分之五捐给济贫院，帮助那些可怜的人。"] = "{{мистер|мисс}}, что бы вы ни купили, наш магазин пожертвует пять процентов прибыли в богадельню, чтобы помочь этим бедным людям.",
    ["{{先生|女士}}，买花吗？"] = "Господин/госпожа. {{|}}, хочешь купить цветов?",
    ["{{先生|女士}}，你不是第一个这样和我说的人，但我会坚持的！"] = "{{ Mr. | Ms. }}, ты не первый, кто говорит мне это, но я буду настойчив!",
    ["{{先生|女士}}，你好。"] = "{{ Mr. | Ms. }}, здравствуйте.",
    ["{{先生|女士}}，你是第一个祝福我的人，我很开心！"] = "{{ Mr. | Ms. }}, ты первый, кто меня благословил. Я так счастлив!",
    ["{{先生|女士}}，你看起来是能够把握命运的那类人。"] = "{{ Mr. | Ms. } }, вы похожи на человека, который может сам разобраться в своей судьбе.",
    ["{{先生|女士}}，别担心，我们调查过那片区域，很安全，没有任何异常。"] = "{{ Mr. | Ms. } }, не волнуйтесь, мы исследовали эту область, здесь очень безопасно, никаких аномалий нет.",
    ["{{先生|女士}}，如果你有见到我的鸟，麻烦悄悄离开，千万不要惊动它。"] = "{{Mr.|Ms.}}, если ты увидишь мою птицу, пожалуйста, тихо уйди и не беспокой ее.",
    ["{{先生|女士}}，您也是来廷根参观的吗？"] = "{{Mr.|Ms.}}, ты тоже приехал в Тинген в гости?",
    ["{{先生|女士}}，您是想租便宜一点的，还是地段好一点，或者是好点的联排别墅。"] = "{{Mr.|Ms.}}, вы хотите арендовать что-нибудь дешевле, в лучшем месте или, возможно, более красивый таунхаус?",
    ["{{先生|女士}}，您有看见一个比我们小一些的孩子吗？"] = "{{Mr.|Ms.}}, ты видел ребенка младше нас?",
    ["{{先生|女士}}，您看见那位女士了吗？妈妈叫孩子回家吃饭，多美好的风景。"] = "{{мистер|мисс}}, вы видели эту женщину? Мать зовет ребенка домой на ужин – какая прекрасная сцена.",
    ["{{先生|女士}}，您要买到哪儿的船票？"] = "{{Господин|Госпожа}}, куда вам нужен билет на корабль?",
    ["{{先生|女士}}，您要来一份报纸吗？"] = "{{Сэр|Мэм}}, не желаете газету?",
    ["{{先生|女士}}，您说，她为什么总看着伯特？"] = "{{Mr.|Ms.}}, скажи мне, почему она всегда смотрит на Берта?",
    ["{{先生|女士}}，您需要临时工吗？我上周失业了，可怜的小温蒂还饿着肚子在家等我……"] = "{{Господин|госпожа}}, вам не нужен подёнщик? На прошлой неделе я потерял работу, а бедная малютка Венди сидит голодная дома и ждёт меня...",
    ["{{先生|女士}}，我不是财务大臣，不乞讨，我是内务大臣。"] = "{{ Mr. | Ms. } }, я не министр финансов и не прошу милостыню; Я министр внутренних дел.",
    ["{{先生|女士}}，我们分头行动吧！"] = "{{Mr.|Ms.}}, давай расходимся!",
    ["{{先生|女士}}，我又被你发现了。我不知道女神会不会原谅我…我那个朋友。"] = "{{ Mr.| Ms.}}, ты снова меня нашел. Я не знаю, простит ли Богиня меня... этого моего друга.",
    ["{{先生|女士}}，洗衣做饭打扫卫生我都很擅长的，我也能正常阅读和书写。"] = "{{Mr.| Ms.}}, я очень хорошо умею стирать, готовить и убираться, нормально читать и писать умею.",
    ["{{先生|女士}}，现在你会发现，你得到的数字是零！哦，一定是零！当然，当然！"] = "{{Mr.|Ms.}}, теперь вы обнаружите, что полученное вами число равно нулю! О, это должно быть ноль! Конечно, конечно!",
    ["{{先生|女士}}，能买一盆花吗，我……我要攒钱给哥哥看病。"] = "{{ Mr.| Ms.}}, ты можешь купить горшок с цветами? Мне... мне нужно накопить денег на лечение моего брата.",
    ["{{先生|女士}}，要买点面包或蛋糕吗？"] = "{{ Mr. | Ms. }}, хочешь купить хлеба или пирожных?",
    ["{{先生|女士}}，要来条咸鱼吗？还是要来份新研发的咸鱼美食？还是想要浓缩咸鱼风味汤？"] = "{{ Mr. | Ms. }}, хочешь соленую рыбку? Или, может быть, недавно разработанный деликатес из соленой рыбы? А может быть, какой-нибудь концентрированный суп со вкусом соленой рыбы?",
    ["{{先生|女士}}，请问您去过贝克兰德吗？"] = "{{мистер|мисс}}, могу ли я спросить, были ли вы когда-нибудь в Баклунде?",
    ["{{先生|女士}}，这只是一种练习，我只练姿势……赢家用嘴打牌就够了。"] = "{{Господин|Госпожа}}, это лишь тренировка, я просто отрабатываю позу... Победителю достаточно играть одними лишь словами.",
    ["{{先生|女士}}，这是菜单，希望能在这里找到你想要的。"] = "{{Mr.|Ms.}}, вот меню. Надеюсь, вы найдете здесь то, что ищете.",
    ["{{先生|女士}}，需要什么？"] = "{{ Mr.| Ms.}}, что тебе нужно?",
    ["{{先生|女士}}，需要羊酪吗？我敢保证，这是廷根最好的羊酪！"] = "{{Mr.|Ms.}}, тебе нужен козий сыр? Гарантирую, это лучший козий сыр в Тингене!",
    ["{{先生|小姐}}您好啊，看看什么？"] = "Привет, {{Mr.|Ms.}}, что ты ищешь?",
    ["{{先生|小姐}}您好，我叫丽兹。欢迎光临！"] = "{{ Mr. | Ms. } }, здравствуйте, меня зовут Лиз. Добро пожаловать!",
    ["{{先生|小姐}}，找到我您真是独具慧眼！这儿的鱼是全廷根城最新鲜的，没错儿！"] = "{{Mr.|Ms.}}, у тебя острый глаз, чтобы найти меня! Рыба здесь самая свежая во всем Тингене, это правда!",
    ["{{哥们|姐们}}，手上有没有活老鼠？"] = "{{ Guys | Gals }}, у тебя есть под рукой живые мыши?",
    ["{{哥们|姐们}}，等你手上有活老鼠了，记得来找我啊！"] = "{{Buddy|Sister}}, если у тебя под рукой будут живые крысы, не забудь прийти и найти меня!",
    ["{{年轻的先生|年轻的女士}}，谢谢你愿意听我一个人唠叨那么多。我的人生很平淡，但愿你能够坚持做自己想做的事情，勇敢一些，不要太受别人影响。"] = "{{Young Mr.|Young Ms.}}, спасибо, что согласились выслушать мою болтовню. Моя жизнь очень обычная, но я надеюсь, что вы сможете настойчиво делать то, что хотите, быть смелым и не поддаваться слишком сильному влиянию других.",
    ["{{英俊的先生|美丽的小姐}}，祝您享受愉快的一天！"] = "{{Handsome Mr.|Beautiful Lady}}, желаю тебе приятного дня!",
    ["“……呜呜……妈妈……不要留下我……”"] = "«…Уууууу… Мама… не оставляй меня……»",
    ["“……带我离开这里……”"] = "«……Забери меня отсюда……»",
    ["“世界”先生，你给予的那件非凡武器超乎我预料得好，我已经攒够功勋，兑换到材料，晋升序列8了。"] = "«Мир», предоставленное вами оружие Потустороннего оказалось лучше, чем я ожидал. Я накопил достаточно заслуг, чтобы обменять их на материалы и перейти к восьмой последовательности.",
    ["“丢掉她！”"] = "«Выбросьте ее!»",
    ["“丹德莉丝（的衣服）安眠于此。\n你是女神赐予我的礼物。”"] = "«Здесь (вместе с нарядом) покоится Дандрис.\nТы — дар, ниспосланный мне Богиней».",
    ["“丽莎晚年在梦境和现实中徘徊，\n感谢女神，她终于结束了那场噩梦。”"] = "«На склоне лет Лиза блуждала меж сном и явью...\nХвала Богине, этот кошмар для неё наконец окончен».",
    ["“书籍是人类进步的阶梯”……我考考你，这句话是谁说的？"] = "«Книги — это лестница человеческого прогресса»... Позвольте мне вас проверить, кто это сказал?",
    ["“于此处长眠的是荒原诗人莉莲，\n喜欢探索自然的她回到了自然的怀抱。”"] = "«Здесь покоится Лилиан, поэтесса диких пустошей.\nЛюбившая исследовать природу, она вернулась в её объятия».",
    ["“他”？"] = "\"Он\"?",
    ["“仰望绯月派”？听起来还挺浪漫的。"] = "«Глядя на школу Багровой Луны»? Звучит весьма романтично.",
    ["“你是个没有家的怪物！”"] = "«Ты монстр без дома!»",
    ["“你这个没用的废物，跟你病死的妈一样废物！”"] = "«Ты бесполезный кусок мусора, такой же бесполезный, как твоя мать, умершая от болезни!»",
    ["“别打了，爸爸……疼……好痛……”"] = "«Перестань меня бить, папа… мне больно… так больно……»",
    ["“可怕的家伙，离我远一点！”"] = "«Ужасный парень, держись от меня подальше!»",
    ["“善良天使行走街头，清新之风温柔协助……”天使？廷根出动这种级别的大人物了？"] = "«Добрый Ангел ходит по улицам, свежий ветерок нежно помогает……» Ангел? Тинген отправил крупную шишку такого уровня?",
    ["“在海盗将军的层层围袭中，格尔曼如一闪迅捷的弧光，他瞬间隐没在滚滚烟尘中。周遭突然静得出奇——”"] = "\"Среди слоев окружения Пиратского Адмирала Герман был подобен быстрой дуге света, мгновенно исчезающей в клубящемся дыме и пыли. Вокруг внезапно стало жутко тихо...\"",
    ["“壁炉在夏日是否会熄灭呢？然而它们是明亮的……\""] = "\"Камин погаснет летом? А они яркие......\"",
    ["“失控”"] = "«Потеря контроля»",
    ["“她亲生爸妈也是疯子。”"] = "«Ее биологические родители тоже были сумасшедшими».",
    ["“她和他、他和她、她和她、他和他、缠绵悱恻的爱情故事”？"] = "«Она и он, он и она, она и она, он и он, затяжные и сентиментальные любовные истории»?",
    ["“她是个怪胎！”"] = "«Она уродка!»",
    ["“她是个疯子！”"] = "«Она просто безумна!»",
    ["“她是魔鬼！”"] = "«Она дьявол!»",
    ["“她的爸妈把她丢在了救济院门口。”"] = "«Ее родители бросили ее прямо у дверей приюта».",
    ["“她经常说些诡异的话，太可怕了。”"] = "«Она часто говорит жуткие вещи, это просто кошмар».",
    ["“妈妈，妈妈救救我……”"] = "«Мама, мама, спаси меня……»",
    ["“孤儿帮”？"] = "«Банда сирот»?",
    ["“就偷了这么一点钱回来，是想饿死我吗！”"] = "«Ты только украл эту небольшую сумму денег, ты пытаешься уморить меня голодом!»",
    ["“忽地一声惊呼：‘在那！’只见格尔曼·斯帕罗已凌空跃起，一枪、两枪、三枪……伴随着血花炸响的，还有疯狂冒险家的名号！”"] = "«Вдруг крик удивления: «Вот!» Герман Воробей уже подпрыгнул в воздух, один выстрел, два выстрела, три выстрела…… вместе с кровотечением крови прозвучало имя Безумного авантюриста!»",
    ["“愚者”先生……就是，就是高大威武的那位！报纸上说您爱听笑话——<P_Heart>（突然抽噎）</>我、我要是摔成肉饼……可就没人讲隔壁瘸腿汤姆被鹅追着跑的糗事了！"] = "«Мистер Шут»… то есть тот высокий и могучий! В газете говорится, что вы любите шутки — <P_Heart> (внезапно всхлипывая) </> Если меня... если меня раздавят в котлету... некому будет рассказать неловкую историю Хромого Тома по соседству, за которым гонялся гусь!",
    ["“愚者”先生利用自己的权柄，在命运之河中开辟出一条世界命运的支流。"] = "Мистер Шут использовал свою власть, чтобы создать приток судьбы мира в Реке Судьбы.",
    ["“愚者”先生沉睡前，发现一颗特殊的光茧。为争取对抗末日的更多希望……"] = "Перед тем как погрузиться в глубокий сон, Господин Шут обнаружил особый кокон света. Чтобы обрести больше надежды в грядущей битве с Апокалипсисом...",
    ["“战士”途径的非凡者拥有高序列以下几乎无人能打破的防御，哪怕步枪子弹也很难伤害到我们。"] = "Потусторонние Пути Воина обладают Защитой, которую почти никто ниже высокого уровня не может сломать; даже винтовочные пули вряд ли могут нам навредить.",
    ["“战士”途径进入中高序列后非常擅长发现不同怪物的弱点，某种程度上，这些经验也可以应用到人类身上。"] = "После входа в среднюю и высшую последовательности Потусторонние Пути Воина очень искусны в обнаружении слабостей различных монстров; в некоторой степени этот опыт можно применить и к людям.",
    ["“排兵布阵，纵横捭阖。”——这是某位学员教给我的“罗塞尔文”，你听着或许不会陌生。"] = "«Развертывание войск и соединений, маневрирование по направлению». — этому «розельскому языку» меня научил один студент; это может показаться вам незнакомым.",
    ["“杀了她！”"] = "«Убей ее!»",
    ["“汪，汪汪！”"] = "«Гав, гав, гав!»",
    ["“清新空气，从你我做起。特供无烟煤，欲购从速。”"] = "\"Свежий воздух, начиная с нас с вами. Специальная поставка бездымного угля, покупайте, пока он есть в наличии\".",
    ["“特拉斯：\n我准备好迎接黑夜了，那么黑夜准备好迎接我了吗？”"] = "\"Трасс: \n Я готов к ночи, так ночь готова для меня?\"",
    ["“献给我忠实的朋友华特森，她的主人敬上。”"] = "«Посвящается моей верной подруге Ватсон от ее хозяина».",
    ["“知识就是力量”——这并不是象征性质的语句。"] = "«Знание — сила» — это не символическое утверждение.",
    ["“给人一种回家的感觉。”"] = "«Дает ощущение дома».",
    ["“致我苏醒的友人”？"] = "«Моему пробудившемуся другу»?",
    ["“莫比乌斯环”的未知谜题增加到11个，我决定将它的危险等级提升为2级。"] = "Неизвестных загадок «Кольца Мебиуса» увеличилось до 11, я решил повысить уровень его опасности до 2-го.",
    ["“莫比乌斯环”的未知谜题增加到8个，我决定将它的危险等级提升为2级。"] = "Неизвестных загадок «Кольца Мебиуса» увеличилось до 8, я решил повысить уровень его опасности до 2-го.",
    ["“警局侦破一起入室骚扰案，疑似神秘接头组织再现身……”"] = "«Полицейский участок обнаружил случай вторжения в дом и преследования, и вновь появилась подозрительная загадочная совместная организация…»",
    ["“远离她！”"] = "«Держись от нее подальше!»",
    ["“那位”"] = "\"Вон тот\"",
    ["…..."] = false,
    ["……"] = false,
    ["……<P_Heart>（呼噜……）</>"] = "……<P_Heart>(Мур-р-р……)</>",
    ["……<P_Heart>（松一口气）</>以前我认为呼吸和心跳是生命的象征，但我最近产生很多疑惑。"] = "...<P_Heart>（Вздыхает с облегчением）</> Раньше я думал, что дыхание и сердцебиение — это признаки жизни, но в последнее время у меня появилось много сомнений.",
    ["……{{PlayerName}}……"] = "……{{PlayerName}}……",
    ["……{{PlayerName}}！醒醒！"] = "……{{PlayerName}}! Проснуться!",
    ["……不如我来帮你找找看吧，猫咪阁下？"] = "……Почему бы мне не помочь вам его найти, Ваше Превосходительство Кот?",
    ["……不打扰了，下次见。"] = "...Не буду вас беспокоить, увидимся в следующий раз.",
    ["……不擦，谢谢。"] = "...Никакого блеска, спасибо.",
    ["……不用了，谢谢。"] = "……Нет необходимости, спасибо.",
    ["……不管怎么说，我不能放任一个超凡生物在外游荡。"] = "...В любом случае, я не могу позволить потустороннему существу бродить на свободе.",
    ["……为什么？"] = "...Почему?",
    ["……他说……孤儿需要救赎……只要追随真实造物主……我们都可以回到……自己的家……"] = "...Он сказал... сироты нуждаются в спасении... пока вы следуете за Истинным Создателем... мы все сможем вернуться... в свой дом...",
    ["……他还是死了好。"] = "…Лучше бы он умер.",
    ["……但你看起来好像有些难过。"] = "...Но ты выглядишь немного грустным.",
    ["……但愿吧。可我不希望她跟着我受苦，更不希望她被困在这里，像我们一样，永远看不到外面的世界。"] = "...Я надеюсь, что это так. Но я не хочу, чтобы она страдала вместе со мной, и я не хочу, чтобы она оказалась здесь в ловушке, как и мы, и никогда не увидит мир снаружи.",
    ["……你令我很失望……"] = "...Ты меня разочаровываешь...",
    ["……你就是新来的家伙，弗莱警官的手下？"] = "...Ты новенький, подчиненный Фрая?",
    ["……你投到过吗？"] = "...Вы когда-нибудь его кастовали?",
    ["……你真好，亲爱的，能再帮我做一件事吗？"] = "……Ты такая добрая, моя дорогая. Не могли бы вы сделать для меня еще одну вещь?",
    ["……再见。"] = "……До свидания.",
    ["……别那样看着我，我可没有斯普林那种特殊癖好。我喜欢待在这里，是因为我的朋友们都在。"] = "……Не смотри на меня так, у меня нет такого особенного хобби, как у Спринга. Мне нравится оставаться здесь, потому что все мои друзья здесь.",
    ["……去年这个时候，您还夸我的花是东区最好的花。"] = "...В это время в прошлом году вы даже похвалили мои цветы как лучшие в Восточном округе.",
    ["……告诉贝尔纳黛殿下……"] = "……Скажите Ее Высочеству Бернадетт……",
    ["……咳，好重的血腥味。"] = "……Кашель, такой тяжелый запах крови.",
    ["……哎呀，忘记你还在这里了。"] = "...О боже, забыл, что ты все еще здесь.",
    ["……哎，那位男士叫艾德蒙，是黛西小姐的心上人，但埃尔顿子爵和夫人始终反对。"] = "...Эй, этого джентльмена зовут Эдмунд, он возлюбленный мисс Дейзи, но виконт Элтон и его жена всегда были против этого.",
    ["……哦，怎么会发生这样的事，简直是灾难！"] = "...Ох, как же такое могло случиться, это просто катастрофа!",
    ["……哦，想要加入罗塞尔大帝的探索队，当然要好好准备。"] = "……О, если ты хочешь присоединиться к исследовательской команде императора Розеллы, ты должен хорошо подготовиться.",
    ["……哦，是昨天买我玫瑰花的客人。您今天也需要玫瑰吗？最新鲜的玫瑰，刚从树上采摘下来的。"] = "...О, вы же вчера покупали у меня розы! Не желаете букетик и сегодня? Самые свежие розы, только-только срезанные с куста.",
    ["……哪里……来不及……"] = "...Где... не успеть...",
    ["……唉。"] = "...Вздох.",
    ["……啾唧……"] = "...Чирик...",
    ["……嗯……好……"] = "...М-м... хорошо...",
    ["……城市？"] = "……Город?",
    ["……女神啊，我觉得他们不会聘用你的。"] = "...Богиня милосердная, не думаю, что они возьмут тебя на работу.",
    ["……好吧，你想去哪？过会儿陪你去。"] = "……Хорошо, куда ты хочешь пойти? Я буду сопровождать тебя через некоторое время.",
    ["……好吧，那你在这里干什么？"] = "……Хорошо, тогда что ты здесь делаешь?",
    ["……好吧，那我试试。"] = "……Хорошо, я попробую.",
    ["……好孩子，安息吧。"] = "...Хороший ребенок, покойся с миром.",
    ["……如果您不相信，可以到处打听，您会知道这片街区到底有多安全。"] = "……Если ты мне не веришь, можешь поспрашивать; вы узнаете, насколько безопасен этот район.",
    ["……如果是这样，那事情就不好办了。"] = "……Если это так, то со всем будет трудно справиться.",
    ["……小戴莉，是戴莉吗？"] = "...Маленький Дейли, это Дейли?",
    ["……小阿诺德这几年，过得怎么样？"] = "...Как себя чувствовал маленький Арнольд последние несколько лет?",
    ["……尤朵拉……在等……阿诺德……回家……"] = "...Йодора... ждет... Арнольда... возвращения домой...",
    ["……很高兴看到你出现在这里。"] = "……Я очень рад видеть тебя здесь.",
    ["……怎么回事？"] = "...Что происходит?",
    ["……总之，后来家里就没了收入，但好在我找到了这份工作，替那边的富家公子卖票。"] = "...Так или иначе, потом семья потеряла доход, но я, к счастью, нашел эту работу, продавая билеты вон тому богатому молодому господину.",
    ["……我不流鼻涕"] = "...у меня нет насморка",
    ["……我不能选择跟着殿下吗？"] = "…Могу ли я не следовать за Ее Высочеством?",
    ["……我会尽力的。"] = "...Я сделаю всё, что в моих силах.",
    ["……我刚刚是不是听到猫说话了？"] = "……Я только что услышал кошачий разговор?",
    ["……我向你奉上我的血肉、我的发肤，请赐予这里……"] = "……Я предлагаю тебе свою плоть и кровь, свои волосы и кожу, пожалуйста, предоставь это место……",
    ["……我学会了阿诺德的歌，阿诺德也喜欢我……家人、跟我走……"] = "...Я выучила песню Арнольда, и Арнольду я тоже нравлюсь... Семья, пойдем со мной...",
    ["……我居然真的帮别人抓过老鼠？我？！怎么可能！"] = "……Я действительно помог кому-нибудь поймать мышь? Мне?! Как это возможно!",
    ["……我带着浑浑噩噩的记忆苏醒了很多次，至少这次我记得他。"] = "...Я много раз просыпался с туманными воспоминаниями, по крайней мере, на этот раз я помнил его.",
    ["……我把我所有的钱都拿去……投资……"] = "……Я взял все свои деньги, чтобы… инвестировать……",
    ["……我拒绝。"] = "……Я отказываюсь.",
    ["……我明白的，值夜者的死亡率一直都很高。"] = "...Я понимаю, смертность «Ночных ястребов» всегда была очень высокой.",
    ["……我是韦尔奇的朋友。"] = "……Я друг Уэлча.",
    ["……我没有察觉到，我确实处理得不太妥当。"] = "...Я не заметил, я действительно не справился с этим должным образом.",
    ["……我的一生都在被知识追逐，可我又哪里不是一生都在追逐知识呢？"] = "……Вся моя жизнь была потрачена на погоню за знаниями, но разве я не провел всю свою жизнь в погоне за знаниями?",
    ["……我的好伙伴，我会向协会申请的。"] = "...Мой добрый Партнер, я подам заявление в Ассоциацию.",
    ["……我看见了……真的是一个很好很好的——"] = "……Я видел это…… это действительно было очень, очень хорошо…",
    ["……或许贝尔纳黛殿下会喜欢。"] = "……Возможно, Ее Высочеству Бернадетте это понравится.",
    ["……战争带来的伤害仍未平息。"] = "……Ущерб, причиненный войной, до сих пор не утих.",
    ["……所以你怀疑与阿诺德在一起的“朋友”——尤朵拉就是儿童失踪案的犯人？"] = "...Значит, вы подозреваете, что «друг» Арнольда — Йодора — является виновником дела о похищении ребенка?",
    ["……时间过得真快啊。"] = "...Время летит так быстро.",
    ["……是你呀。"] = "...Это ты.",
    ["……晚安，会长。"] = "……Спокойной ночи, Президент.",
    ["……柠檬、香草、巧克力，美味清新沁心脾！"] = "...Лимонный, ванильный, шоколадный, вкусный, освежающий и согревающий!",
    ["……歌声……好听的歌声……妈妈……"] = "...Пение... красивое пение... Мама...",
    ["……殿下……"] = "...Ваше Высочество...",
    ["……每当梨花开遍了天涯，河上飘着柔曼的轻纱。"] = "……Когда на горизонте расцветает груша, по реке плывет мягкая марля.",
    ["……比南大陆更南，比北大陆更北，比苏尼亚海更东，比迷雾海更西……"] = "«...Южнее Южного континента, севернее Северного континента, восточнее моря Сони, западнее Туманного моря...»",
    ["……比地心更深，比星空更高……"] = "……Глубже ядра Земли, выше звездного неба……",
    ["……毕竟有些人，什么都没有留下。"] = "……В конце концов, некоторые люди ничего не оставляют после себя.",
    ["……汪呜？"] = "……Гав?",
    ["……没有办法继续询问了。"] = "...Продолжать расспросы бессмысленно.",
    ["……没有太多有用的线索，需要注意的只有一点。"] = "...Полезных подсказок не так уж и много, стоит только отметить одну вещь.",
    ["……没有？看来，今天我们都该休息了。嗯，这是不需要灵性直觉也能得到的启示。"] = "...Нет? Похоже, сегодня нам обоим стоит отдохнуть. Хм, это откровение, которое можно получить и без духовной интуиции.",
    ["……画得一般。"] = "...Рисунок посредственный.",
    ["……直到追到西边太阳落下的谷地，他们与太阳一同进入长眠。"] = "...пока они не доберутся до долины, где солнце садится на западе, и вместе с солнцем не войдут в долгий сон.",
    ["……真是热闹啊。"] = "...Здесь действительно оживленно.",
    ["……祂的精神化为永恒烈阳、风暴之主、知识与智慧之神，祂的智慧中诞生了人类。"] = "...Его дух превратился в Вечное Пылающее Солнце, Повелителя Бурь и Бога Знаний и Мудрости; человечество родилось из Его мудрости.",
    ["……笛子？是叔叔给尤朵拉的……笛子可以让家人们听话……跟我回家……"] = "...Флейта? Дядя подарил ее Юдоре... Флейта заставляет родных слушаться... Пойдем со мной домой...",
    ["……美丽的姑娘站在峻峭的岸上，歌声好像明媚的春光。"] = "……Красивая девушка стоит на крутом берегу и поет, как яркий весенний свет.",
    ["……艾登……"] = "……Эйден……",
    ["……蒙巴顿先生，我还什么都没说呢。"] = "...Мистер. Маунтбаттен, я еще ничего не сказал.",
    ["……让我们彻底忘掉那场战争，安娜。"] = "...Давайте совсем забудем о той войне, Анна.",
    ["……证件也是可以伪造的，在我的家乡，这种劣质的证件两苏勒一个。"] = "...Документы также могут быть подделаны. В моем родном городе эти некачественные документы стоят по два сола каждый.",
    ["……贝尔纳黛殿下会喜欢么？"] = "……Понравится ли это Ее Высочеству Бернадетте?",
    ["……贝尔纳黛殿下可是个诚实的人！"] = "……Ее Высочество Бернадетт – честный человек!",
    ["……资料并不多，他们已经尽力了。"] = "... Информации не так много, а они постарались.",
    ["……还是想不起来。"] = "...Всё равно не могу вспомнить.",
    ["……还是看看别的地方吧。"] = "...Давайте посмотрим где-нибудь еще.",
    ["……还是算了，谢谢你。"] = "……Неважно, спасибо.",
    ["……这不是什么需要否认的事情。"] = "...Это не то, что нужно отрицать.",
    ["……这个世界讨厌我……尤朵拉不是怪物……"] = "...Этот мир меня ненавидит... Йодора не монстр...",
    ["……这个小家伙，我记得它、我依旧记得它，记得他们……"] = "...Эти малыши, я помню их, я до сих пор помню их, помню их...",
    ["……这是什么情况。不过刚好带了些零钱，拿去吧。"] = "...Что происходит. Но мне довелось принести сдачу, возьмите ее.",
    ["……这话听起来怎么像骂人呢？"] = "……Почему это звучит как оскорбление?",
    ["……这里似乎是一处据点？"] = "...Кажется, это крепость?",
    ["……邓恩叔叔、戴莉姐姐，我终于考上了霍伊大学，说真的，这很不容易。"] = "...Дядя Данн, сестра Дейли, я наконец-то поступил в Университет Хой, честно говоря, это было непросто.",
    ["……那时你闻到雏菊的清香了吗？"] = "...Вы тогда чувствовали аромат ромашки?",
    ["……那时候，我跟邓恩都非常悲伤。"] = "...В то время нам с Данном было очень грустно.",
    ["……那走吧，跟我去基地。你救了我，我理应帮你。还有，我叫兰格。"] = "...Тогда пойдем, пойдем со мной на базу. Ты спас меня, я должен помочь тебе. Кроме того, меня зовут Ланге.",
    ["……队长、戴莉女士？"] = "...Капитан, мисс Дейли?",
    ["……队长，我刚24岁，还远不到被说老的年纪。"] = "...Капитан, мне всего 24 года, меня еще далеко не можно назвать старым.",
    ["……韦尔奇？"] = "……Уэлч?",
    ["……项链我不卖了，你还给我吧。"] = "...Я больше не продаю ожерелье, верните его мне.",
    ["……骨笛对他没有作用……鸟儿们在追随阿诺德……"] = "...Костяная флейта на него не действует... Птицы следуют за Арнольдом...",
    ["《大冒险家》最新一册昨晚就卖完了？不是前天刚到货吗？"] = "Последний том \"Великого авантюриста\" распродан вчера вечером? Разве оно не пришло позавчера?",
    ["《大冒险家》最新系列，{{先生|女士}}，我在学习名作家佛尔思·沃尔女士的表达方式。"] = "Новейшая серия «Великого искателя приключений», {{сэр|мисс}}. Я изучаю стиль знаменитой писательницы, мисс Форс Уолл.",
    ["《大冒险家》本轮廷根末场，前五十位观众可得原著作者佛尔思·沃尔小姐的签名海报！"] = "Финальное шоу Тингена этого тура «Великий авантюрист»: первые пятьдесят зрителей смогут получить подписанный плакат от оригинального автора, мисс Форс Уолл!",
    ["《大冒险家》？"] = "«Великий авантюрист»?",
    ["《女士审美》杂志"] = "Журнал 《Женская эстетика》",
    ["《女士审美》杂志？"] = "Журнал «Женская эстетика»?",
    ["《女巫之书》、《第二纪十大未解之谜》，总有人致力于拨开神秘学的迷雾，你有什么感兴趣的吗？"] = "«Книга ведьм», «Десять неразгаданных тайн Второй эпохи» — всегда находятся люди, призванные развеять туман мистики. Есть ли что-нибудь, что вас интересует?",
    ["《廷根晨报》1便士一份。"] = "«Утренний вестник Тингена», 1 пенс за штуку.",
    ["《我与格尔曼·斯帕罗二三事》已经加印第五版了，可《第三纪十大未解之谜》的销量还是很低迷，得拜托吉尔希多宣传一下。"] = "«Вещи между мной и Германом Воробьем» уже переизданы пятым изданием, но продажи «Десяти неразгаданных тайн третьей эпохи» все еще очень низкие. Я должен попросить Гильшидо продвигать его.",
    ["【CS-1.1】雏菊凋落-第一次循环"] = "【CS-1.1】 Увядшая маргаритка — первый цикл",
    ["【CS-1.2】雏菊凋落-第二次循环"] = "【CS-1.2】 Дейзи Фолс — второй цикл",
    ["【CS-1.3】雏菊凋落-第三次循环"] = "【CS-1.3】 Увядание маргаритки — третий цикл",
    ["【CS-2.1】雏菊花香-第一次循环"] = "【CS-2.1】 Аромат ромашки — первый цикл",
    ["【CS-2.2】雏菊花香-第二次循环"] = "【CS-2.2】 Аромат ромашки — второй цикл",
    ["【CS-2.3】雏菊花香-第三次循环"] = "【CS-2.3】 Аромат ромашки — третий цикл",
    ["【临时占位】这里是一段精美的动画"] = "[Заполнитель] Это красивая анимация",
    ["【格斗检定】武力威胁"] = "【Проверка рукопашного боя】Угроза силой",
    ["【测试用】在Loading中可以配置黑屏字幕，来降低黑屏字幕过程对任务的打断感"] = "[Тест] Субтитры на черном экране можно настроить во время загрузки, чтобы уменьшить ощущение прерывания выполнения квестов во время процесса черного экрана.",
    ["【表演】侠盗失控。"] = "【Спектакль】 Благородный разбойник теряет контроль.",
    ["【表演】凯娜快速跑远。"] = "【Представление】 Кена быстро убегает.",
    ["【表演】大家议论纷纷。"] = "【Представление】 Все это обсуждают.",
    ["【表演】少女状态痛苦。"] = "【Представление】 Девушка находится в состоянии боли.",
    ["【表演】扭曲感出现，侠盗变少女。"] = "【Выступление】 Появляется искажение: благородный разбойник превращается в девушку.",
    ["【表演】白莉夫人离开，侠盗一动不动，但头上开始冒泡，十分混乱。"] = "【Выступление】 Госпожа Байли уходит; благородный разбойник не шевелится, но над его головой начинают всплывать мыльные пузыри полного замешательства.",
    ["【表演】蒙特利死亡。他的身上析出了一些亮晶晶的东西（门的非凡特性）。给旁边散乱的面具板子一个镜头。"] = "[Сцена] Монтерей умирает. Из его тела выделяются какие-то сверкающие частицы (Потусторонняя характеристика Двери). Показать кадр с разбросанными рядом масками-табличками.",
    ["【表演】镜头给到正在梧桐树下交谈的二人，再给到地上躺着的“劫匪”。"] = "【Перформанс】 Камера фокусируется на двоих, разговаривающих под платаном, затем на «разбойнике», лежащем на земле.",
    ["【谈判检定】开始说服"] = "[Проверка переговоров] Начать убеждать",
    ["一个……一个说大不大、说小不小的错误。"] = "А... ошибка ни большая, ни маленькая.",
    ["一个……小女孩？"] = "Маленькая... девочка?",
    ["一个声音让我们重新变成了我。"] = "Голос заставил нас снова стать «я».",
    ["一个外表略显轻浮，其实很有礼貌的家伙。"] = "Парень, который выглядит немного легкомысленным, но на самом деле очень вежливый.",
    ["一个好的设计师绝对不能只局限于自己的工作坊中，每天对着尺子和缝纫机。"] = "Хороший дизайнер никогда не должен ограничиваться собственной мастерской, каждый день сталкиваясь с линейкой и швейной машинкой.",
    ["一个小女孩挤到街中，蹲下拾取雏菊花束，凑近鼻子闻闻。\n然后，小女孩抱着雏菊，朝你的方向微笑起来。"] = "Маленькая девочка протиснулась на середину улицы, присела, чтобы поднять букет маргариток, и поднесла его к носу, вдыхая аромат.\nЗатем девочка прижала маргаритки к груди и улыбнулась вам.",
    ["一个平等的交易。交给我吧！"] = "Честная торговля. Оставьте это мне!",
    ["一个晦气的前任。您明白吧，优秀的前任就应该像不存在一样，而不是在别人高高兴兴逛街的时候突然出现！"] = "Неудачливый бывший. Вы понимаете, да? Порядочный бывший должен вести себя так, как будто их не существует, а не появляться внезапно, пока кто-то радостно делает покупки!",
    ["一个没有姓氏的，游荡在廷根市贫民区的孤儿。"] = "Сирота без фамилии, скитающаяся по трущобам Тингена.",
    ["一个神秘符号<P_Yellow>“∞”</>？符号上还有循环流动的光？"] = "Загадочный символ <P_Yellow>\"∞\"</>? Есть ли на символе свет, струящийся по петле?",
    ["一个路过的服务员。你们到底还点不点餐？"] = "Мимо проходит официант. Собираетесь заказывать или нет?",
    ["一份报纸，多少钱？"] = "Одна газета, сколько?",
    ["一位老爷宣讲时说的，我用这句话来形容我们和王国的关系。最开始那不过是一片荒地，我们经历了很多，才有了现在的它。"] = "Один джентльмен сказал это во время своей речи, и я использую это предложение, чтобы описать наши отношения с королевством. Сначала это был просто кусок пустыни, и нам пришлось через многое пройти, чтобы сделать его таким, какой он есть сегодня.",
    ["一切命运的馈赠都在暗中标好了价码。"] = "Всем подаркам судьбы уже в темноте отмечена цена.",
    ["一刻钟后……"] = "Через четверть часа...",
    ["一千多年前，一场<P_Yellow>“苍白之灾”</>降临于北大陆，从此神灵不再现世，只通过教会传下神谕。"] = "Более тысячи лет назад на Северный континент обрушилась «Бледная катастрофа» <P_Yellow> </>. С тех пор боги больше не появлялись в мире, лишь передавая прорицания через церкви.",
    ["一半左右……不得不承认，还是你的记忆力更好。"] = "Примерно наполовину... Вынужден признать, память у тебя лучше.",
    ["一只非常奇特的小猫，会像变魔术一样突然出现在家里。"] = "Очень своеобразный котёнок, который внезапно, словно по волшебству, появлялся в доме.",
    ["一只，两只，三只……\n你通过她唇齿张合的动作判断着数量。"] = "Раз, два, три... \n О числе судишь по движениям ее губ и зубов.",
    ["一只，两只，三只……\n有细小的虫足从她裙下爬出，又攀上你的腿脚……"] = "Раз, два, три... \n Из-под юбки выползают крошечные ножки насекомых, а потом карабкаются по ногам и ступням...",
    ["一只，两只，三只……你感觉有细小的虫足从她裙下爬出，又攀上你的腿脚"] = "Раз, два, три... Ты чувствуешь, как крошечные жучьи лапки вылезают из-под ее юбки и карабкаются по твоим ногам.",
    ["一只，两只，三只……你通过她唇齿张合的动作判断着数量。"] = "Раз, два, три... О количестве судишь по движению ее губ и зубов.",
    ["一场战斗"] = "Битва",
    ["一场献祭"] = "Жертва",
    ["一场谋害"] = "Убийство",
    ["一场谋杀"] = "Убийство",
    ["一声枪响传来，\n随之而来的，\n是一阵夹杂着痛苦悲鸣的嘈杂人声。"] = "Грянул выстрел,\nа вслед за ним\nраздался разноголосый гул толпы, смешанный со стонами боли.",
    ["一定是你的配方不对，怎么还来怪我呢！"] = "Должно быть, это твой рецепт неправильный, почему ты винишь меня!",
    ["一年前的今天……我和我的孩子，被另一所济贫院分开安置……最终失散了。"] = "Сегодня, год назад... меня и моего ребенка разлучили еще в одном богадельне... и в конце концов мы потеряли друг друга.",
    ["一开始只是卖几件廷根大剧院瞧不上的瑕疵品，结果意外地受欢迎。"] = "Сначала я просто продал несколько бракованных вещей, которые не понравились Большому театру Тинген, но они неожиданно пользовались популярностью.",
    ["一张3……这也太小了……偷偷换成……"] = "Тройка... слишком мало... незаметно подменить на...",
    ["一想到友情和羁绊，我就感觉浑身充满了力量！"] = "В тот момент, когда я думаю о дружбе и узах, я чувствую прилив сил!",
    ["一想到这个，我就心情愉悦，忍不住想多喝一杯上好的苏尼亚血酒。"] = "Одна только мысль об этом заставляет меня чувствовать себя счастливым, я не могу не хотеть еще одного бокала прекрасного кровавого вина Сониата.",
    ["一月一签？"] = "Ежемесячная отметка?",
    ["一杯咖啡，加一块方糖、两勺牛奶。"] = "В чашку кофе добавьте кусочек сахара и две ложки молока.",
    ["一杯咖啡，加一块方糖，两勺牛奶，谢谢。"] = "Чашка кофе, один кусочек сахара, две ложки молока, пожалуйста.",
    ["一根、三根、五根……满满一盒！珍妮，珍妮从来没有见过这么多火柴！"] = "Одна, три, пять... целая коробка! Дженни, Дженни никогда не видела столько спичек!",
    ["一根火柴……"] = "Один матч...",
    ["一根？"] = "Один?",
    ["一次购买两个雕像，我还可以给您一定的优惠。"] = "Если вы купите две статуи сразу, я могу сделать вам определенную скидку.",
    ["一段时间后……"] = "Через некоторое время……",
    ["一段时间后，你想知道后续情况，所以再次来到霍伊大学……"] = "Некоторое время спустя вам захотелось узнать результат, и вы снова пришли в Университет Хой...",
    ["一段爆炸表现，爆炸的声效、火光和震屏特效之类的，周围的铁栅栏应声倒下……"] = "Представление о взрыве со звуковыми эффектами взрыва, светом огня и эффектами тряски экрана, а окружающие железные заборы рухнули в ответ...",
    ["一百二十便士。"] = "Сто двадцать пенсов.",
    ["一直以来，我都非常感谢你对我的帮助……与救赎。"] = "Все это время я был очень благодарен за вашу помощь... и спасение.",
    ["一直在身上"] = "Всегда на мне",
    ["一直在？"] = "Всегда?",
    ["一看您就能理解咸鱼的魅力，哈哈。您想要咸鱼还是咸鱼派，又或者浓缩咸鱼风味汤？"] = "Сразу видно, что вы понимаете толк в солёной рыбе, ха-ха! Чего желаете: солёной рыбки, пирог с солёной рыбой или наваристый рыбный бульон?",
    ["一种特别的气息，一种久违的感觉。"] = "Особый аромат, давно утраченное чувство.",
    ["一种独到的见解。至少在感情上，我完全、彻底地认同您的看法。"] = "Уникальное понимание. Я целиком и полностью с вами согласен, по крайней мере эмоционально.",
    ["一群穿越者？"] = "Группа переселенцев?",
    ["一般值夜者小队需要驻守在自己的辖区内，没有允许不能去辖区外追捕罪犯，这其实不太方便。"] = "Как правило, отряды Ночного Ястреба должны размещаться в пределах своей юрисдикции и не могут без разрешения преследовать преступников за пределами своей территории, что на самом деле весьма неудобно.",
    ["一言为定！"] = "Это сделка!",
    ["一通忙碌后，你终于安葬了芙拉，让她和杰温安息在了一起……"] = "После бурной деятельности вы, наконец, похоронили Фулу, позволив ей и Джуэн вместе покоиться с миром...",
    ["一阵星芒落下，谜虫松开了对你的钳制，丢了魂一般瘫软在这梦幻的牢笼中。"] = "Падает вспышка звездного света, и загадочное насекомое ослабляет хватку, погружаясь в эту мечтательную клетку, как заблудшая душа.",
    ["一阵阴冷的风吹起，伴随而来一阵诡异的口琴声……"] = "Дул холодный, жуткий ветер, сопровождаемый звуками странной гармошки...",
    ["七年了，我还是忘不了被霍尔行长指出记账错误的事情。"] = "Прошло семь лет, а я до сих пор не могу забыть тот момент, когда управляющий банком Холл указал на мою ошибку в бухгалтерском учете.",
    ["七神指引着北大陆，而传闻中的<P_Yellow>南大陆</>处于冥皇的统治之下。如今<P_Yellow>北大陆的四大国</>，就是这个时候，在神的支持下建立。"] = "Семь Богов направляют Северный континент, в то время как легендарный <P_Yellow>Южный континент</> находился под владычеством Императора Преисподней. Именно тогда при поддержке богов и были основаны нынешние <P_Yellow>четыре великие державы Северного континента</>.",
    ["万事小心。"] = "Будьте осторожны со всем.",
    ["万事小心，{{PlayerName}}。"] = "Будь осторожен со всем, {{PlayerName}}.",
    ["三百便士就能饱餐一顿了，难道邪神不用吃饭的吗？艺术创作要融入生活……"] = "Трехсот пенсов хватит на полноценный обед. Разве злым богам не нужно есть? Художественное творчество должно интегрироваться в жизнь...",
    ["上周就说要和劳伦斯去恶龙酒吧……现在都没空去，万恶的工厂主。"] = "На прошлой неделе я сказал, что пойду в бар ««Злой Дракон»» с Лоуренсом… у меня до сих пор нет времени, эти злые фабриканты.",
    ["上班地一号和上班地二号，死了都逃不过打工的命运。"] = "Работа номер один и работа номер два... Даже после смерти не сбежать от участи батрака.",
    ["下一个功能，展示一下分支选项吧。"] = "Следующая функция, давайте покажем варианты ветвления.",
    ["下一个要展示的是实机场景表现，显而易见，我们目前身处真正的主城场景。"] = "Следующее, что нужно продемонстрировать, — это производительность внутриигровой сцены. Очевидно, что сейчас мы находимся на сцене настоящего главного города.",
    ["下一位病人，不要跑！"] = "Следующий пациент, не беги!",
    ["下午茶可以尝试柠檬蛋糕和小松饼，可以搭配费内波特的高原咖啡，或者我家乡的甜冰茶。"] = "На послеобеденный чай вы можете попробовать лимонный пирог и небольшие кексы, которые можно сочетать с высокогорным кофе Фейнапота или сладким холодным чаем из моего родного города.",
    ["下午茶点心也会用这笔钱购买。"] = "На эти деньги также приобретаются закуски к послеобеденному чаю.",
    ["下周就要在教堂里演出了，还唱得这么糟糕！"] = "На следующей неделе выступление в церкви, а ты все еще так плохо поешь!",
    ["下周，索菲纺织厂的活儿也不干了，在专心收拾我们弗拉德街的新房子了。"] = "На следующей неделе я тоже не буду работать на текстильной фабрике «Софи». Я занимаюсь приведением в порядок нашего нового дома на улице Влада.",
    ["下定决心"] = "Решаюсь",
    ["下次一定……"] = "В следующий раз обязательно...",
    ["下次再去吧"] = "Иди в следующий раз",
    ["下次再来啊。"] = "Приходите снова в следующий раз.",
    ["下次再看见她，我联系你。女神在上，别再给我增加工作量了。"] = "Я свяжусь с тобой в следующий раз, когда увижу ее. Богиня выше, не увеличивай мою нагрузку больше.",
    ["下次再聊！"] = "Поговорим в следующий раз!",
    ["下次卡斯伯特女士回来时，会做什么样的新甜品呢？"] = "Какой новый десерт приготовит миссис Катберт, когда вернется в следующий раз?",
    ["下次见面，把他们给你讲的睡前故事说给我听就好。"] = "В следующий раз, когда мы встретимся, просто расскажи мне сказки, которые они тебе рассказали на ночь.",
    ["不……不可能！"] = "Нет... невозможно!",
    ["不……不好意思，我刚……来，说话有……有点不利索。"] = "Я... извини, я только... приехал, моя речь... немного корявая.",
    ["不……不是的，泽维尔只是……<P_Heart>（她看起来很是慌乱，在急于为她的心上人辩解。）</>"] = "Нет... это не так, Ксавье просто... <P_Heart> (Она выглядит очень взволнованной, жаждущей защитить своего возлюбленного.) </>",
    ["不……你不能带走……"] = "Нет... ты не можешь это отнять...",
    ["不……我绝对不会就这样放弃……"] = "Нет... Я никогда не сдамся просто так...",
    ["不、不要吃我，不要吃我啊！！！"] = "Нет, не ешь меня, не ешь меня!!!",
    ["不不不，塔芒先生是全廷根最优秀最专业的咖啡师了。"] = "Нет, нет, нет, мистер Таманг — лучший и самый профессиональный бариста во всем Тингене.",
    ["不不不，我不是这个意思，我只是例行问问病情。祝您健康！"] = "Нет-нет-нет, я вовсе не это имел в виду, просто дежурный вопрос о самочувствии. Крепкого вам здоровья!",
    ["不不不，我的意思是，这一切就跟做梦似的……"] = "Нет, нет, нет, я имею в виду, все это похоже на сон...",
    ["不不，我们还没有交易！对不起，我下次再也不敢了！"] = "Нет-нет, мы еще не заключили сделку! Прости, я больше не посмею этого сделать!",
    ["不不，是打算送给朋友的礼物。"] = "Нет-нет, это подарок, который я собираюсь сделать другу.",
    ["不了，免费的就是最贵的。"] = "Нет, спасибо, бесплатные вещи самые дорогие.",
    ["不予置评"] = "Без комментариев",
    ["不介意的话，这块给你尝尝吧，我本来打算带回家的！"] = "Если не брезгуете, попробуйте этот кусочек, я вообще-то домой его нес!",
    ["不会的，带走3-888之前，我会让小黛西再次进入循环。"] = "Этого не произойдет. Прежде чем я заберу 3-888, я позволю маленькой Дейзи снова войти в цикл.",
    ["不像有的富家子弟，他只会爬到树上求我帮忙，像我很闲似的。"] = "В отличие от какого-нибудь богатого ребенка, он умеет только залезть на дерево и попросить меня о помощи, как будто мне больше нечего делать.",
    ["不只是想"] = "Это больше, чем просто думать",
    ["不可能，菲利普是个胆小鬼，哪敢开枪。"] = "Невозможно, Филип — трус, он бы ни за что не осмелился спустить курок.",
    ["不咋样，淡入淡出的功能不建议频繁使用，打断性会比较强。"] = "Не здорово. Не рекомендуется часто использовать функцию постепенного появления/затухания, так как это может сильно мешать.",
    ["不够灵敏的占卜家先生，这个架子明明离我更近，如果不是你挡住了路……"] = "Недостаточно проворный господин Провидец, эта полка явно ближе ко мне, если бы не вы, преградивший путь...",
    ["不好意思，我对这里的情况也不太了解。"] = "Прошу прощения, я тоже не слишком хорошо знаком со здешними местами.",
    ["不好意思，我有约了。"] = "Извините, у меня назначена встреча.",
    ["不好意思，我要工作了，改天再聊！"] = "Извините, мне нужно на работу, поговорим в другой день!",
    ["不如来杯度数适中的南威尔啤酒，这可是全鲁恩自产的最好的啤酒。"] = "Как насчет стакана умеренно алкогольного пива Southwell? Это лучшее пиво, производимое во всем Лоене.",
    ["不客气，你还好吗？"] = "Не за что. Ты в порядке?",
    ["不客气，国王。"] = "Не за что, король.",
    ["不客气，这是我的职责所在。"] = "Пожалуйста, это мой долг.",
    ["不对，是你先提的……对，咳咳，你说这话的目的是什么？动机是什么？谁指使你的？你是不是被某些危险存在蛊惑了？跟我走一趟！"] = "Нет, ты сам первый это начал... Так, кхм-кхм, с какой целью ты это говоришь? Каковы твои мотивы? Кто тебя подослал? Не околдовала ли тебя какая-то опасная сущность? А ну пройдем со мной!",
    ["不工作……哈哈！你见过我同事渥克吗？你没见过！"] = "Не работает... Хаха! Вы видели моего коллегу Уока? Вы этого не сделали!",
    ["不得不说，你是位聪明的小姐，所以现在也请聪明地跟我们走吧。"] = "Должен сказать, вы умная юная леди, так что, пожалуйста, будьте умны и пойдите с нами сейчас.",
    ["不得不说，遇见您这样一位活泼风趣的太太，和这样一间面包房，真是让人高兴。"] = "Надо сказать, встретить такую ​​жизнерадостную и веселую даму, как вы, и такую ​​пекарню, это настоящая радость.",
    ["不必在意，我什么也不会做的。只是，想要看看。"] = "Не обращайте на меня внимания, я ничего не буду делать. Я просто хочу посмотреть.",
    ["不必多问。"] = "Не нужно спрашивать больше.",
    ["不必悲伤，我的孩子们。我死于五年前，我的故事早就结束了。"] = "Не грустите, дети мои. Я умер пять лет назад; моя история закончилась давно.",
    ["不必拘谨。会长这个头衔并不代表你我之间有地位的高下，我接受它，只是因为我接受了随它而来的责任和义务。"] = "Не нужно церемониться. Звание президента вовсе не значит, что между нами есть разница в положении; я принял его лишь потому, что взял на себя связанные с ним обязанности и ответственность.",
    ["不必道歉，这位女士。"] = "Не нужно извиняться, мадам.",
    ["不急的票我不卖，不急的票我卖什么？"] = "Несрочные билеты я не продаю, какой смысл продавать то, что не к спеху?",
    ["不想卖的票我不卖，我不想卖我怎么卖？"] = "Билеты, которые я продавать не хочу, я не продаю. А если не хочу продавать — как я их продам?!",
    ["不明白我的意思？那很好。抱歉，闲聊的话恕不奉陪。我还有事要忙。"] = "Не понимаете, о чем я? Вот и отлично. Прошу прощения, но у меня нет времени на пустую болтовню. Дела ждут.",
    ["不是"] = "Нет",
    ["不是。"] = "Нет.",
    ["不是二手吗？怎么还这么贵？"] = "Оно же подержанное? Почему всё равно так дорого?",
    ["不是小偷！"] = "Не вор!",
    ["不是我，是我旁边这位。"] = "Это не я, это человек рядом со мной.",
    ["不是教堂，我说的是北区的塔楼，我以后也一定要住在那上边，能够俯视整个廷根！"] = "Не собор, я говорю о башне в Северном округе. В будущем мне придется жить на вершине этого холма, чтобы иметь возможность обозревать весь Тинген!",
    ["不是的。"] = "Нет, я не такой.",
    ["不是！<P_Heart>（小声）</>“那份”手稿……怎么样了？你看完了吗？"] = "Нет! <P_Heart>(шепотом)</> \"Эта\" рукопись... как она? Вы закончили читать?",
    ["不来一点格尔曼辣奶油蛋糕吗？"] = "Хотите немного пряного кремового торта «Немецкий»?",
    ["不止是想，人生在世，何妨一试！也就试了几次而已。"] = "Не просто подумал об этом, в этой жизни, почему бы не попробовать! Я пробовал всего несколько раз.",
    ["不然你猜猜我这里为什么是半袋呢？"] = "А иначе, почему ты думаешь, что у меня здесь полсумки?",
    ["不然呢？是好是坏总得试试，我可不想进了坟墓还抱着膝盖喊妈妈。"] = "А как иначе? Хорошо или плохо, но попытаться стоит. Не хочу я и в могиле лежать, обхватив коленки и звя мамочку.",
    ["不然，一个亡魂的投影无法在现实驻留如此之久。"] = "В противном случае проекция мертвой души не могла бы оставаться в реальности так долго.",
    ["不用了……"] = "Незачем...",
    ["不用了，不过你确实有很好的外交能力。"] = "Не нужно, но дипломатические способности у вас определенно на высоте.",
    ["不用了，我已经都说完了。不过……我可以附身在你身上做点别的，例如，你一直犹豫的事情？"] = "Не надо, я уже всё сказал. Однако... я мог бы заставить тебя сделать что-нибудь еще, например, то, о чем ты колебался?",
    ["不用了，最近廷根有几起儿童失踪案，这几天尽量不要让阿诺德独自出门。"] = "Незачем. В последнее время в Тингене произошло несколько случаев похищения детей. Постарайтесь в эти дни не позволять Арнольду выходить одному.",
    ["不用了，谢谢"] = "Нет необходимости, спасибо",
    ["不用了，谢谢。"] = "Нет необходимости, спасибо.",
    ["不用了，谢谢，我喝不下东西。"] = "Нет необходимости, спасибо. Я не могу ничего пить.",
    ["不用在意，女士"] = "Не обращайте на это внимания, мадам.",
    ["不用奇怪，每个月的市政拨款，根本不够里边的人吃饱饭。"] = "Не удивляйтесь; ежемесячного муниципального финансирования просто не хватает для того, чтобы люди внутри наелись досыта.",
    ["不用客气，我不靠这个赚钱。"] = "Не упоминайте об этом, я не полагаюсь на это, чтобы заработать деньги.",
    ["不用担心，我也算是黑荆棘的老朋友。"] = "Не волнуйтесь, я еще и старый друг Блэкторна.",
    ["不用担心，我只是想带她回家。"] = "Не волнуйся, я просто хочу отвезти ее домой.",
    ["不用担心，我手上还有一点闲钱呢。"] = "Не волнуйся, у меня еще есть немного свободных денег.",
    ["不用担心，这是我们的职责。"] = "Не волнуйтесь, это наш долг.",
    ["不用这么看着我，别担心，我很好、我真的很好，我们早就应该习惯离别了。"] = "Не смотри на меня так. Не волнуйся, я в порядке, я действительно в порядке. Мы уже давно должны были привыкнуть к расставанию.",
    ["不用，你喝吧，我本来就不爱喝酒。"] = "Не надо, выпейте. Я вообще не люблю пить.",
    ["不用，小事情而已，我们在附近等着就好，灵性会指引它会回到这里的。"] = "Не нужно, это мелочь. Мы просто подождём поблизости — Духовность подскажет ему вернуться сюда.",
    ["不用，谢谢您。您瞧，我又有钱买吃的了！"] = "Нет, спасибо. Видите ли, у меня снова есть деньги, чтобы купить еду!",
    ["不瞒您说，今天我们第一次见面。但是，我已经深深爱上了她。"] = "Честно говоря, сегодня мы встретились впервые. Но я уже сильно влюбился в нее.",
    ["不知为何，感觉他很亲切。"] = "Почему-то мне кажется, что он очень добрый.",
    ["不知谁留在这里的尖碑，用非凡力量记录了几个区域地点。"] = "Неизвестно кем оставленный здесь обелиск с помощью Потусторонней силы запечатлел несколько мест в этом регионе.",
    ["不知道。我们一般都去他的诊所请他过来，在<P_Yellow>奥尔斯纳街</>。"] = "Я не знаю. Обычно мы ходим в его клинику, чтобы пригласить его, на улице <P_Yellow>Olsna Street</>.",
    ["不知道你是否听说过，二十一年前轰动了整个廷根市的连环杀手。"] = "Не знаю, слышал(а) ли ты о серийном убийце, который двадцать один год назад потряс весь город Тинген.",
    ["不知道哪里传出的消息，说背对净化之泉，右手拿硬币从左肩上方向后投入水中，能够实现自己的愿望。"] = "Неведомо откуда пошел слух: если встать спиной к Источнику Очищения, взять правой рукой монетку и бросить ее через левое плечо в воду, то загаданное желание непременно сбудется.",
    ["不知道奥黛丽小姐近况如何。"] = "Интересно, как мисс Одри поживает в последнее время?",
    ["不知道她现在怎么样了……"] = "Интересно, как она сейчас...",
    ["不知道查理是它的名字还是主人的名字，以后多留意一下吧。"] = "Я не знаю, Чарли — это его имя или имя владельца; В будущем я буду уделять этому больше внимания.",
    ["不祥的气息向你扑来，你躲不过去，被诅咒缠身。"] = "Зловещее дыхание устремилось к вам; не сумев увернуться, вы пали жертвой проклятия.",
    ["不能充分享受博弈中随机性的人，不能真正地享受“斗邪恶”。"] = "Те, кто не может в полной мере насладиться случайностью в игре, не могут по-настоящему насладиться «борьбой со злом».",
    ["不能吃？煮一煮、炖一炖，照样填饱肚子！你们这些体面的少爷小姐，怎么会知道下街人的生活？"] = "Не можешь это съесть? Вари, туши, все равно желудок набьет! Откуда вам, порядочным молодым господам и леди, знать жизнь людей на Нижней улице?",
    ["不能证明什么"] = "Не могу ничего доказать",
    ["不行！妈妈晾的衣服还在外面挂着！"] = "Нельзя! У мамы белье еще сушится на улице!",
    ["不要伤害她，不要吓坏她，夜莺是好鸟，夜莺的歌，好听！"] = "Не делайте ей больно, не пугайте ее. Соловей – добрая птица, песня соловья прекрасна!",
    ["不要冲动！"] = "Не будьте импульсивны!",
    ["不要听信谣言啊……怎么还越传越广了。"] = "Не слушайте слухи... как они распространяются еще дальше.",
    ["不要把自己的背后交给任何人，即使是曾经一起训练的同伴。"] = "Никому не подставляй спину — даже товарищу, с которым когда-то вместе тренировался.",
    ["不要离开我，阿诺德！！！"] = "Не оставляй меня, Арнольд!!!",
    ["不要让任何人触碰黛西小姐，这很危险，我很快就会回来。"] = "Не позволяй никому прикасаться к мисс Дейзи, это опасно. Я скоро вернусь.",
    ["不要说我心狠，在这糟糕的时代里，我们自己能活下去就很不容易了，又哪有那么多心思来可怜别人呢？"] = "Не говори, что я бессердечный. В эту ужасную эпоху нам нелегко выжить самим, так как же у нас хватит духу жалеть других?",
    ["不要，不要抛弃我……叔叔……"] = "Не, не бросай меня... Дядя...",
    ["不见了？"] = "Исчезнувший?",
    ["不认识……"] = "Никогда о ней не слышала...",
    ["不认识的叔叔，你好！"] = "Привет, незнакомый дядя!",
    ["不记得了"] = "Не помню",
    ["不论如何，我得先找个地方藏起来……要是被发现靠着魔药偷偷通宵学习的事就糟了。"] = "В любом случае, сначала мне нужно найти место, где можно спрятаться... было бы плохо, если бы меня поймали на том, что я всю ночь тайно занимаюсь зельями.",
    ["不说"] = "Не говорить",
    ["不说了，还是看看菜吧。新鲜的黄瓜、西红柿，多么可爱！"] = "Хватит разговоров, давайте посмотрим на овощи. Свежие огурцы, помидоры, как прелестно!",
    ["不过今天真不巧，他刚刚出门了。"] = "Но сегодня это действительно прискорбно; он только что вышел.",
    ["不过他应该与这次的恶性杀人案件无关，他有不在现场的证明，死亡时间内他正在参加另一场拳赛。"] = "Однако он не должен иметь отношения к этому жестокому убийству. У него есть алиби; на момент смерти он участвовал в другом боксерском поединке.",
    ["不过以前我们这确实有一户人家去了大城市……噢，是莫雷蒂一家。"] = "Но здесь действительно была семья, которая раньше уезжала в большой город... о, это была семья Моретти.",
    ["不过以前我们这确实有一户人都变成金凤凰了，对，莫雷蒂一家，兄妹三人。"] = "Но у нас здесь была семья, которая превратилась в золотых фениксов — да, семья Моретти, трое братьев и сестер.",
    ["不过你不害怕吗？作为一名值夜者，你会经常面对危险、甚至是死亡的威胁。"] = "Но ты не боишься? Будучи Ночным Ястребом, вы часто будете сталкиваться с опасностью, даже с угрозой смерти.",
    ["不过你倒是提醒我了，是该见见老朋友。"] = "Но ты напомнил мне; пришло время увидеть старых друзей.",
    ["不过在此之前，我需要使用一些手段，来隔绝封印物3-116的负面影响。"] = "Но прежде мне нужно применить некоторые средства, чтобы изолировать негативное влияние Запечатанного Артефакта 3-116.",
    ["不过好在救赎已至，请坚信，我们必将在“愚者”先生的带领下步入无暗的时代。"] = "Но, к счастью, спасение пришло. Пожалуйста, поверьте, что мы обязательно вступим в эпоху без тьмы под руководством  Шута.",
    ["不过这几天她都没有出现，出什么事了吗？"] = "Но она не появлялась уже несколько дней. Что-то случилось?",
    ["不过这里的每杯酒都来自恶龙的馈赠。尽享美味吧，{{先生|女士}}。"] = "Однако каждый напиток здесь исходит от дара дракона. Наслаждайтесь вкусом, {{Mr.|Ms.}}.",
    ["不过，他们似乎是在执行重要的任务，这就是“欲戴皇冠，必承其重”吗……"] = "Впрочем, похоже, они выполняют важное задание. Вот что значит «желающий носить корону должен выдержать её тяжесть»...",
    ["不过，原来不眠者也会需要喝咖啡吗？"] = "Однако нужно ли Неспящему вообще пить кофе?",
    ["不过，她的头发倒是梳得很整齐。看样子就算贫穷，她也有深爱她的家人。"] = "Впрочем, её волосы были причёсаны очень аккуратно. Похоже, несмотря на бедность, у неё есть семья, которая горячо её любит.",
    ["不过，我可以大胆地告诉你，你买一整块也不会感到失望。"] = "Однако могу смело сказать вам, что вы не разочаруетесь, если купите целое изделие.",
    ["不过，由于3-888的失踪，《谜题破解法》的保密等级提升了，需要<P_Yellow>找希罗多德申请</>。"] = "Однако из-за исчезновения номера 3-888 уровень конфиденциальности «Методов решения головоломок» был повышен; вам нужно <P_Yellow> обратиться к Геродоту за </>.",
    ["不远处，一位年轻男士驾马车，载黛西小姐快速朝玩家方向前进。\n黛西小姐手捧一束雏菊。男士一边驾车，一边把黛西小姐逗得大笑。"] = "Неподалеку молодой человек правил экипажем, быстро везя мисс Дейзи в сторону игрока.\nМисс Дейзи держала в руках букет маргариток. Юноша управлял лошадьми и весело шутил, заставляя мисс Дейзи звонко смеяться.",
    ["不错。不少离奇的案件，都是由不起眼的小事引起的。"] = "Правильный. Многие причудливые случаи вызваны незаметными мелочами.",
    ["不错。调查过程中如果遇到意外情况，一定要确保自己的安全，有问题随时联系我。"] = "Неплохо. Если в ходе расследования вы столкнетесь с непредвиденными ситуациями, вы должны обеспечить собственную безопасность и связаться со мной, если у вас возникнут вопросы.",
    ["不错，我和你想的一样。"] = "Неплохо, я думаю так же, как и вы.",
    ["不错，我没白死。"] = "Неплохо, моя смерть не была напрасной.",
    ["不，一定不要"] = "Нет, определенно нет",
    ["不，不会是海岸线餐厅。海岸线餐厅以南部美食闻名，而南威尔红酒产自北方的鲁恩王国，到海岸线餐厅喝南威尔红葡萄酒并不合适……"] = "Нет, это будет не ресторан «Береговая линия». Ресторан Coastline славится блюдами южной кухни, а вино Southwell производится в северном королевстве Лоен. В ресторане Coastline пить красное вино Southwell неуместно...",
    ["不，不是占卜的问题，是我高估了队长的记忆力……"] = "Нет, дело не в гадании, просто я переоценил память капитана...",
    ["不，不是这样，相反，现在的日子要好得多，我得到了一大笔遗产。"] = "Нет, это не так. Напротив, жизнь теперь стала намного лучше, я получил большое наследство.",
    ["不，为了小黛西，为了小黛西！"] = "Нет, для маленькой Дейзи, для маленькой Дейзи!",
    ["不，你不能带走它。没有循环空间，小黛西会死，她会死！"] = "Нет, вы не можете его забрать. Без места для цикла маленькая Дейзи умрет, она умрет!",
    ["不，你刚才已经打破小黛西的循环，她会一步步走向死亡。"] = "Нет, ты уже разорвал петлю маленькой Дейзи, и она шаг за шагом будет двигаться к смерти.",
    ["不，你刚才已经打破小黛西的循环，她会走向死亡。"] = "Нет, ты уже разорвал петлю маленькой Дейзи, и она пойдет навстречу смерти.",
    ["不，因为它好像就……窝在你后面啊……\n<P_Heart>（这种水平真的适合当私家侦探吗？）</>"] = "Нет, потому что он, кажется... притаился прямо у вас за спиной...\n<P_Heart>(С такими способностями точно можно работать частным сыщиком?)</>",
