    ["你好，旁边有长椅可以坐。"] = "Здравствуйте, рядом есть скамейка, где можно посидеть.",
    ["你好，有什么事吗？"] = "Здравствуйте, могу ли я вам чем-нибудь помочь?",
    ["你好，朋友，愿意加入俱乐部一起锻炼吗？"] = "Привет, друг, ты готов вступить в клуб и заниматься вместе?",
    ["你好，洛耀女士。"] = "Здравствуйте, г-жа Ло Яо.",
    ["你好，请问你是索菲娅吗？"] = "Здравствуйте, могу я спросить, вы София?",
    ["你好，请问你能送我一束花吗？"] = "Здравствуйте, могу ли я спросить, можете ли вы подарить мне букет цветов?",
    ["你好，请问是想找杂活女仆吗？我手脚麻利，热情洋溢，保证您雇佣了我天天都有好心情！"] = "Здравствуйте, вы ищете обычную горничную? Я сообразительный, энергичный и гарантирую, что если вы возьмете меня на работу, у вас будет хорошее настроение каждый день!",
    ["你好，这位{{英俊的先生|优雅的女士}}。"] = "Привет, {{handsome Mr.|elegant Ms.}}.",
    ["你完全不工作吗？"] = "Вы вообще не работаете?",
    ["你定定地凝视着微笑的黛西和雏菊花束。\n忽然间，小黛西和雏菊同时消失了。"] = "Вы пристально смотрите на улыбающуюся Дейзи и букет маргариток.\nВнезапно и маленькая Дейзи, и цветы бесследно исчезают.",
    ["你将昨天梦境中发生的事情，一五一十地告诉了弗莱队长。"] = "Вы рассказали капитану Фраю все, что произошло вчера во сне, слово в слово.",
    ["你将现场观众的评价转述给了施佩尔。"] = "Вы передали Шпееру оценку аудитории.",
    ["你就不害怕吗？"] = "Ты не боишься?",
    ["你就不要谦虚了，一天就抓住凶手，可不是运气两个字能概括的。"] = "Не будьте скромными. Поимку убийцы за один день невозможно описать словом «удача».",
    ["你就像……就像传说中的魔法师一样！"] = "Вы прямо как... как маг из легенд!",
    ["你就是之前向我推销火柴的外交大臣？"] = "Вы министр иностранных дел, который раньше пытался продать мне спички?",
    ["你就是军情大臣？"] = "Вы и есть министр военной разведки?",
    ["你已经做出自己的决定，对吗？"] = "Ты уже принял решение, верно?",
    ["你希望有谁？这群咋咋呼呼的小家伙，我这张你看了十几年的老脸，还是你希望在聚会上看见圣赛琳娜教堂的主教大人？"] = "На кого вы надеетесь? Эта кучка шумных маленьких придурков? Мое старое лицо, на которое ты смотрел уже больше десяти лет, или ты надеешься увидеть на вечеринке епископа собора Святой Селены?",
    ["你平安回来就好，海上那么危险，光是听你信里描述的什么“冒险”“海盗”就吓得我一身冷汗……我和阿尔伯特都很担心你。"] = "Я просто рад, что ты вернулся в целости и сохранности. Море так опасно; просто услышав о «приключениях» и «пиратах», которые вы описали в своих письмах, я покрылся холодным потом... Мы с Альбертом оба очень волновались за вас.",
    ["你应该去和会长聊聊。实际上，这件事就是她让我委托给你的。"] = "Вам следует поговорить с президентом. На самом деле именно она просила меня доверить это дело вам.",
    ["你应该去和会长聊聊。实际上，这起案件就是会长让我委托给你的。"] = "Вам следует поговорить с президентом. На самом деле это дело вам поручил Президент.",
    ["你应该去找医生看看。"] = "Вам следует сходить к врачу.",
    ["你应该称我为尊贵的阿罗德斯大人！"] = "Вам следует обращаться ко мне как к благородному лорду Арродесу!",
    ["你度过了漫长且无梦的一夜……"] = "Ты провел долгую ночь без снов...",
    ["你开枪啊"] = "Иди и стреляй",
    ["你开玩笑吧？"] = "Вы шутите?",
    ["你当初也是……"] = "Ты тоже был...",
    ["你彻底杀死了这只黑雾中的怪物，静静地看着怪物眼中的光芒消散。你榨出自己的最后一点灵性，将怪物的灵唤出……"] = "Вы полностью убили этого монстра в черном тумане, молча наблюдая, как рассеивается свет в его глазах. Вы выжимаете последнюю каплю духовности, чтобы вызвать дух монстра...",
    ["你很快就会习惯的。贝克兰德发生了一件案子，需要你前去调查。"] = "Скоро ты к этому привыкнешь. В Баклунде произошел случай, и вам нужно отправиться его расследовать.",
    ["你怎么在这上面，这里很危险？"] = "Как ты тут очутился? Здесь же очень опасно!",
    ["你怎么睡在这里？你怎么了？"] = "Почему ты спишь здесь? Что с тобой не так?",
    ["你怎么知道，嘿嘿，不愧是邓恩叔叔，偷偷告诉你，我觉得……"] = "Как вы узнали? Хе-хе, как и ожидалось от дяди Данна. Позвольте мне сказать вам по секрету, я думаю...",
    ["你惊醒了，原来只是一个噩梦。"] = "Ты проснулась, это был просто кошмар.",
    ["你想买哪种魔药？我现在手上有“安格尔威德之梦”、“夜访魔女”，以及“浴火的吞尾蛇”。"] = "Какое зелье вы хотите купить? В настоящее время у меня есть «Сон Ангервейда», «Ночная ведьма» и «Огненный Уроборос».",
    ["你想使用那个炉子？"] = "Хотите воспользоваться этой плитой?",
    ["你想去哪里，我一定准时送达！"] = "Куда вы хотите поехать? Доставлю точно в срок!",
    ["你想带他们回去过生日？"] = "Хотите забрать их обратно, чтобы отпраздновать день рождения?",
    ["你想聊点什么？"] = "О чем бы вы хотели поговорить?",
    ["你想要咨询什么问题？"] = "Какой вопрос вы хотите задать?",
    ["你想要挑战哪个关卡？"] = "Какой уровень вы хотите бросить вызов?",
    ["你想要查询哪段进度？"] = "Какой этап прогресса вы хотите проверить?",
    ["你或许需要一些时间休息，剩下的事由丽贝卡处理。"] = "Возможно, вам понадобится некоторое время, чтобы отдохнуть; Ребекка позаботится обо всем остальном.",
    ["你所学到的一切非凡知识，都能成为击败敌人的刀刃。"] = "Все, что вы узнали о знаниях Потусторонний, может стать клинком для победы над врагами.",
    ["你才来不久，可能不知道这些事情，后边就会清楚的，这不是秘密，邓恩队长是个好人，克莱恩也是很不错的值夜者。"] = "Вы здесь недавно, поэтому, возможно, не знаете об этих вещах, но поймете позже. Это не секрет; Капитан Данн — хороший человек, а Клейн — еще и очень хороший Ночной Ястреб.",
    ["你打算带阿尔伯特出海？"] = "Вы планируете взять Альберта в море?",
    ["你指谁？"] = "Кого вы имеете в виду?",
    ["你挑一个。"] = "Вы выбираете один.",
    ["你收到请柬了？其实我自己都忘记了，是老尼尔他们……"] = "Вы получили приглашение? Собственно, я даже сам об этом забыл; это был Старина Нил и остальные...",
    ["你既让犯罪的人接受惩罚，又带回封印物3-888、消除潜在危险。"] = "Вы оба заставили преступников принять наказание и вернули Запечатанный Артефакт 3-888, устранив потенциальную опасность.",
    ["你昏睡前见到的最后一个人是谁，还记得吗？"] = "Вы помните, кого вы видели последним перед тем, как впали в кому?",
    ["你是……？我们见过？"] = "Кто ты...? Мы встретились?",
    ["你是不会懂的。"] = "Тебе этого не понять.",
    ["你是今天第一位来占卜的人，免费。"] = "Вы первый, кто сегодня придет на гадание, это бесплатно.",
    ["你是否听说过特伦索斯特黄铜书？"] = "Слышали ли вы о Латунной книге Трунсоэста?",
    ["你是在说桌子上那些报销单吗？"] = "Вы имеете в виду те формы возмещения расходов, которые лежат на столе?",
    ["你是廷根的人吗？抱歉，我哥哥说话太没礼貌了。"] = "Вы из Тингена? Извините, мой брат слишком невежлив.",
    ["你是新来的？别乱找人占卜，他们大多连最基本的灵数都算不清！"] = "Ты здесь новенький? Не ходите и не просите людей о гадании; большинство из них не могут даже вычислить самые элементарные числа духов!",
    ["你是来体验生活的？"] = "Вы здесь, чтобы испытать жизнь?",
    ["你是温弗的剧迷吗？"] = "Вы поклонник Винфра?",
    ["你是看报纸过来的吗，来看看，我这有廷根市面上最齐全的家伙！"] = "Вы пришли сюда после прочтения газеты? Приходите и посмотрите; У меня самый полный запас в Тингене!",
    ["你是说，你在寻找姐姐，你的姐姐失踪了？"] = "Вы хотите сказать, что ищете свою сестру, а она пропала?",
    ["你是谁，为什么要赶走我的客人？"] = "Кто вы и почему прогоняете моего клиента?",
    ["你是谁？"] = "Кто ты?",
    ["你是谁？你怎么知道？"] = "Кто ты? Откуда ты это знаешь?",
    ["你是贵族？"] = "Ты дворянин?",
    ["你是这的学生吗？"] = "Ты здесь студент?",
    ["你是遇到什么烦心事了吗？"] = "Были ли у вас какие-либо проблемы?",
    ["你是那个顾客？"] = "Ты тот самый покупатель?",
    ["你是黄牛？"] = "Вы скальпер?",
    ["你是黛丝？"] = "Ты Дейзи?",
    ["你有东西被抢了吗？"] = "У вас что-то украли?",
    ["你有为实现梦想拼过命吗？"] = "Приходилось ли тебе рисковать жизнью ради своей мечты?",
    ["你有什么事？阿尔伯特这孩子，唉。"] = "У вас какое-то дело? Этот мальчишка Альберт... эх.",
    ["你有什么想知道的，只要是在廷根的，我都能帮你调查明白。"] = "Что бы вы ни хотели знать, если это находится в Тингене, я могу помочь вам тщательно это изучить.",
    ["你有仔细看它们吗？没有的话，可以先去看看。"] = "Вы внимательно их рассмотрели? Если нет, то сначала можно пойти посмотреть.",
    ["你有兴趣参加下一届恶龙争霸赛吗？"] = "Вы заинтересованы в участии в следующем Чемпионате Драконов?",
    ["你有梦想吗？你的梦想是什么？"] = "У вас есть мечта? Какая у тебя мечта?",
    ["你有空的话，可以进去给夏尔夫先生帮忙。"] = "Если у вас есть время, можете зайти и помочь господину Шарфу.",
    ["你服务态度也太差了吧，女士。"] = "Ваше отношение к обслуживанию ужасно, мисс.",
    ["你来了。"] = "Ты здесь.",
    ["你来得正是时候！"] = "Вы пришли в идеальное время!",
    ["你果然来了，很高兴能够再见面，我的新同事。"] = "Ты действительно пришел. Я очень рад видеть Вас снова, мой новый коллега.",
    ["你比我想象中能干。"] = "Вы более способны, чем я предполагал.",
    ["你没有做错。不过随着序列晋升，人性的情感会越来越稀缺，你需要警惕。"] = "Вы не сделали ничего плохого. Однако по мере продвижения вашей Последовательности человеческие эмоции будут становиться все более скудными; вам нужно быть бдительным.",
    ["你没有被扭曲认知？"] = "Ваше сознание не было искажено?",
    ["你没见过流浪儿的住所吗？"] = "Вы никогда не видели приюта для бездомного ребенка?",
    ["你父母不在吗？怎么留你一个人在这里？"] = "Твоих родителей здесь нет? Почему ты остался здесь один?",
    ["你牺牲那年他刚7岁，这样的信任是不是太沉重了？"] = "Ему было всего 7, когда ты пожертвовал собой. Не слишком ли тяжело такое доверие?",
    ["你现在需要休息，我先带你回黑荆棘。"] = "Тебе сейчас нужно отдохнуть. Сначала я отвезу тебя обратно в Блэкторн.",
    ["你的伤还好吗？"] = "С твоей травмой все в порядке?",
    ["你的叔叔叫什么名字？"] = "Как зовут твоего дядю?",
    ["你的叫卖……很特别。"] = "Ваша охота... очень уникальна.",
    ["你的妈妈……"] = "Твоя мама...",
    ["你的意思是我们现在该去试炼场互殴？"] = "Ты имеешь в виду, что нам следует пойти на тренировочную площадку и побить друг друга прямо сейчас?",
    ["你的搭讪技巧一直这么烂吗？"] = "Ваши линии пикапа всегда такие плохие?",
    ["你的板车上有黑荆棘的标志，你是值夜者？"] = "На вашей тележке изображен символ Блэкторна. Ты Ночной Ястреб?",
    ["你的气色看起来很不错，斯林太太。"] = "Вы выглядите так, будто у вас хорошее настроение, миссис Слин.",
    ["你的理解和接受能力一如既往地优秀。"] = "Ваше понимание и принятие, как всегда, превосходны.",
    ["你的笛子是哪里来的？它有什么作用？"] = "Где ты взял свою флейту? Что он делает?",
    ["你的脑海中闪过一段记忆，年轻的女工穿着这双舞鞋，纵身投向火炉之中。"] = "В памяти вспыхивает воспоминание: молодая работница в этих танцевальных туфлях бросается в печь.",
    ["你的脑袋里一定冒出了很多问题？调查就是解答疑问的过程！"] = "У тебя, наверное, голова кружится от вопросов? Расследование – это процесс ответов на вопросы!",
    ["你的腿……抱歉，我没发现……"] = "Твоя нога... извини, я не заметил...",
    ["你的责任是调查黛西小姐的案件，现在调查已经结束。"] = "В вашу обязанность входило расследование дела мисс Дейзи, и теперь расследование окончено.",
    ["你的身手不错，小伙子"] = "У тебя хорошие навыки, молодой человек.",
    ["你的运气爆棚是指？"] = "Что вы подразумеваете под взрывной удачей?",
    ["你的魅力源于自己"] = "Ваше очарование исходит от вас самих",
    ["你盘子里的柠檬蛋糕看起来很别致，是在哪家店买的呢？"] = "Лимонный пирог на вашей тарелке выглядит очень уникально; в каком магазине ты его купил?",
    ["你看什么看？此路不通！看不见吗！"] = "Что уставился? Прохода нет! Ослеп, что ли?!",
    ["你看到弗兰克吗？船刚靠岸，他就不见了，真令人担心。"] = "Ты видел Фрэнка? Он исчез, как только корабль пришвартовался. Это действительно тревожно.",
    ["你看到我旁边那位学员了吗？他总是待在那里不走，也许有什么烦恼想要倾诉。"] = "Вы видите этого студента рядом со мной? Он всегда остается там и не уходит. Возможно, у него есть какие-то проблемы, и он хочет кому-то довериться.",
    ["你看旁边这个！你戏剧的海报！这不就是你被认可的证明吗？"] = "Посмотрите на это рядом с вами! Афиша вашего спектакля! Разве это не доказательство того, что вас узнали?",
    ["你看看就知道了。"] = "Взгляни, и сам все поймешь.",
    ["你看起来很洒脱，完全不像一个阴魂不散的魂灵。"] = "Ты выглядишь очень беззаботно, совсем не похоже на медлительный дух.",
    ["你看那家餐厅，店主老维尔经常会分些东西给我吃。"] = "Посмотрите на этот ресторан; владелец, Старый Уилл, часто делится со мной едой.",
    ["你看，我才听了一次就已经记住了。小巴特更加不会忘记你为他写的这首曲子！"] = "Слушай, я вспомнил это, услышав всего один раз. Маленький Барт точно не забудет песню, которую ты для него написал!",
    ["你看，那个风车转起来了，我会召唤风了！这样，你是不是能带我去海上了？"] = "Смотри, мельница вращается! Я могу вызвать ветер! С этим ты сможешь отвезти меня к морю?",
    ["你看，里昂就是这么爱我。"] = "Видишь ли, Леон так меня любит.",
    ["你真好！我也有礼物给你，等等我们就可以一起交换礼物了，想想就开心！"] = "Ты такой добрый! У меня для тебя тоже есть подарок, мы можем обменяться подарками позже, одна мысль об этом меня радует!",
    ["你真棒，奖励你和我一起写诗。"] = "Ты молодец, я вознагражу тебя тем, что напишешь со мной стихи.",
    ["你真正做到了！怎么样，还顺利吗？"] = "Вы действительно сделали это! Как это было? Все прошло гладко?",
    ["你真的还在研究魔镜占卜？！风暴在上，你该知道那有多危险。"] = "Вы все еще изучаете гадание по волшебному зеркалу?! Шторм наверху, ты должен знать, насколько это опасно.",
    ["你真该去做波拿巴餐厅做个美食评论家，这条鱼我也要了。"] = "Тебе действительно стоит пойти в ресторан «Бонапарт» и стать кулинарным критиком. Я тоже возьму эту рыбу.",
