    ["先生，我想诊金并不是关键。或许这是霍森医生的某种行事准则吧。"] = "Сэр, я не думаю, что гонорар является ключевым моментом. Возможно, это своего рода кодекс поведения доктора Хозена.",
    ["先生，打扰了，我想您家里应该聘请了家庭医生？或者您需要什么额外的帮助吗？"] = "Сэр, извините, я полагаю, вы наняли семейного врача на дом? Или вам нужна дополнительная помощь?",
    ["先生，等您女儿在纺织厂咳出第一口血痰时，您就会觉得这海报比歌剧院的广告还美丽。"] = "Сэр, когда ваша дочь впервые кашляет кровью на текстильной фабрике, вы найдете этот плакат более красивым, чем любая реклама оперного театра.",
    ["先生，请看这种食物，我想它会大卖的！"] = "Сэр, пожалуйста, посмотрите на эту еду, я думаю, она будет хорошо продаваться!",
    ["先生，请问……"] = "Сэр, позвольте спросить...",
    ["先看看情况"] = "Сначала оценить обстановку",
    ["先离开，找找线索"] = "Уходи первым, ищи подсказки",
    ["先约个会怎么样？在我执念消散前能看到你们的婚礼吗？"] = "Как насчет того, чтобы сначала пойти на свидание? Могу ли я увидеть твою свадьбу, прежде чем моя одержимость рассеется?",
    ["先解决完危机再训斥我吧，队长。"] = "Давайте разрешим кризис, прежде чем читать мне нотации, капитан.",
    ["先试着聊聊如何？"] = "Как насчет того, чтобы сначала попытаться поговорить?",
    ["先选择一个基底。"] = "Сначала выберите основу.",
    ["光之折射也发射长枪，是否确认选择这项能力？选择后其他2个会消失"] = "Преломление Света также стреляет копьем. Подтвердить эту способность? Выбор этого приведет к исчезновению двух других.",
    ["光靠我的慈善基金是没办法帮助他们的，只有增收才能带动经济发展。"] = "Один лишь мой благотворительный фонд не сможет им помочь; только увеличивая доходы, мы можем стимулировать экономическое развитие.",
    ["克莱恩?"] = "Клейн?",
    ["克莱恩·莫雷蒂"] = "Клейн Моретти",
    ["克莱恩·莫雷蒂。"] = "Клейн Моретти.",
    ["克莱恩……嗯，他倒没什么不吃的，就是偏好甜味的食物。"] = "Клейн... ну, он ничего не любит, но предпочитает сладкое.",
    ["克莱恩匆忙冲出小巷，背后黑雾从小巷涌出，其不得不继续向前逃窜（过场文本先行占位）。"] = "Клейн в спешке выбегает из переулка, клубы черного тумана вырываются следом, вынуждая его бежать дальше без оглядки (временный текст кат-сцены).",
    ["克莱恩？他是我见过最有天赋的占卜家，只是……很可惜他已经回归女神的拥抱了！"] = "Кляйн? Он самый талантливый прорицатель, которого я когда-либо видел, но... как жаль, что он вернулся в объятия богини!",
    ["免费？请给我一块。"] = "Бесплатно? Дайте мне кусочек, пожалуйста.",
    ["免费？！"] = "Бесплатно?!",
    ["入梦"] = "Погружение в сон",
    ["全部写完了！乔纳尔，90种谜题的答案都在这里。"] = "Все дописано! Джонас, здесь ответы ко всем девяноста загадкам.",
    ["公主殿下，放心交给我吧。"] = "Ваше Высочество, пожалуйста, оставьте это мне.",
    ["公司环境"] = "Окружающая среда компании",
    ["公司的环境真的很不错。"] = "Атмосфера в компании действительно очень хорошая.",
    ["六十便士。"] = "Шестьдесят пенсов.",
    ["兰格是国王，那你是什么大臣？"] = "Ланге — король, а ты тогда какой министр?",
    ["关于一些细节，详见文档，在这里就不赘述了。顺便我需要在这里多说一点废话，来展示这里的动态镜头。"] = "Более подробную информацию можно найти в документации; Я не буду повторять их здесь. Кстати, здесь нужно еще немного ерунды говорить, чтобы продемонстрировать динамическую камеру.",
    ["关于伦纳德"] = "О Леонарде",
    ["关于安保公司"] = "Об охранной компании",
    ["关于尤朵拉"] = "Об Юдоре",
    ["关于廷根"] = "О Тингене",
    ["关于格尔曼先生的冒险之旅，这是一本精彩绝伦的小说，涉及到很多超凡世界隐秘的小说。"] = "Это блестящий роман о приключениях мистера Германа, затрагивающий множество тайн потустороннего мира.",
    ["关于生和死的界限？你有新的答案了？"] = "О границе между жизнью и смертью? У вас есть новый ответ?",
    ["关于红手套"] = "О «Ночных ястребах»",
    ["关心伊妮德"] = "Позаботиться об Энид",
    ["关键问题是，角落里那个人跟我们追查的凶手样貌完全不同。除非……"] = "Главная загвоздка в том, что человек в углу совершенно не похож на убийцу, которого мы выслеживаем. Если только...",
    ["兴奋地点头"] = "Восторженно кивнуть",
    ["其他孩子都只想玩游戏，你为什么这么想工作？"] = "Другие дети просто хотят играть в игры, почему вам так хочется работать?",
    ["其实……我也跟自己的父母失散了，现在只剩孤零零一个人。也不知道他们在哪里……"] = "Вообще-то... Я тоже потеряла родителей и теперь совсем одна. Я не знаю, где они...",
    ["其实我最近每天晚上都会做噩梦，早上起床的时候还发现枕头上掉了不少头发。"] = "На самом деле, в последнее время мне снятся кошмары каждую ночь, и когда я просыпаюсь утром, я заметил на подушке немало волос.",
    ["其实我还挺喜欢廷根，安静又漂亮，空气也很清新。"] = "На самом деле, мне очень нравится Тинген. Здесь тихо и красиво, а воздух очень свежий.",
    ["其实这是我第一次去钓鱼，我只是爱赌。"] = "На самом деле, это моя первая рыбалка, я просто люблю рисковать.",
    ["其实，这条途径在后期同样会获得不输他人的攻击和防御能力。但大家总是不太相信这一点。"] = "Фактически, этот путь также приобретет способности атаки и защиты, которые не уступают другим на более поздних стадиях. Но не все в это верят.",
    ["具体需要我做什么呢？"] = "Что конкретно мне нужно сделать?",
    ["内务大臣你听到了，{{先生|女士}}不擦皮鞋，你可以走开了。{{先生|女士}}，看报纸吗？"] = "Министр внутренних дел, вы его слышали, {{Mr.|Ms.}} не хочет чистить обувь, можете идти. {{Mr.|Ms.}}, хочешь почитать газету?",
    ["内务大臣又是做什么的？"] = "Чем занимается министр внутренних дел?",
    ["内务大臣是今天的生日吗？"] = "У министра внутренних дел сегодня день рождения?",
    ["内务大臣，行政大臣，搞砸了吧，{{先生|女士}}不擦皮鞋，也不看报纸。{{先生|女士}}是想买盒火柴，对吧{{先生|女士}}。"] = "Министр внутренних дел, исполнительный министр, облажайтесь, {{Сэр | Мадам}} не чистит обувь и не читает газету. {{Г-н|Мисс.}} хочет купить коробок спичек, верно {{Г-н|Мисс.}}.",
    ["再减去二十。"] = "Затем вычтите двадцать.",
    ["再减去您原来的年龄！"] = "А теперь вычтите ваш настоящий возраст!",
    ["再加上“歌颂者”能力对本身的临时提升，我完全可以与序列7层次，近身战斗型的怪物对抗。"] = "В сочетании с временным усилением моих собственных способностей от Барда я могу полностью бороться с монстрами ближнего боя уровня 7-го уровня.",
    ["再加上七。"] = "И прибавить еще семь.",
    ["再加入2茶匙的薄荷糖。嗯，独特的搭配。"] = "Добавьте 2 чайные ложки мятных леденцов. Хм, уникальное сочетание.",
    ["再加入2茶匙的鲜姜。嗯，独特的搭配。"] = "Добавьте 2 чайные ложки свежего имбиря. Хм, уникальное сочетание.",
    ["再加入2茶匙薄荷糖。"] = "Добавьте 2 чайные ложки мятных леденцов.",
    ["再加入2茶匙薄荷糖。嗯，独特的搭配。"] = "Добавьте 2 чайные ложки мятных леденцов. Хм, уникальное сочетание.",
    ["再加入2茶匙鲜姜。"] = "Добавьте 2 чайные ложки свежего имбиря.",
    ["再加入半杯弗萨克烈酒。嗯……看起来还可以。让我们继续。"] = "Добавьте полстакана крепкого ликера «Фейсак». Хм... выглядит нормально. Давайте продолжим.",
    ["再加入半杯弗萨克烈酒，喔，看起来真不错。让我们继续。"] = "Добавьте полстакана крепкого ликера «Фейсак». Вау, это выглядит очень хорошо. Давайте продолжим.",
    ["再加入半杯橙汁。嗯……看起来还可以。让我们继续。"] = "Добавьте еще полстакана апельсинового сока. Хм... на вид вполне прилично. Продолжаем.",
    ["再加入半杯橙汁，喔，看起来真不错。让我们继续。"] = "Добавьте полстакана апельсинового сока. Вау, это выглядит очень хорошо. Давайте продолжим.",
    ["再好好观察一下吧。"] = "Еще раз внимательно понаблюдайте.",
    ["再往右转，向前走，就能看到了。"] = "Снова поверните направо и продолжайте идти вперед, и вы это увидите.",
    ["再拿起那件蕴含非凡力量的武器，激发身体中被馈赠的非凡能力！"] = "Затем возьмите это оружие, пропитанное силой Потустороннего, и зажгите способности Потустороннего, подаренные вашему телу!",
    ["再来一把？还是回去带孩子？"] = "Сыграем еще партию? Или пойдешь нянчиться с детьми?",
    ["再次询问卡萝"] = "Спроси Кэрол еще раз",
    ["再等几天他们自然就会离开啦。"] = "Через несколько дней они уйдут сами.",
    ["再等等……这一章实在太刺激了，我必须多读几遍。"] = "Подожди секунду... эта глава слишком захватывающая, я должен перечитать её ещё разок.",
    ["再者，救济院每年的拨款是有限的，抛开一些年纪大的，作为工作人员，是真的不想让普通人都来这里。"] = "Кроме того, ежегодное финансирование богадельни ограничено. Если оставить в стороне некоторых пожилых людей, то мы очень не хотим, чтобы сюда приходили обычные люди.",
    ["再见。"] = "До свидания.",
    ["再见了，斯卡纳女士。"] = "До свидания, мисс Скана.",
    ["再见！"] = "До свидания!",
    ["再见，希罗多德先生，祝您和阿曼达女士生活愉快。"] = "До свидания, господин Геродот. Желаю вам и мисс Аманде приятной жизни.",
    ["再见，波特！"] = "До свидания, Поттер!",
    ["再见，雪莉。"] = "До свидания, Шерри.",
    ["再观察一下"] = "Понаблюдайте еще немного",
    ["冒险回来了？就按之前说好的办，一分不少。"] = "Вернулся из приключения? Поступим, как договаривались, ни гроша меньше.",
    ["写不下去了，感觉每一句话都不太对。"] = "Я больше не могу писать. Я чувствую, что каждое предложение просто неправильно.",
    ["军情大臣！等等我！"] = "Министр военной разведки! Подожди меня!",
    ["决定了，我要一杯迪西咖啡。"] = "Решено, возьму чашечку кофе по-дисийски.",
    ["决绝地告诉她"] = "Твердо скажи ей",
    ["冷静一点"] = "Успокойся",
    ["冷静分析"] = "_\n\nСпокойный анализ",
    ["冷静点老费奇！是，是梅丽妮夫人说您总把衣服熏得一股煤烟味……"] = "Успокойся, старина Фитч! Это миссис Мелини сказала, что одежда всегда пахнет угольным дымом...",
    ["冷静，大家都冷静一下。我知道这件事情很突然，但我们必须想好对策。"] = "Успокойся, все успокойся. Я знаю, что это очень неожиданно, но мы должны подумать о контрмере.",
    ["冷静？我冷静不了！我想睡觉！我要睡觉！"] = "Спокойствие? Я не могу успокоиться! Я хочу спать! Я хочу спать!",
    ["准备仪式"] = "Подготовительный ритуал",
    ["准备好了……这事一点也不危险，对吧？"] = "Я готов... это ведь совсем не опасно, правда?",
    ["准备好了。在塔罗学派的时候，我就已经下定决心。"] = "Я готов. Когда я была в Клубе Таро, я уже приняла решение.",
    ["准备好了请告诉我，我们即刻出发。"] = "Скажите мне, когда будете готовы, и мы немедленно отправимся в путь.",
    ["几个学生来到公告栏前……"] = "К доске объявлений подошли несколько студентов...",
    ["几天后……"] = "Несколько дней спустя...",
    ["几年前我试着把他们从回忆里一点点复现出来，没想到附近的邻居也都挺喜欢的，就一并放在店里卖了。"] = "Несколько лет назад я попытался по крупицам воссоздать их по памяти. Кто бы мог подумать, что соседям они тоже приглянутся, вот я и выставил их на продажу в лавке.",
    ["凭什么……"] = "На каком основании...",
    ["凭你？现在的非凡者都这么没礼貌吗？"] = "Вами? Неужели все Потусторонние в наши дни такие грубые?",
    ["凶杀！真相只有一个！一定有人在这里被杀害了！"] = "Убийство! Есть только одна истина! Должно быть, здесь кого-то убили!",
    ["出什么事了？"] = "Что случилось?",
    ["出价"] = "Делать ставку",
    ["出去散散心吧，今天天气很不错。我会看着这群小家伙，不会让他们炸掉黑荆棘的。"] = "Выйдите и очистите голову; погода сегодня довольно хорошая. Я присмотрю за этими малышами и не позволю им взорвать Чёрный Чертополох.",
    ["出场动画"] = "Входная анимация",
    ["出示怀表"] = "Показать карманные часы",
    ["出示警徽"] = "Покажите значок полиции",
    ["分开寻找或许更快一些，麻烦您了。"] = "Отдельный поиск может быть быстрее. Извините, что беспокою вас.",
    ["刚开始的时候很辛苦，每天要起得很早，最难受的还是吃不饱。"] = "Вначале было очень тяжело; Мне приходилось каждый день вставать очень рано, и самое ужасное было то, что мне не хватало еды.",
    ["刚开始，她和一位男士，共乘一辆马车，很开心、很天真……"] = "Вначале она и один господин ехали вместе в карете, очень счастливые, очень невинные...",
    ["刚才……？尤朵拉去哪里了？"] = "Прямо сейчас...? Куда пропал Йодора?",
    ["刚才发生了什么，你为什么会昏迷在巷子里？"] = "Что произошло только что? Почему ты был без сознания в переулке?",
    ["刚才我买完菜，有个小家伙说帮我提袋子，只要1便士。现在的孩子们都这么鬼灵精了么？"] = "Только что, когда я закончила покупать продукты, малыш сказал, что поможет мне донести сумку всего за 1 пенс. Неужели современные дети такие умные?",
    ["初次见面，阿诺德"] = "Приятно познакомиться, Арнольд",
    ["别别别！我这就下来！真是的，连个观众都不配合！"] = "Нет, нет, нет! Я спускаюсь! Честно говоря, даже зритель не будет сотрудничать!",
    ["别吵……《贝克兰德日报》卖完了，《海上新闻》还没到货……要买就自己去拿，零钱放罐子里……"] = "Не беспокойте меня... \"Бэклунд Дейли\" распродана, \"Мэритайм Ньюс\" еще не пришла... Если хочешь купить, иди и возьми сам, положи сдачу в банку...",
    ["别吵我！背不完了！背不完了！"] = "Не беспокой меня! Я не могу все это запомнить! Я не могу все это запомнить!",
    ["别吵！我快够到它了……就差一点！"] = "Не ворчите! Я почти достиг цели... еще немного!",
    ["别在意这些家伙了，你该多关注些有意思的事情。"] = "Не беспокойтесь об этих ребятах, вам следует уделять больше внимания интересным вещам.",
    ["别墅。"] = "Вилла.",
    ["别墅的话，豪尔斯街有栋豪华别墅正在出租，一位大富豪的房子，现在他们去贝克兰德定居了。"] = "Что касается виллы, то на Холлс-стрит сдается в аренду роскошная вилла. Он принадлежит богатому человеку. Сейчас они обосновались в Баклунде.",
    ["别小瞧它，露娜女士自死亡中诞生，碧绿的瞳孔中是来自死神的窥视，冒犯露娜女士的人都会被镶进漆黑的墙壁之中。"] = "Не стоит ее недооценивать. Госпожа Луна родилась из смерти, и ее изумрудные зрачки удерживают взгляд Бога Смерти. Любой, кто оскорбит мисс Луну, будет заперт в кромешной тьме стен.",
    ["别忘记常来修炼。"] = "Не забывайте часто приходить и совершенствоваться.",
    ["别怕，已经没事了，阿尔伯特。"] = "Не бойся, теперь все в порядке, Альберт.",
    ["别急着溜走，不然我可能会用一些不那么温柔的手段了，呵呵。"] = "Не спеши ускользать, иначе мне, возможно, придется использовать какие-то менее щадящие методы, хех.",
    ["别打断我呀。听我说，老乘客的票我不卖，因为没法拉动新需求。"] = "Не перебивай меня. Послушайте меня, я не продаю билеты старым пассажирам, потому что это не вызывает нового спроса.",
    ["别担心伙计们，没人能抢走属于我们的东西。"] = "Не волнуйтесь, мальчики, никто не сможет отобрать то, что принадлежит нам.",
    ["别担心，你会获得一场愉快的谈话的。"] = "Не волнуйтесь, вас ждет приятная беседа.",
    ["别提了！这几天膝盖疼得像被马车碾过一样，我那儿子非让我在家躺着。这不，刚能走路，我就来了。"] = "И не спрашивай! Все эти дни колени болели так, будто по ним экипаж проехал, сынок велел дома отлёживаться. Вот, только смог ходить — сразу сюда.",
    ["别提了，我这脑袋像是被蒸汽锤砸过一样，嗡嗡直响。昨晚加班到半夜，工头连口热水都没给。"] = "Забудьте об этом, в голове гудело, как будто по ней ударили паровым молотом. Вчера вечером мы работали сверхурочно до полуночи, а бригадир даже не дал мне горячей воды.",
    ["别提什么雇佣兵小队，来喝一杯吧！"] = "Брось ты этот наемничий отряд, давай лучше выпьем!",
    ["别提啦，年纪那么大了。等老了，跳不动咯。"] = "Не упоминай об этом, я уже так стар. Когда я состарюсь, я уже не смогу танцевать.",
    ["别提带孩子——快快快，还有五分钟我就要回家了，在那之前还来得及再来一把！"] = "Не говоря уже о том, чтобы взять с собой детей — торопитесь, торопитесь, торопитесь, мне нужно идти домой через пять минут, до этого еще есть время еще на один раунд!",
    ["别有一番风味的<P_Heart>（嚼嚼嚼）</>点心，适合下午茶……"] = "Закуска с уникальным вкусом <P_Heart> (жуй, жуй) </>, подойдет к послеобеденному чаю...",
    ["别沮丧，亲爱的。还记得我们初遇时我在读的罗塞尔诗集吗？来吧，擦干眼泪，我们再一同吟咏当年的那首诗。"] = "Не расстраивайся, моя дорогая. Помнишь сборник стихов Розеллы, который я читал, когда мы впервые встретились? Давай, вытри слезы и давай вместе прочтем это стихотворение того времени.",
    ["别生气……我听说，投硬币会增加好运，运气爆棚的人能在净化之泉里获得非凡奖励！"] = "Не сердись... Я слышал, что подбрасывание монеты увеличивает удачу. Обладатели взрывной удачи могут получить необыкновенные награды в Фонтане Очищения!",
    ["别看黑兹那样，他也曾经是个很好的队长。"] = "Не смотри на Хейза так; он тоже был очень хорошим капитаном.",
    ["别着急，我问问附近的灵……"] = "Не волнуйтесь, позвольте мне спросить духов поблизости...",
    ["别紧张，没人指责你。干脆你把大家都叫来吧，我们未来的目标不是做大学同学吗？"] = "Не волнуйся, тебя никто не винит. Почему бы тебе просто не позвать всех сюда? Разве нашей общей целью не было учиться в одном университете?",
    ["别紧张，灵界谜虫危害不大，交给我来处理，你回去休息吧。"] = "Не нервничайте. Загадочные насекомые духовного мира не очень опасны. Предоставьте это мне; ты возвращаешься и отдыхаешь.",
    ["别误会，不是她嫌我打扫得不好，我的妻子是一位风暴信徒。"] = "Не поймите неправильно, дело не в том, что она думает, что я плохо убираюсь, моя жена верит в Шторм.",
    ["别说出那个名字！我已经连续吃了半个月那东西，连呼吸都是格尔曼风味，又甜又辣……看！我好不容易换到的赠品。"] = "Не произноси это имя! Я ем это уже полмесяца подряд. Даже мое дыхание имеет вкус Германа, и сладкое, и пряное... Смотри! Халява, на которую мне наконец удалось обменять.",
    ["别走！不要离开我！不要逃开！不要骂我！不要打我！"] = "Не уходи! Не оставляй меня! Не убегай! Не ругайте меня! Не бей меня!",
    ["别过来！别过来！"] = "Не подходи! Не подходи!",
    ["别过来！我受够了这该死的生活！今天谁都别想拦我！"] = "Держитесь подальше! Мне надоела эта проклятая жизнь! Сегодня меня никто не остановит!",
    ["别这么小气，我只是犯了所有小猫咪都会犯的错。"] = "Не будь таким скупым; Я только что совершил ошибку, которую совершают все маленькие котята.",
    ["到你出场了，听话的好心人。"] = "Твоя очередь блистать, послушный и добрый человек.",
    ["到处抱怨的赌徒"] = "Игроки, которые жалуются повсюду",
    ["到处都找不到那份资料，它还能在哪里呢……"] = "Нигде не могу найти эту информацию, где еще она может быть...",
    ["到处都是非凡力量的残留……献祭？还是什么仪式？"] = "Повсюду остаточные следы Потусторонней силы... Жертвоприношение? Или какой-то ритуал?",
    ["到时候……管理委员会来调查……你也别想逃得了干系！"] = "Когда придет время... комитет управления приедет для расследования... вам не удастся избежать участия!",
    ["刻意一点，可以摔断骨头，但是又有什么用呢？"] = "Если я сделаю это намеренно, я могу сломать кость, но какой в ​​этом смысл?",
    ["前不久，有人在贝克兰德发现了他的踪迹，教区值夜者博尔吉亚立即带人追捕，一路到了廷根附近，向圣堂请求支援。"] = "Не так давно кто-то обнаружил его следы в Баклунде. Епархиальный Ночной Ястреб Борджиа немедленно повел людей преследовать его, вплоть до окрестностей Тингена, и запросил поддержки у Святого собора.",
    ["前不久，有多位目击者在夜晚目击到疑似活尸的踪迹。"] = "Не так давно многочисленные свидетели заметили ночью следы того, что предположительно было зомби.",
    ["前几十年不敢买的东西，现在能随便买，可好吃的食物已经嚼不动，好喝的饮料已经咽不下，想做的事也没那个心力了。"] = "Вещи, которые я не решался покупать десятилетиями, теперь я могу купить случайно, но я больше не могу жевать вкусную еду, не могу глотать вкусные напитки, и у меня нет ни сил, ни сил на то, что я хотел сделать.",
    ["前段时间太忙，一直没去看望阿诺德，据说他和卡萝队长的性格越来越像了，呵呵。"] = "В последнее время я был слишком занят, чтобы навещать Арнольда, говорят, его характер все больше и больше становится похожим на капитана Кэрола, хаха.",
    ["剩下跟着我的这群小混球叫我“乞丐王”，但不如说我是所有人的教母。"] = "Маленькие дети, которые следуют за мной, называют меня «Королем-нищим», но правильнее было бы сказать, что я для всех крестная мать.",
    ["剪裁也比以前的更加严谨精致了，更加，更加……"] = "Да и покрой стал куда строже и изящнее прежнего, куда более... куда более...",
    ["劝说吉尔达"] = "Убедить Гильду",
    ["办完事就早点离开吧，年轻人，夜晚这里将不属于你们。"] = "Уходите пораньше, когда закончите свои дела, молодой человек; ночь здесь не будет принадлежать тебе.",
    ["加入了糖和其他风味原料，非常适合咀嚼……"] = "Добавлен сахар и другие ароматизаторы, очень подходят для жевания...",
    ["加入塔罗学派时，我们都曾面对屏障碎片宣誓——“以人性守护未来，于末日相互守望”，每个塔罗学派成员都明白这句话的意义。"] = "Вступая в Клуб Таро, мы все поклялись перед осколками Барьера: «Сохраняйте будущее вместе с человечеством и берегите друг друга в конце света». Каждый член Клуба Таро понимает смысл этого предложения.",
    ["加油，你就要胜利了！"] = "Держись, победа уже близка!",
    ["加油，施耐德先生！"] = "Давайте, мистер Шнайдер!",
    ["动画"] = "Анимация",
    ["动画占位"] = "Заполнитель анимации",
    ["动身返回塔罗学派……"] = "Отправиться обратно в Школу Таро...",
    ["劳维斯先生……"] = "Мистер Ловис...",
    ["劳维斯先生，我想知道，火柴对珍妮而言，是不是很特殊？"] = "Мистер Ловис, я хочу знать, являются ли матчи чем-то особенным для Дженни?",
    ["包在我身上。"] = "Оставьте это мне.",
    ["医生怎么站在诊所外面？"] = "Почему врач стоит возле клиники?",
    ["医生！为什么我的背上全是曲奇饼一样的淤青！"] = "Доктор! Почему моя спина вся в синяках, похожих на печенье!",
    ["医生？不，哪有这么严重，再说我哪里有钱去医院呢？"] = "Врача? Да нет, всё не настолько серьёзно, к тому же откуда у меня деньги на больницу?",
    ["千万不要低估这些小家伙的食欲，亲爱的，我们必须尽快捉到它们！"] = "Никогда не недооценивайте аппетит этих малышей, мои дорогие, мы должны поймать их как можно скорее!",
    ["午餐不愉快？"] = "Обед не понравился?",
    ["午餐时如果移开视线，食物就会被幽灵带走。"] = "Если вы отвернетесь во время обеда, еду заберет призрак.",
    ["午餐消失？"] = "Обед пропал?",
    ["半年前……"] = "Полгода назад...",
    ["半杯弗萨克烈酒，半杯柠檬汁，2茶匙薄荷糖，再加上一点柠檬瓣。接下来摇一摇……"] = "Полстакана крепкого ликера «Фейсак», полстакана лимонного сока, 2 чайные ложки мятных леденцов плюс немного цедры лимона. Далее встряхните его...",
    ["半杯柠檬汁，半杯橙汁，2茶匙薄荷糖……接下来摇一摇。"] = "Полстакана лимонного сока, полстакана апельсинового сока, 2 чайные ложки мятных леденцов... затем встряхните.",
    ["半杯柠檬汁，半杯橙汁，2茶匙鲜姜……接下来摇一摇。"] = "Полстакана лимонного сока, полстакана апельсинового сока, 2 чайные ложки свежего имбиря... затем встряхните.",
    ["半杯甜柠檬汁，半杯弗萨克烈酒，2茶匙鲜姜，一些冰块。接下来摇一摇……"] = "Полстакана сладкого лимонного сока, полстакана крепкого ликера «Фейсак», 2 чайные ложки свежего имбиря, несколько кубиков льда. Далее встряхните его...",
    ["半杯甜苹果汁，半杯橙汁，2茶匙薄荷糖，再加上一点柠檬瓣。接下来摇一摇……"] = "Полчашки сладкого яблочного сока, полчашки апельсинового сока, 2 чайные ложки мятного сахара и дольку лимона. Теперь хорошенько взболтать...",
    ["半杯甜苹果汁，半杯橙汁，2茶匙鲜姜，一些冰块。接下来摇一摇。"] = "Полстакана сладкого яблочного сока, полстакана апельсинового сока, 2 чайные ложки свежего имбиря, несколько кубиков льда. Затем встряхните его.",
    ["半杯苹果汁，半杯弗萨克烈酒，2茶匙薄荷糖，一些冰块。接下来摇一摇……"] = "Полстакана яблочного сока, полстакана крепкого ликера «Фейсак», 2 чайные ложки мятных леденцов, несколько кубиков льда. Далее встряхните его...",
    ["半杯苹果汁，半杯弗萨克烈酒，2茶匙鲜姜……让我们摇一摇。"] = "Полстакана яблочного сока, полстакана крепкого ликера «Фейсак», 2 чайные ложки свежего имбиря... встряхнем.",
    ["卖票，我有五不卖。"] = "Продам билеты, у меня пять \"не продаются\".",
    ["卖给你，只要15苏勒，我保证，你一定会每天期待夜晚的降临，怎么样？"] = "Я продам его тебе всего за 15 суле. Гарантирую, вы будете с нетерпением ждать наступления ночи каждый день. Как насчет этого?",
    ["南大陆非常喜欢黄金制品，这部分的产品也以黄金为主材料，配合南大陆本土的各种宝石。"] = "На Южном континенте очень любят изделия из золота, поэтому в этой части коллекции в качестве основного материала используется золото в сочетании с различными драгоценными камнями, произрастающими на Южном континенте.",
    ["卜杖寻路找到解决诅咒的方式，指向了炼钢厂的氛围，焚烧炉的镜头一闪而过（字幕代替）"] = "Компания Лозоходство нашла способ снять проклятие, указав на атмосферу сталелитейного завода вспышкой мусоросжигателя (заменены субтитры).",
    ["占位"] = "Инфо",
    ["占卜多少钱？"] = "Сколько стоит гадание?",
    ["占卜家途径导师"] = "Наставник Пути Провидца",
    ["占字符"] = "Символ-заполнитель",
    ["卡座角落的男人"] = "Мужчина в углу будки",
    ["卡特，那200里纳尔什么时候还我？或者，再玩一局桌球？"] = "Картер, когда ты вернешь мне эти 200 фунтов? Или сыграть еще раз в бильярд?",
    ["卡萝·比舍普队长是一位伟大无私的值夜者。"] = "Капитан Кэрол Бишоп была великим и самоотверженным Ночным Ястребом.",
    ["卡萝队长……"] = "Капитан Кэрил...",
    ["卡萝队长，如果你想与邓恩说话，我可以尝试一些办法。例如……让他感知到你的意识？"] = "Капитан Кара, если вы хотите поговорить с Данном, я могу попробовать некоторые методы. Например... позволить ему воспринимать твое сознание?",
    ["卡萝队长，需不需要附身在我身上再与阿诺德再见一面，你还有很多话想对他说吧。"] = "Капитан Кэрил, вам нужно завладеть мной, чтобы еще раз увидеть Арнольда? Должно быть, ты хочешь сказать ему гораздо больше.",
    ["卡萝队长，黑夜教会派遣我来，本来就是做了这样的打算。"] = "Капитан Кэрол, Церковь Вечной Ночи отправила меня с этим намерением с самого начала.",
    ["卡萝队长？"] = "Капитан Кэрол?",
    ["卢卡斯告诉我，过几天济贫院会发放免费的食物，也会给我们安置住所。我鼓励珍妮，让她再撑几天。"] = "Лукас сказал мне, что богадельня через несколько дней раздаст бесплатную еду и предоставит нам жилье. Я посоветовал Дженни продержаться еще несколько дней.",
    ["卢瑟这个笨蛋到底什么时候出来！"] = "Когда же выйдет этот идиот Лютер!",
    ["危险已经基本排除了，只是有人来过这里，我担心他们有可能将污染带了出去，所以目前暂时又重新封锁了这里，防止受影响的范围扩大。"] = "Опасность в основном устранена, но кто-то здесь был. Я обеспокоен тем, что они могли вывести порчу наружу, поэтому мы снова временно запечатали это место, чтобы предотвратить расширение сферы влияния.",
    ["即使你也还是个孩子……"] = "Даже если ты еще еще ребенок...",
    ["即使如此……你还是欺骗了我。"] = "Несмотря на это... ты все равно обманул меня.",
    ["即使我是因蒂斯人，也不得不承认鲁恩王国的强大。"] = "Несмотря на то, что я человек Интис, я должен признать силу Королевства Лоен.",
    ["即使没有这些传闻，下街也够糟糕了。偷盗抢劫，打架斗殴，一天都不得安宁。"] = "Даже без этих слухов жизнь на Нижней улице — сущий кошмар. Воровство, грабежи, драки... ни дня покоя.",
    ["即使渺小如我，也留下了完整的作品……我从未后悔过……"] = "Каким бы незначительным я ни был, я оставил после себя целое произведение... Я ни разу об этом не пожалел...",
    ["即使爸爸妈妈不在，我也可以照顾好客人呀。"] = "Даже если мамы и папы здесь нет, я смогу хорошо позаботиться о гостях.",
    ["卷毛狒狒听了都觉得荒谬，你看看你写了什么？女神啊，我受够了，哪有邪神在意这区区几百便士的？"] = "Даже кучерявому павиану это показалось бы абсурдом. Посмотрите, что вы написали! Богиня, с меня хватит. Какого злого бога волнуют несколько сотен пенсов?",
    ["卷边的纸牌，已经有些旧了。"] = "Потертые игральные карты, уже немного старые.",
    ["历史的孔隙需要勇敢的人探索。"] = "Просветы истории ждут отважных исследователей.",
    ["厉害有什么用？上头随便一个指令，下面的人就为了“美观”，把菜都铲了！市政厅的大人们连泥土都要管束！"] = "Какой смысл впечатлять? Один-единственный приказ сверху, и люди внизу все разгребают ради «эстетики»! Лорды в мэрии даже хотят контролировать грязь!",
    ["厉害，厉害。"] = "Впечатляет, впечатляет.",
    ["原因……有些复杂，在她心里，我一直都是夺走了她未来的那个人吧。"] = "Причина... несколько сложна. В ее сердце я всегда был тем, кто отнял у нее будущее.",
    ["原来他们不只是乞丐，还是逃出工厂的童工……他们会被打死的，不行，得去拦一下！"] = "Значит, это не просто нищие, это дети-работники, сбежавшие с Фабрики... Их будут забивать до смерти. Нет, я должен пойти и остановить их!",
    ["原来你知道啊。"] = "Итак, вы знаете.",
    ["原来如此。<P_Heart>（不知道我的职业病是不是看到什么可疑的人都想聊聊天呢……）</>"] = "Я понимаю. <P_Heart> (Интересно, мое профессиональное заболевание заключается в том, что я хочу поболтать с кем-нибудь, кого я вижу и кто выглядит подозрительно...) </>",
    ["原来是一只猫……"] = "Так это был кот...",
    ["原来是任务……需要帮忙吗？"] = "Итак, это был квест... Тебе нужна помощь?",
    ["原来是这样解决的吗？"] = "Так вот как это решилось?",
    ["原来是这样，但你已经……嗯，我是说你早应该考虑婚姻和家庭了。虽然警察的工作忙碌又危险，但会有很多姑娘喜欢你这样温柔又可靠的绅士。"] = "Вот так оно и есть. Но ты уже... ну, я имею в виду, что тебе давно следовало подумать о браке и семье. Хотя работа в полиции занята и опасна, есть много девушек, которым нужен такой нежный и надежный джентльмен, как ты.",
    ["原来这个方向是老维尔餐厅的后门啊！我才发现。"] = "Значит, это направление — черный ход ресторана Old Will's! Я только что понял.",
    ["原来邓恩接了队长这个烂摊子，那我就放心了！"] = "Итак, Данн взял на себя эту неразбериху в должности капитана, и тогда я могу быть спокоен!",
    ["去世了？这么短的时间，发生什么事了？"] = "Ушёл из жизни? Что произошло за такое короткое время?",
