    ["去哪里？"] = "Куда пойти?",
    ["去海上？太好啦！我要告诉玛里琳这个好消息！"] = "Поехать на море? Замечательно! Я хочу сообщить Мэрилин эту хорошую новость!",
    ["去看看"] = "Иди посмотри",
    ["去看看。"] = "Иди посмотри.",
    ["去码头运鱼……已经很努力了……"] = "Перевозка рыбы в причал... Я уже постарался...",
    ["去自由地大笑、尽情地相爱、幸福地活着，然后去做个美梦。"] = "Смейся свободно, люби всласть, живи счастливо, а потом мечтай о сладком.",
    ["去问清楚"] = "Иди спроси четко",
    ["参加生日会，当然要带个蛋糕。"] = "Чтобы пойти на день рождения, мне, конечно, нужно принести торт.",
    ["又不抓小偷了？还是先找到那个孩子吧。"] = "Отказаться от поимки вора? Давайте сначала найдем этого ребенка.",
    ["又偷偷学习。哼，世界上怎么会有你这样阴险的人？"] = "Снова учится тайно. Хм, как может быть в мире такой коварный человек, как ты?",
    ["又是来要钱的？"] = "Опять деньги просить?",
    ["又来一个，你们不买花就赶快走，要不然我可要叫治安官了。"] = "Еще один... Если не собираетесь покупать цветы, проваливайте, иначе я вызову констебля!",
    ["又来廷根出任务了？"] = "Снова задание в Тингене?",
    ["发型"] = "Прическа",
    ["发生了什么？"] = "Что случилось?",
    ["发生什么了？"] = "Что случилось?",
    ["发生什么事了？"] = "Что случилось?",
    ["发财这种事，什么时候轮到我们这些平民了？我倒是见过不少想去拜亚姆赌场，渴望一夜暴富的人，谁都没有回来。"] = "Когда же настанет очередь разбогатеть и таких простолюдинов, как мы? Я видел многих, кто хотел пойти в казино Баям, желая разбогатеть в одночасье, но никто из них так и не вернулся.",
    ["取决于你点了多少杯酒。"] = "Это зависит от того, сколько напитков вы заказываете.",
    ["受你召唤的愚者牌，以正位之姿显现。你是结束，也是开始……抱歉，我看不到更多了。"] = "Карта Шута, которую вы призвали, появляется в вертикальном положении. Ты — конец, а также начало... Извините, я не могу видеть большего.",
    ["受你召唤的月亮牌，以逆位之姿显现。你的过去被迷雾遮盖……抱歉，我看不到更多了。"] = "Карта Луны, которую вы призвали, отображается в перевернутом виде. Ваше прошлое покрыто туманом... Извините, я не могу больше видеть.",
    ["受你召唤的隐者牌，以正位之姿显现。真正的答案往往来自内心……抱歉，我看不到更多了。"] = "Карта Отшельника, которую вы призвали, отображается вертикально. Истинный ответ часто приходит изнутри... Извините, большего я не вижу.",
    ["变态。"] = "Извращенец.",
    ["另一个值班人员"] = "Еще один дежурный",
    ["另外，不要尝试撬开它，否则，我不得不考虑将你告上法庭！"] = "И не пытайтесь его открыть, иначе мне придется подать на вас в суд!",
    ["另外，我们似乎搞砸了邓恩的生日呢，我还有最后一点力气……"] = "Кроме того, похоже, мы испортили Данну день рождения. У меня еще осталось немного сил...",
    ["只是……很多人永远都回不来了，留在间海前线，留在明尔明斯克山脉上。"] = "Просто... многие люди так и не вернулись, оставшись на Мидсиширском фронте, оставшись в Минминских горах.",
    ["只是看起来体面罢了，服装店的安迪和我抱怨好多次了，说他每天以各种理由去服装店退货。"] = "Он просто выглядит прилично. Энди из магазина одежды много раз жаловался мне, говоря, что каждый день ходит в магазин, чтобы вернуть вещи по разным причинам.",
    ["只有借阅更高保密等级的资料，才需要老希罗多德、导师们甚至会长的批准。"] = "Только заимствование информации с более высоким уровнем конфиденциальности требует одобрения старого Геродота, наставников или даже президента.",
    ["只有变得更便宜，才能被更多人买到，只要买的人足够多，我们就能定义什么是风尚——这可比原料贵重得多。"] = "Только подешевев, его сможет купить больше людей. Пока достаточное количество людей покупают это, мы можем определить, что такое мода — это гораздо более ценно, чем сырье.",
    ["只有找到故事的真相，才能平安离开这个空间，这其实是你唯一的选择……"] = "Только узнав правду истории, вы сможете безопасно покинуть это пространство. На самом деле это ваш единственный выбор...",
    ["只要尽快把那个藏在暗处的家伙抓出来，就没什么需要担心的。"] = "Если вы как можно скорее поймаете этого парня, прячущегося в темноте, вам не о чем беспокоиться.",
    ["只要弄对了祈求的对象就不会，如果您想放下偏见找我占卜的话，随时恭候。"] = "Пока вы найдете подходящего человека, которому можно молиться, этого не произойдет. Если вы хотите отбросить свои предубеждения и попросить меня о гадании, я всегда рядом с вами.",
    ["只要相信，一定可以。"] = "Если вы верите, это обязательно произойдет.",
    ["叫我出来做什么？你终于对《机械制造技术基础》感兴趣了吗？"] = "Для чего ты хочешь меня? Вас наконец заинтересовали «Основы технологии механического производства»?",
    ["可不仅仅是场地，他也庇护着这里。"] = "И дело не только в помещении: он к тому же защищает это место.",
    ["可不是吗？然后长大的年轻人们带着自己的伴侣，自己的孩子又来到我的面包房。"] = "Не так ли? А потом подросшая молодежь приводит своих партнеров, и их дети снова приходят в мою пекарню.",
    ["可不止如此，{{先生|女士}}。拜亚姆可是以香料、妓院、赌场闻名于海。赌博这东西一旦碰了，就很难再脱身了。"] = "Это нечто большее, {{ Mr. | Ms. } }. Баям известен за морем своими специями, борделями и казино. Если однажды вы ввязались в азартные игры, то выйти из них будет очень сложно.",
    ["可以给我果子吗？"] = "Можете ли вы дать мне немного фруктов?",
    ["可以给我点提示吗？"] = "Можете ли вы дать мне несколько советов?",
    ["可以让我的劳拉一起进去用餐吗？"] = "Могу ли я позволить моей Лоре прийти пообедать со мной?",
    ["可以试试柠檬蛋糕和小松饼，我想你会爱上它们的，只要你喜欢甜点。"] = "Вы можете попробовать лимонный пирог и маленькие кексы; Думаю, вы в них влюбитесь, если любите десерты.",
    ["可以，你说说看，是什么故事。"] = "Ладно, расскажи мне, что за история?",
    ["可你不仅赚不到钱，还要每月给他上缴。"] = "Но вы не только не сможете заработать, вам еще и придется платить ему каждый месяц.",
    ["可你看见门口那些干蝙蝠了吗？还有那一罐罐奇怪的粉末……"] = "Но вы видели этих сушеных летучих мышей у двери? И эти баночки со странными порошками...",
    ["可你看起来很累。"] = "Но ты выглядишь очень усталым.",
    ["可别告诉别人，来自南大陆的纯正木乃伊粉，足以让腰都直不起来的老家伙们……"] = "Никому не говорите, но этого чистого порошка мумии с Южного континента достаточно, чтобы сделать стариков, которые даже стоять прямо не могут...",
    ["可怜的劳维斯，一夜之间头发全白了，不知道他现在这个状态，还能撑多久……"] = "Бедный Ловис, поседел за одну ночь. Даже не знаю, долго ли он еще протянет в таком состоянии...",
    ["可怜的孩子。"] = "Бедный ребенок.",
    ["可怜的小珍妮，每天都攥着这个火柴盒。可工厂拖欠工资太久，我们连填肚子都困难，更何况买火柴……"] = "Бедная малютка Дженни, каждый день сжимала в кулачке этот спичечный коробок... Но на фабрике так долго задерживают жалованье, что нам едва хватает на еду, какие уж тут спички...",
    ["可恶，你，你们给我等着！"] = "Черт побери, вы все подождите!",
    ["可惜今天被别人先搜过一遍了！"] = "Жаль, что кто-то другой уже просмотрел это сегодня!",
    ["可惜她妈妈患了肺病，我们掏空了家产治疗，也还是没能治好，唉……"] = "Жаль только, её мать заболела чахоткой... Мы потратили всё наше состояние на докторов, но так и не смогли её спасти, ох...",
    ["可惜，他去贝克兰德念大学被弗萨克的杂种们炸死了，不然还能介绍你们认识。"] = "Жаль, что его взорвали ублюдки Фейнапоттера, когда он уезжал в Бэкланд поступать в университет, иначе я мог бы вас познакомить.",
    ["可我只能在这里帮伯特鼓掌……"] = "Но я могу только помочь Берту аплодировать здесь...",
    ["可我听说这很难找到。"] = "Но я слышал, что их трудно найти.",
    ["可我的花不一样！它们是自然的馈赠，是女神赐予的美丽！您不能把它们和人造花相提并论！"] = "Но мои цветы совсем другие! Они — дар природы, красота, дарованная Богиней! Нельзя сравнивать их с искусственными цветами!",
    ["可是……{{PlayerName}}，这毕竟是一件有风险的事。"] = "Но... {{PlayerName}}, в конце концов, это рискованное дело.",
    ["可是……哪里是北，哪里是东呢？我再研究一下吧。"] = "Но... где север, а где восток? Я изучу это еще немного.",
    ["可是……已经过去一年了，也许小巴特早已忘了，或者他已经……"] = "Но... прошел год, может быть, маленький Барт давно забыл, или уже...",
    ["可是你明明告诉我你是<P_Yellow>被困在塔罗牌里</>的，怎么回事？"] = "Но вы ясно сказали мне, что вы <P_Yellow> в ловушке карт Таро </>. Что случилось?",
    ["可是我一天到晚都见不到他……"] = "Но я не могу видеть его целый день...",
    ["可是我一点也不快乐，这种一眼望到头的日子太无趣了。"] = "Но я совсем не рад. Такая жизнь, в которой конец виден с первого взгляда, слишком скучна.",
    ["可是我怎么面对她……我出海整整十年，被海盗弄瞎一只眼。等赚够了金镑，回来却发现我的爱人身患重病……我不敢告诉小莉迪，她的妈妈已经……"] = "Но как мне противостоять ей... Я ходил в море целых десять лет и пираты ослепили меня. Когда я заработал достаточно золотых фунтов и вернулся, я обнаружил, что мой возлюбленный серьезно болен... Я не осмелился сказать маленькой Лидди, что ее мать уже сказала...",
    ["可是探索队为什么要考历史？"] = "Но почему исследовательская группа сдала тест по истории?",
    ["可是昨天早上我醒来时，珍妮已经不见了。等再找到她时，她已经……"] = "Но когда я проснулся вчера утром, Дженни уже не было. А когда ее наконец нашли, она уже...",
    ["可是，我真的需要这份工作吗……"] = "Но нужна ли мне эта работа...",
    ["可是，要怎样……"] = "Но как...",
    ["可珠宝的价值在于原料"] = "Но ценность украшения — в самом сырье",
    ["可能是因为这里阳光太好、书的味道很香，还有安洁莉卡泡的咖啡比别处好喝吧。"] = "Возможно, это потому, что солнечный свет здесь такой приятный, книги чудесно пахнут, а кофе, который варит Анжелика, вкуснее, чем где-либо еще.",
    ["可能都是。"] = "Может быть, это все из них.",
    ["可这也太……"] = "Но это слишком...",
    ["可这是末场啊！您不知道，末场的演出有多么激动人心，扮演格尔曼的演员会在场中引领观众……"] = "Но это финальное шоу! Вы не представляете, насколько захватывающим будет финальное шоу. Актер, играющий Германа, будет вести за собой зрителей...",
    ["可这肉根本不能吃了吧？"] = "Но это мясо больше нельзя есть, верно?",
    ["可，可是，殿下能带我离开……殿下能让我的头不痛……"] = "Н-но Ваше Высочество может забрать меня отсюда... Ваше Высочество может избавить меня от головной боли...",
    ["各位！新朋友帮我们解决了难题，我们可以回王国过生日了！"] = "Каждый! Наш новый друг решил за нас проблему, и мы можем вернуться в королевство, чтобы отпраздновать день рождения!",
    ["各位，这是我们的新朋友，今天救了我们。新朋友有问题要问，大家配合一下。"] = "Ребята, это наш новый друг, который нас сегодня спас. У нашего нового друга есть вопросы, пожалуйста, сотрудничайте.",
    ["各种事情都可以吗？"] = "Для всяких вещей?",
    ["合上"] = "Закрой это",
    ["合起"] = "Закрывать",
    ["吉尔达失忆了"] = "У Джильды амнезия",
    ["吉瑞尔，你终于回来了！都多久了？"] = "Гирель, ты наконец вернулся! Сколько времени прошло?",
    ["吉瑞尔，得赶紧处理阿尔伯特身上邪异的气息！"] = "Гирель, мы должны немедленно разобраться со злой энергией Альберта!",
    ["吉瑞尔，阿尔伯特看起来是在准备……"] = "Гирель, Альберт, кажется, готовится...",
    ["同样的方式，也可以实现角色的退场，我就不展示了。"] = "Тот же метод можно использовать и для выхода персонажа, поэтому я не буду это демонстрировать.",
    ["同样的话别让我重复第二遍，重复同样的话是一件没用的事，我最讨厌这种没用的行为，没用，没用。"] = "Не заставляй меня повторять одно и то же дважды. Повторять одно и то же – бесполезное действие. Больше всего я ненавижу такое бесполезное поведение. Бесполезно, бесполезно.",
    ["名字……不知道……"] = "Имя... Я не знаю...",
    ["名字是奥利维亚，经营着这个小摊和对面那家没生意的餐厅。"] = "Меня зовут Оливия. Я заправляю этой лавкой и тем рестораном напротив, в котором совсем нет посетителей.",
    ["名字？流浪久了……我连自己的名字都忘了。"] = "Имя? Я так долго бродил... Даже имя свое забыл.",
    ["后天，后天史丹尼喊我去钓鱼！我们打了赌谁钓得少谁请客吃饭！"] = "Послезавтра Стэнни зовёт меня на рыбалку! Спорим, кто меньше поймает, тот угостит другого!",
    ["后来……"] = "Позже...",
    ["后来我才明白，他没什么好怕的，他只是用自己的方式在照顾我们。"] = "Только потом я понял, что в нем нет ничего страшного. Он просто заботился о нас по-своему.",
    ["后续编辑器也会不断迭代和更新，而现在，我们要去吃饭了。"] = "Редактор будет продолжать дорабатываться и обновляться в будущем, а пока мы будем есть.",
    ["后置氛围：占卜俱乐部新来了一位很灵的占卜师，神似曾经的【黛丝】小姐。"] = "Пост-атмосфера: в Клуб гадания прибыла новая, очень точная прорицательница, поразительно похожая на бывшую мисс Дейзи.",
    ["后置氛围：廷根报纸刊登一则新闻【近日，警方在廷根市郊的一处公寓内，发现一名不明原因身亡的年轻女子。经查，死者名为黛丝，早在半年前便已作为已故市民记录于廷根市档案。鉴于存在“死者曾死而复生”的复杂情节，案件真相目前仍在深入调查中。 】"] = "Пост-атмосфера: Газета Тинген опубликовала новость: [Недавно полиция обнаружила молодую женщину, умершую по неизвестным причинам, в квартире на окраине Тингена. По данным следствия, погибшую назвали Дейзи, которая полгода назад была записана в архиве Тингена как умершая гражданка. Учитывая сложные обстоятельства «умершего, вернувшегося из мертвых», истина этого дела все еще находится на стадии тщательного расследования.]",
    ["后面也就是发生了一起警察和罪犯的冲突嘛！"] = "Это был всего лишь конфликт между полицией и преступниками, произошедший позже!",
    ["向它讲述笔记疑案"] = "Расскажи о чехле для ноутбука",
    ["向居民问问情况"] = "Расспросите жителей о ситуации",
    ["向您的学习精神看齐！"] = "Я буду следовать вашему духу обучения!",
    ["向神明祈祷、求助学派可以解决你的一部分困难，但不要怠于提升自身实力。"] = "Молитвы богам и обращение за помощью в школу могут решить некоторые ваши трудности, но не ленитесь совершенствовать собственные силы.",
    ["吟唱"] = "Пойте",
    ["听不懂你在说什么，不过这只是一个空盒子，请带走它吧。对了，关于酬劳，我打算记在弗莱队长的账上，嘿嘿。"] = "Я не понимаю, о чем вы говорите, но это всего лишь пустая коробка. Пожалуйста, заберите это. Кстати, что касается оплаты, я планирую отнести ее на счет капитана Фрая, хе-хе.",
    ["听听蒙特利的回忆"] = "Послушайте воспоминания Монтерея",
    ["听听里面的声音！不妙！很不妙！"] = "Слушайте звуки внутри! Это плохо! Очень плохо!",
    ["听您的吩咐，警官。"] = "Как прикажете, офицер.",
    ["听我继续说，她还有一个卧病在床的母亲，现在药钱也很贵，济贫院也排不上号。"] = "Послушайте меня, продолжайте, у нее тоже есть мать, которая прикована к постели, лекарства сейчас очень дорогие, а работного дома даже нет.",
    ["听着怪怪的，但是感觉很有道理。"] = "Звучит странно, но кажется вполне разумным.",
    ["听着让人难过……"] = "Это звучит грустно...",
    ["听着，风暴之主的唱诗班可不是过家家！在大海上，歌声就是水手们的武器。"] = "Послушайте, хор Повелителя Бурь – это не детская игра! В открытом море пение — оружие моряков.",
    ["听说他们感情不和？"] = "Слышали, будто они не ладят между собой?",
    ["听说你在这里混得不错？"] = "Я слышал, у тебя здесь все хорошо?",
    ["听说哈罗德百货又出新款了。"] = "Я слышал, что в универмаге «Гарольд» снова появились новые поступления.",
    ["听说她去了因蒂斯和费内波特学习甜品制作，直到之前那场战争，才回到鲁恩。"] = "Я слышал, что она отправилась в Интис и Фейнапот, чтобы научиться готовить десерты, и вернулась в Лоен только до той войны.",
    ["听说您是位作家？"] = "Я слышал, ты писатель?",
    ["听说有位伟大的生物学家曾经把小麦和牛杂交，这是一次巨大的物种基因进化！我一直很好奇为什么到处都找不到相关的文献？"] = "Я слышал, как один великий биолог однажды скрестил пшеницу с говяжьим рубцом; это была масштабная генетическая эволюция видов! Мне всегда было интересно, почему я нигде не могу найти соответствующую литературу?",
    ["听说枪声响后，他的邻居立刻就赶到了现场，菲利普的确是开枪自杀的。"] = "Я слышал, что после выстрела на место сразу прибыл его сосед; Филип действительно покончил жизнь самоубийством, застрелившись.",
    ["听说没，隔壁老瑞恩买了一辆脚踏车，用起来比马车方便多了。"] = "Слыхали? Старина Райан по соседству купил велосипед, говорит, куда удобнее экипажа.",
    ["听说老板你这里消息很灵通。"] = "Я слышал, вы очень хорошо информированы, босс.",
    ["听说能欣赏雏菊香味的，都是富有同情心的人。"] = "Говорят, лишь люди с чутким сердцем способны по-настоящему оценить аромат маргариток.",
    ["听说钢铁厂在招人呢？"] = "Я слышал, сталелитейный завод нанимает сотрудников?",
    ["听起来……是一些属于孩子的东西。"] = "Звучит как... вещи, принадлежащие детям.",
    ["听起来不错。"] = "Звучит отлично.",
    ["听起来不错，我再看看。"] = "Звучит хорошо, я посмотрю.",
    ["听起来他确实是位不错的实业家。"] = "Он определенно производит впечатление прекрасного промышленника.",
    ["听起来像是策划想偷懒，不想再做一遍了。"] = "Звучит так, будто геймдизайнер решил схалявить и не делать это заново.",
    ["听起来十分虔诚"] = "Звучит очень благочестиво",
    ["听起来多奇怪，阁下，大量的针刺入皮肤就能缓解腰痛，这是什么道理！"] = "Это звучит так странно, сэр. Большое количество игл, введенных в кожу, может облегчить боль в пояснице – что это за логика!",
    ["听起来很不错。"] = "Звучит великолепно.",
    ["听起来很厉害，也很危险。"] = "Это звучит впечатляюще, но в то же время очень опасно.",
    ["听起来没有危害性，好温柔的封印物，不愧是我。"] = "Звучит безобидно. Какой нежный Запечатанный Артефакт; как и ожидалось от меня.",
    ["听起来真好。"] = "Это звучит очень хорошо.",
    ["听起来近乎偏执"] = "Звучит на грани паранойи",
    ["听起来还不错。"] = "Звучит неплохо.",
    ["听起来都是很好的人，真想见见他们呀……"] = "Все они кажутся хорошими людьми. Я очень хочу с ними познакомиться...",
    ["启示、征兆、不可言说的秘辛，你终会了解的命运。"] = "Откровения, предзнаменования и невыразимые тайны — со временем вы поймете судьбу, которая вас ждет.",
    ["呀……他们都是流浪儿？挺不容易的。"] = "Ох... они все бездомные дети? Это непросто.",
    ["呀我状态精神好挺的。"] = "Мое психическое состояние вполне хорошее.",
    ["呀！你们把队长吵醒了，明明打算给他一个惊喜的！"] = "Привет! Вы разбудили капитана! Мы должны были сделать ему сюрприз!",
    ["呀，实在不凑巧，周二《伯爵归来》复排，我花好大力气才买的票。"] = "Ох, какое совпадение, повтор «Возвращение графа» во вторник, а я потратила столько сил, чтобы купить билет.",
    ["呃……"] = "Эм-м-м...",
    ["呃……去年毕业的学生搬家时带不走的，我是在打包箱子里发现的。丢掉多浪费啊，你说是吧。"] = "Э-э... Студенты, окончившие школу в прошлом году, не смогли взять его с собой, когда переезжали. Я нашел его в упаковочной коробке. Какая трата выбрасывать, вам не кажется?",
    ["呃……头好痛……斯卡纳呢？"] = "Ох... голова раскалывается... Где Скана?",
    ["呃……我是文职人员。"] = "Э-э... Я гражданский служащий.",
    ["呃……所以才是稀缺货，这可是我费了大功夫收来的！只要5镑，你很难找到更便宜的价格了。"] = "Э-э... вот почему они редкие товары. Я потратил много усилий, чтобы собрать их! Всего за 5 фунтов вам будет сложно найти более дешевую цену.",
    ["呃……没有，那里很平静，路人平安无事，孩子在玩扮演摊主的游戏。"] = "Э... нет, там очень спокойно. Прохожие целы и невредимы, а дети играют в игру, изображая из себя лавочников.",
    ["呃……确实是鱼？"] = "Э-э... это действительно рыба?",
    ["呃……这场聚会还会有谁来吗？"] = "Э... кто-нибудь еще придет на эту вечеринку?",
    ["呃……这就……"] = "Э-э... это...",
    ["呃，不好意思，如果你要找陪练，还是去问问索多玛吧，或者像我一样找个木桩。"] = "Э-э, извини, если ты ищешь спарринг-партнера, тебе следует спросить Содома или найти деревянный манекен, как это сделал я.",
    ["呃，好、好的。伦纳德先生和弗莱队长都帮过我，我会帮忙的。"] = "Э, о-окей. Мистер Леонард и капитан Фрай оба помогли мне, так что я помогу.",
    ["呃，怎么说呢，比起仰望绯月，更感觉像死不瞑目……"] = "Э-э, как бы сказать... Вместо благоговейного взора на алую луну это скорее похоже на взгляд человека, умершего с незакрытыми глазами...",
    ["呃，您好，转人工？"] = "Привет, могу я поговорить с человеком?",
    ["呃，没有。"] = "Э-э, нет.",
    ["呃，没有，艾米丽小姐。我平时……嗯，没什么机会玩这种游戏。"] = "Э-э, нет, мисс Эмили. Обычно я... ну, у меня не так уж много шансов поиграть в такую ​​игру.",
    ["呃，没有，还在尝试……人总要有梦想的，不然和咸鱼有什么区别。"] = "Э-э, нет, все еще пытаюсь... Мечты всегда должны быть у людей, иначе какая разница между ними и соленой рыбкой.",
    ["呃，虽然他已经成为了净化之泉的信徒……"] = "Э-э, хотя он уже стал верующим в Фонтан Очищения...",
    ["呃，这位先生，我愿意听听你的“伟大见解”。"] = "Э-э, сэр, я готов выслушать ваше «великое прозрение».",
    ["呆头鹅？"] = "Глупый гусь?",
    ["告知墓园的经历"] = "Расскажите о своем опыте на кладбище.",
    ["告知波特的困难"] = "Рассказать о трудностях Поттера",
    ["告示牌？您是说那块连字都看不清的铁疙瘩？"] = "Табличка? Вы про ту железку, на которой и букв-то не разобрать?",
    ["告诉他愚者的尊名"] = "Назови ему почетное имя Шут.",
    ["告诉我……告诉我！无所不知的神灵，隐匿的贤者，把一切都告诉我！"] = "Скажи мне... скажи мне! Всеведущий Бог, Скрытый Мудрец, расскажи мне всё!",
    ["告诉我，{{先生|女士}}，你也看到它了，到处杀人的鬼魂！"] = "Скажи мне, {{Mr.|Ms.}}, ты тоже это видел, да? Призрак, который убивает повсюду!",
    ["告诉玛莎真相"] = "Скажи Марте правду",
    ["告诉真相"] = "Скажи правду",
    ["告诉艾登自己的故事"] = "Рассказать Эйдену свою историю",
    ["呜……"] = "Ууу...",
    ["呜……呜……"] = "Ууу... ууу...",
    ["呜啊啊啊啊啊！"] = "Вааааа!",
    ["呜汪！"] = "Гав!",
    ["呵,那你也可以跟我们回警局确认一下。并且，你这样驱赶好心的客人，我这位朋友可是会伤心的。"] = "Хех, тогда ты можешь вернуться с нами в полицейский участок, чтобы убедиться в этом. Кроме того, моему другу будет очень грустно, если вы вот так прогоните гостя из лучших побуждений.",
    ["呵呵……什么都可以，我只想要一个未来的指引。"] = "Хе-хе... все в порядке. Мне просто нужен путеводитель на будущее.",
    ["呵呵……只不过他们现在都变成了封印物。"] = "Хе-хе... просто теперь они все стали запечатанными артефактами.",
    ["呵呵……如果对这款药剂好奇，我建议你直接去休息室找阿曼达女士要一杯伏特加。不过，它的味道大概要比伏特加好上那么一点……"] = "Хе-хе... Если вам интересно это зелье, предлагаю вам пойти прямо в гостиную и попросить у мисс Аманды стакан водки. Однако вкус у нее, наверное, немного лучше, чем у водки...",
    ["呵呵……等你沦落到我这个地步就明白了。"] = "Хех... ты поймешь, когда опустишься до моего уровня.",
    ["呵呵，不必紧张，只是一次友好的切磋。在你做好充分的心理准备前，我不会强人所难。"] = "Хе-хе, не надо нервничать, это всего лишь товарищеский спарринг. Я не буду вас заставлять, пока вы не будете полностью морально готовы.",
    ["呵呵，你会喜欢他们的。"] = "Хе-хе, они тебе понравятся.",
    ["呵呵，你再仔细想想……我怎么会是那个妄想愚弄命运的蠢女人？"] = "Хех, подумай хорошенько... как я могла быть той глупой женщиной, которая обманывает себя, обманывая судьбу?",
    ["呵呵，你可真不会安慰人呢。真正的绅士，现在应该将我揽进怀中，再说些甜蜜的情话。"] = "Хе-хе, ты действительно не умеешь утешать людей. Настоящий джентльмен должен сейчас обнять меня и сказать несколько ласковых слов.",
    ["呵呵，你还是这么亲切，希望之前的案子没有给你们带来太多困扰。"] = "Хе-хе, ты по-прежнему такой же добрый, как и всегда. Надеюсь, предыдущий случай не доставил вам особых хлопот.",
    ["呵呵，别这么瞧我，就算住在墓地边，日子也是要过的。"] = "Хе-хе, не смотри на меня так; даже если ты живешь рядом с кладбищем, жизнь все равно должна продолжаться.",
    ["呵呵，如果你临时缺钱，可以来找我。"] = "Хе-хе, если у тебя мало денег, ты можешь прийти ко мне.",
    ["呵呵，小戴莉，有些话，是需要尽快说出口的。"] = "Хе-хе, малыш Дейли, кое-что нужно сказать как можно скорее.",
    ["呵呵，尽快消化魔药，提升实力吧，那样你才能与必将到来的沉重命运抗衡。"] = "Хех, переваривай свое зелье как можно скорее и улучшай свою силу. Только тогда вы сможете справиться с тяжелой судьбой, которая вас ждет.",
    ["呵呵，您最好比较灵验……否则，忽视命运的代价，您纤细的——<P_Heart>（举起手比划了两下）</>想必无法承受。"] = "Хех, тебе лучше быть точным... иначе цена игнорирования судьбы, твоя стройная — <P_Heart> (подняла руку и дважды махнула рукой) </>, видимо, не вынесет этого.",
    ["呵呵，我们看起来很般配，对吗？"] = "Хе-хе, мы выглядим идеальной парой, не так ли?",
    ["呵呵，我开玩笑的。学派里严肃的人太多了，我想偶尔也需要调节一下气氛。"] = "Хе-хе, я шучу. В школе слишком много серьезных людей, я думаю, иногда нужно подкорректировать атмосферу.",
    ["呵呵，我想你现在这个样子，会让他更加歉疚、并留下新的心理阴影。"] = "Хе-хе, я думаю, то, как ты себя чувствуешь сейчас, только заставит его чувствовать себя еще более виноватым и оставит ему новую психологическую травму.",
    ["呵呵，我能够理解。不过好奇心总是伴随着一定的危险。"] = "Хе-хе, я могу это понять. Однако любопытство всегда сопровождается определенными опасностями.",
    ["呵呵，活到老，学到老——罗塞尔大帝说的嘛！"] = "Хе-хе, живи и учись — вот что сказал император Розель!",
    ["呵呵，说实在的，我觉得有不少“学徒”会冲着旅行的目的追求晋升。嗯，享受人生才是生活的真谛嘛。"] = "Хе-хе, честно говоря, я думаю, что немало «учеников» стремятся к развитию ради путешествий. Хм, в конце концов, наслаждение жизнью — это и есть истинный смысл жизни.",
    ["呵呵，这两个人关系真不错。年轻真好，对吧邓恩？"] = "Хех, эти двое очень хорошо ладят. Хорошо быть молодым, не так ли, Данн?",
    ["呵呵，这个声音可就不那么好听了。"] = "Хе-хе, этот звук не такой приятный.",
    ["呵，你们明白的，这件事也只能由我去做。"] = "Хех, знаешь, это могу сделать только я.",
    ["呵，卡萝队长，你真的睡了很久呢。"] = "Хех, капитан Кэрол, вы действительно давно спали.",
    ["呵，我家的黛比可是耕过十年地的，耐力没得说。"] = "Хех, моя Дебби уже десять лет пашет поля; ее выносливость вне всякого сравнения.",
    ["呸呸……你加了什么，好难喝，怎么有股子土腥味？"] = "Птуи... что ты к этому добавил? Это ужасно, почему на вкус как мокрая грязь?",
    ["呸呸呸——哈哈，比我还倒霉的倒霉蛋！"] = "Птуи, птуи, птуи — ха-ха, неудачник еще более неудачливый, чем я!",
    ["呼——呼——"] = "Ху-ху-",
    ["呼——好诡异的梦。"] = "Уф, какой странный сон.",
    ["呼——终于结束了！非常感谢你的帮忙，{{PlayerName}}。"] = "Уф, наконец-то закончил! Большое спасибо за помощь, {{PlayerName}}.",
    ["呼……多亏了你。看来一次性摘太多果子是个错误决定。"] = "Фух... спасибо тебе. Похоже, собирать столько фруктов за один раз было ошибкой.",
    ["呼……看来，这位焦急的父亲并没有他说的那样爱孩子。"] = "Эх... Кажется, этот встревоженный отец не любит своего ребенка так сильно, как он утверждал.",
    ["呼吸和心跳是活着的象征，也许有别的东西能成为一个人的“呼吸”和“心跳”……"] = "Дыхание и сердцебиение — символы жизни; возможно, есть и другие вещи, которые могут стать «дыханием» и «биением сердца» человека...",
    ["呼吸和心跳是活着的象征，但有更珍贵的东西能成为一个人的“呼吸”和“心跳”。"] = "Дыхание и сердцебиение являются символами жизни, но есть более ценные вещи, которые могут стать «дыханием» и «биением сердца» человека.",
    ["呼噜噜——"] = "Мурлыканье—",
    ["呼，原来不是西尼。"] = "Уф, это был не Чини.",
    ["呼，吓我一跳！"] = "Фух, ты меня напугал!",
    ["呼，好困……怎么回事？"] = "Уф, так хочется спать... Что происходит?",
    ["命运会给您一笔财富，并指引您后续的行动。"] = "Судьба подарит вам состояние и направит ваши дальнейшие действия.",
    ["命运确实无常。"] = "Судьба действительно непредсказуема.",
    ["命运给予了你崎岖的道路，但不必恐惧未来，“愚者”会注视着你。"] = "Судьба подарила вам тернистый путь, но не бойтесь будущего; «Шут» будет присматривать за тобой.",
    ["和之前一样？试试新品，比如芋圆波波？"] = "То же, что и раньше? Почему бы не попробовать что-то новое, например боба с мячом таро?",
    ["和之前一样？还是试试新品，比如芋圆波波？"] = "Как обычно? Или попробуешь новинку, например, чай с шариками таро?",
    ["和吉瑞尔一路跑到了风车附近。"] = "Пробежали весь путь до ветряной мельницы с Джирель.",
    ["和死人住在一起没什么不好。某种程度上来说，死人可比活人省心多了！"] = "Нет ничего плохого в том, чтобы жить с мертвыми. В каком-то смысле мертвые доставляют гораздо меньше хлопот, чем живые!",
    ["和波特一起返回了塔罗学派。"] = "Вернулся в Клуб Таро с Поттером.",
    ["和莱昂说明了自己的想法，随后在道格的墓碑前忙碌起来。"] = "Вы объяснили свои мысли Леону, а затем начали усердно работать перед надгробием Дуга.",
    ["咕、咕、咕！"] = "Коу, ку, ку!",
    ["咕咕咕咕咕咕咕咕咕咕咕咕——"] = "Ку-ку-ку-ку-ку-ку-ку-ку-ку-ку-ку-ку-ку-ку-ку-ку-ку-ку-ку-ку-ку-ку-ку-ку-ку.",
    ["咕咕咕咕咕咕！"] = "Курлы-курлы-курлы!",
    ["咕咕！"] = "Коу!",
    ["咕噜咕噜……"] = "Гулу гулу...",
    ["咕噜咕噜……<P_Heart>（看起来挺温顺的。）</>"] = "Гулу гулу... <P_Heart> (Выглядит довольно послушно.) </>",
    ["咕！"] = "Коу!",
    ["咦……不对，兰格你认识他们吗？"] = "Ха... подожди, Ланге, ты их знаешь?",
    ["咦，你好聪明，怎么这也能猜到？她还有个弟弟在上学，唉，一家四口重担都在她身上。"] = "Эх, ты такой умный, как ты это догадался? У нее есть младший брат, который учится в школе, вздох, все бремя семьи из четырех человек лежит на ней.",
    ["咦，你知道他们的模样？但你们应该从来没有见过面吧？"] = "Э, ты знаешь, как они выглядят? Но вам не следовало встречаться, верно?",
    ["咦，你知道我的名字，邓恩叔叔他们跟你提起过我吗？"] = "Эй, ты знаешь мое имя, дядя Данн, они когда-нибудь упоминали обо мне?",
    ["咦，刚才数到多少了？不管了，从三百再开始吧……"] = "Ой, на каком числе я сбился? Ладно, начну опять с трехсот...",
    ["咦，这个孩子是谁？"] = "Эй, кто этот ребенок?",
    ["咦？你能看到我，人类能看到我？"] = "Э? Ты меня видишь? Люди могут меня видеть?",
    ["咦？安静了……"] = "Э? Тихо...",
    ["咪呜咪呜……"] = "Мяу-мяу...",
    ["咱们也去买一辆？可是，哪来的钱啊。"] = "Может, и нам купить такую? Но откуда взять столько денег...",
    ["咱们这儿就这样，骗子不少，小偷也不少。不过，我还是喜欢这地方。"] = "У нас такие дела, много мошенников и много воров. Но мне все равно нравится это место.",
    ["咱们这把年纪，得学会对自己好一点。别总想着逞强，健康才是最重要的，明白吗？"] = "В нашем возрасте нам нужно научиться быть добрыми к себе. Не пытайся всегда быть жестким, здоровье – это самое главное, понимаешь?",
    ["咳咳……天哪，你想什么呢？我才、才没有想这么诡异的事情呢！"] = "Кашель, кашель... Боже, о чем ты думаешь? Я, я точно не думаю о таких странных вещах!",
    ["咳咳……您说得对！其实这只是……只是南大陆的安神草药。"] = "Кхм... ты прав! На самом деле, это просто... успокаивающие травы с Южного континента.",
    ["咳咳……拉里，实话说，你加入代罚者之前头顶也并不茂盛，或许这并不是非凡因素导致的。"] = "Кхм... Ларри, если честно, до того, как ты присоединился к Назначенным Карателям, твоя голова была не очень пышной. Возможно, это не вызвано факторами Потустороннего.",
    ["咳咳……这太危险了！"] = "Кхм-кхм... Это слишком опасно!",
    ["咳咳咳！好刺鼻的味道……水！水！"] = "Кхе-кхе-кхе! Такой острый вкус... Вода! Вода!",
    ["咳咳咳，你就是黑荆棘新来的员工吗？"] = "Кашель, кашель, кашель, ты новый сотрудник в Чёрный Чертополох?",
    ["咳咳，今天这锅炉怎么这么呛！"] = "Кхе-кхе, почему этот котел сегодня такой дымный!",
    ["咳咳，嗯……有什么需要配合的可以和我说。"] = "Кхе-кхе, эм... ты можешь сказать мне, есть ли что-то, с чем тебе нужно сотрудничать.",
    ["咳咳，您就是新来的警官！可真年轻呀，年轻有为！"] = "Кхм-кхм, так вы и есть новый офицер полиции! Какой молодой, молодой да ранний!",
    ["咳咳，我们是警察，来这里调查一起案件，请配合一下。"] = "Кхм, мы полицейские, пришли расследовать дело. Пожалуйста, сотрудничайте.",
    ["咳咳，行了，我假装听不见，你先站起来，咱们别较量了！"] = "Кхе-кхе, ладно, я сделаю вид, что не слышал, ты первый встань, давай перестанем соревноваться!",
    ["咳咳，邓恩、戴莉，辛苦你们了。"] = "Кхе-кхе, Данн, Дейли, спасибо вам за вашу тяжелую работу.",
    ["咳！这你就不懂了吧！去去去！别打扰我做生意！"] = "Кхм! Вот тут ты ошибаешься! Давай, давай! Не мешайте моим делам!",
    ["咳，我们走吧。"] = "Эм, поехали.",
    ["咳，我瞎起的名字。不过他们都称自己是什么“流浪王国”还是“帽子帮”的成员。"] = "Кхм, это я сам придумал. Но сами они зовут себя жителями какого-то «Королевства бродяг» или бандой «Шляпников».",
    ["咿呀！可怕、好可怕的人类！"] = "Ой-ой! Страшный, какой страшный человек!",
    ["哇哇哇！你抓到我了吗？"] = "Вау вау вау! Ты меня поймал?",
    ["哇啊！啊啊啊啊——对不起，阿罗德斯大人！我没有为难您，哦不，拿这种小问题打扰您的意思！"] = "Вааа! Аааааа, простите, лорд Арродес! Я не хотел вас усложнять, о нет, я не хотел беспокоить вас такими тривиальными вопросами!",
    ["哇！那我要像他们那样优雅地坐着，小口小口地吃着面包。"] = "Ух ты! Тогда я хочу сидеть элегантно, как они, и есть Хлеб небольшими кусочками.",
    ["哇，小戴莉你的发言真是越来越……个性了。"] = "Ух ты, малыш Дейли, твои высказывания становятся все более и более... индивидуалистическими.",
    ["哈哈……"] = "Хаха...",
    ["哈哈……懦夫……你说得对！嗝，我就是……就是个懦夫……无耻的、下贱的、遭人唾弃的懦夫……"] = "Ха-ха... Трус... Ты прав! *ик*, я... Я трус... Бесстыдный, подлый, презираемый трус...",
    ["哈哈……我想拿去市场上卖掉，赚点学费。"] = "Ха-ха... Я хотел отвезти их на рынок, продать и заработать немного за обучение.",
    ["哈哈哈哈！倒霉蛋！大倒霉蛋！"] = "Ха-ха-ха! Неудачник! Большой неудачник!",
    ["哈哈哈哈！倒霉蛋，倒霉蛋，全世界都是倒霉蛋！"] = "Ха-ха-ха! Неудачник, неудачник, весь мир полон неудачников!",
    ["哈哈哈，并没有呢，您可真是个热心的家伙。"] = "Ха-ха-ха, совсем нет. Вы действительно увлеченный человек.",
    ["哈哈哈，您说的是事实，如您所见，我并不擅长打点花园，只是我不想尼尔先生的花园就这么荒废掉。"] = "Ха-ха-ха, то, что ты сказал, это факт. Как видите, я не очень хорошо умею ухаживать за садом, я просто не хочу, чтобы сад мистера Нила был заброшен вот так.",
    ["哈哈对，摊位补货和大单运送都归我们管。西尼他们去盥洗室了，我们刚才在阴凉的地方打牌呢。"] = "Ха-ха, верно! Пополнение прилавков и доставка крупных заказов — это все по нашей части. Сини с ребятами отошли в уборную, а мы пока в тенечке карты раскинули.",
    ["哈哈，不有趣吗？简直像在剧院里看到的情节一样！"] = "Хаха, разве это не интересно? Это прямо как сюжет из театра!",
    ["哈哈，也不用太担心。里面至少还有两位教会内部的看守者，以及数不清的陷阱。"] = "Ха-ха, не стоит слишком беспокоиться. Внутри есть как минимум два внутренних церковных стража, а также бесчисленное количество ловушек.",
    ["哈哈，只是平时多看了一些报纸上的美食栏目罢了。"] = "Ха-ха, я просто стал читать статьи о еде в газетах немного чаще.",
    ["哈哈，后来她为梦想去了贝克兰德，我们只会偶尔通信。"] = "Ха-ха, позже она отправилась в Бэкланд ради своих мечтаний, и мы переписываемся лишь изредка.",
    ["哈哈，小戴莉，一定不要像我一样心存遗憾啊。"] = "Ха-ха, малыш Дейли, ты не должен сожалеть так, как я.",
    ["哈哈，尝起来很棒对吧？我家祖传的秘方，你在因蒂斯都找不到这么香的精酿。"] = "Хаха, отличный вкус, правда? Это секретный рецепт моей семьи; Такого ароматного крафтового напитка вы не найдете больше нигде в Интисе.",
    ["哈哈，感谢你毫不吝啬的夸赞！这都是年轻时学到的道理了，却在年岁大了之后才懂得。"] = "Ха-ха, спасибо за щедрую похвалу! Это принципы, которые я усвоил, когда был молод, но по-настоящему понял их только тогда, когда стал старше.",
    ["哈哈，老邻居们吃习惯了。你再看看，那张菜单可就有点区别了。"] = "Ха-ха, старые соседи к этому привыкли. А ты присмотрись: то меню немного отличается.",
    ["哈哈，这手艺没有什么特殊的……前两天有个作家来取材，问我烘焙的秘方是什么，我说不出什么答案。"] = "Ха-ха, в этой поделке нет ничего особенного... Пару дней назад зашел писатель собирать материал и спросил, в чем секретный рецепт выпечки, а я не смогла дать ответа.",
    ["哈啊？小戴莉，你怎么突然这么老了！"] = "А-а? Малышка Дейли, почему ты вдруг так постарела?!",
    ["哈罗德……"] = "Гарольд...",
    ["哈罗德。"] = "Гарольд.",
    ["哈罗德百货……"] = "универмаг Гарольда...",
    ["哈罗德百货没有开门，为什么还有安保？"] = "Универмаг «Гарольд» закрыт, почему там еще охрана?",
    ["哈！不必艳羡血族的天赋异禀。只要努力，你也可以做到。当然，成品或许比不上专家，但已经足够值得称赞。"] = "Ха! Не нужно завидовать врожденным дарам вампиров. Если вы много работаете, вы тоже можете это сделать. Конечно, готовый продукт может быть не так хорош, как у эксперта, но уже достоин похвалы.",
    ["哈！别一会儿趴着出去。"] = "Ха! Не окажитесь лицом вниз на полу по пути наружу.",
    ["哈！别担心，人肉从一开始就不合我口味。"] = "Ха! Не волнуйтесь, человеческая плоть с самого начала мне никогда не нравилась.",
    ["哈！我要臭晕每一个试图打开我的人！"] = "Ха! Я хочу вонять всех, кто попытается меня открыть!",
    ["哈，你不明白。现在是我的下班路上，再过一刻钟，我就得回去见我夫人。"] = "Ха, ты не понимаешь. Сейчас я еду домой с работы. Еще через четверть часа мне придется вернуться к жене.",
    ["哈，我不要。"] = "Ха, я не хочу.",
    ["哈，这下你就能精神抖擞地开始行动了！"] = "Ха, теперь вы можете начать свое действие в приподнятом настроении!",
    ["哈，那东西的精度我可不敢恭维。"] = "Ха, я бы не осмелился хвалить точность этой штуки.",
    ["哎呀呀，原来是警察先生，我还以为是什么可疑的家伙。"] = "О боже, так это полицейские. Я думал, что вы какие-то подозрительные персонажи.",
    ["哎呀呀，邓恩队长别这么慌乱嘛，再见我不高兴吗？"] = "Ай-ай, капитан Дэн, к чему такая суматоха? Разве вы не рады снова меня видеть?",
    ["哎呀失礼了，你们要调查什么？铁十字街上的事我都知道！"] = "Ой, извини, что ты расследуешь? Я знаю все, что происходит на улице Айрон-Кросс!",
    ["哎呀！你别跟我说话了！我会忍不住搭理你的！"] = "Ой! Перестань со мной разговаривать! Я не смогу вам не ответить!",
    ["哎呀！吓我一跳！……你好？"] = "Ой! Ты меня напугал!...Привет?",
    ["哎呀！杯子是我给内务大臣的生日礼物，我得回去拿！"] = "Ой! Эта чашка — подарок ко дню рождения министра внутренних дел, я должен вернуться и забрать её!",
    ["哎呀，好像完全无法交流呢。"] = "О боже, кажется, общение совершенно невозможно.",
    ["哎呀，就是那个啊，那个绿绿的，香香的……"] = "О, знаешь, эта штука, зеленая, ароматная...",
    ["哎呀，这真是可怕……他刚离开不久、不到十分钟，我跟您一起去找。"] = "О боже, это действительно страшно... Он ушел не так давно, меньше десяти минут. Я пойду с тобой искать его.",
    ["哎呀，都是很久以前的事情了，是我太啰嗦了。"] = "О боже, это все было очень давно; Я слишком многословен.",
    ["哎哟，你又瞎说！哪有诗人是杂活女仆呢？"] = "Ой, ты опять говоришь ерунду! Какой поэт служанка, выполняющая случайную работу?",
    ["哎哟，我这肚子疼得厉害，昨晚那黑面包怕是馊了……你怎么样？"] = "Ой, у меня так болит живот. Боюсь, вчерашний черный хлеб испортился... А ты?",
    ["哎，肯定又是童工受不了折磨跑出来了，要被工头抓回去干活，咱们管不了。"] = "Эх, должно быть, это дети-работники не выдержали мучений и выбежали только для того, чтобы их поймал бригадир и они вернулись на работу. Мы не можем с этим справиться.",
    ["哔哩吧啦柠檬橙汁好了。喔，我敢说这是小孩子的口味。"] = "Лимонно-апельсиновый сок «Били-Бала» готов! Ух, готов поклясться, это чисто детский вкус.",
    ["哟，今天又来提升自己啊？"] = "Эй, ты сегодня снова здесь, чтобы улучшить себя?",
    ["哥哥，你的“下午咖啡”还是留着自己享用吧，我喝下午茶就好。"] = "Брат, тебе лучше оставить свой «послеобеденный кофе» себе. Я просто выпью послеобеденный чай.",
    ["哦{{PlayerName}}，我的小猫头鹰。瞌睡虫已经侵占了我的脑子，你可要独处了。"] = "О, {{PlayerName}}, моя маленькая сова. Сонливость завладела моим мозгом; тебе придется побыть одному.",
    ["哦{{PlayerName}}，我的小猫头鹰，熬夜可不是好习惯——你确定要咖啡么？"] = "О, {{PlayerName}}, моя маленькая сова, ложиться спать допоздна — это не очень хорошая привычка. Ты уверен, что хочешь кофе?",
    ["哦{{PlayerName}}，爱喝甜冰茶的人都很可爱——至少我是这么认为的。"] = "О{{PlayerName}}, люди, которые любят сладкий чай со льдом, все очень милые — по крайней мере, я так думаю.",
    ["哦……"] = "Ой...",
    ["哦……亲爱的真对不起，我、我受到了些惊吓……"] = "Ох... дорогая, прости, я немного испугалась...",
    ["哦……希望这个小家伙放过珍贵的书籍。"] = "Ох... Надеюсь, этот малыш пощадит драгоценные книги.",
    ["哦……赞美罗塞尔大帝，他穿越了狂暴海，发现了那本来只存在于古书里的南大陆。"] = "Ох... хвала императору Розелле. Он пересек Море Берсерка и открыл Южный континент, который изначально существовал только в древних книгах.",
    ["哦……还好是只猫。"] = "Ох... К счастью, это всего лишь кошка.",
    ["哦……这里没有因蒂斯温暖，总是雾蒙蒙的，还常常下雨……需要太阳的眷顾。"] = "Ох... здесь не так тепло, как в Интисе. Всегда туманно и часто идут дожди... ему нужна благосклонность солнца.",
    ["哦……风暴在上……那其实都是我丈夫的意愿。"] = "Ох... Буря наверху... на самом деле это было желание моего мужа.",
    ["哦不……我会尽快控制……"] = "О нет... Я проконтролирую это как можно скорее...",
    ["哦不，那一切很真实，是小黛西一生中最美丽的真实。"] = "О нет, там все очень реально; это самая прекрасная реальность в жизни Маленькой Дейзи.",
    ["哦哦哦——戴着金边眼镜的、黑猫！"] = "Ой-ой-ой — черный кот в очках в золотой оправе!",
    ["哦哦哦哦哦！就这么写，等我写完了我会送你一本的。"] = "О-о-о-о-о! Так и напишу! А как допишу, подарю тебе один экземпляр.",
    ["哦哦，好的！那就拜托你们了。"] = "Ой-ой, ладно! Тогда я оставлю это вам двоим.",
    ["哦太神奇了，那些苦苦的黑色药汁真的治好了我的膝盖疼痛……"] = "О, это потрясающе! Эти горькие черные целебные отвары действительно вылечили мою боль в коленях...",
    ["哦！不要打扰伟大的侦探伊里斯！伟大的伊里斯正在寻找恶劣的毛球恶魔，懦弱的四脚兽，如影随形的逃匿者……"] = "Ой! Не беспокойте великого сыщика Айрис! Великая Ирис ищет злого мехового демона, трусливого четвероногого, неуловимого беглеца...",
    ["哦！我还不习惯这个称呼！"] = "Ой! Я до сих пор не привык к этому названию!",
    ["哦！黑夜协会，女神在上，我向你们祈求寻找我的姐姐，但你们毫无回应。现在却来欺负我，想要抢夺我的花朵！"] = "Ой! Ночная Ассоциация, Высшая Богиня, я молила тебя найти мою сестру, но ты не получила ответа. Теперь ты здесь, чтобы запугать меня и хочешь украсть мои цветы!",
    ["哦，你也需要我的力量吗？没问题，这是我的幸运，我的光荣，我理应背负的责任。"] = "О, тебе тоже нужна моя сила? Нет проблем, это моя удача, моя честь и ответственность, которую я должен нести.",
    ["哦，你回来了，请告诉我你找到了它们。"] = "О, ты вернулся. Скажи мне, что ты нашел их.",
    ["哦，你能想象吗？我甚至能在旅行中遇到酒友！"] = "О, ты представляешь? Я умудрился найти собутыльников прямо во время странствий!",
    ["哦，你说他们啊。"] = "О, ты имеешь в виду их.",
    ["哦，你说的一定是退伍军官俱乐部的贝内特夫人。"] = "О, вы, должно быть, имеете в виду миссис Беннетт из Клуба отставников.",
    ["哦，嗯，我觉得<P_Heart>（嚼嚼嚼）</>，是否有点过于黏糊？"] = "О, хм, я думаю, <P_Heart> (жуй, жуй, жуй) </>, он слишком липкий?",
    ["哦，多谢你的鼓励。我想也是。"] = "О, спасибо за вашу поддержку. Я тоже так думаю.",
    ["哦，尊敬的主人！有什么吩咐？"] = "О, уважаемый Мастер! Какие у вас заказы?",
    ["哦，就是学派“战士”途径的导师。"] = "А, это же наставник пути «Воина» из школы.",
    ["哦，廷根有这么多餐厅，我一定是等错地方了……"] = "Ох, в Тингене так много ресторанов, что я, наверное, ждала не там, где надо...",
    ["哦，我就知道你是有品味的人。"] = "О, я знал, что ты человек со вкусом.",
    ["哦，我当然希望所有的值夜者都长命百岁，愿黑夜女神护佑他们。"] = "О, конечно, я надеюсь, что все Ночные Ястребы проживут долгую и здоровую жизнь. Пусть Богиня Вечной Ночи защитит их.",
    ["哦，我忍不住想做一次尝试了。现在的时尚界缺乏一些勇气。"] = "Ох, не могу не попробовать. Нынешнему миру моды не хватает смелости.",
    ["哦，我忘了，你并不是血族。那这份任务对你来说或许颇具挑战性。"] = "Ой, я забыл, ты не вампир. Тогда этот квест может оказаться для вас довольно сложным.",
    ["哦，我想我该鼓起勇气进去了！"] = "Ох, думаю, мне пора собраться с духом и войти!",
    ["哦，我是老医生，也是老病人，罗塞尔大帝说过，医生无法医治自己。"] = "О, я старый врач и старый пациент. Император Розель однажды сказал, что врач не может исцелить себя.",
    ["哦，我的救星！我是说……很高兴看到你出现在这里！"] = "О, мой спаситель! Я имею в виду... Я очень рад видеть тебя здесь!",
    ["哦，我路过想看看花。你负责送花吗？"] = "Ой, я просто проходил мимо и хотел посмотреть на цветы. Вы несете ответственность за доставку цветов?",
    ["哦，戴安娜，我明天，不，后天，后天一定交稿！"] = "Ой, Диана, рукопись я сдам завтра, нет, послезавтра, обязательно послезавтра!",
    ["哦，抱歉，我不是在和你说话。你似乎并不是我的友人。"] = "Ой, извини, я не с тобой разговаривал. Кажется, ты мне не друг.",
    ["哦，是您！我还以为……"] = "О, это ты! Я думал...",
    ["哦，没错，你真是太懂我了！这会是个划时代的突破！"] = "О, это правда, вы меня очень понимаете! Это было бы эпохальным прорывом!",
    ["哦，真希望这些人永远不要出现在我身边，光是与他们擦肩而过，都担心裙摆上沾上泥泞……我们还是快离开吧。"] = "Ох, я очень надеюсь, что эти люди никогда не появятся рядом со мной. Просто проходя мимо них, я беспокоюсь о том, что юбка испачкается грязью... Давай быстро уйдем.",
    ["哦，等等，原来是流浪猫小分队又私闯民宅了啊。"] = "Ой, подождите, оказывается, отряд бродячих кошек снова ворвался в дом.",
    ["哦，罗塞尔大帝真是个爱折腾的人，听说贝尔纳黛殿下的离开，也是因为不满于父亲的统治。"] = "О, император Розель был поистине беспокойным человеком. Я слышал, что отъезд Ее Высочества Бернадетты произошел еще и потому, что она была недовольна правлением своего отца.",
    ["哦，西尼你回来啦！哈哈哈，没有，你看错了，怎么可能换牌了呢！"] = "О, Чини, ты вернулся! Ха-ха-ха, нет, ты ошибся, как я мог поменять карты!",
    ["哦，说的是你写的小说《灵界小淘气》？我最喜欢淘气鬼惹恼城堡女公爵的那段，它……"] = "О, вы имеете в виду роман «Маленький озорник в духовном мире», который вы написали? Мне больше всего нравится та часть, где озорное привидение раздражает герцогиню Замковую, это...",
    ["哦，请先放在那里就好……"] = "Ох, пожалуйста, просто оставьте их там пока...",
    ["哦，请原谅我略显过剩的关心，毕竟我第一次带你来这里时，你还装了满脑子问号，不知从哪里能获得解答。"] = "Ох, прости мою излишнюю заботу. В конце концов, когда я впервые привел тебя сюда, твоя голова была забита вопросами, и ты понятия не имел(а), где искать ответы.",
    ["哦，请相信我们，这些银针能替您疏通穴位。"] = "О, пожалуйста, доверьтесь нам; эти серебряные иглы помогут вам очистить акупунктурные точки.",
    ["哦，这两位设计师我好像听过啊……设计采风？感觉真是有意思的工作。"] = "О, кажется, я слышал об этих двух дизайнерах... Собираетесь дизайнерское вдохновение? Это звучит как действительно интересная работа.",
    ["哦，这些都是……呃，餐厅里特别挑出来的，种类多，价格还便宜！一磅只要1便士！"] = "Ох, это все... э-э, специально отобранные из ресторана, много сортов, и цена копеечная! Всего 1 пенс за фунт!",
    ["哦，这位{{英俊的先生|美丽的女士}}，如您所见，诗人的灵感是破碎的，您需要将它们连贯起来。您想到的，美好的东西，皆可入诗……"] = "Ох, этот {{handsome gentleman/beautiful lady|}}, как видите, вдохновение поэта разбито, и нужно их соединить. Все прекрасное, о чем вы только можете подумать, можно превратить в поэзию...",
    ["哦，这是我最喜欢的药剂！它会让你整夜连续不断地做梦，在星象房使用效果最佳。"] = "О, это мое любимое зелье! Он заставит вас непрерывно видеть сны всю ночь, и лучше всего он работает, когда используется в астрологическом кабинете.",
    ["哦，这里流行着这样的一首歌……"] = "О, здесь популярна такая песня...",
    ["哦？那根据对等原则，你准备好回答祂的问题了吗？"] = "Ой? Тогда, согласно принципу взаимности, готовы ли вы ответить на Его вопрос?",
    ["哪件事情？"] = "Какой инцидент?",
    ["哪怕在其他人眼中的我们的生活是荒唐的……但至少，我们在一起。"] = "Пусть наша жизнь кажется абсурдной в глазах других... но, по крайней мере, мы вместе.",
    ["哪把呢"] = "Который из?",
    ["哪里有趣了？！"] = "Что в этом интересного?!",
    ["哪里，都是朋友们给面子"] = "Вовсе нет, просто мои друзья дают мне лицо",
    ["哼……那你帮我做一份吧，喝完应该就能想起来了！"] = "Хм... тогда ты поможешь мне приготовить порцию. Я должен быть в состоянии вспомнить все после того, как выпил это!",
    ["哼。"] = "Хм.",
    ["哼，不思进取！"] = "Хм, никакого стремления к развитию!",
    ["哼，他不过是提供了一个交易的场地！"] = "Хм, он всего лишь предоставил место для сделок!",
    ["哼，你那花再好看，能有我这些书本实在？它们可不需要肥料，比某些人的账本还诚实！"] = "Хм, какими бы красивыми ни были твои цветы, разве сравнятся они с полезностью моих книг? Им не нужны удобрения, и они честнее гроссбухов некоторых личностей!",
    ["哼，如果让我发现，一定会温柔地生擒这恶魔，交归它原本该去的圣所，然后，获取我应得的报偿……"] = "Хм, если я найду его, я обязательно аккуратно поймаю этого демона, верну его в святилище, где ему и место, а затем получу заслуженную награду...",
    ["哼，怕什么，恶龙酒吧可是斯维因的地盘，谁敢在这儿找麻烦？"] = "Хм, чего ты боишься? Бар ««Злой Дракон»» — территория Суэйна; кто осмелится устроить здесь неприятности?",
    ["哼，我说过很多次了，我不喜欢公共马车出行……"] = "Хм, я уже много раз говорил, я не люблю ездить в общественном транспорте...",
    ["哼，穿得人模人样！还不如狗忠诚，成天花言巧语，骗那些涉世未深的姑娘。"] = "Хм, одет как приличный человек! А преданности в нём меньше, чем в собаке: целыми днями сыплет сладкими речами да обманывает наивных девиц.",
    ["哼，还不算太笨！"] = "Хм, не так уж и глупо!",
    ["哼，这家的缝制手艺不错，但这设计嘛……"] = "Хм, пошив у них неплохой, но вот фасон...",
    ["唉……"] = "Вздох...",
    ["唉……他要是再这样买衣服退货，一定得把他拉进黑名单了！"] = "Эх... если он продолжит покупать и возвращать такую ​​одежду, мне обязательно придется внести его в черный список!",
    ["唉……小艾恩可爱又聪明，比我家那小子乖巧太多，她在学校里成绩每年都是最优秀的。"] = "Эх... маленькая Айна милая и умная, ведет себя гораздо лучше, чем тот мой ребенок. Ее оценки в школе каждый год самые лучшие.",
    ["唉……算了。"] = "Эх... забудь об этом.",
    ["唉……请先进屋再说吧。"] = "Эх... пожалуйста, сначала зайди внутрь, и мы поговорим.",
    ["唉！还多花钱租了二手的礼服，我愚蠢的哥哥啊！"] = "Вздох! И он потратил лишние деньги на аренду подержанного смокинга, мой глупый брат!",
    ["唉，下次还是得找人同行，迷路对我而言真是一件再正常不过的事了。"] = "Эх, в следующий раз мне действительно стоит найти с кем пойти. Заблудиться для меня – обычное явление.",
    ["唉，不过办事效率确实是需要提升，看那些排队市民抱怨的样子……"] = "Эх, но эффективность действительно нужно повысить. Посмотрите, как жалуются граждане в очереди...",
    ["唉，他们是流浪画家，我上周还看过他们的画展呢……看的人很多，可大家也拿不出多余的钱给他们。"] = "Эх, они были странствующими художниками. Я даже видел их выставку на прошлой неделе... Многие смотрели, но никто не мог выделить на них лишних денег.",
    ["唉，你和赫拉一样，理论基础还有待提高。白讲那么多知识点了！"] = "Эх, ты как Гера, твоя теоретическая база все еще нуждается в улучшении. Все те знания, которыми я поделился, были напрасны!",
    ["唉，你和那四个诗人一样理论水平有待提高。白讲那么多知识点了！"] = "Эх, твой уровень теории хромает прямо как у тех четверых поэтов. Зря я только распинался и втолковывал тебе все эти вещи!",
    ["唉，你并不需要对阿诺德或卡萝承担什么责任……这别扭的性格，你到底什么时候改一改？"] = "Эх, тебе не нужно брать на себя ответственность за Арнольда или Кару... Эту твою неловкую личность, когда именно ты собираешься ее изменить?",
    ["唉，你来帮帮我吧，我在想要不要去赌场呢？"] = "Эх, иди помоги мне, я думаю, стоит ли идти в казино?",
    ["唉，别提了！上次比赛它让我输掉了半个月的酒钱，真想不通它是怎么被选上的。"] = "Эх, не упоминай об этом! Из-за этого я потерял деньги на выпивку за полмесяца на последнем соревновании. Я правда не могу понять, как оно было выбрано.",
    ["唉，如果我也能像导师们一样就好了。我要投放100个自己的历史投影，足不出户环游各大陆。"] = "Эх, если бы я только мог быть таким, как наставники. Я хочу составить 100 исторических проекций себя и объехать все континенты, не выходя из дома.",
    ["唉，工作没了，买到的东西也越来越次。"] = "Эх, работы больше нет, а вещи, которые я покупаю, становятся всё хуже и хуже.",
    ["唉，愿他们在女神的神国获得了宁静。"] = "Вздох, пусть они найдут покой в ​​королевстве Богини.",
    ["唉，我最近在想，或许像斯维因队长那样早点退休，找份安稳的工作，会是更好的选择。"] = "Эх, в последнее время я подумал, что, возможно, лучше уйти на пенсию раньше, чем капитан Суэйн, и найти стабильную работу.",
    ["唉，我还想着观众的好评，总该能把她从自我贬低的漩涡里捞出来一阵子。"] = "Эх, я-то надеялся, что похвала публики хоть ненадолго вытащит ее из омута самоуничижения.",
    ["唉，我还是回教会的培训班再进修一下吧。"] = "Эх, пожалуй, вернусь-ка я на церковные курсы подучиться.",
    ["唉，是也不是。我好像已经习惯了被别人安排好自己的命运了。"] = "Вздох, да и нет. Кажется, я уже привык к тому, что мою судьбу решают другие.",
    ["唉，是最近在大学区流行的传闻。"] = "Эх, это слух, который в последнее время стал популярен в университетском районе.",
    ["唉，有个野生非凡者集会。"] = "Эх, это дикая сборище Потусторонних.",
    ["唉，突然想起了一位总是想拿额外经费报销咖啡的老朋友。"] = "Эх, вдруг вспомнился старый друг, который вечно норовил списать кофе за счет казенных средств.",
    ["唉，这次又有三位无辜的人遇难，丽埃娜一家三口也都……"] = "Эх, на этот раз погибли трое невинных людей, и семья Лианы из трех человек тоже...",
    ["唉，这次又有三位无辜的人遇难，真希望我们能保护所有人。可是……"] = "Эх, на этот раз погибли три невинных человека. Я очень надеюсь, что мы сможем защитить всех. Однако...",
    ["唉，这还不算，她还有一个上学的弟弟。一家四口重担都在她身上。"] = "Увы, и это ещё не всё: у неё ведь ещё младший брат учится в школе. Все тяготы содержания семьи из четырёх человек лежат на её плечах.",
    ["唉，遵命，继续挑选吧，我的首席大厨。"] = "Вздохните, как хотите, продолжайте выбирать, мой шеф-повар.",
    ["唉，那怎么可能，好好复习考试吧。"] = "Эх, как это могло быть возможно? Просто сосредоточьтесь на подготовке к экзамену.",
    ["唉？我吗，那好吧。"] = "Э? Мне? Хорошо, тогда.",
    ["唔……"] = "Хм...",
    ["唔……好浓的臭味。"] = "Ух... такой сильный запах.",
    ["唔……请不要乱动桌上的文件，只要清扫一下地板，收走乱堆的杂物就好。"] = "Хм... пожалуйста, не трогайте документы на столе. Просто подметите пол и уберите разбросанный беспорядок.",
    ["唔……邓恩叔叔？"] = "Мм... дядя Данн?",
    ["唔，可恶啊！"] = "Ух, блин!",
    ["唔，可能后劲有点大……没关系，适应一会儿就好了！"] = "Хм, возможно, последействие немного сильное... Ничего страшного, со временем привыкнешь!",
    ["唔，头好疼……"] = "Мм, у меня так голова болит...",
    ["唔，我记不清楚了……"] = "Хм, я точно не помню...",
    ["唔，或许你应该尝试多接触一些其他学员。"] = "Хм, возможно, тебе стоит попытаться пообщаться с большим количеством студентов.",
    ["唤起她的注意"] = "Привлеки ее внимание",
    ["唱歌障碍？"] = "Поющее препятствие?",
    ["唱诗班表演对您很重要吗？"] = "Важно ли для вас выступление хора?",
    ["唱诵会结束后，众人纷纷离开，波特似乎意犹未尽，仍然待在原地。"] = "После окончания концерта все ушли один за другим. Поттеру, казалось, все еще нравилось это, и он остался на месте.",
    ["唱诵会结束后，波特和乔治待在原地，没有离开。"] = "После того, как сеанс пения закончился, Поттер и Джордж остались на месте и не ушли.",
    ["商人需要信守承诺"] = "Торговцы должны выполнять свои обещания",
    ["啊……"] = "Ах...",
    ["啊……{{先生|女士}}，你怎么知道我这么想去？"] = "Ах... {{sir|madam}}, откуда ты узнал, что я так хочу пойти?",
    ["啊……你想了解哪一个？"] = "Ах... о каком из них ты хочешь узнать?",
    ["啊……原来是这样……"] = "А... вот оно как...",
    ["啊……又来了……"] = "Ах... и вот снова...",
    ["啊……只是刚入门的新人，还没有写出什么拿的出手的东西。"] = "А... просто новичок, еще не написал ничего достойного показа.",
    ["啊……很抱歉，我以为是……免费的。"] = "Ах... извини, я думал, это... бесплатно.",
    ["啊……我还看到一个小女孩，跑去街上捡一束雏菊，被马车撞倒……"] = "Ах... Еще я видела, как маленькая девочка бежала на улицу собирать букет ромашек, и ее сбила карета...",
    ["啊……抱歉，我们还没有结婚。"] = "Ах... прошу прощения, мы еще неженаты.",
    ["啊……这，我，好像还真的忘了问了。下次我去酒馆的时候再问问她，她在那工作。"] = "А... это, я, кажется, и вправду забыл спросить. В следующий раз, как пойду в таверну, обязательно спрошу ее: она ведь там работает.",
    ["啊不是{{奥洛|莉莉娅}}……你这人怎么这么奇怪啊！为什么要和一个桶说话！"] = "Да нет же, {{Аоло|Лилия}}... Ну что ты за странный человек! Зачем ты разговариваешь с бочкой?!",
    ["啊哈，当然，当然！你一定会收获满满。"] = "Ага, конечно, конечно! Вы обязательно много выиграете.",
    ["啊哈，那请问，塔罗学派的创始人是？"] = "Ага, тогда позвольте спросить, кто является основателем Клуба Таро?",
    ["啊哈？！我又是什么东西？！"] = "Ага?! И что я?!",
    ["啊啊啊啊别过来！"] = "Ааааа, не подходи!",
    ["啊啊啊虫子！"] = "Аааа, ошибки!",
    ["啊！你看！差点掉下去！快回来，求你了！你需要梯子！"] = "Ах! Смотреть! Ты чуть не упал! Вернись, я прошу тебя! Вам нужна лестница!",
    ["啊！吓我一跳。"] = "Ах! Ты меня напугал.",
    ["啊！啊！有本事……你打死我！"] = "А-а! А-а! Если кишка не тонка... убей меня!",
    ["啊！我得回去补案件文档了，希望弗莱队长还没发现……"] = "Ах! Мне нужно вернуться и дописать отчёты по делу. Надеюсь, капитан Фрай ещё не заметил...",
    ["啊，{{先生|小姐}}，欢迎您去事务所里面的窗口排号，最近业务太多了，请谅解。"] = "Ах, {{ Mr. | Ms. }}, подойди, пожалуйста, к окну в офисе, чтобы получить номер. В последнее время мы были очень заняты, пожалуйста, поймите.",
    ["啊，一个没有失控的生物……在这里真是罕见。"] = "Ах, существо, которое не выходит из-под контроля... здесь редкость.",
    ["啊，你好你好，我在看报纸，有什么事情随便问吧。"] = "Ах, привет, привет. Я читаю газету, не стесняйтесь спрашивать что угодно.",
    ["啊，女士，您是想买什么东西吗？"] = "Ах, леди, вы хотите что-нибудь купить?",
    ["啊，妈妈真是的！赶快回来呀，我要忘记歌词啦。"] = "Ах, мама так раздражает! Возвращайся быстрее, я забуду текст.",
    ["啊，库尔斯先生！"] = "Ах, господин Курс!",
    ["啊，我明白了……我失败了，我被祂放弃了，我要被骨笛吃掉了。"] = "Ах, я понимаю... Я потерпел неудачу. Он оставил меня, и меня съест костяная флейта.",
    ["啊，我知道了，准是那个“孤儿帮”的成员。"] = "Ах, я знаю, это, должно быть, член той «банды сирот».",
    ["啊，或许是同一位小女孩。请{{先生|女士}}不必客气，我愿意免费给您一盒火柴。"] = "Ах, возможно, это та же самая маленькая девочка. Пожалуйста, {{Mr.| Ms.}}, не будь таким вежливым; Я готов подарить вам коробок спичек бесплатно.",
    ["啊，是{{PlayerName}}！回来有什么事吗？"] = "Ах, это {{PlayerName}}! Тебе что-нибудь нужно теперь, когда ты вернулся?",
    ["啊，最近有人向会长信箱提建议，希望在学派内补充一些装饰……"] = "Ах, кто-то недавно сделал предложение в почтовый ящик президента, надеясь украсить школу...",
    ["啊？"] = "Хм?",
    ["啊？七个插在派上的鱼头？"] = "Хм? Семь рыбьих голов застряли в пироге?",
    ["啊？你是怎么上来的？"] = "Хм? Как ты сюда попал?",
    ["啊？呃，我在，呃……我在做什么？"] = "Хм? Э-э, я, э-э... что я делаю?",
    ["啊？我吗？长官，这是意外……"] = "Ах? Мне? Офицер, это несчастный случай...",
    ["啊？那我虔诚地祈求您……快下雨！快打雷！"] = "Ах? Тогда я усердно молюсь тебе... поспеши и дождись! Спешите и гром!",
    ["啧啧啧，呦呦呦。"] = "Тск-цк-цк, йо-йо-йо.",
    ["啧啧，听起来很不可思议，这样的案子你居然都能侦破。"] = "Ц-ц-ц, звучит невероятно. Подумать только, ты раскрыл такое дело!",
    ["啾啾是多漂亮的小鸟啊，像天空一样蓝……它是最棒的玩偶。"] = "Чиу-Чиу была такая красивая птичка, голубая, как небо... Это была лучшая кукла.",
    ["啾啾，啾唧唧！"] = "Чирик, чирик-чирик!",
    ["喂——回来吃饭啦——不然玛丽阿姨就没收你们的全部酥皮挞——还要罚你们下个礼拜都吃不到米布丁——"] = "Эй, возвращайся к ужину, иначе тетя Мэри конфискует все твои слоеные пирожные и накажет тебя, не разрешив тебе есть рисовый пудинг на следующей неделе.",
    ["喂亨特，管好你的狗，它吵得像刚出生的婴儿！"] = "Эй, Хантер, управляй своей собакой, она шумная, как новорожденный ребенок!",
    ["喂那边的臭小孩，玩狗的时候安静一点！我不能再输了！"] = "Эй, сопляк, потише там со своей собакой! Мне больше нельзя проигрывать!",
    ["喂！喂！你怎么又开始了！"] = "Привет! Привет! Зачем ты снова начинаешь!",
    ["喂，乔治，别再提这些无聊的事！我要被你吓坏了！"] = "Эй, Джордж, хватит говорить об этих глупостях! Я буду тебя бояться!",
    ["喂，你注意到楼上那个怪人了吗？"] = "Эй, ты заметил того чудака наверху?",
    ["喂，你这人怎么这么冷漠？我可是在生死边缘啊！"] = "Эй, почему ты такой хладнокровный? Я на грани жизни и смерти!",
    ["善意提醒"] = "Дружеское напоминание",
    ["善良的{{先生|女士}}，感谢您我唠叨了这么多。知道这个世界上还有人会记得珍妮，我就已经很欣慰了。"] = "Добрый {{Mr.|Ms.}}, спасибо, что позволили мне так много болтать. Сознания, что в этом мире еще есть кто-то, кто помнит Дженни, достаточно, чтобы утешить меня.",
    ["善良的女士，能不能给我一根火柴，一根就好……"] = "Добрая госпожа, не найдётся ли у вас спички? Хотя бы одной...",
    ["喔……你想炼制什么药水或者符咒吗？还是想进行一些神秘学知识的学习？"] = "Ох... хочешь усовершенствовать какие-нибудь зелья или чары? Или вы хотите познать какие-то оккультные знания?",
    ["喔，抱歉埃德加，我想一定是我哪里弄错了！你拿去，这是新鲜的夜香草。"] = "Ой, прости, Эдгар, кажется, я где-то напутал! Вот, пожалуйста, это свежая трава с ночным ароматом.",
    ["喔，经典的搭配，是我祖母小时候喜欢的口味。"] = "Ого, классическое сочетание, именно этот вкус нравилась моей бабушке в детстве.",
    ["喔，酒吧内还有恶犬，虽然我并不这样认为，但你最好也别碰它们。"] = "О, еще в баре есть злобные собаки. Хотя я так не думаю, лучше их тоже не трогайте.",
    ["喜欢的话，就让我这个魔法师为你再吹奏一曲吧。"] = "Раз уж вам понравилось, позвольте мне, волшебнику, сыграть для вас ещё одну мелодию.",
    ["喜欢，谁不会对过往发生的一切感兴趣呢。"] = "Я делаю. Кому не будет интересно все, что произошло в прошлом?",
    ["喝下去"] = "Выпей это",
    ["喝东西找我，有事请找我老板。"] = "Приходите ко мне выпить; Если у тебя есть дела, пожалуйста, найди моего босса.",
    ["喝点什么？"] = "Что бы вы хотели выпить?",
    ["喧闹的牌桌安静了一瞬，又再次喧闹了起来，你用当初挣脱出红茧的意志力狠狠地把纸牌往前掷去。"] = "Шумный карточный стол на мгновение затих, а затем снова зашумел. Вы яростно швыряли карты вперед с той силой воли, которую использовали, чтобы вырваться из красного кокона.",
    ["喵……喵喵喵咪喵咪喵！<P_Heart>（啊……猫帮训话时间到！）</>"] = "Мяу... мяу-мяу-мяу-мяу-мяу! <P_Heart> (Ах... пришло время лекции кошачьей банды!) </>",
    ["喵喵咪。"] = "Мяу-мяу-мяу.",
    ["喵嗷！"] = "Мяу-у!",
    ["喵！"] = "Мяу!",
    ["喵！喵喵喵！<P_Heart>（猫们！报数！）</>"] = "Мяу! Мяу-мяу-мяу! <P_Heart>(Коты! Рассчитайся по порядку!)</>",
    ["喵，喵咪咪喵喵喵。<P_Heart>（你甚至不愿意叫我一声猫教父。）</>"] = "Мяу, мяу-мяу-мяу-мяу. <P_Heart> (Ты даже не хочешь называть меня Крестным отцом.) </>",
    ["嗝……<P_Heart>（喝得醉醺醺的。）</>"] = "Ик... <P_Heart>(Мертвецки пьян)</>",
    ["嗝……嗯？什……嗝……么？……<P_Heart>（头都没抬。）</>"] = "Ик... Хм? Что... ик... что?... <P_Heart> (Даже головы не поднял.) </>",
    ["嗝……鸽子小姐，你说我是不是连卷毛狒狒都不如？"] = "Ик... Мисс Голубь, вы думаете, я даже не так хорош, как кудрявый павиан?",
    ["嗨！"] = "Привет!",
    ["嗨，看点什么？报纸？杂志？"] = "Привет, ищешь что-нибудь? Газета? Журнал?",
    ["嗨，这里是亨利侦探事务所。\n我们对工作业务进行了数字分类："] = "Привет, это детективное агентство Генри. \nМы классифицировали наши рабочие операции по цифрам:",
    ["嗯……"] = "Хм...",
    ["嗯……不就是些小虫子吗？"] = "Хм... разве это не какие-то маленькие жучки?",
    ["嗯……也许我等错了地方？对吗？"] = "Хм... может я не там жду? Верно?",
    ["嗯……你说得对，但是南威尔啤酒做梦以后会在豪尔斯街<P_Yellow>流通</>\n，伴随黑色的月亮一起度过春夏<P_Yellow>秋冬</>。"] = "Гм... ты прав, но саутвеллское пиво после сна начнет <P_Yellow>расходиться</>\n по улице Хоулс, коротая весну, лето, <P_Yellow>осень и зиму</> под черной луной.",
    ["嗯……平平无奇的搭配，还有些奇怪。"] = "Хм... посредственное сочетание и немного странное.",
    ["嗯……我们听起来像是一群不讲理的流氓。"] = "Хм... мы звучим как кучка неразумных головорезов.",
    ["嗯……我保证绝不会放它们逃出<P_Yellow>文献室</>，如果一楼已经找不到了，或许可以考虑到<P_Yellow>二楼</>看看？当然，千万别忘了“<P_Yellow>灵视</>”，这些小东西很会藏。"] = "Хм... Обещаю, я никогда не позволю им сбежать из Архива <P_Yellow> </>. Если вы не можете найти их на первом этаже, возможно, вам стоит рассмотреть возможность поиска <P_Yellow> на втором этаже </>? Конечно, не забывайте «<P_Yellow> Spirit Vision </>», эти мелочи очень хорошо прячутся.",
    ["嗯……我只是他的妻子，只要支持他就好。"] = "Эм... Я всего лишь его жена, мне просто нужно его поддержать.",
    ["嗯……我明白了，谢谢你，丽贝卡。"] = "Хм... Я понимаю, спасибо тебе, Ребекка.",
    ["嗯……是在某个地方学习。"] = "Мм... Я где-то учусь.",
    ["嗯……有意思。旧日文明一度覆灭，但人类存续后又重建繁荣的社会。秩序是文明稳定之兆？感谢你的回答。"] = "Хм... интересно. Цивилизация Великого Древнего однажды погибла, но после того, как человечество выжило, оно восстановило процветающее общество. Является ли порядок признаком стабильности цивилизации? Спасибо за ваш ответ.",
    ["嗯……有趣。凭借自认为的“正确性”构建秩序，也是一种失序？感谢你的回答。"] = "Хм... Любопытно. Выстраивать порядок на основе собственной «правильности» — это тоже форма беспорядка? Благодарю за ответ.",
    ["嗯……汤底清新，罗勒馥郁的香气和牛肉的味道融为一体了，像是春天推开窗子看到草地上的牛羊。"] = "Хм... бульон освежает, а насыщенный аромат базилика идеально сочетается со вкусом говядины, как будто весной открываешь окно и видишь на лугу крупный рогатый скот и овец.",
    ["嗯……热牛奶，就要一杯热牛奶吧。"] = "Хм... горячее молоко, просто чашка горячего молока.",
    ["嗯……现在很需要排查一下近期在这边活动的人，我们目前已经掌握了旁边区域活动的人的行踪，但这边还没来得及调查。"] = "Хм... нам действительно нужно проверить людей, которые в последнее время были здесь активны. Мы уже отследили перемещения тех, кто находится на прилегающей территории, но пока не успели исследовать эту сторону.",
    ["嗯……目前在湖畔活动的人都排查好了，没有问题。但不能保证是否还有潜在的危险。"] = "Хм... Все, кто сейчас работает на берегу озера, проверены, проблем нет. Однако нет никакой гарантии, что потенциальные опасности все еще существуют.",
    ["嗯……等你恢复力气，可以去外面花圃里散散心，雏菊都开了。"] = "Хм... когда ты восстановишь силы, ты сможешь пойти в сад на улицу, чтобы расслабиться; все ромашки расцвели.",
    ["嗯……虽然银冠餐厅也值得一去，但葡萄酒并不是招牌。"] = "Хм... хотя ресторан Silver Crown стоит посетить, вино не является их фирменным блюдом.",
    ["嗯……谢谢。"] = "Хм... спасибо.",
    ["嗯……还是去<P_Yellow>休息室</>细说吧——我们也占用这里够久了。"] = "Хм... пойдем в <P_Yellow>lounge</>, чтобы уточнить - мы занимаем это место достаточно долго.",
    ["嗯……那个拳手确实有问题，他身上有非凡物品的痕迹。"] = "Хм... у этого боксера действительно проблема. На нем есть следы предметов Потусторонний.",
    ["嗯……银是女神领域的金属，陶艺也不错，我该选哪个呢？"] = "Хм... серебро — это металл во владениях Богини, да и керамика тоже неплохая. Какой из них мне выбрать?",
    ["嗯。"] = "Мм.",
    ["嗯嗯。"] = "Мм-хм.",
    ["嗯嗯快去吧。"] = "Мм-хм, давай.",
    ["嗯嗯，之前运送那个木偶，在瑞尔……"] = "Ага, когда мы перевозили ту марионетку, у Рэя...",
    ["嗯！一言为定！"] = "Да! Договорились!",
    ["嗯，一定会有那样一天的。"] = "Да, такой день обязательно будет.",
    ["嗯，一杯甜冰茶，当然是甜冰茶。"] = "Хм, стакан сладкого чая со льдом, конечно же, это сладкий чай со льдом.",
    ["嗯，保守估计，一个月吧？"] = "Хм, по скромным подсчетам — месяц?",
    ["嗯，如果有家庭事务相关的咨询可以来找我。"] = "Ну а если у вас есть консультации по семейным вопросам, можете прийти ко мне.",
    ["嗯，总之欢迎你来了解！"] = "Хм, в любом случае, пожалуйста, приходите и узнайте больше!",
    ["嗯，感谢您的告诫，平常练习我会栓一根绳子在身上。"] = "Мм, спасибо за совет. Обычно я привязываю к себе веревку, когда тренируюсь.",
    ["嗯，我会好好想想的。"] = "Да, я хорошенько подумаю над этим.",
    ["嗯，我会教你的，用正确的方法。"] = "Да, я научу тебя — как положено.",
    ["嗯，我听西迦说，你在黑市调查里表现得还不错。正好，又有一桩紧急案件要委托给你。"] = "Хм, я слышал от Сиги, что ты неплохо справился с расследованием дела о черном рынке. Так получилось, что мне нужно поручить вам еще одно срочное дело.",
    ["嗯，有桩紧急案件要委托给你。"] = "Хм, у меня есть для тебя срочное дело.",
    ["嗯，有线索可以随时来找我。"] = "Ну, ты можешь прийти ко мне в любое время, если у тебя есть подсказки.",
    ["嗯，没问题，但最大的危险来源于那7个未知的谜题……"] = "Хм, без проблем, но наибольшую опасность исходят от этих семи неизвестных загадок...",
    ["嗯，牛尾炖得也很嫩。"] = "Ммм, бычий хвост тоже тушится очень нежно.",
    ["嗯，百货商店出售的服饰虽然多，但缺乏量体裁衣的美感，高级定制的服饰必须要带有本人的特色……"] = "М-да, в универмагах хоть и полно одежды, но в ней нет изящества индивидуального пошива. Настоящий наряд на заказ обязан подчеркивать уникальные черты владельца...",
    ["嗯，看来你的灵性直觉给出了相当不错的引导，今天是个适合休息的日子！"] = "Хм, кажется, твоя духовная интуиция дала неплохие подсказки. Сегодня день подходящий для отдыха!",
    ["嗯，老尼尔……你身体还好吗？有什么困扰都可以跟我商量。"] = "Хм, старина Нил... как твое здоровье? Вы можете обсудить со мной любые проблемы.",
    ["嗯，谢谢提醒，我会多加注意的！"] = "Хм, спасибо за напоминание, буду внимательнее!",
    ["嗯，过去看看。"] = "Хм, пойду взгляну.",
    ["嗯，这就是最后一句了……"] = "Хм, это последняя строчка...",
    ["嗯，非凡世界很残酷，我也处理过几件难以释怀的案件……"] = "Хм, Необыкновенный Мир очень жесток. Я также занимался несколькими делами, от которых не мог отказаться...",
    ["嗯？"] = "Хм?",
    ["嗯？什么掉出来了？"] = "Хм? Что выпало?",
    ["嗯？这个名字是……"] = "Эм? Имя...",
    ["嗯？这只狗的脖子挂着狗牌，上面刻着……查理？"] = "Хм? У этой собаки на шее висит бирка с выгравированной надписью... Чарли?",
    ["嗯？非凡者……有什么事？"] = "Хм? Потустороннее... что-то случилось?",
    ["嘘——小声点，低调，低调。……我是正经剧友！"] = "Тсс, потише, будь сдержанным, сдержанным....Я серьезный любитель театра!",
    ["嘘——还是别乱说话，小心这句话传到斯维因耳朵里。"] = "Тсс, лучше не говори чепухи, будь осторожен, чтобы это не дошло до ушей Суэйна.",
    ["嘘！"] = "Тсс!",
    ["嘘！嘘……小声点，可以先还给我吗？我和佛尔思女士约定的时间马上就要到了……"] = "Тсс! Тсс... потише, можешь сначала вернуть его мне? Время, когда я договорился с мисс Форс, почти истекло...",
    ["嘘！小声点，这事可不能乱说。你是值夜者？我怎么不记得你，难道我的记性也变差了？"] = "Тсс! Потише, об этом нельзя болтать попусту. Ты из Ночных Ястребов? Почему я тебя не помню... неужели и у меня память стала сдавать?",
    ["嘘，你小点声。败坏我的名声！"] = "Тсс, потише. Вы портите мою репутацию!",
    ["嘘，先等我们赞美完比星空更崇高，比永恒更久远的黑夜女神。"] = "Тсс, подожди, пока мы не закончим восхвалять Богиню Вечной Ночи, которая более возвышенна, чем звездное небо, и более вечна, чем сама вечность.",
    ["嘘，小点声，别被脑子有病的人听见！"] = "Тс-с, потише, а то ещё эти сумасшедшие услышат!",
    ["嘘，小点声，那个人看起来可不好惹，刚才被他盯着的时候，我全身的寒毛全都立起来了"] = "Тсс, потише. Этот человек не похож на человека, с которым можно связываться. Когда он только что смотрел на меня, все волосы на моем теле встали дыбом.",
    ["嘘，我的面前有一名敌人。"] = "Тсс, передо мной враг.",
    ["嘶……谢谢。"] = "Хисс... спасибо.",
    ["嘶吼声中，莫名夹杂着些痛苦的情绪，也似乎在苦苦哀求着什么。"] = "В рёве необъяснимым образом смешались какие-то болезненные эмоции, и оно тоже как будто что-то умоляло.",
    ["嘿你算是问对人了，我这还有两页罗塞尔大帝的笔记，这可是稀缺货！"] = "Эй, ты спросил у правильного человека. У меня также есть две страницы заметок императора Розеллы. Это редкие товары!",
    ["嘿嘿，其实你一直以来表现都很棒啦。刚刚开玩笑的啦，不用那么严肃。对啦，等会我们去哪吃饭想好了吗？"] = "Хе-хе, на самом деле у тебя всё время всё отлично получалось. Я раньше просто пошутил, не надо быть таким серьезным. Кстати, ты уже решил, где мы пообедаем позже?",
    ["嘿嘿，咋样呀？"] = "Хе-хе, ну как оно?",
    ["嘿嘿，我乖乖的，爸爸回来的时候，就不会难过了。"] = "Хе-хе, я буду хорошей девочкой, и когда папа вернется, он не будет грустить.",
    ["嘿嘿，我会建议你先去队长办公室看看！"] = "Хе-хе, я советую вам сначала заглянуть в кабинет капитана!",
    ["嘿嘿，我觉得那边的海茵就不错，你看她的笑容，多么迷人！"] = "Хе-хе, я думаю, что Гейне там довольно хорош. Посмотрите на ее улыбку, какая она очаровательная!",
    ["嘿嘿，是我。你想买火柴吗？我们已经算是朋友了，我可以送你一根。"] = "Хе-хе, это я. Хотите купить спички? Мы уже друзья, я могу подарить тебе один.",
    ["嘿嘿，这可是来自东拜朗的植物精油，能让你变成床上的蒸汽列车，深夜的连发火炮，你懂的，嘿嘿。"] = "Хе-хе, это растительное эфирное масло из Восточного Балама, оно может превратить тебя в паровоз на кровати, в непрерывный артиллерийский огонь посреди ночи, понимаешь, хе-хе.",
    ["嘿嘿，那我就期待着下次值班了！"] = "Хе-хе, тогда я с нетерпением буду ждать следующей смены!",
    ["嘿！看到里面那位相亲的男士吗？对面坐着一位女士的那个。"] = "Эй! Видите того джентльмена на свидании внутри? Того, напротив которого сидит дама.",
    ["嘿，{{先生|女士}}，别这么说！须知智慧也是赚取钱财的途径之一，当然，当然！它不一定道德。"] = "Эй, {{ Mr.| Ms.}}, не говори так! Вы должны знать, что мудрость – это также один из способов заработка. Конечно, конечно! Это не обязательно морально.",
    ["嘿，{{小伙子|小姑娘}}！你最好待一边儿去，货箱边上可危险了。"] = "Эй, {{парень|девушка}}! Отойди-ка лучше в сторону, рядом с грузовыми ящиками небезопасно.",
    ["嘿，上面的！要跳就快点，别耽误大家时间！我还得去上班呢！"] = "Эй, ты там! Если собираешься прыгнуть, делай это быстро, не трать время зря! Мне еще на работу идти!",
    ["嘿，今天来了一波新的非凡材料，来看看？"] = "Эй, сегодня ожидается новая волна необычных материалов, приходите и посмотрите?",
    ["嘿，你借封印物的时候，尽量对他们好点……不要淋到雨。"] = "Эй, когда берешь Запечатанные Артефакты, постарайся обращаться с ними повежливее... и не мочи под дождем.",
    ["嘿，你看起来很年轻啊！还在上学吗？"] = "Эй, ты выглядишь очень молодо! Ты еще учишься в школе?",
    ["嘿，你这小子——什么交易？我听不懂，我就是个破卖报纸的！走开走开！"] = "Эй, малыш, что за дела? Я не понимаю. Я всего лишь плохой продавец газет! Уходи, уходи!",
    ["嘿，先生，要来束鲜花吗？这与您美丽的妻子很相配。"] = "Эй, сэр, хотите купить букет цветов? Он идеально подходит вашей прекрасной жене.",
    ["嘿，小伙子，买点苹果吧，新鲜着呢！或者来点葡萄——今天早上才从藤上摘下来的！"] = "Эй, молодой человек, купите яблок, они свежие! Или купите виноград, сорванный с лозы только сегодня утром!",
    ["嘿，布莱特，你以前玩过槌球吗？这可是我们西区最流行的游戏……我猜你大概连见都没见过吧？"] = "Эй, Брайт, ты когда-нибудь играл в крокет? Это же самая популярная игра у нас в Западном районе... Держу пари, ты ее даже в глаза не видел, верно?",
    ["嘿，我们一定要这么不务正业吗？"] = "Эй, неужели нам действительно обязательно быть такими непродуктивными?",
    ["嘿，我听见了！"] = "Эй, я это слышал!",
    ["嘿，朋友，你听说过罗塞尔大帝的风流往事吗？"] = "Эй, друг, ты слышал о романтических похождениях императора Розеллы?",
    ["嘿，这儿的龙骨鱼，可是出海的船刚刚带回来的。香煎味道好极了！"] = "Эй, килевую рыбу только что привезла лодка, вышедшая в море. Жареная на сковороде очень вкусная!",
    ["嘿，这可不能说。你要真想知道，不如去问问买过的人是什么体验。"] = "Эй, я не могу сказать. Если вы действительно хотите это знать, почему бы не спросить об их опыте тех, кто их купил.",
    ["嘿，这把有些人的裤衩都要赔掉了。"] = "Хех, в этом раунде кое-кто останется без последних штанов.",
    ["噢……{{先生|女士}}，你知道吗，有两个流浪汉死在这里了。"] = "Ох... {{Mr.|Ms.}}, ты знал, что здесь умерли два бездомных?",
    ["噢不……小黛西……"] = "О нет... малышка Дейзи...",
    ["噢不，我们是文明人，不会做这种不文明的事情。"] = "О нет, мы цивилизованные люди и не будем совершать такие нецивилизованные поступки.",
    ["噢噢！您说的对，少凑热闹，少凑热闹。"] = "Ох, ох! Ты прав, не присоединяйся к веселью, не присоединяйся к веселью.",
    ["噢！吉瑞尔，你的确要好好教育阿尔伯特，他最近很不听话。"] = "Ой! Гирель, тебе действительно нужно как следует дисциплинировать Альберта. В последнее время он стал очень непослушным.",
    ["噢！这是卡斯伯特甜品俱乐部特供的柠檬蛋糕，是卡斯伯特女士的独家配方！"] = "Ой! Это лимонный пирог, специально предоставленный Десертным клубом Катберт, по эксклюзивному рецепту мисс Катберт!",
    ["噢！那请务必——务必买一束包扎精美的花送给她，庆祝你们的好日子！"] = "О! Тогда непременно — непременно купите ей красиво оформленный букет цветов в честь вашего праздника!",
    ["噢，<P_Yellow>丽埃娜</>，我就知道，你一定能完全记住的。"] = "О, <P_Yellow>Liana</>, я знал, что ты сможешь запомнить их полностью.",
    ["噢，{{先生|女士}}！你有工作要介绍给我吗？"] = "О, {{Mr.|Ms.}}! У вас есть какие-нибудь работы, которые вы можете мне представить?",
    ["噢，不好意思，差点忘了，杂货摊的火柴应该是要按盒购买的。"] = "Ой, извини, чуть не забыла, спички в продуктовом ларьке надо покупать коробочками.",
    ["噢，你是说小福戈给工人们提供的免费盒饭？"] = "О, вы имеете в виду бесплатные упакованные ланчи, которые маленький Фога раздает рабочим?",
    ["噢，又一位警官？但愿您能查清事情的真相。"] = "О, ещё один офицер полиции? Надеюсь, вам удастся докопаться до истины.",
    ["噢，在塔罗学派内部，3级封印物的资料是接近公开的，你直接去<P_Yellow>二楼</>取阅就行。"] = "О, в Клубе Таро информация о запечатанных артефактах 3-го уровня почти общедоступна; вы можете просто пойти на второй этаж <P_Yellow>, </>, чтобы прочитать его.",
    ["噢，大家都是那样说他的。实际上斯帕罗先生只是看起来冷漠……他可是个真正的绅士，绅士里还带着一些霸道，霸道里又带着一些温柔……"] = "Ох, все так про него говорят. На самом деле, мистер Воробей выглядит просто холодным... Он настоящий джентльмен, джентльмен с некоторой доминантностью, и в этом доминировании есть немного нежности...",
    ["噢，当然。我是<P_Yellow>新管家——汉娜</>。请问您是？"] = "О, разумеется. Я <P_Yellow>новая экономка — Ханна</>. А вы, позвольте узнать?",
    ["噢，很遗憾，我以为你一定能闻得到雏菊的香味。"] = "О, как жаль. Я думала, ты обязательно почувствуешь аромат ромашки.",
    ["噢，您看着是生面孔，可能不知道这家店。"] = "О, ты выглядишь как новое лицо, возможно, ты не знаешь этот магазин.",
    ["噢，感谢世界上还有记得她的人。"] = "Ох, спасибо, что на свете еще есть люди, которые ее помнят.",
    ["噢，我的小天使，你总是比我还要坚强。好吧，为了你和这个家，我豁出去了。"] = "О, мой маленький ангел, ты всегда сильнее меня. Хорошо, ради тебя и этой семьи я попробую.",
    ["噢，我还记得三十多年前他说要给我送一枚戒指，只是要等一等，这一等，又等到了今天。"] = "О, я до сих пор помню, как более тридцати лет назад он сказал, что позвонит мне, но мне пришлось немного подождать, и это ожидание продолжалось до сегодняшнего дня.",
    ["噢，抱歉，我居然开始喜欢回忆过去了。"] = "Ой, извини, мне действительно стало нравиться вспоминать прошлое.",
    ["噢，是吗？那太遗憾了。不过只要学校不放假，河水不结冰，我们都会在这里训练，欢迎你来观看！"] = "О, это так? Очень жаль. Но пока в школе не каникулы и река не замерзла, мы будем тренироваться здесь. Добро пожаловать, приходите и смотрите!",
    ["噢，没关系，欢迎下次再来。"] = "О, все в порядке, пожалуйста, приходите снова в следующий раз.",
    ["噢，真不好意思，我周三要去海边散步，我约好了为那些海鸥带去金黄的炸薯条。"] = "Ой, мне очень жаль, я собираюсь гулять по морю в среду. Я обещал принести чайкам золотую картошку фри.",
    ["噢，谢谢你，没关系的！"] = "Ой, спасибо, все в порядке!",
    ["噢，风暴在上，快降下神罚，赶走这个疯子！"] = "О, Бури небесные, ниспошли скорее божественную кару и прогони этого безумца!",
    ["四十年了,开这家店的时候我才二十岁，那可真是一个美好的年纪。"] = "Сорок лет прошло... Когда я открыл эту лавку, мне было всего двадцать — чудесный был возраст.",
    ["四处溃散的我们，就像盛放的烟火。"] = "Мы разбегаемся во все стороны, словно искры праздничного салюта.",
    ["四年前就是他们偷袭贝克兰德挑起的战争！"] = "Четыре года назад именно они внезапно напали на Бэкланд и начали войну!",
    ["四次会，三次不会，应该会有好结果吧？"] = "Четыре раза да, три раза нет. Должен быть хороший результат, верно?",
    ["四面八方！不过，我认为你可以用灵视找到它们。"] = "Со всех сторон! Однако я думаю, что вы можете найти их, используя духовное зрение.",
    ["回去通知贝尔纳黛"] = "Вернитесь и сообщите Бернадетт.",
    ["回家啊……"] = "Иди домой...",
    ["回家，回家……唉，要是这样就能回家，我早就回去了。"] = "Иди домой, иди домой... Эх, если бы вернуться домой было так легко, я бы уже давно вернулся.",
    ["回家？"] = "Идти домой?",
    ["回报实情"] = "Сообщите правду",
    ["回来了？"] = "Вернулся?",
    ["回答正确，看来你适应得不错。"] = "Правильный ответ, кажется, вы хорошо адаптировались.",
    ["因为今天本该是他值班的日子，他却没有出现！而我，在睡梦中被主管叫醒，替他工作！"] = "Потому что сегодня его смена, а он не явился! И меня прямо из постели выдернул надзиратель, чтобы я вкалывал за него!",
    ["因为他从绳索跌下来了，没办法像以前一样在绳索间起舞跳跃，后来我们回到了这里，他也开始喝酒度日。"] = "Потому что он упал с веревки и не мог танцевать и прыгать между веревками, как раньше. Позже мы вернулись сюда, и он начал пить.",
    ["因为婚姻的事，黛西小姐和家里的关系一直很疏远，也很少见面。"] = "Из-за замужества мисс Дейзи всегда держалась отчуждённо от своей семьи и редко с ними виделась.",
    ["因为我的钱包在上面。"] = "Потому что на нем мой кошелек.",
    ["因为这并不算是一种有智慧的灵界生物，只要控制了母体，就能轻易消灭虫潮。"] = "Потому что это не тип разумного существа из Духовного мира. Пока материнское тело находится под контролем, прилив насекомых можно легко устранить.",
    ["因为，咳咳，我破过一些特别离奇的案子，当然主要是靠我的委托高完成率。"] = "Потому что, кхм, мне удалось раскрыть некоторые особенно странные дела, в основном благодаря высокому проценту выполнения моих заказов.",
    ["因此，我大部分时间都在这里指导、帮助学员们提高战斗能力，无论你是否选择了“战士”途径。"] = "Поэтому я провожу здесь большую часть своего времени, помогая ученикам улучшить их боевые способности, независимо от того, выбрали ли вы путь «Воина».",
    ["因蒂斯信仰着永恒烈阳与蒸汽与机械之神，是北大陆最强势的国家……之一，嗯。"] = "Интис верит в Вечное Пылающее Солнце и Бога пара и машин. Это одна из самых могущественных стран Северного континента... ну.",
    ["因蒂斯的珠宝和那里的人一样，充满浪漫色彩。"] = "Драгоценности Интиса, как и его жители, полны романтики.",
    ["土豆、豌豆、白萝卜、莴苣……我保证，我的摊上有着全廷根、不，乃至全阿霍瓦郡所有餐桌上全部的蔬菜种类！"] = "Картофель, горох, белая редиска, салат... Я гарантирую, что в моем ларьке есть все виды овощей, которые можно найти на каждом обеденном столе во всем Тингене — нет, во всем округе Ахоава!",
    ["土豆买二送一——伙计们，还等什么，仅限今日！"] = "Купи две картошки, получи одну бесплатно — ребята, чего вы ждете, только сегодня!",
    ["圣典《风暴之书》告诉我们，不要崇尚战斗，也不宣扬战争，但绝对要以风暴般的酷烈对待敌人！"] = "Священное Писание «Книга бурь» говорит нам не пропагандировать борьбу и не проповедовать войну, но мы должны относиться к врагам с жестокостью шторма!",
    ["圣赛琳娜教堂，还是北区的塔楼？"] = "Собор Святой Селены или башня в Северном округе?",
    ["在世的人往往需要一些东西去纪念逝去的人。"] = "Живым всегда нужны какие-то вещи, чтобы хранить память об ушедших.",
    ["在你身后飘荡的、即将飘散的、虚幻的灵。"] = "Иллюзорные духи, которые плывут позади вас и вот-вот рассеются.",
    ["在占卜什么？"] = "Что ты предсказываешь?",
    ["在哪儿呢……小家伙？"] = "Где ты... малыш?",
    ["在哪认识不重要，重要的是，她对我很信任，和我说了她的身世。"] = "Где мы встретились, не важно, важно то, что она мне доверяет и рассказала о своем прошлом.",
    ["在学派待得还习惯吗？"] = "Вы привыкаете оставаться в школе?",
    ["在密林中……"] = "В густом лесу...",
    ["在密林中用新鲜采摘的香草煎肉，油润的芳香中，饱含着南大陆的自然气息。"] = "Обжаренное мясо со свежесобранными травами в густом лесу; маслянистый аромат наполнен естественным дыханием Южного континента.",
    ["在小艾恩失踪之前，我听见她家天天吵架，闹得可凶啦，说不定就是因为这……唉……"] = "До того, как маленькая Айне пропала, я каждый день слышал, как они ссорились дома, это было довольно жестоко. Может быть, из-за этого... вздох...",
    ["在廷根市适合约会的餐厅里，会把南威尔红葡萄酒作为特色的或许是……嗯，不是南方食物，餐厅特点也鲜明……对了！"] = "Среди ресторанов Тингена, подходящих для свиданий, один, в котором можно попробовать красное вино Southwell, - это... хм, не южная еда, да и характеристики ресторана тоже различимы... Вот и все!",
    ["在心里默念问题7次，然后上抛硬币，人像代表肯定，数字代表否定。"] = "Повторите вопрос про себя 7 раз, затем подбросьте монету. Орел символизирует утверждение, решка — отрицание.",
    ["在您眼前的是最纯净的绿意！来自霍伊河上游流域——零工业侵扰，远离烟囱与工厂！"] = "Перед вашими глазами чистейшая зелень! Из верховьев бассейна реки Хой — никакого промышленного вмешательства, вдали от труб и заводов!",
    ["在感情里，你是个懦夫"] = "Когда дело касается чувств, ты трус",
    ["在我了解一切后……或许我会用罗莎琳的名字发表这些东西。我们这些小人物从来不被那些大人物看在眼里，但这所城市理应记住姐姐的名字。"] = "После того, как я все пойму... возможно, я опубликую эти вещи под именем Розалинды. Нас, маленьких людей, эти важные шишки никогда не видят, но этот город должен помнить имя моей сестры.",
    ["在我们的世界里，是不存在\"宰了他们\"这种台词的，这是胆小鬼才会说的台词，因为我和我的同伴们在脑海中浮现出这句台词时，实际上早就已经要了对方的命，一切都结束了。"] = "В нашем мире нет такой фразы, как «убей их». Эту фразу могли бы сказать только трусы, потому что к тому времени, когда у меня и моих товарищей возникнет эта мысль в голове, мы уже забрали жизнь другого человека. Все уже закончилось.",
    ["在我最后那次任务里，如果只有我一个牺牲者……我们拯救了27个人。"] = "Если бы на моем последнем задании единственной жертвой оказался я... мы спасли двадцать семь жизней.",
    ["在我的治理下，廷根井然有序。"] = "Под моим руководством Тинген в полном порядке.",
    ["在我这定制衣服，比去那些服饰店里更便宜，只赚些手工费。"] = "Персонализировать одежду здесь дешевле, чем ходить в магазины одежды; Я лишь немного зарабатываю за свой труд.",
    ["在抓老鼠上，您应该比我专业？"] = "Ты должен быть профессиональнее меня в ловле мышей, верно?",
    ["在暗室将你出售的物品写到黑板上。交易达成后，露娜女士会为我们验证非凡材料的真伪。"] = "Напишите на доске в темной комнате товары, которые вы продаете. Как только сделка будет достигнута, г-жа Луна проверит для нас подлинность материалов Потусторонний.",
    ["在月光下……"] = "Под лунным светом...",
    ["在月光下用一支香草蜡烛的火焰煎肉，而且不会过分甜腻，是一个清新美好的夜晚。"] = "Мясо, обжаренное на сковороде при лунном свете с использованием пламени травяной свечи; он не слишком сладкий и не жирный, что делает ночь свежей и красивой.",
    ["在桌子侧面。"] = "На краю стола.",
    ["在消失前，我会尽全力保护萝拉，保护这个街区。"] = "Пока я не исчез, я сделаю все возможное, чтобы защитить Лолу и этот квартал.",
    ["在灵界漫游的时候我总是忍不住感慨，对像我这样的作家来说，采风真是所有任务中最令人心情舒畅的一件。"] = "Странствуя по Миру Духов, я не устаю повторять: для такого писателя, как я, сбор материала — самое приятное из всех занятий.",
    ["在盥洗室里……等等？"] = "В туалете... подожди?",
    ["在盥洗室里和一头冲出来的海狸搅拌二十四斤香草混凝土后，共享一块煎肉！"] = "Разделить кусок жареного мяса после замешивания двадцати четырех фунтов ванильного бетона с выскочившим из уборной бобром!",
    ["在窥秘之眼的帮助下，你以极快的速度找到了那在书页中徜徉的谜虫。"] = "С помощью Тайных любопытных глаз вы обнаружили Таинственного червя, блуждающего по страницам с невероятной скоростью.",
    ["在美好的午餐时间吵架，是发生什么了吗？"] = "Спорили во время прекрасного обеда. Что-то случилось?",
    ["在警察来之前，这里很难恢复安静了，您要是想买花，还是去别处吧。"] = "Здесь трудно восстановить тишину до прибытия полиции. Если вы хотите купить цветы, вам лучше пойти в другое место.",
    ["在这个世界，我们要承担责任，也要寻找生命的意义。能看出来，你在坚守学派的理念，守望人间的正义，但同时又有人性中的细腻和同情心。"] = "В этом мире мы должны брать на себя ответственность, а также искать смысл жизни. Я вижу, что ты придерживаешься философии клуба, следишь за справедливостью в мире, но в то же время в тебе есть деликатность и сострадание человечности.",
    ["在这儿还是维尔餐厅的时候，我父母常常领着我来吃饭。"] = "Когда это место еще называлось рестораном «Уилл», родители часто приводили меня сюда поесть.",
    ["在这类事件中，我们只能尽全力去协助你们……但我们的动作快一点，说不定你们就能救下更多人。"] = "В подобных событиях мы можем сделать все возможное, чтобы помочь вам... но если мы будем действовать немного быстрее, возможно, вы сможете спасти больше людей.",
    ["在这里安静一会，你知道对岸那边最高的房子是哪儿那？"] = "Помолчи здесь какое-то время. Вы знаете, где на другой стороне самый высокий дом?",
    ["在这里蒸汽与机械之神教会、黑夜女神教会和风暴之主教会是信仰的主流，还允许着大地母神教会传教，我想，包容是生产力强盛的标志。"] = "Здесь Церковь Бога Пара и Машин, Церковь Богини Ночи и Повелителя Бурь являются основным направлением веры, а также позволяют Церкви Матери-Земли проповедовать. Я считаю, что толерантность — признак высокой продуктивности.",
    ["在这里，从来没有一个人夸奖过我的画，说不定贝克兰德的艺术评论家们会欣赏我的风格。"] = "Здесь никто никогда не хвалил мои картины. Возможно, искусствоведы в Баклунде оценят мой стиль.",
    ["在那之后又发生了很多故事吧，戴莉女士有没有把那句话说出口，邓恩先生是不是一直那么别扭……"] = "Много историй, должно быть, произошло после этого, верно? Неужели леди Дейли сказала эти слова, мистер Данн всегда был таким неловким...",
    ["在酒吧内打听到相应线索"] = "Расспросить в баре и найти зацепки",
    ["在酒吧内搜寻所需物品"] = "Поиск необходимых предметов в баре",
    ["在铁十字街下街，不过那里的地理位置不错，临近水仙花街和金梧桐大道，生活也便利。"] = "Он находится на Лоуэр-Айрон-Кросс-стрит, но расположение хорошее, недалеко от Даффодил-стрит и Голден-Инд-авеню, и жизнь здесь удобна.",
    ["在陵园深处、在墓钟之上，夜莺在唱歌，夜莺在徘徊。"] = "Глубоко в мавзолее, над кладбищенским колоколом, поет соловей, бродит соловей.",
    ["坏孩子？"] = "Плохой ребенок?",
    ["坦诚说服"] = "Искреннее убеждение",
    ["垃……和餐厅后厨拉近距离，就能收到这样的菜！"] = "Мусор... приблизившись к кухне ресторана, можно получить эти овощи!",
    ["垃圾桶？"] = "Мусорный бак?",
    ["埃尔顿子爵和夫人在哪里？这两次都没有见到他们。"] = "Где виконт Элтон и его жена? Мы их ни разу не видели.",
    ["埃尔顿子爵家的黛西小姐住在这里吗？"] = "Здесь ли живет мисс Дейзи из семьи виконта Элтона?",
    ["埃德加，消消气。我这里的东西货真价实，谁买了都说好！"] = "Эдгар, успокойся. Вещи у меня настоящие, все, кто их покупает, говорят, что они хорошие!",
    ["埋葬这株黄水仙，它象征着我死去的爱情。"] = "Похороните этот желтый нарцисс; это символизирует мою мертвую любовь.",
    ["基本是的。不过，我们还需要再次确认黛西小姐的状态。"] = "В принципе, да. Однако нам все еще нужно еще раз подтвердить состояние мисс Дейзи.",
    ["塔利姆有骑士精神"] = "У Талима есть рыцарство",
    ["塔利姆行事荒唐"] = "Талим действует абсурдно",
    ["塔索克鱼肉质鲜嫩，鱼刺又少，最适合高温油炸，再撒些孜然、迷迭香，外脆里嫩，焦黄可口，绝对好吃！"] = "Рыба-кочка нежная, в ней мало костей, поэтому она идеально подходит для жарки во фритюре. Посыпьте немного тмина и розмарина, и он станет хрустящим снаружи, нежным внутри и золотисто-коричневым — просто восхитительный!",
    ["塔索克鱼肉质鲜嫩，鱼刺又少，最适合高温油炸，再洒些孜然、迷迭香，外脆里嫩，焦黄可口，绝对好吃！"] = "Рыба-кочка нежная и в ней мало костей, что делает ее идеальной для жарки во фритюре. Посыпьте его немного тмина и розмарина, и он станет хрустящим снаружи и нежным внутри, золотистым и вкусным. Очень вкусно!",
    ["塔罗占卜，由你来洗牌和切牌。"] = "Гадание Таро, вы занимаетесь перетасовкой и разрезанием карт.",
    ["塔罗学派是一个尝试。我和我的同伴在某次航程中偶然发现了这个新的可能性。"] = "Клуб Таро – это попытка. Я и мои спутники случайно обнаружили эту новую возможность во время путешествия.",
    ["塔罗学派毫无疑问是个奇迹，我们的学员总是对探寻它的源头表现出浓厚的兴趣。"] = "Школа Таро, вне всяких сомнений, настоящее чудо, и наши ученики неизменно проявляют живейший интерес к ее истокам.",
    ["塔芒先生什么都好，就是在咖啡上太古板了，让人头疼……"] = "Мистер Таманг хорош во всем, но его консерватизм в отношении кофе просто невыносим...",
    ["墓园里分为三片区域，西南侧是有钱人的地方，中间区域是还算富裕的人的园区，东北方向是穷人墓区。"] = "Кладбище разделено на три части: на юго-западе хоронят богачей, в центре — людей со средним достатком, а на северо-востоке расположен участок для бедняков.",
    ["壁炉旁边比较干爽，这里一般也不会有人来，偶尔会有一点瓶瓶罐罐碰撞的声音，我喜欢这种感觉。"] = "У камина суше, и люди сюда приходят редко. Время от времени раздается звон бутылок и банок; Мне нравится это чувство.",
    ["士兵应该死在战场上！"] = "Солдаты должны погибнуть на поле боя!",
    ["外交大臣就是我，{{先生|女士}}，我们见过了。帽子帮是这片街区活动的另一个流浪儿组织，他们多数是从纺织厂跑出来的。"] = "Я министр иностранных дел, {{ Mr.| Ms.}}, мы уже встречались. «Банда шляп» — еще одна организация беглецов, действующая в этом районе; большинство из них сбежало с текстильных фабрик.",
    ["外交大臣？帽子帮？"] = "Министр иностранных дел? Банда в шляпах?",
    ["外送？抱歉……在用餐时段，我们店里通常会很忙，而我们的人力，不足以提供外送服务。"] = "Доставка? Извините... наш магазин обычно очень занят во время еды, и у нас недостаточно рабочей силы, чтобы обеспечить услуги доставки.",
    ["外面不是还有一个值班的队员吗？"] = "Разве снаружи нет еще одного дежурного офицера?",
    ["多么疯狂！"] = "Как безумие!",
    ["多亏了你，帮我找到了故事的真相……"] = "Благодаря вам вы помогли мне узнать правду в этой истории...",
    ["多大了？我想想……12岁左右吧，不过她太瘦了，或许实际上会更大一些。"] = "Сколько лет? Дай подумать... около 12, но она слишком худая, может быть, она на самом деле старше.",
    ["多熬几个通宵就不会失眠了。"] = "Если вы не спите еще несколько ночей, это поможет вам избежать бессонницы.",
    ["多管闲事的？奉劝你别插手，我们有合同在的。"] = "Назойливый? Советую не вмешиваться, у нас есть договор.",
    ["多谢，到时候请你喝奥尔米尔葡萄酒！"] = "Спасибо, тогда я угощу вас вином Ормье!",
    ["多陪陪萝拉吧，即使她看不到你了。"] = "Проводи больше времени с Лолой, даже если она больше не сможет тебя видеть.",
    ["够了！你们两个废物！我要回间海郡娘家！"] = "Достаточно! Вы двое неудачники! Я возвращаюсь в дом моей матери в Мидсишире!",
    ["大人的事情，你少管！"] = "Взрослое дело, ты не забывай о себе!",
    ["大人，不够啊……"] = "Господин, этого недостаточно...",
    ["大厅这边差不多了，可以麻烦你去清扫队长的办公室吗？"] = "Здесь, в холле, все уже сделано, не могли бы вы потрудиться навести порядок в кабинете капитана?",
    ["大帝说“开眼看世界”，这句话可太酷了！"] = "Император сказал: «Открой глаза и посмотри на мир». Эта фраза такая крутая!",
    ["大概要排多长时间才能轮到我呢？"] = "Сколько примерно придется стоять в очереди, пока дойдет до меня?",
    ["大部分精神出了问题，还是习惯去教会，找教士们来解决。还有些他们解决不了的就来我们这了，当然还有一些只是疯癫就不用来我们这。"] = "Большинство людей с психическими проблемами привыкли ходить в церковь, чтобы найти священников, которые смогут их решить. К нам приходят другие, которые они не могут решить. Конечно, некоторые просто сумасшедшие и им не нужно к нам обращаться.",
    ["天哪……我眼睛都看花了！"] = "Боже мой... у меня глаза ослеплены!",
    ["天然发酵，纯手工制作，{{先生|女士}}要来点面包吗？"] = "Натурального брожения и ручной работы. {{ Mr. | Ms. }}, хочешь хлеба?",
    ["太可怕了。"] = "Это ужасно.",
    ["太可怕了，我得让孩子们离这里远点。"] = "Это ужасно, я должна держать детей подальше отсюда.",
    ["太多……你把所有果子都摘了？"] = "Слишком много... ты собрал все фрукты?",
    ["太多果子？"] = "Слишком много фруктов?",
    ["太好了！这首乐曲真的有魔法，艾登说得对，只要相信，一定可以！"] = "Это замечательно! В этой музыке действительно есть волшебство. Эйден был прав: пока ты веришь, это определенно осуществимо!",
    ["太好了，你通过了，我的帮手又增加了！"] = "Отлично, вы прошли, мой помощник снова увеличился!",
    ["太好了，那我们去休息室跳舞吧！"] = "Отлично, тогда пойдем в гостиную потанцевать!",
    ["太感谢了。我最近好像总是遇到一些倒霉的事情，朋友推荐我来挑选一个护身符。"] = "Огромное спасибо. В последнее время на меня словно посыпались неудачи, и друг посоветовал мне выбрать какой-нибудь амулет.",
    ["太棒了玛莎，你学得真快！"] = "Это здорово, Марта, ты так быстро учишься!",
    ["太没礼貌了！你怎么敢弄脏我的毛？！"] = "Так грубо! Как ты посмел испачкать мою шерсть?!",
    ["太聪明的女仆会有自己的想法，总想骑在总管和雇主的头上做事。"] = "Слишком умная горничная будет иметь свои собственные идеи и всегда будет пытаться обойти головы дворецкого и работодателя.",
    ["太过分了，先保护孩子们再说。"] = "Это уже чересчур! Сначала защитим детей.",
    ["夫人正是因此投资了许多像爱丽丝小姐一样的珠宝匠。"] = "Именно поэтому мадам поддержала стольких ювелиров, как мисс Элис.",
    ["夫人说过，抓住机遇的都搬去了更富有的地方，北区，或者贝克兰德，而没有抓住机遇的……抱歉，这个夫人没有说过。"] = "Дама сказала, что те, кто воспользовался этой возможностью, перебрались в более богатые места, в Северный район или Бэкланд, а те, кто не воспользовался этой возможностью... извините, дама этого не сказала.",
    ["夫人，再等等吧。"] = "Мэм, пожалуйста, подождите еще немного.",
    ["失控者已处理，现场只有一名幸存者，是窥秘人途径序列9的女孩，她是试验品之一。"] = "С вышедшим из-под контроля человеком разобрались. На месте происшествия остался только один выживший, девушка из эпизода 9 пути Тайного Прайера; она одна из испытуемых.",
    ["失礼了，这不是麦格文家的待客之道。"] = "Извините, семья Макговернов не так обращается с гостями.",
    ["失踪地点附近的人似乎听到了诡异的、像是笛子的曲调。"] = "Люди, находящиеся рядом с местом исчезновения, похоже, услышали странную мелодию, напоминающую флейту.",
    ["失踪的封印物3-116，它从来没有展现过自主逃离意向，为什么突然……"] = "Пропавший Запечатанный Артефакт 3-116 никогда не выказывал намерения сбежать самостоятельно, с чего вдруг...",
    ["头……好痛……"] = "Голова... болит...",
    ["头发……不，是鱼线？"] = "Волосы... нет, это леска?",
    ["头好痛……呜呜呜……"] = "У меня так болит голова... ууууу...",
    ["头疼……还有几个案件没分派出去，得抓紧处理一下……"] = "Головная боль... есть еще несколько дел, которые не назначены, мне нужно поторопиться и разобраться с ними...",
    ["奇怪的鸟，它们聚在这里做什么？"] = "Странные птицы... зачем они слетелись сюда?",
    ["奇怪，照片里的地方好像都变了样……"] = "Странно, места на фотографиях вроде все поменялись...",
    ["奇怪，照片里的地方好像都变了样儿……"] = "Странно, места на фотографиях вроде все поменялись...",
    ["奇怪，这个时候了，还有谁在文献室？"] = "Странно, в этот час кто еще находится в архивах?",
    ["奥利安娜太太，您对这里熟悉吗？"] = "Миссис Орианна, вам знакомо это место?",
    ["奥利安娜太太，您还好吗？"] = "Миссис Орианна, с вами все в порядке?",
    ["奥利安娜太太，我一定会把罗珊带回来的。"] = "Миссис Орианна, я обязательно верну Розанну.",
    ["女仆失踪案，看来这次要解决的案件不止一件，不知道报酬会不会多一倍。"] = "Дело о пропавшей горничной. Кажется, на этот раз предстоит раскрыть не одно дело. Интересно, удвоится ли награда?",
    ["女士……"] = "Леди...",
    ["女士，一根火柴，一根就好……"] = "Мэм, спичка, всего одна спичка...",
    ["女士，你们在聊些什么？"] = "Дамы, о чем вы говорите?",
    ["女士，你见过3级封印物的资料吗？"] = "Мэм, вы видели информацию о запечатанных артефактах 3-го уровня?",
    ["女士，您也知道，我爸爸是廷根大学文学系的毕业生，他有个文学梦啊！"] = "Сударыня, вы знаете, мой отец окончил литературный факультет Тингенского университета; у него есть литературная мечта!",
    ["女士，您是在作诗吗？其实我对此也有些兴趣……您是否能指教一二？"] = "Мадам, вы пишете стихи? На самом деле, меня это тоже интересует... Не могли бы вы дать мне несколько советов?",
    ["女士，您是？"] = "Мэм, вы кто?",
    ["女士，您知道什么时间开始接诊吗？"] = "Мэм, вы знаете, во сколько он начинает принимать пациентов?",
    ["女士，我想只有这些了。"] = "Мисс, боюсь, это всё.",
    ["女士，我认识您吗？"] = "Мэм, я вас знаю?",
    ["女士，虽然我不知道您经历了什么……但这儿的市场卖的东西也并非一无是处呀。"] = "Леди, хотя я не знаю, через что вам пришлось пройти... но вещи, продаваемые на этом рынке, не совсем бесполезны.",
    ["女士，这些花是我一大早从郊外采来的，新鲜得很！您给的价钱连成本都不够！"] = "Мадам, я собрал эти цветы в сельской местности рано утром. Они очень свежие! Цена, которую вы указали, даже не покрывает стоимость!",
    ["女士，需要帮助吗？"] = "Мэм, вам нужна помощь?",
    ["女孩向你道谢后，安静地转身离去。"] = "Поблагодарив вас, девушка тихо развернулась и ушла.",
    ["女孩服下了宁静药剂，身体仍痛苦地颤抖着。"] = "Девушка приняла глоток спокойствия, ее тело все еще дрожало от боли.",
    ["女神啊……那不是廷根富人区吗……怎么住到咱们这儿来了？"] = "Богиня... разве это не богатая местность Тинген... Почему ты приехала жить сюда с нами?",
    ["女神啊，你小心点！别为了那只猫把自己搭进去！"] = "Богиня, будь осторожна! Не убивай себя из-за этого кота!",
    ["女神啊，听听这说的是什么话？"] = "Богиня, да что за вздор он несет?!",
    ["女神啊，居然在这种地方遇见他，这太晦气了。"] = "Богиня, встретить его в таком месте, это такая неудача.",
    ["女神啊，居然在这种地方遇见她，这难道就是神给我指示，让我这次牢牢抓住她，不再放手？"] = "Богиня, встретиться с ней в таком месте, это знак Божий, говорящий мне на этот раз крепко держать ее и никогда не отпускать?",
    ["女神啊，我不会以后都吃不上午餐吧？"] = "Богиня, теперь я не смогу обедать, не так ли?",
    ["女神在上，那可是詹姆斯！“终结者”！"] = "Леди наверху, это Джеймс! «Терминатор»!",
    ["女神庇佑！谢谢你！"] = "Защита Богини! Спасибо!",
    ["女神庇佑，我想试试买下那对绿宝石耳坠呢……虽然这实在要花一点钱。"] = "Да защитит меня Богиня, я хочу попробовать купить эти изумрудные серьги... хотя они действительно стоят немалых денег.",
    ["女神？这里是风暴之主的地盘！这样吧，我再加一点价，但你也得理解我的难处。我们各退一步！"] = "Богиня? Это территория Повелителя Штормов! А как насчет этого, я немного подниму цену, но вы должны понимать мои трудности. Давайте оба сделаем шаг назад!",
    ["她……她是虫子？"] = "Она... она ошибка?",
    ["她、她是怎么突破学派的防线进来的？"] = "Как, как ей удалось прорваться через защиту школы и попасть внутрь?",
    ["她也很幸运……我很快就病死了，她被教会带走……后来，市场贩卖肉类的好心夫妻收养了她。"] = "Ей тоже очень повезло... Я вскоре умерла от болезни, и ее забрала церковь... Позже ее усыновила добрая пара, торговавшая мясом на рынке.",
    ["她会好起来的。她肯定会的。\n等我们攒够钱，我就带她去豪森医生的诊所。"] = "Она поправится. Обязательно поправится.\nКак только мы накопим достаточно денег, я отведу её в клинику доктора Хорсена.",
    ["她像只流浪猫，肮脏又危险，不知道哪天就会腐烂在下水道里。"] = "Она как бездомная кошка, грязная и опасная. Кто знает, когда она сгниет в канализации.",
    ["她出现的原因"] = "Причина ее появления",
    ["她唱着睡吧，睡吧，死神的羽翼垂下之时，我们收获美梦。"] = "Она пела: «Спи, спи, когда опустится крылья Бога Смерти, мы пожнем сладкие сны».",
    ["她在躲谁？"] = "От кого она прячется?",
    ["她尖叫着，撕扯着自己的头发，虫子一样翻滚在地。"] = "Она кричит, рвет на себе волосы, катаясь по земле, как червяк.",
    ["她就是内务大臣，梅。每年我们王国都只过一次生日，主角都是她。"] = "Она министр внутренних дел Мэй. Каждый год наше королевство празднует только один день рождения, и главным героем всегда является она.",
    ["她就是小黛西？我好像见过她……在黛西小姐的循环空间中，她拿着雏菊花奔跑在路上，但……"] = "Она Маленькая Дейзи? Кажется, я видел ее... в пространстве мисс Дейзи, она бежала по дороге с маргаритками в руках, но...",
    ["她并没有使用匕首“自杀”，锁门也不是关键线索，<P_Yellow>导致她“死亡”的直接因素是房间里的仪式魔法</>……"] = "Она не использовала кинжал для «самоубийства», и запертая дверь тоже не была ключевой зацепкой. <P_Yellow>Непосредственной причиной её «смерти» стала ритуальная магия в комнате</>...",
    ["她引诱孩子们的能力，应该是靠那根笛子释放的。"] = "Ее способность привлекать детей должна проявиться через эту флейту.",
    ["她很不幸，有我这样的妈妈，让她在下街的垃圾堆里长大。"] = "Ей не повезло с такой матерью, как я... Ей пришлось расти на свалках Нижней улицы.",
    ["她很厉害，很坚强，我输得心服口服。"] = "Она очень мощная и очень сильная. Я проиграл и принимаю это всем сердцем.",
    ["她很瘦，衣服又破又旧，连双鞋都没穿，这样的孩子在铁十字街太多了。我当时急着卖货，确实没细看。"] = "Она была очень худая, ее одежда была изорванной и старой, и на ней даже не было обуви. На Айрон-Кросс-стрит слишком много таких детей. Я тогда спешил продать свой товар, поэтому не присматривался.",
    ["她很聪明，才五岁，就会拾走市场的猪膀胱，卖给苦酒贩子……也会细心地帮我分类垃圾，把白色的废布料送去造纸厂，那能卖出更高的价钱。"] = "Она очень умна. Когда ей было всего пять лет, она забирала на рынке свиные пузыри и продавала торговцам горьким вином... Она также заботливо помогала мне сортировать мусор, отправляя обрезки белой ткани на бумажную фабрику, так как за них можно было получить более высокую цену.",
    ["她想和我一起生活，我想和她一起承担生活的狂风大雨。"] = "Она хотела жить со мной, а я хотел переносить вместе с ней жизненные бури.",
    ["她扔下一句话，说“这都是什么烂叶子！”，带着她那颗高傲的心走啦。"] = "Она бросила фразу: «Что это за гнилые листья!» и ушла с гордым сердцем.",
    ["她是个疯子，经常在角落里嘟囔一些毛骨悚然的话，还会无缘无故尖叫，连黑夜女神的祈祷词都无法令她安静哪怕十分钟。"] = "Она сумасшедшая, которая часто бормочет жуткие вещи по углам и кричит без причины. Даже молитва Богини Вечной Ночи не может заставить ее замолчать даже на десять минут.",
    ["她是什么"] = "Что она",
    ["她是？"] = "Кто она?",
    ["她曾是上流社会的宠儿，可自从她的丈夫破产后……唉，我们这寒酸地方如今成了她的归宿。"] = "Когда-то она была любимицей высшего света, но стоило ее мужу разориться... Эх, теперь эта убогая дыра стала ее последним пристанищем.",
    ["她有一个好赌的父亲，让家里欠了很多钱，她只好自己出来打工……"] = "У нее отец-игрок, из-за которого семья задолжала кучу денег, поэтому ей пришлось самой пойти на работу...",
    ["她有很多、很多的故事，要告诉你。"] = "Она может рассказать вам много, много историй.",
    ["她没有恶意，又或许……"] = "Она не замышляет дурного, или, возможно...",
    ["她牺牲在一次任务中，和阿诺德的爸爸一样，也跟许多值夜者一样。"] = "Она пожертвовала собой во время квеста, как и отец Арнольда, и как многие другие Ночные Ястребы.",
    ["她现在属于贝克兰德教区，值夜者不能随便离开自己辖区，这你应该清楚。"] = "Сейчас она относится к Бэкландской епархии. Ночные Ястребы не могут самовольно покидать свой округ, ты должен это понимать.",
    ["她的丈夫和孩子在几年前的战争中去世了，只剩下她和那条叫劳拉的狗，去哪儿都要一起。"] = "Ее муж и ребенок погибли на войне несколько лет назад. Теперь остались только она и собака по имени Лора, и они повсюду ходят вместе.",
    ["她的丈夫牺牲后，她致力于推动退伍士兵的福利事业，也成为了俱乐部的重要成员……"] = "После того, как ее муж пожертвовал собой, она посвятила себя улучшению благосостояния отставных солдат, а также стала важным членом клуба...",
    ["她的声音很平静，像是在讲睡前故事。"] = "Ее голос очень спокойный, как будто рассказывает сказку на ночь.",
    ["她真是我们的榜样，我会一直支持她。"] = "Она действительно наш образец для подражания. Я всегда поддержу ее.",
    ["她说搭配的衣服？"] = "Она говорила об одежде под стать?",
    ["她说，很久很久以前，在东方的东方，生活着一群巨人……"] = "Она сказала, что давным-давно на востоке востока жила группа гигантов...",
    ["她跟我一样，都是孤儿。我想，她是想跟我做朋友。她很温柔，会认真地跟我学妈妈的歌……"] = "Она такая же сирота, как и я. Я думаю, она хочет со мной дружить. Она очень нежная и будет усердно учиться у меня маминой песне...",
    ["她通常什么时候会消失？"] = "Когда она обычно исчезает?",
    ["好……"] = "Хорошо...",
    ["好……痛……好痛……"] = "Так... больно... так больно...",
    ["好……这是我最后能为你们做的事……"] = "Ладно... это последнее, что я могу для тебя сделать...",
    ["好、好的，谢谢您的关心，我会考虑的。"] = "О-окей, спасибо за беспокойство. Я рассмотрю это.",
    ["好、好的，长官！"] = "Да-да, сэр!",
    ["好。"] = "Хорошо.",
    ["好。我先把这本资料还回去，然后马上出发。"] = "Хорошо. Сначала я верну этот документ, и мы немедленно уедем.",
    ["好不容易熬出头了，孩子也有了体面的工作，谁能想到……那场该死的大雾霾……"] = "Наконец-то они справились, и у ребенка появилась достойная работа, кто бы мог подумать... этот чертов Великий Смог...",
    ["好久不见，卡萝队长。"] = "Давно не виделись, капитан Кэрол.",
    ["好了好了，我知道你心仪的嘉宾是谁，当然也给她寄了邀请函，但是还没有收到回复。"] = "Хорошо, хорошо, я знаю, кто твой желанный гость. Я, конечно, отправил ей приглашение, но ответа пока не получил.",
    ["好了，我明白。"] = "Хорошо, я понимаю.",
    ["好了，爱德华，再分几个硬币给可怜的布莱特，让他祛祛身上的霉味。"] = "Хорошо, Эдвард, дай бедному Брайту еще несколько монет, чтобы он избавился от заплесневелого запаха.",
    ["好了，线索收集得差不多了，该回黑荆棘问问小阿诺德关于他这位“朋友”的事了。"] = "Хорошо, улики в основном собраны. Пришло время вернуться в Чёрный Чертополох и расспросить маленького Арнольда о его «друге».",
    ["好些孩子？嗯……那再多给你一些。"] = "Много детей? Хм... тогда дам тебе еще немного.",
    ["好任性"] = "Так своенравно",
    ["好像……一旦有大人靠近，她就不见了。"] = "Кажется... как только взрослый приближается, она исчезает.",
    ["好像……这杯没有什么特殊的感觉？"] = "Кажется... эта чашка не вызывает каких-то особенных ощущений?",
    ["好像在……画画？他不让我看，连靠近都不行！"] = "Похоже на... рисование? Он не позволяет мне ни посмотреть, ни даже приблизиться!",
    ["好像是的，但你已经画得很好了。"] = "Вроде так, но вы уже очень хорошо нарисовали.",
    ["好像有人在争吵……听听发生了什么吧。"] = "Кажется, кто-то спорит... Давайте послушаем, в чем дело.",
    ["好别扭的家伙，让我亲自去给这家伙好好上一课！"] = "Какой неуклюжий парень, позволь мне пойти и самому преподать ему хороший урок!",
    ["好可怜的小女孩，她瘦得像一根即将被风吹折的秸秆。"] = "Такая жалкая маленькая девочка, она тонкая, как стебель соломы, который вот-вот сломает ветер.",
    ["好可爱的狗狗。"] = "Какая милая собака.",
    ["好吧……但你得快点儿，它看起来挺害怕的。"] = "Хорошо... но надо действовать быстро, он выглядит очень напуганным.",
    ["好吧……现在的年轻人真是缺乏进取精神。唉，末日可怎么办……"] = "Ладно... современной молодежи очень не хватает духа предприимчивости. Эх, что будет с апокалипсисом...",
    ["好吧……那这只猫，呃，我是说可敬的露娜女士，它要怎么为我们验证非凡材料的真伪呢？"] = "Ладно... Но как эта кошка, э-э, то есть достопочтенная мисс Луна, проверит для нас подлинность Потусторонних материалов?",
    ["好吧。"] = "Отлично.",
    ["好吧，不过我还是建议你买条咸鱼，毕竟它有着很神奇的寓意，罗塞尔大帝一直都说咸鱼翻身！"] = "Хорошо, но я все же предлагаю вам купить соленую рыбку. Ведь это имеет очень магическое значение; Император Розель всегда говорил: «Соленая рыба может перевернуться!»",
    ["好吧，你要是回心转意了就再来找我。"] = "Хорошо, вернись ко мне, если передумаешь.",
    ["好吧，原来是扶老奶奶过马路的好心人。辛苦了。"] = "Итак, это был добрый человек, который помог пожилой женщине перейти улицу. Спасибо за ваш тяжелый труд.",
    ["好吧，我明白了，你就是不想上班。奇了怪了，你怎么还没被开除？"] = "Ладно, всё понятно: ты просто не хочешь работать. Ума не приложу, как тебя до сих пор не уволили?",
    ["好吧，我明白，但……大人，我从来没有做过任何称得上不好的事。"] = "Хорошо, я понимаю, но... сэр, я никогда не делал ничего, что можно было бы назвать плохим.",
    ["好吧，真是遗憾。"] = "Ладно, как жаль.",
    ["好吧，还说和你比上一局。"] = "Хорошо, я надеялся провести с тобой матч.",
    ["好吧，那12苏勒……10苏勒也行，喂，别急着走啊！"] = "Хорошо, тогда 12 суле... 10 суле вполне, эй, не спеши уходить!",
    ["好呀，不过今天它们都睡着啦，改天，改天{{大哥哥|大姐姐}}我带你和它们认识认识！"] = "Конечно, но они сегодня все спят. Когда-нибудь, когда-нибудь, {{big brother|big sister}}, я познакомлю тебя с ними!",
    ["好呀，不过今天它们都睡着啦，改天，改天我带{{大哥哥|大姐姐}}和它们认识认识！"] = "Конечно, но они сегодня все спят. В другой раз, в другой раз я приведу им на встречу {{big brother|big sister}}!",
    ["好呀，我们拉钩，一言为定！"] = "Ладно, давай мизинец поклянемся, это сделка!",
    ["好啦，那这次的紧急会议就结束了，我们等你们的好消息，国王、外交大臣。"] = "Что ж, на этом экстренное заседание окончено. Мы ждем от вас добрых вестей, ваше величество, господин министр иностранных дел.",
    ["好喔。"] = "Хорошо.",
    ["好困……好累……我要休息了……"] = "Так хочется спать... так устал... Мне нужно отдохнуть...",
    ["好在大帝从不欠薪水……"] = "По крайней мере, Император никогда никому не был должен зарплату...",
    ["好在祂的灌输多少也有些有用的知识，嗯……需要整理整理……"] = "К счастью, Его идеологическая обработка действительно содержит некоторые полезные знания. Хм... Мне нужно это организовать...",
    ["好大的广告页。广告连廷根都做到了，销售面还挺广的。"] = "Какая большая рекламная страница. Реклама дошла даже до Тингена; охват продаж довольно широк.",
    ["好夸张的成长速度，你是个真正的天才……已经比当初的我强大很多了。"] = "Какой преувеличенный темп роста. Ты настоящий гений... Ты уже намного сильнее, чем я был тогда.",
    ["好奇艾登的身份"] = "Интерес к личности Эйдена",
    ["好奇辨认"] = "Любопытно идентифицировать",
    ["好心人可以帮我捉一下老鼠吗？"] = "Может ли добрый человек помочь мне поймать мышей?",
    ["好心安慰"] = "Добрый комфорт",
    ["好心的{{先生|女士}}，多给点吧……还有好些个孩子没饭吃……"] = "Добрый {{сэр|мисс}}, подайте еще хоть немного... у нас дома дети голодают...",
    ["好心的先生，可以给我一根火柴吗……"] = "Добрый сэр, не найдется ли у вас спички?..",
    ["好暴躁的男人，接下来，我们应该……"] = "Какой сварливый человек. Дальше нам следует...",
    ["好极了！请在心里默默记住你的年龄，不用告诉我，这毕竟是个人隐私。"] = "Отличный! Пожалуйста, про себя вспомните свой возраст, не нужно мне говорить, ведь это личная тайна.",
    ["好消息是，谜虫看起来也有些恍惚。"] = "Хорошей новостью является то, что Таинственное Насекомое тоже кажется немного ошеломленным.",
    ["好状态挺精神的我呀。"] = "Мое психическое состояние вполне хорошее.",
    ["好狗狗！"] = "Хорошая собака!",
    ["好疼……我想回家……我想回家……"] = "Больно... Я хочу домой... Я хочу домой...",
    ["好痛苦，快一点、让尤朵拉解脱吧。"] = "Это так больно, поторопись, дай Йодоре свободу.",
    ["好的"] = "Хорошо",
    ["好的。"] = "Хорошо.",
    ["好的。这也算回答了一个问题吗？"] = "Хорошо. Это тоже считается за ответ?",
    ["好的服装一定要规避顾客的劣势，而张扬其身材和气质的优势与特殊性。在这一点上，我们服装店是全廷根做得最好的。<P_Heart>（自豪）</>"] = "Хорошая одежда должна избегать недостатков покупателя, подчеркивая достоинства и уникальность его фигуры и темперамента. В этом плане наш магазин одежды лучший во всем Тингене. <P_Heart> (Гордый) </>",
