    ["感觉到了吗？"] = "Вы это чувствуете?",
    ["感觉怎么样，还记得自己是谁吗？"] = "Как ты себя чувствуешь? Помнишь, кто ты?",
    ["感觉最近运势不太好，是不是要去占卜俱乐部占卜一下。"] = "Я чувствую, что в последнее время мне не везет. Стоит ли мне пойти в Клуб гадания на чтение?",
    ["感觉有点超出我的实际需求了。"] = "Кажется, это немного превосходит мои реальные потребности.",
    ["感觉离开很长时间了……明明不久前才被调去贝克兰德教区。"] = "Такое ощущение, что меня долго не было... хотя меня перевели в Баклундскую епархию совсем недавно.",
    ["感谢你朋友！为我收集了所有的音符。"] = "Спасибо, друг! Ты собрал для меня все ноты.",
    ["感谢你的好意，这就不必了。"] = "Спасибо за вашу доброту, но в этом нет необходимости.",
    ["感谢你的帮助。下次从新白银城回来，我会给你带一包牛奶蘑菇做的奶糖。"] = "Спасибо за помощь. В следующий раз, когда я вернусь из Нью-Сильвер-Сити, я принесу тебе пакет молочных конфет из груздей.",
    ["感谢你的慷慨。"] = "Спасибо за вашу щедрость.",
    ["感谢你的推荐。"] = "Благодарю за рекомендацию.",
    ["感谢你的提醒。"] = "Спасибо за напоминание.",
    ["感谢你，善良的{{先生|女士}}，愿女神眷顾你。"] = "Спасибо, добрый {{ Mr. | Ms. } }, пусть Богиня благословит тебя.",
    ["感谢你，小{{PlayerName}}。也请你多加小心，无论失去哪一位同伴，对于我们来讲都是同等沉痛的打击。"] = "Спасибо тебе, {{PlayerName}}. Пожалуйста, будь осторожнее: потеря любого товарища станет для нас одинаково тяжким ударом.",
    ["感谢你，朋友！为我收集了所有的音符。"] = "Спасибо, друг! Ты собрал для меня все ноты.",
    ["感谢你，真的很感谢。"] = "Спасибо, правда, спасибо.",
    ["感谢您。"] = "Спасибо.",
    ["感谢您的介绍，您知道乔纳尔医生家在哪里吗？"] = "Спасибо за разъяснения. Вы не знаете, где живёт доктор Джонар?",
    ["感谢您的宽容和理解，会长女士。"] = "Спасибо за вашу терпимость и понимание, госпожа Президент.",
    ["感谢您的宽容和理解，会长女士。这是我带回的封印物。"] = "Спасибо за вашу терпимость и понимание, госпожа Президент. Это запечатанный артефакт, который я принес.",
    ["感谢您的帮助。"] = "Спасибо за помощь.",
    ["感谢您的提醒。"] = "Благодарю за напоминание.",
    ["感谢您的教诲。"] = "Благодарю вас за наставление.",
    ["感谢您的教诲！"] = "Благодарю за наставления!",
    ["感谢您的祝福！"] = "Спасибо за ваше благословение!",
    ["感谢您的认同，这些观点只是我在故乡经常听到的一些想法。"] = "Спасибо за ваше признание. Эти взгляды — лишь некоторые идеи, которые я часто слышал в своем родном городе.",
    ["感谢您的说明，希罗多德先生。"] = "Благодарю за объяснение, мистер Геродот.",
    ["感谢您的鼓励，会长女士。"] = "Спасибо за вашу поддержку, госпожа Президент.",
    ["感谢黛西小姐的仁慈，她还没有苏醒吗？"] = "Благодаря милосердию мисс Дейзи, она еще не проснулась?",
    ["愿大地庇佑你！"] = "Пусть Земля защитит вас!",
    ["愿女神庇佑他们！"] = "Да благословит их Богиня!",
    ["愿女神庇佑你我。"] = "Пусть Богиня защитит тебя и меня.",
    ["愿女神庇佑你！"] = "Да хранит тебя Богиня!",
    ["愿女神的力量帮助我们在现下的危机中挽救廷根，愿未能免于受难的人们能在神国中得到安眠。"] = "Пусть сила Богини поможет нам спасти Тинген от нынешнего кризиса, и пусть те, кого не удалось избавить от страданий, найдут сон в Царстве Божием.",
    ["愿女神祝福你。"] = "Пусть Богиня благословит вас.",
    ["愿愚者庇佑你！"] = "Да пребудет с тобой Благословени Шута!",
    ["愿蒸汽庇佑你！"] = "Пусть пар благословит вас!",
    ["愿风暴庇佑你！"] = "Пусть Буря защитит тебя!",
    ["愿黑夜庇佑你！"] = "Пусть Ночь защитит тебя!",
    ["懂事的小珍妮，一定是怕我看到后伤心，才拖着虚弱的身体跑到了这么远的地方……"] = "Разумная маленькая Дженни, должно быть, боялась, что мне станет грустно, если я ее увижу, поэтому она утащила свое слабое тело так далеко...",
    ["成为值夜者？"] = "Стать Ночным Ястребом?",
    ["成为自己？"] = "Стать самим собой?",
    ["成交！你们什么时候出航？"] = "Иметь дело! Когда ты отправляешься в плавание?",
    ["成功了！"] = "Успех!",
    ["我……"] = "Я...",
    ["我……不……能……输……给……老……人……"] = "Я... не могу... проиграть...... старику... человеку...",
    ["我……不，我们承受了千万次的知识灌输，为了那个答案，不断地死去。"] = "Я... нет, мы пережили тысячи вливаний знаний, постоянно умирая за этот ответ.",
    ["我……不，我们，承受了千万次的知识灌输，不断孕育，不断诞生，不断死去。"] = "Я… нет, мы пережили тысячи идеологических манипуляций, постоянно вынашиваясь, постоянно рождаясь, постоянно умирая.",
    ["我……我不知道。但叔叔阿姨告诉我，只要我向女神祈祷一百天，噢不，是一千天，布鲁斯的病就会好起来的。"] = "Я... я не знаю. Но мои тетя и дядя сказали мне, что если я буду молиться Богине сто дней, о нет, тысячу дней, болезнь Брюса поправится.",
    ["我……我们也有自己的游戏，只是和你们的不太一样。"] = "Я... у нас тоже есть свои игры, только не такие, как у тебя.",
    ["我……我们会开王国会议讨论。"] = "Я... мы проведем собрание королевства, чтобы обсудить это.",
    ["我……我会去尝试的！谢谢你！"] = "Я... я попробую! Спасибо!",
    ["我……我可以吗？"] = "Я... можно?",
    ["我……我实在不知道自己能做什么。"] = "Я... я правда не знаю, что я могу сделать.",
    ["我……我把我的女儿小艾琳弄丢了。你能帮帮我吗？"] = "Я... я потерял свою дочь, маленькую Ирен. Вы можете помочь мне?",
    ["我……我等会要去和莱丝莉约会，您有什么推荐的吗？"] = "Я... я позже иду на свидание с Лесли, у тебя есть какие-нибудь рекомендации?",
    ["我……我绝对不会忘记……你提过的东大陆！一定存在的西大陆！"] = "Я... я никогда не забуду... упомянутый вами Восточный континент! Западный континент, который должен существовать!",
    ["我……有做得像你一样好吗？"] = "Я... справился так же хорошо, как ты?",
    ["我……真的可以吗？"] = "Я... правда справлюсь?",
    ["我、我只是来帮忙的，我不知道……"] = "Я, я здесь, чтобы помочь, я не знаю...",
    ["我一定会去拜读的。"] = "Я обязательно прочту это.",
    ["我一定会把她带回来的。"] = "Я обязательно верну ее.",
    ["我一直四处寻找他。这首曲子，是我写给他的，他从小就听我吹奏。"] = "Я искал его повсюду. Эту песню я написал для него; он слушал, как я играю, с тех пор, как был маленьким.",
    ["我一直在争取增加藏书预算，也在联系一些愿意捐书的上等人。希望总有一天，这里会有看不完的书。"] = "Я стремлюсь увеличить бюджет на книги, а также связываюсь с некоторыми высококлассными людьми, готовыми пожертвовать книги. Я надеюсь, что однажды здесь будет бесконечное количество книг для чтения.",
    ["我一直带在身上。你是说……用警官身份介入调查？"] = "Оно у меня с собой. Ты имеешь в виду... вмешаться в расследование как офицер полиции?",
    ["我一辈子都不可能像那些小姐一样，住大房子，穿亮晶晶的衣服，吃漂亮点心，是不是？"] = "Я никогда не буду такой, как те дамы, живущие в больших домах, носящие блестящую одежду и поедающие изысканные десерты, верно?",
    ["我下次一定好好复习少出去玩，下次一定！"] = "Я определенно буду усердно учиться и в следующий раз меньше выходить на улицу. Я обещаю!",
    ["我不一样，他们都是笨蛋！"] = "Я другой; они все идиоты!",
    ["我不在乎这些。但扣除风险费，我只能出2000便士，海上的客人也不都是傻子。"] = "Меня это не волнует. Но после вычета комиссии за риск я могу предложить только 2000 копеек. Гости с моря не все дураки.",
    ["我不害怕，妈妈曾告诉过我，她会成为星星守护我的。"] = "Я не боюсь. Мама однажды сказала мне, что станет звездой, чтобы защитить меня.",
    ["我不想和尤斯塔斯一块打牌，他打牌的技术太糟糕了，他还可能随时睡着。"] = "Я не хочу играть в карты с Юстасом. Он ужасно играет, да ещё и может уснуть в любой момент.",
    ["我不想和杰尼玩了，他总跑这么慢。"] = "Я больше не хочу играть с Дженни, он всегда так медленно бегает.",
    ["我不提倡沉溺于酒精，但是辛苦一天后来这里喝一杯，放松一下，还是很需要的。"] = "Я не призываю злоупотреблять алкоголем, но после тяжелого дня прийти сюда выпить и расслабиться все равно очень необходимо.",
    ["我不擅长做饭"] = "Я не умею готовить",
    ["我不是保罗。"] = "Я не Пол.",
    ["我不是怪物！<P_Yellow>贝尔纳黛殿下</>……我不是怪物……我不是怪物！"] = "Я не монстр! <P_Yellow> Ее Высочество Бернадетта </>... Я не монстр... Я не монстр!",
    ["我不是非常懂服装，能聊聊量身定制吗？"] = "Я не особо разбираюсь в одежде, можем ли мы поговорить о индивидуальном пошиве?",
    ["我不清楚姐姐身上到底发生了什么，但她真的消失了，而那些人都在说谎！他们说她不存在，那是我的姐姐，她怎么可能不存在！！"] = "Я не знаю, что случилось с моей сестрой, но она действительно исчезла, а эти люди все врут! Говорят, ее не существует, но она моя сестра, как она могла не существовать!!",
    ["我不相信你"] = "я тебе не верю",
    ["我不知道。"] = "Я не знаю.",
    ["我不知道，他最近老说些我不懂的事情，什么控制风、召唤雨之类的。"] = "Я не знаю. В последнее время он говорит вещи, которых я не понимаю, например, управление ветром, вызов дождя и так далее.",
    ["我不知道，妈妈好几天没回家。早上我还没醒，突然有人闯进家里，把我赶出来了。"] = "Я не знаю, мамы не было дома уже несколько дней. Не успел я проснуться этим утром, как кто-то внезапно ворвался в дом и выгнал меня.",
    ["我不要打架啊！根本赢不了……"] = "Я не хочу драться! Мне ни за что не победить...",
    ["我不记得了，嘿嘿，脑子里乱七八糟的。"] = "Я не помню, хе-хе, у меня в голове бардак.",
    ["我不这么觉得，这会破坏它们的风味……"] = "Я так не думаю, это испортит их вкус...",
    ["我不！"] = "Я не буду!",
    ["我与那位非凡者见过，他的气息诡异又古怪，但序列似乎并不高，估计在序列九或八左右。"] = "Я встретил этого Потустороннего. Их аура жуткая и странная, но их Последовательность не кажется высокой — скорее всего, около Последовательности 9 или 8.",
    ["我为她们每个人送上来自因蒂斯的黄水仙，祈求那些美丽小姐的垂怜。"] = "Каждому из них я дарю желтый нарцисс от Интиса, молясь за благосклонность этих прекрасных дам.",
    ["我主要治疗孩子们生长发育时会遇到的种种问题……"] = "В основном я занимаюсь различными проблемами, с которыми сталкиваются дети в процессе роста и развития...",
    ["我乘上了前往南大陆的船只，驶入了险流无数的狂暴海。"] = "Я сел на корабль, направлявшийся на Южный континент, и поплыл в Море Берсерка, в котором бесчисленное множество опасных течений.",
    ["我也一直这么认为的，在活着的时候去做想做的事，不要临死前有所遗憾！"] = "Я тоже всегда так думал. Делай то, что хочешь, пока жив, и не жалей ни о чем перед смертью!",
    ["我也不记得以前了，我也感受过被人帮助的温暖。我理解你的感受，但是……"] = "Я тоже не помню прошлого, и я также чувствовал теплоту помощи. Я понимаю, что ты чувствуешь, но...",
    ["我也完全理解你即将做出的决定。但在这之前，我想邀请你再闻闻雏菊的芬芳。"] = "Я также полностью понимаю решение, которое вы собираетесь принять. Но перед этим я хотел бы предложить вам еще раз почувствовать аромат ромашки.",
    ["我也希望，小黛西能特殊地“活下去”。但按照我们对封印物的管理守则，我必须带回3-888。"] = "Я тоже надеюсь, что малышка Дейзи сможет жить дальше — пусть и таким необычным образом. Но согласно нашим правилам обращения с Запечатанными Артефактами, я обязан вернуть 3-888.",
    ["我也很难过……但我不得不带回封印物，让他们接受应有的惩罚。"] = "Мне тоже очень грустно... Но мне пришлось вернуть Запечатанный Артефакт и позволить им принять заслуженное наказание.",
    ["我也很难过……我虽然带回了封印物，却不忍心浇灭丽埃娜最后的希望。"] = "Мне тоже очень грустно... Хоть я и вернул Запечатанный Артефакт, я не смог уничтожить последнюю надежду Лианы.",
    ["我也很难过，丽贝卡……我把封印物3-888留给丽埃娜也是暂时的决定。"] = "Мне тоже очень грустно, Ребекка... Оставить Лиане Запечатанный Артефакт 3-888 - тоже временное решение.",
    ["我也才加入俱乐部不久，但听说她正在周游世界寻找新的甜品灵感呢！"] = "Я и сам вступил в клуб не так давно, но слышал, что она путешествует по свету в поисках вдохновения для новых десертов!",
    ["我也是这么希望的，我也要成为高空杂技演员，去莱斯马戏团，让我老爸看到。"] = "Я тоже на это надеюсь! Я обязательно стану воздушным акробатом, попаду в цирк Рейса, и папа меня увидит.",
    ["我也曾是“窥秘人”，我知道你在忍受什么，所以，我能帮你。"] = "Я тоже когда-то был таинственным священником. Я знаю, что ты терпишь, поэтому могу помочь тебе.",
    ["我也有个朋友"] = "у меня тоже есть друг",
    ["我也来帮忙找找线索。"] = "Я тоже помогу искать улики.",
    ["我也要等到老特勒被找到才能回到圣赛琳娜教堂。"] = "Мне также придется подождать, пока не найдут Старого Теллера, прежде чем я смогу вернуться в собор Святой Селены.",
    ["我也这么觉得，这里的每一个设计我都很喜欢！"] = "Я тоже так думаю, мне здесь нравится каждый дизайн!",
    ["我也这样跟邓恩说过，但他似乎听不进去。"] = "Я говорил Данну то же самое, но он, похоже, не слушал.",
    ["我书包里还有三块奶油硬糖！都给您！其实妹妹打碎花瓶那次……是我干的！还有小狗哈尼，它没有偷吃土豆……"] = "У меня в школьной сумке до сих пор лежат три леденца с кремом! Они все для тебя! На самом деле, когда моя сестра разбила вазу... это был я! А щенок Милый, он картошку не крал...",
    ["我今天涂了新的口红，好看吗？"] = "Я сегодня накрасила губы новой помадой, красиво?",
    ["我从上面学到了不少。"] = "Я многому научился из этого.",
    ["我以为你更擅长的是魔镜占卜？或许你能教教可怜的小默里，他翻书都要翻出火星了。"] = "Я думал, ты лучше разбираешься в гадании по Волшебному зеркалу? Возможно, ты сможешь научить бедного маленького Мюррея; он собирается перелистывать свои книги, пока не полетят искры.",
    ["我以前……我以前可是在金梧桐区数得上的有钱人，海岸线餐厅老板得请我进去吃饭！"] = "Раньше я... Раньше я был известным богатым человеком в районе Императрицы. Владельцу ресторана «Береговая линия» пришлось пригласить меня на ужин!",
    ["我以女神的名义发誓！我绝对是在清醒的状态下写的！"] = "Клянусь именем Богини! Я был абсолютно трезв, когда писал это!",
    ["我们一直希望学派在教授非凡能力之外，也成为所有人在这个世界不变的归所。"] = "Мы всегда надеялись, что помимо обучения выдающимся способностям школа также станет постоянным домом для каждого в этом мире.",
    ["我们一起……回家……"] = "Мы пойдем... домой... вместе...",
    ["我们一起记？万一到时候有意外，我也许能帮上忙。"] = "Запишем это вместе? Если случится авария, я смогу помочь.",
    ["我们不像那些政治或商业俱乐部，需要正式成员的推荐才能加入，只要填写详细资料，缴纳会员年费。初次是150镑，之后每年50镑。"] = "В отличие от тех политических или коммерческих клубов, которые требуют рекомендаций от формальных членов, вам нужно только заполнить подробную информацию и оплатить ежегодный членский взнос. В первый раз это 150 фунтов, а в дальнейшем — 50 фунтов.",
    ["我们也会玩捉迷藏，还有打弹珠……这些游戏也挺有趣的。"] = "Еще мы играем в прятки и шарики... эти игры тоже очень веселые.",
    ["我们也是可怜虫，看着队友们牺牲，直到最后自己也走进黑夜。"] = "Мы также бедняки, наблюдающие, как наши товарищи по команде жертвуют собой, пока в конце концов сами не уходим во тьму.",
    ["我们会去向这些人查证。现在，你需要停止售卖这些玫瑰，并告诉我们你的玫瑰是从哪里采摘的。"] = "Мы пойдем и сверимся с этими людьми. А пока вам нужно прекратить продажу этих роз и рассказать нам, где они были собраны.",
    ["我们伟大的拉斯廷伯爵牺牲在了这场战争里，他的名字就是哈罗德。"] = "Наш великий граф Ластинг отдал свою жизнь в этой войне, и звали его Гарольд.",
    ["我们做这个行当还是需要“大人物们”照拂的。"] = "Чтобы работать в этом бизнесе, нам все еще нужна защита «больших шишек».",
    ["我们偶尔也会接点额外的委托，不管是找人还是当保镖，也是有可能涉及到超凡力量的。"] = "Время от времени мы берем дополнительные заказы, будь то поиск людей или работа телохранителями, но также возможно, что они связаны со сверхъестественными способностями.",
    ["我们公司的招牌十分特殊，偶尔还会有额外经费。"] = "Вывеска нашей компании очень особенная, и иногда появляются дополнительные средства.",
    ["我们努力尝试过，但无法拯救她、也不忍心毁灭她。去送她最后一程吧，她理应在黑夜的神国里获得长眠。"] = "Мы очень старались, но не смогли ее спасти и не смогли уничтожить. Иди и проводи ее в последний путь; она заслуживает того, чтобы найти сон в Царстве Ночи.",
    ["我们去看看。"] = "Пойдем посмотрим.",
    ["我们去看看吧。"] = "Пойдем посмотрим.",
    ["我们发现你正在售卖一些危险物品，黑夜协会现在正式介入对你的调查，黛西小姐。"] = "Мы обнаружили, что вы продаете опасные предметы. Церковь Вечной Ночи официально начинает расследование в отношении вас, мисс Дейзи.",
    ["我们可以把你刚刚吹奏的这段旋律记录下来，共同创作一首乐曲。"] = "Мы можем записать мелодию, которую вы только что сыграли, и вместе создать музыкальное произведение.",
    ["我们可是自营农场，不像隔壁的某个摊主，伪装自己信仰大地母神，结果满口谎话！您可得小心点，{{先生|女士}}。"] = "У нас собственная ферма, не то что у того торговца по соседству: притворяется верующим в Мать-Землю, а сам нагло врёт на каждом шагу! Будьте осторожны, {{сэр|мэм}}.",
    ["我们可没有多余的钱。<P_Heart>（小声笑）</>要什么大智慧？雇主太太心情好才是要紧事。"] = "У нас нет лишних денег. <P_Heart> (тихо смеется) </> Что за великая мудрость? Главное – сохранить хорошее настроение хозяйке.",
    ["我们在廷根也算幸运，躲过了这一切。"] = "Нам в Тингене повезло, что мы избежали всего этого.",
    ["我们家乡也有对传统草药的研究。"] = "В нашем родном городе также проводятся исследования традиционных трав.",
    ["我们对铁十字街很熟悉，能帮您找人和送信，需要吗？"] = "Мы хорошо знакомы с улицей Айрон-Кросс и можем помочь вам найти людей или доставить письма. Вам это нужно?",
    ["我们当然可以偶尔点其他餐厅的食物，但是也许有些东西……是没办法替代的。"] = "Мы, конечно, можем время от времени заказывать еду в других ресторанах, но, возможно, некоторые вещи... невозможно заменить.",
    ["我们得来的钱，有几便士是能留给自己的呢？"] = "Сколько копеек из денег, которые мы зарабатываем, мы можем оставить себе?",
    ["我们愿意让小黛西以特殊的方式“活着”，你一定也认同这种做法？"] = "Мы хотим позволить Маленькой Дейзи «жить» по-особому. Вы должны согласиться с таким подходом, верно?",
    ["我们把诚信看得比什么都重要，胜过兄弟、钱，还有手上的酒。"] = "Мы ценим честность превыше всего — больше, чем братьев, деньги или выпивку в наших руках.",
    ["我们把那东西一路逼到这，凯蒂妮她们在里面收尾。"] = "Мы преследовали эту штуку всю дорогу, а Кэти и остальные убираются внутри.",
    ["我们掘墓人是世袭的，当然会知道这些事情，有什么好害怕的，反正迟早都要躺到墓穴里。"] = "Мы, могильщики, по наследству, поэтому, конечно, знаем об этих вещах. Чего тут бояться? Все равно рано или поздно мы все окажемся в могиле.",
    ["我们收到可靠情报，金梧桐连环杀人案的凶手出没在恶龙酒吧附近，务必要对酒吧内的人进行重新排查。"] = "Мы получили достоверные сведения о том, что виновник серийных убийств в Золотом Вязе скрывается возле бара ««Злой Дракон»». Крайне важно повторно проверить всех, кто находится в баре.",
    ["我们是伪装成安保公司的值夜者小队，专门处理超凡事件，这是你已经知道的。"] = "Мы — отряд «Ночных Ястребов», замаскированный под охранную компанию, специализирующийся на урегулировании сверхъестественных событий. Это то, что вы уже знаете.",
    ["我们是守护者，守护廷根市民每一个宁静的夜晚。"] = "Мы — Стражи, защищающие каждую мирную ночь жителей Тингена.",
    ["我们是安保公司，不是冒险者公会。"] = "Мы охранная компания, а не гильдия искателей приключений.",
    ["我们是廷根的老牌餐厅，味道和价格都是没得说。"] = "Мы – давний ресторан в Тингене; вкус и цена безупречны.",
    ["我们是水仙花街上最好的餐厅。"] = "Мы лучший ресторан на улице Даффодил.",
    ["我们是流浪儿。内务大臣是我们之中唯一知道自己生日的人，她的妈妈死前把生日缝在了襁褓里。"] = "Мы беспризорные дети. Министр внутренних дел — единственный из нас, кто знает день своего рождения; ее мать перед смертью зашила день рождения в пеленки.",
    ["我们是警察，来调查小艾恩失踪的事，请问他的家人呢？"] = "Мы из полиции, расследуем исчезновение маленького Эна. Скажите, где его родные?",
    ["我们是警察，这里曾收留过一个叫尤朵拉的孤儿，对吗？"] = "Мы полиция, и сюда забрали сироту по имени Юдора, верно?",
    ["我们曾经有两位具备特殊报销技巧的同事。可惜你不认识他们，否则他们可以教你不少东西。"] = "Когда-то у нас были двое коллег, владевших особым талантом списывать любые расходы. Жаль, ты с ними не знаком, а то они могли бы многому тебя научить.",
    ["我们最终会在黑夜的神国里相聚。"] = "В конце концов мы встретимся в Королевстве Богини Вечной Ночи.",
    ["我们有些延续了好多年的传统，比如有新的正式成员加入时，会一起去老维尔餐厅吃一顿……"] = "У нас есть некоторые традиции, которые сохраняются уже много лет, например, когда присоединяется новый официальный участник, мы вместе идем в ресторан Old Will's, чтобы пообедать...",
    ["我们有好几种路线可供选择，您可以仔细看看。"] = "У нас есть несколько маршрутов на ваш выбор. Вы можете внимательно посмотреть.",
    ["我们本来可以在湖畔过个好生日的，现在只能在垃圾堆里庆祝了。"] = "Мы могли бы хорошо провести день рождения на берегу озера, но теперь можем праздновать только среди кучи мусора.",
    ["我们本来就在一个疯狂的世界，像邓恩、戴莉这些强者也都回归女神的拥抱了。"] = "Мы уже находимся в сумасшедшем мире. Даже такие сильные мира сего, как Данн и Дейли, вернулись в объятия Богини.",
    ["我们正企图在混沌的世界里建立起秩序，如同行走于空中钢缆。如今人类所作所为，是必要的改变，还是无意义的自我约束？"] = "Мы пытаемся навести порядок в хаотичном мире, словно ходим по стальному тросу в воздухе. Является ли то, что сейчас делает человечество, необходимым изменением или бессмысленным самоограничением?",
    ["我们正在清理卫生，公司里到处都是灰尘和杂物，大家怎么也学不会将东西放在它们应该在的位置上！"] = "Мы убираемся; В компании повсюду пыль и беспорядок, и кажется, что все просто не могут научиться класть вещи на свои места!",
    ["我们每个月至少会请一位有名的占卜者来讲课，来解答疑难。"] = "Каждый месяц мы приглашаем хотя бы одного известного прорицателя прочитать лекцию и ответить на сложные вопросы.",
    ["我们没办法让她苏醒，只能靠一些仪式来维持微弱的生命。"] = "У нас нет возможности разбудить ее, и мы можем полагаться только на некоторые ритуалы, чтобы сохранить ее слабую жизнь.",
    ["我们现在出发吧，关于失踪案，你还有其他的线索吗？"] = "Давайте отправимся сейчас. Есть ли у вас какие-либо еще улики по делу о похищении?",
    ["我们的内务大臣，梅，生日快乐！我的礼物是一个水杯。"] = "Наш министр внутренних дел, Май, с днем ​​рождения! Мой подарок — чашка для воды.",
    ["我们目前的站位和镜头机位，都是基于剧情模板的基础上，根据具体的需要，进行直接的调用。"] = "Наше текущее позиционирование и ракурсы камеры основаны на шаблонах сюжетов, вызываемых непосредственно в соответствии с конкретными потребностями.",
    ["我们经常一起玩，但她总是突然就消失了。"] = "Мы часто играем вместе, но она всегда внезапно исчезает.",
    ["我们能帮到您这样的大人物？"] = "Мы можем помочь такой важной персоне, как ты?",
    ["我们该怎么处理……"] = "Как нам следует поступить с...",
    ["我们调查到有个罪犯可能藏在你这里"] = "В ходе расследования мы выяснили, что здесь может скрываться преступник",
    ["我们还会再见面的。"] = "Мы встретимся снова.",
    ["我们还会再见，在塔罗学派……或者其他地方。"] = "Мы встретимся снова, в Клубе Таро... или где-нибудь еще.",
    ["我们还会见面的"] = "Мы встретимся снова.",
    ["我们还是尝试一下普通一点的菜品吧……"] = "Давайте вместо этого попробуем что-нибудь более обычное...",
    ["我们这些普通人，没什么技能和才识，只能卖些力气，当工人了。"] = "У нас, простых людей, нет ни навыков, ни знаний, поэтому мы можем только продать свои силы и стать рабочими.",
    ["我们这提供全廷根最正宗的因蒂斯美食。"] = "Мы предлагаем самую настоящую кухню Интиса во всем Тингене.",
    ["我们这种老家伙，能安安稳稳地活着，有几瓶酒喝，就算走狗屎运了，不是吗？"] = "Для таких стариков, как мы, возможность жить в безопасности и выпить несколько бутылок вина считается удачей, не так ли?",
    ["我们这里有好几位侦探，每个人擅长的领域也不一样，比如我，从小就在廷根生活，对廷根的历史、街区、居民都很了解。"] = "У нас работает несколько сыщиков, и у каждого своя специализация. Я, например, с детства живу в Тингене и превосходно знаю его историю, улицы и горожан.",
    ["我们那把投资股市的普通居民称作“韭菜”。"] = "Мы называем рядовых жителей, инвестирующих в фондовый рынок, «луком-пореем».",
    ["我们都很想念他。"] = "Мы все очень скучаем по нему.",
    ["我们需要仔细研究那本《谜题破解法》，借助书里的内容破解谜题、打破循环。"] = "Нам нужно внимательно изучить книгу «Методы решения головоломок» и использовать ее содержание, чтобы решить головоломки и разорвать цикл.",
    ["我会一直守着你，不用太过担心。"] = "Я присмотрю за тобой, не волнуйся слишком сильно.",
    ["我会全程陪在他们身边，保证安全。"] = "Я буду сопровождать их все время, чтобы обеспечить их безопасность.",
    ["我会努力不辜负您的期待，“正义”女士。"] = "Я постараюсь оправдать ваши ожидания, мисс Джастис.",
    ["我会努力的，成为廷根最有钱的人，然后把这个村子也建的很豪华。"] = "Я буду усердно работать, чтобы стать самым богатым человеком в Тингене, а затем сделать и эту деревню очень роскошной.",
    ["我会努力训练的，“正义”女士。"] = "Я буду усердно тренироваться, мисс Джастис.",
    ["我会去间海郡，他出生和埋葬的地方。"] = "Я поеду в Мидсишир, место, где он родился и похоронен.",
    ["我会听话……我会努力……我会做最好的孩子……"] = "Я буду послушным... Я буду много работать... Я буду самым лучшим ребенком...",
    ["我会好好读完大学，毕业后我打算从黑荆棘安保公司的文员开始努力，最终成为一名能守护廷根的值夜者。"] = "Я закончу университет как следует. После окончания учебы я планирую начать усердно работать клерком в охранной компании «Чёрный Чертополох» и в конечном итоге стать Ночным Ястребом, который сможет защитить Тингена.",
    ["我会尽我所能守护这份光。"] = "Я сделаю все возможное, чтобы охранять этот свет.",
    ["我会带着最饱满的热情完成工作！"] = "Я завершу свою работу с величайшим энтузиазмом!",
    ["我会把全部情况都汇报给会长。阿罗德斯，我想重新回答你的问题。"] = "Я доложу всю ситуацию президенту. Арродес, я хотел бы еще раз ответить на ваш вопрос.",
    ["我会把那些伤害你、弄脏你甚至想砍掉你的人都赶走……"] = "Я прогоню всех, кто причиняет тебе боль, оскверняет тебя или хочет срубить...",
    ["我会汇报全部真相，以及自己的看法，你们还需要等待处置结果。"] = "Я сообщу всю правду, а также свое собственное мнение. Вам еще нужно дождаться окончательного решения.",
    ["我会派人安抚和守护他们的家人，给予一笔抚恤金，让他们好好活下去。"] = "Я пошлю людей утешать и охранять свои семьи и обеспечивать их пенсиями, чтобы они могли жить хорошо.",
    ["我会派人追踪丽埃娜一家的情况，避免有意外发生。当然，他们也要为所犯的罪接受对等的惩罚。"] = "Я пришлю людей проследить за ситуацией в семье Лианы, чтобы избежать несчастных случаев. Конечно, они также должны принять равное наказание за совершенные ими преступления.",
    ["我会派人追踪丽埃娜和封印物的情况，避免再有发生意外。当然，他们也要为所犯的罪接受对等的惩罚。"] = "Я отправлю людей проследить за Лианой и Запечатанным Артефактом, чтобы избежать новых происшествий. И, разумеется, за совершенные злодеяния они понесут заслуженное наказание.",
    ["我会的，我也会告诉其他学员的。"] = "Я сделаю это и расскажу другим ученикам.",
    ["我会的，谢谢您。"] = "Я сделаю, спасибо.",
    ["我会让灵使包裹住封印物3-116，它可以隔绝封印物的作用，也能让你自由地跟在我的身边。"] = "Я велю Посланнику окутать Запечатанный Артефакт 3-116. Это изолирует воздействие артефакта и позволит тебе свободно следовать за мной.",
    ["我会送珍妮一程。"] = "Я провожу Дженни.",
    ["我作为一名医生，应该按照医学的原则来判断生死。"] = "Как врач, я должен судить о жизни и смерти в соответствии с медицинскими принципами.",
    ["我依稀记得有什么事情一定要去做，那我必须要去做，不然我死也不甘心……嗯，现在已经是某种意义上的死也不甘心了。"] = "Я смутно помню, что есть что-то, что я должен сделать, и я должен это сделать, иначе я не захочу умирать... ну, теперь я в каком-то смысле не хочу умирать.",
    ["我倒不觉得她值得同情。前两天我见她买菜，挑挑拣拣地翻了八百多遍，然后你猜怎么着？"] = "Я не думаю, что ей стоит сочувствовать. Пару дней назад я видел, как она покупала продукты, выбирала и выбирала более восьмисот раз, а потом угадайте, что?",
    ["我倒觉得，您爱这些胖乎乎的面团，也爱您的生活，也爱周围的邻居们，所以您的面包格外好吃。"] = "Я думаю, это потому, что ты любишь это пухлое тесто, любишь свою жизнь и любишь соседей вокруг тебя, поэтому твой хлеб исключительно вкусный.",
    ["我偶尔会想，如果我的长孙没有死去，应该也像他一样大了……"] = "Я иногда думаю, что если бы мой старший внук не умер, ему, наверное, было бы столько же лет, сколько ему...",
    ["我偷偷回去过一次，但东西都不见了。妈妈的水杯、衣服，还有我的啾啾……"] = "Однажды я пробрался обратно, но все пропало. Мамина чашка с водой, ее одежда и мой Чиу-Чиу...",
    ["我先带您看看小姐的情况。我理解，这是必要流程。"] = "Сначала я отведу вас, чтобы увидеть ситуацию с молодой леди. Я понимаю, это необходимая процедура.",
    ["我先自己看看吧。"] = "Сначала я осмотрюсь вокруг сам.",
    ["我再想想。"] = "Дай мне подумать об этом.",
    ["我再看看"] = "Позвольте мне посмотреть еще раз",
    ["我再问一次——为、什、么、冲、着、我、吐、痰？"] = "Я спрошу еще раз — почему ты плюешься на меня?",
    ["我决定今天一整天都不理彼得了，他竟然说我的穿搭奇怪，我明明模仿的是会长，而她毋庸置疑是全学派时尚风潮的引领者！"] = "Я решил сегодня весь день игнорировать Питера. Он вообще сказал, что мой наряд странный, хотя я явно подражал президенту, а она, несомненно, является лидером модного направления всей школы!",
    ["我准备参加这一届的廷根市长选举，现在的廷根实在太糟糕了。"] = "Я готовлюсь принять участие в выборах мэра Тингена. Тинген сейчас слишком ужасен.",
    ["我准备当个送货员，把它还给它真正的主人。"] = "Я планирую поработать курьером и вернуть его законному владельцу.",
    ["我刚刚似乎听到了什么论文，什么代写，也许我应该考虑一下举报……"] = "Кажется, я только что услышал что-то о диссертации, что-то о писательстве-призраке. Возможно, мне стоит подумать об этом и сообщить...",
    ["我刚刚说话的声音是不是太大了？对不起，我有点兴奋过头了，嘿嘿。"] = "Был ли мой голос сейчас слишком громким? Извините, я был слишком взволнован, хе-хе.",
    ["我刚到廷根，您能给我透露一下这边的状况吗？"] = "Я только что прибыл в Тинген. Можете ли вы раскрыть мне ситуацию?",
    ["我刚才路过的时候，听见他又是自言自语，又是发出怪笑声，挺瘆人的……"] = "Когда я только что проходил мимо, я услышал, как он разговаривал сам с собой и издал странный смех. Это было довольно страшно...",
    ["我刚睡醒，至少还有足够的力气回答你的提问。"] = "Я только проснулся, но сил ответить на твои вопросы у меня хватит.",
    ["我劝你别在我眼前转身，小心我狠狠踢你的屁股！"] = "Советую тебе не поворачиваться ко мне спиной, иначе я надеру тебе задницу!",
    ["我加入俱乐部的原因吗？嗯……如果赛艇成绩优异的话，也是可以申请奖学金的。"] = "Причина, по которой я вступил в клуб? Хм... если мои результаты в гребле будут отличными, я тоже смогу подать заявку на стипендию.",
    ["我原本也很怀疑，但感谢上次的相遇，你让我深受启发。"] = "Я тоже был настроен очень скептически, но благодаря нашей последней встрече вы меня глубоко вдохновили.",
    ["我厨艺很好"] = "Я хороший повар",
    ["我去帮你问问吧。"] = "Я пойду спрошу тебя.",
    ["我去附近找找看。"] = "Я поищу поблизости.",
    ["我只想永远和我的木桩朋友待着。"] = "Я просто хочу навсегда остаться со своим деревянным другом-пустышкой.",
    ["我只是一个凶手。"] = "Я просто убийца.",
    ["我只是为了不待在家里，女神鼓励她的女性信徒外出工作，寻找更多自我的价值。"] = "Я делаю это просто для того, чтобы не оставаться дома. Богиня призывает своих верующих женщин работать вне дома и обретать большую самооценку.",
    ["我只是去买了个冰激凌，回来路上就看到凶手倒在路边了。"] = "Я просто ходила за мороженым, а на обратном пути увидела убийцу, лежащего у дороги.",
    ["我只是最近胸口有点闷，喘不过气来，其实完全不影响我工作！可主管说我迟早会给他惹麻烦……"] = "В последнее время у меня просто стеснение в груди, и я не могу отдышаться, но это никак не влияет на мою работу! Но начальник сказал, что я рано или поздно доставлю ему неприятности...",
    ["我只是有时候很想念他们……真的很想念他们……"] = "Просто иногда я так сильно по ним скучаю... правда очень скучаю...",
    ["我只知道，我在等待一个结果，一个<P_Yellow>必须完成的使命</>。"] = "Я знаю только, что жду результата, миссии <P_Yellow>, которую необходимо выполнить</>.",
    ["我只能从过去的故事里认识他们，也只能在梦里见到他们生动的样子，这真遗憾。"] = "Я могу узнать о них лишь из старых историй и увидеть их живыми только во сне. Какая жалость.",
    ["我叫安东尼，行政大臣。我们是个严谨，独立的国家。"] = "Меня зовут Энтони, я министр администрации. Мы строгая, независимая нация.",
    ["我叫玛莎。"] = "Меня зовут Марта.",
    ["我可以"] = "Я могу",
    ["我可以帮你，是什么事情？"] = "Я могу помочь вам. Что это такое?",
    ["我可以帮忙。"] = "Я могу помочь.",
    ["我可以感知到阿诺德现在的大致位置，我也不知道为什么，但可以隐约感觉到！"] = "Теперь я чувствую общее местоположение Арнольда. Не знаю почему, но я смутно это чувствую!",
    ["我可以把这个盒子带走吗？"] = "Могу ли я забрать эту коробку?",
    ["我可以看看你的作品吗？"] = "Могу я взглянуть на ваши работы?",
    ["我可以跟你们走，治安官先生，但请找到我的姐姐，这是你们的职责，不是吗？"] = "Я могу пойти с вами, мистер Констебль, но, пожалуйста, найдите мою сестру. Это ваш долг, не так ли?",
    ["我可是很开心能看到你这么成熟靠谱的样子。"] = "Я очень рад видеть тебя таким зрелым и надежным.",
    ["我向偶遇的朋友们分享了几杯奥尔米尔葡萄酒，其中有几位路过的小信使醉得几乎要分不清前后左右了。"] = "Я разделил несколько бокалов вина Ульмье со случайно встреченными друзьями, а несколько проходящих мимо маленьких посыльных были настолько пьяны, что едва могли отличить переднюю часть от задней.",
    ["我听到了……笛子的声音，很诡异的调子，然后就……！！！"] = "Я услышал... звук флейты, очень жуткую мелодию, а потом...!!!",
    ["我听到脚步声了，请别管我，让我睡吧……我不会打扰到任何人。离灵界越近，就能捕捉到更多信息……包括已逝的梦境……"] = "Я услышал шаги, пожалуйста, оставьте меня в покое, дайте мне поспать... Я никого не побеспокою. Чем ближе я к Миру Духов, тем больше информации я могу уловить... включая сны усопших...",
    ["我听见你们在说，午餐凭空消失了？"] = "Я слышал, ты говорил, что обед растворился в воздухе?",
    ["我听说了，策划的文案被偷了！"] = "Я слышал, что запланированный экземпляр украли!",
    ["我听说，运气爆棚的人能在这喷泉里获得非凡的奖励呢！"] = "Я слышал, что люди с взрывной удачей могут получить из этого фонтана необыкновенные награды!",
    ["我和你一样，也不知道比迷雾海更西的地方是哪里，或许，还没有人知道。"] = "Как и вы, я не знаю, где находится место дальше на запад, чем Туманное море. Возможно, никто еще не знает.",
    ["我和你一起去，我也掌握一些信息，也许能帮到你。"] = "Я пойду с тобой: у меня тоже есть кое-какие сведения, быть может, они пригодятся.",
    ["我和你吻别，在无人的港……让风嘲笑我不能改写……"] = "Целую тебя на прощание в пустынном порту... пусть ветер издевается надо мной за то, что я не умею переписывать...",
    ["我和你吻别，在晦暗的夜……我的心哭着迎接悲伤……"] = "Целую тебя на прощание в тусклой ночи... Мое сердце плачет, приветствуя печаль...",
    ["我哥哥，他天天就往这俱乐部跑！说能看清运势！"] = "Мой брат, он каждый день бегает в этот клуб! Он говорит, что видит свою судьбу!",
    ["我唯一的遗憾……就是没有把世界……各处的……睡前故事……"] = "Единственное, о чем я сожалею... это то, что я не рассказывала на ночь сказки... со всего мира...",
    ["我喜欢这个广场的氛围，也喜欢女神的教堂，选择在这里当一名画家而已。"] = "Мне нравится атмосфера этой площади, и мне нравится церковь Богини; Я просто решил стать здесь художником.",
    ["我喜欢阴冷和靠近尸体的感觉，总是徘徊于墓园、在坟墓前睡觉。那时候，他们畏惧我、厌恶我……"] = "Мне нравился холод и ощущение близости трупов. Я вечно бродил по кладбищам и спал перед могилами. В те времена люди боялись меня и чурались...",
    ["我回去就没命了！"] = "Я умру, если вернусь!",
    ["我回家了"] = "Я дома",
    ["我在循环空间中，只是旁观者，能看到雏菊开得很好，但却没有嗅觉。"] = "В пространстве цикла я был просто наблюдателем. Я мог видеть красиво цветущие ромашки, но у меня не было обоняния.",
    ["我在想，是否要写信给我的好朋友。"] = "Я думал, стоит ли мне написать моему хорошему другу.",
    ["我在找猫"] = "Я ищу кота",
    ["我在拉斐尔墓园看到他的墓碑了，上边有他的照片。1327年3月-1349年9月，最好的哥哥；最好的弟弟；最好的同事。"] = "Я видел его надгробие на кладбище Рафаэля с его фотографией. март 1327 г. — сентябрь 1349 г., лучший брат; лучший младший брат; лучший коллега.",
    ["我在旁边都听到了！"] = "Я услышал это со стороны!",
    ["我在模仿爸爸。"] = "Я подражаю папе.",
    ["我在河岸街卖了10年鱼了，大家都认识我。"] = "Я продаю рыбу на Риверсайд-стрит уже 10 лет; меня все знают.",
    ["我在等她给我唱完那首摇篮曲，那首歌真的太好听了，可惜她唱到一半又跑走了。"] = "Я жду, пока она закончит петь мне эту колыбельную. Песня очень красивая, но жаль, что она убежала на середине.",
    ["我在等，戴里克导师，感到疲惫的瞬间。"] = "Я жду момента, наставник Деррик, когда вы почувствуете усталость.",
    ["我在维纳的碗里放了它最爱吃的肉骨头……"] = "Я положила его любимую мясную косточку в миску Вины...",
    ["我在贝克兰德待了那么久，从来没见过出了案子警察迟迟不来维持秩序的情况！"] = "Сколько я живу в Бэкланде, еще ни разу не видел, чтобы после преступления полиция так долго не являлась наводить порядок!",
    ["我在这里等他。"] = "Я подожду его здесь.",
    ["我在这里等妈妈来找我就好了，她应该正在路上呢。"] = "Я просто подожду здесь, пока мама меня найдет; она должна быть в пути.",
    ["我在附近找到了这个油漆桶。"] = "Я нашел это ведро с краской неподалеку.",
    ["我在静待某位钢琴家的到来。"] = "Я жду приезда некоего пианиста.",
    ["我女儿赛琳娜，一位美丽的淑女，我的小甜心，最近闹着要去贝克兰德旅行，一点也不顾我这个老父亲的心情。"] = "Моя дочь Селена, прекрасная женщина, моя маленькая возлюбленная, в последнее время шумит по поводу поездки в Бэкланд, совершенно не заботясь о чувствах этого старого отца.",
    ["我女朋友觉得我做饭很好吃，就建议我开一家餐厅，做些日常菜色。"] = "Моя девушка подумала, что я хорошо готовлю, поэтому предложила мне открыть ресторан и готовить ежедневные блюда.",
    ["我好像做了一个很长很长的梦……"] = "Такое ощущение, что мне приснился очень, очень длинный сон...",
    ["我好像忘记了什么事情……终究是上了年纪了。"] = "Кажется, я что-то забыл... Возраст все-таки дает о себе знать.",
    ["我好像没看见啊？"] = "Кажется, я никого не вижу?",
    ["我好像看见了很多肝。"] = "Кажется, я вижу много печени.",
    ["我好精神挺状态的呀。"] = "Да в полном я порядке, в прекрасном состоянии.",
    ["我妈妈说过，只要心诚，风暴之主就会听见，所以，为了治好妈妈的咳嗽病，我每天都对着喷泉祈祷！"] = "Мама говорила, если молиться от всего сердца, Повелитель Бурь обязательно услышит. Поэтому, чтобы вылечить её кашель, я каждый день молюсь у фонтана!",
    ["我完全不记得过去了，这曾让我不知道自己是谁。"] = "Я совершенно не помню своего прошлого, и когда-то это заставляло меня мучиться вопросом, кто я такой.",
    ["我实在害怕，您愿意帮帮忙吗？"] = "Мне очень страшно, ты хочешь помочь?",
    ["我实在是看不懂现在的物价了，为什么现在的钱越来越难赚，却越来越不值钱。"] = "Я действительно не могу понять текущие цены. Почему деньги становится все труднее и труднее зарабатывать, а они стоят все меньше и меньше?",
    ["我家老约翰虽然胖，但跑起来可快了！上次偷吃燕麦，追都追不上！"] = "Мой старый Джон, может, и толстый, но он быстро бегает! В прошлый раз, когда он украл овес, я даже не смог его поймать!",
    ["我家雪球可不是一般兔子！"] = "Мой Снежок – не обычный кролик!",
    ["我对庄园很熟悉，可以带你前往想去的地方……"] = "Я очень хорошо знаком с поместьем и могу отвезти вас туда, куда вы захотите...",
    ["我对死掉的那天没什么印象了，一切都还顺利吗？"] = "Я совсем не помню день своей смерти. Все прошло гладко?",
    ["我对自己的记忆力还算有信心，记住谜题的答案应该不难。"] = "Я немного доверяю своей памяти; запомнить ответы на головоломки не составит труда.",
    ["我将进入这片历史的权限赐予你，请帮助我，用他们的眼睛去见证他们的故事。"] = "Я даю вам право войти в эту часть истории. Пожалуйста, помогите мне увидеть их историю их собственными глазами.",
    ["我少管？晚上回家喊疼的时候是谁照顾您！为了给您热敷膝盖，烧水壶都快罢工了！"] = "Не лезть не в свое дело? А кто за вами ухаживает, когда вы по ночам стонете от боли?! Чтобы ставить вам горячие компрессы на колени, чайник на плите уже чуть ли не треснул!",
    ["我尝试了很多种方法都没有考到第一名。"] = "Я испробовал много методов, но так и не смог занять первое место.",
    ["我就是个人渣……呜呕……"] = "Я просто кусок мусора... *ик*...",
    ["我就是来工作的。你知道的，我们值夜……咳咳，不，安保公司，平时值班都是点老维尔餐厅的外送。"] = "Я здесь по работе. Знаете, наши «Ночные ястребы»... кхм, нет, охранная компания обычно на наши смены заказывает доставку из ресторана Олд Уилла.",
    ["我就知道，{{先生|女士}}您看起来就是那种很注重健康的人，自然会介意那些用工业废水浇灌的蔬菜。"] = "Я знал это, {{Mr.|Ms.}}, ты выглядишь как человек, который заботится о своем здоровье, поэтому, естественно, ты бы возражал против полива овощей промышленными сточными водами.",
    ["我就知道，阿尔伯特这小子迟早会变得和他父亲一样惹人嫌弃。一棵烂了的苹果树，结不出好果子！"] = "Я знал, что этот мальчишка Альберт рано или поздно станет таким же раздражающим, как и его отец. Гнилая яблоня не может принести добрых плодов!",
    ["我就说说。只吃得起免费餐的人，有一双能走的腿就够了！"] = "Я просто говорю. Для человека, который может позволить себе только бесплатное питание, достаточно пары ног, способных ходить!",
    ["我已有了面对一切的觉悟。啊，赞美愚者！"] = "Я готов встретиться со всем. Ах, хвала Шуту!",
    ["我已经没脸在恶龙酒吧混了，可能之后会去某个码头工作吧。"] = "У меня не осталось лица, которое можно было бы показать в баре ««Злой Дракон»». Возможно, позже я пойду работать в какой-нибудь причал.",
    ["我已经睡了很久，但这抹意识应该不是为了睡觉而存在的。"] = "Я спал уже давно, но этот след сознания не должен существовать только ради сна.",
    ["我带你过去，跟紧我。"] = "Я отвезу тебя туда, следуй за мной внимательно.",
    ["我常常觉得，自己就要见不到明天的太阳了。"] = "Мне часто кажется, что я не доживу до завтрашнего солнца.",
    ["我年轻时早早滑入了诱惑的泥潭，可小伊芙，你还有重来的机会。"] = "Я рано погрузился в трясину искушения, когда был молод, но, Маленькая Ева, у тебя еще есть шанс начать все сначала.",
    ["我应该完全记住了。"] = "Я считаю, что запомнил их полностью.",
    ["我当然知道，不用担心。不久后我就遇到了卡萝队长和你……如果能再早一点就好了。"] = "Я знаю, конечно. Не волнуйся. Вскоре после этого я встретил капитана Кару и тебя... Если бы это могло быть раньше.",
    ["我彻底相信，你可以顺利地唤醒黛西小姐。"] = "Я полностью верю, что ты сможешь успешно разбудить мисс Дейзи.",
    ["我很乐意。具体是什么案件？有什么线索吗？"] = "Я был бы рад. Какой конкретно случай? Есть ли какие-нибудь подсказки?",
    ["我很冷静，从这里跳下去，就这个高度无非是软组织挫伤。"] = "Я очень спокоен. Прыжок отсюда, на такую ​​высоту, это не что иное, как ушиб мягких тканей.",
    ["我很喜欢的一位侦探小说家说过，元凶通常隐藏于最不起眼之处！"] = "Один мне очень понравившийся писатель-детектив однажды сказал, что преступник обычно прячется в самом незаметном месте!",
    ["我很好、很健康！放心吧队长。"] = "Я в порядке, очень здоров! Не волнуйтесь, капитан.",
    ["我很崇拜他的！但是一直当学徒也有怨气嘛，就小小抱怨几句，就几句……你就当我没说过。"] = "Я очень им восхищаюсь! Но я был учеником так долго, что у меня возникла некоторая обида, поэтому я просто немного жалуюсь, совсем немного... просто делаю вид, что ничего не говорил.",
    ["我很愿意。"] = "Я был бы очень рад.",
    ["我很理解他们的心情，也羡慕他们还能找到重要的人的遗物。"] = "Я понимаю их чувства и завидую тому, что они все еще могут найти реликвии кого-то важного.",
    ["我很荣幸，能遇到一位懂得欣赏的听众。"] = "Для меня большая честь встретить слушателя, способного оценить это по достоинству.",
    ["我很高兴看到琳达获胜，老维德吃了一个大亏，说不定现在正躲在厕所里哭呢。 "] = "Я рад видеть победу Линды. Старый Уэйд понес большую утрату; возможно, он сейчас прячется в туалете и плачет.",
    ["我忍无可忍，就开口骂了他，但他却来得更勤了。"] = "Я больше не могла этого терпеть и начала его ругать, но он приходил чаще.",
    ["我快疯了"] = "Я с ума схожу",
    ["我怀疑这起儿童失踪案与非凡者有关，我准备去调查一下。"] = "Я подозреваю, что дело о похищении ребенка связано с Потусторонним, и я готовлюсь к расследованию.",
    ["我怎么知道，它又不是我的信使……不过，它好像在研制某种药剂，桌子上的那个是我听到的药剂配方，说不定你把药剂做出来它就会出现。"] = "Откуда мне знать? Это не мой посланник... Однако, похоже, он разрабатывает какое-то зелье. Тот, что на столе, — это формула зелья, которую я слышал. Возможно, если ты приготовишь зелье, оно появится.",
    ["我总觉得股市就是政府公开的赌博，最起码鲁恩的股市是这样的，有钱千万别炒股。"] = "Я всегда чувствую, что фондовый рынок — это открытая игра правительства. По крайней мере, фондовый рынок в Лоене такой. Если у вас есть деньги, не спекулируйте на фондовом рынке.",
    ["我恨历史，那都是一团又一团的迷雾，像隐匿贤者的灌输一样让人头痛！"] = "Терпеть не могу историю! Это сплошной туман, от которого раскалывается голова, совсем как от нашептываний Сокрытого Мудреца!",
    ["我悄悄告诉你，你不要告诉别人。梅是……流浪王国的大臣！"] = "Я скажу тебе тихо, больше никому не говори. Мэй... министр Странствующего Королевства!",
    ["我想了解一下公司的福利。"] = "Хотелось бы узнать о преимуществах компании.",
    ["我想你应该知道，神弃之地在“愚者”的庇佑下得以结束持续千年的苦难。"] = "Я думаю, вам следует знать, что Заброшенная Земля Богов смогла положить конец своим тысячелетним страданиям под защитой «Шута».",
    ["我想你来找我肯定不只是想和我闲聊这么简单。"] = "Я не думаю, что ты пришел ко мне не просто ради простой беседы.",
    ["我想你说的是柠檬蛋糕，孩子们都喜欢这种蛋糕。"] = "Я думаю, вы имеете в виду лимонный пирог. Всем детям нравится такой торт.",
    ["我想修好那边的简易锅，你可以帮帮我吗？"] = "Я хочу починить вон тот простой горшок. Вы можете помочь мне?",
    ["我想和人分享这个发现很久了！你知道蔷薇战争吗？"] = "Давно хотела с кем-нибудь поделиться этим открытием! Знаете ли вы о Войне роз?",
    ["我想在任何一个城市的这种调研都能让我们收获良多……"] = "Я думаю, такого рода исследования в любом городе могут дать очень многое...",
    ["我想您愿意用一点点金钱来交换获取这个伟大智慧的机会，当然，当然！"] = "Я думаю, вы были бы готовы обменять немного денег на возможность приобрести эту великую мудрость, конечно-конечно!",
    ["我想想……1350年战争爆发时，他比我大三岁，今年，我比他大一岁……"] = "Дай подумать... когда в 1350 году разразилась война, он был на три года старше меня. В этом году я на год старше его...",
    ["我想想，你去找全学派最爱睡觉的那位吧，她会给你中肯的商品评价。"] = "Дай мне подумать, тебе стоит найти в школе человека, который больше всего любит спать; она даст вам честный обзор продукта.",
    ["我想想，肯最爱偷懒，多半在休息室，萨拉应该在帮忙打扫会长办公室……"] = "Дай подумать, Кен больше всего любит бездельничать, он, наверное, в гостиной, а Сара должна помогать с уборкой в ​​кабинете президента...",
    ["我想我今晚睡不着了……"] = "Я не думаю, что смогу уснуть сегодня вечером...",
    ["我想找队长。"] = "Я хочу найти Капитана.",
    ["我想确认一件事。不过放心，如果我有恶意，刚刚就不会救你们。"] = "Я хочу кое-что прояснить. Но не волнуйтесь: замышляй я недоброе, я бы не стала вас спасать.",
    ["我想要……"] = "Я хотел бы...",
    ["我想请假"] = "Я хочу попросить отпуск",
    ["我想起一些以前的事情，呵，这个世界对待孤儿并不友好。"] = "Я вспомнил некоторые вещи из прошлого. Хех, этот мир недружелюбен к сиротам.",
    ["我想起了那个血肉魔法，让灵界谜虫吞吃了我的身体。"] = "Я вспомнил ту Магию Плоти, позволив Таинственному Червю Мира Духов поглотить мое тело.",
    ["我想邀请梅丽莎回来参加我的生日宴会，但我不知道她是否有空。"] = "Я хочу пригласить Мелиссу на вечеринку по случаю моего дня рождения, но не знаю, свободна ли она.",
    ["我想，我可以独自应对这件事。"] = "Думаю, я справлюсь с этим вопросом в одиночку.",
    ["我想，这或许不是一个能令你开心的话题。"] = "Я думаю, что это не та тема, которая сделает вас счастливыми.",
    ["我感觉距离与父母团聚的那一天又近了一步！"] = "Я чувствую, что стал на шаг ближе к тому дню, когда воссоединюсь с родителями!",
    ["我懂了，我其实已经死了，现在的我只是一缕偏执的意识、一片残破的灵体。"] = "Я понимаю. На самом деле я уже мертв. Нынешний я — всего лишь нить навязчивого сознания, сломанное духовное тело.",
    ["我成为医生四十年了，有自己的诊所和病人，但我也需要帮助。"] = "Я работаю врачом уже сорок лет, у меня своя клиника и пациенты, но мне тоже нужна помощь.",
    ["我手上就是一张小牌，哦不，是小王吧！哎呀，我怎么会为了赢你用这种下三滥手段呢……"] = "У меня в руке маленькая карточка, о нет, это маленький Джокер! О боже, как я мог использовать такие подлые методы, чтобы победить тебя...",
    ["我打算……"] = "Я собираюсь...",
    ["我打算做一个经典招牌，当当当当！“想你的风还是吹到了塔罗学派”，怎么样？"] = "Планирую сделать классический знак, да-да-да-да! «Ветер, который скучает по тебе, все еще дует в Клуб Таро», как насчет этого?",
    ["我打算问阿罗德斯一些难以回答的问题。"] = "Я планирую задать Арродесу несколько трудных вопросов.",
    ["我投资修建的一栋房子塌了，我以为已经够倒霉了。"] = "Здание, в которое я вложил деньги, рухнуло; Я подумал, что этого уже достаточно.",
    ["我报销的单子去哪——啊，{{PlayerName}}？你也来练习射击吗？"] = "Куда делась моя форма возмещения? Ах, {{PlayerName}}? Ты тоже здесь, чтобы попрактиковаться в стрельбе?",
    ["我担心这里的情况。"] = "Меня беспокоит ситуация здесь.",
    ["我拒绝回答。"] = "Я отказываюсь отвечать.",
    ["我放弃！"] = "Я сдаюсь!",
    ["我敢保证，这杯一定会引发你肚子的风暴。"] = "Гарантирую, это обязательно вызовет бурю в желудке.",
    ["我整天就……嗝，在这里喝酒。把年幼的女儿晾在店里……她还那么小，我却……嗝，没能承担起，作为父亲的责任……"] = "Я провожу весь день... *ик*, пью здесь. Оставив в магазине маленькую дочку... Она еще такая маленькая, а я... *ик*, не выполнил свой родительский долг...",
    ["我无法思考，只能用所有的时间去绘制南大陆的地图……"] = "Я не могу думать... Всё моё время уходит лишь на то, чтобы рисовать карту Южного континента...",
    ["我早就不怕了，从商业学校毕业后我就来这里工作了，很高兴能遇到这样的一群人。"] = "Я уже давно не боюсь. После окончания бизнес-школы я приехал сюда работать. Я очень рад, что встретил такую ​​группу людей.",
    ["我早起……去码头……"] = "Я встаю рано... чтобы пойти на пристань...",
    ["我时刻期盼着乐曲完成的那一天。\n可是，还没等乐曲完成，艾登就要离开济贫院了。"] = "Я всегда с нетерпением жду того дня, когда музыка закончится. \n Однако прежде чем музыка закончилась, Эйден собирался покинуть работный дом.",
    ["我明白……"] = "Я понимаю...",
    ["我明白……乔纳尔，请让我和{{他|她}}<P_Yellow>单独</>谈谈。"] = "Я понимаю... Джонар, пожалуйста, позвольте мне поговорить с {{ним|ней}} <P_Yellow>наедине</>.",
    ["我明白。"] = "Я понимаю.",
    ["我明白了……"] = "Я понимаю...",
    ["我明白了。"] = "Я понимаю.",
    ["我明白了。汉娜女士，请不要让任何人进入卧室，直到我们出去。"] = "Я понимаю. Мисс Ханна, пожалуйста, не позволяйте никому входить в спальню, пока мы не выйдем.",
    ["我明白了，谢谢您。"] = "Я понимаю, спасибо.",
    ["我明白，毕竟你连我的生日都会忘记。如果你能记住自己的生日，那我们都需要提高警惕了。"] = "Я понимаю, ты ведь даже мой день рождения забываешь. А вот если ты вдруг вспомнишь свой собственный, нам всем стоит насторожиться.",
    ["我明白，独处也是一项能力。"] = "Я понимаю, быть одному – это тоже навык.",
    ["我明白，跟这群孩子们呆在一起，我都感觉自己年轻了不少。"] = "Понимаю. Рядом с этими детьми я и сам чувствую себя помолодевшим.",
    ["我昨天在老实人报上看到了一篇关于灵能现象的报道，魔法一定是存在的！"] = "Вчера я видел репортаж о психических явлениях в «Честной газете». Магия должна существовать!",
    ["我昨晚梦见自己变成了贝克兰德那个霍尔家的孩子。"] = "Прошлой ночью мне приснилось, что я стал ребенком семьи Холл из Баклунда.",
    ["我是不是很棒很棒的孩子，嘿嘿。"] = "Я очень, очень хороший ребенок? Хе-хе.",
    ["我是不是很糟糕？你、你告诉我……呜呕……呜，我的女儿，我懂事的可怜的小莉迪……"] = "Я ужасен? Ты, ты скажи мне... *ик*... Ууу, моя дочь, моя разумная, бедная маленькая Лидди...",
    ["我是供品？"] = "Я подношение?",
    ["我是好孩子，我要帮上姐姐的忙，让她吃上新鲜的面包！"] = "Я послушная, я хочу помогать сестренке, чтобы она могла есть свежий хлеб!",
    ["我是玛丽，就住在隔壁，有什么能帮上忙的吗？"] = "Меня зовут Мария, я живу рядом. Могу ли я чем-нибудь помочь?",
    ["我是说可米娅，您身边那位可爱的小淑女。"] = "Я имею в виду Комию, милую маленькую леди рядом с тобой.",
    ["我是说，我的意思是说，我有一个从来都勤勤恳恳、老实本分的朋友，但有一次鬼迷心窍犯了错……"] = "Я имею в виду... то есть, у меня есть друг, всегда работящий и честный человек, но однажды чёрт попутал его, и он оступился...",
    ["我是说，邀请你看看小黛西短暂人生中，最快乐的时候。"] = "Я имею в виду, я приглашаю вас увидеть самое счастливое время в короткой жизни Маленькой Дейзи.",
    ["我是这的掘墓人，你需要挖坟，还是来调查老特勒的？"] = "Я здешний Могильщик. Тебе нужно выкопать могилу, или ты пришёл расследовать дело старого Трелле?",
    ["我是问你，好不好看！"] = "Я вас спрашиваю, хорошо это выглядит или нет!",
    ["我暂时不会带走3-888。但你们在黛西小姐身上的尝试，间接害死两位仆人和一位管家……"] = "Я пока не заберу 3-888. Но ваши эксперименты над мисс Дейзи косвенно привели к гибели двух слуг и дворецкого…",
    ["我曾在一次占卜后，<P_Yellow>得知了错误的结论</>，与我的命运擦肩而过——如今我在等的那个真相，就是<P_Yellow>命运给我新的指引</>。"] = "Однажды я <P_Yellow> получил неправильное заключение </> после гадания и упустил свою судьбу — истина, которую я жду сейчас, это <P_Yellow>, новое руководство судьба дала мне </>.",
    ["我曾经也被叫做怪胎，在失去家人又误食魔药成为“收尸人”之后。"] = "Меня тоже однажды назвали уродом, после того как я потерял семью и случайно выпил зелье, чтобы стать собирателем трупов.",
    ["我曾经也觉得这里有些阴森，有些寒冷。"] = "Раньше мне казалось, что это место немного жуткое и холодное.",
    ["我曾经多次安顿同事们的家属，黑夜教会会尽最大的努力去对待我们的家人。"] = "Я много раз заселял семьи своих коллег. Церковь Богини Вечной Ночи сделает все возможное, чтобы хорошо относиться к нашим семьям.",
    ["我曾经尝试给自己医治，却没有任何效果，但我的病人说，这里新来了一名医生，用银针缓解了他的腰痛。"] = "Я когда-то пробовала себя лечить, но эффекта не было. Однако мои пациенты говорят, что сюда приехал новый врач, который использует серебряные иглы для облегчения болей в пояснице.",
    ["我曾见过失去了半边身体的妇人抚摸着身旁干枯的孩子，她竟然在微笑！"] = "Однажды я увидела женщину, потерявшую половину своего тела, гладившую рядом с собой иссохшего ребенка, и она действительно улыбалась!",
    ["我最喜欢热闹！空气里炖汤香极了，叫卖声也好听。莴苣叶子滴着水，马铃薯圆滚滚的，多可爱！"] = "Обожаю суету и шум! В воздухе чудесно пахнет тушеным мясом, и звуки ястреба тоже приятны. С листьев салата капает вода, а картофель такой круглый и милый!",
    ["我有一个想法"] = "у меня есть идея",
    ["我有个提议，如果你能说服伊琳来看《伯爵归来》，我就把这两张特票送给你。"] = "У меня есть предложение. Если ты сможешь уговорить Ирэн пойти на «Возвращение графа», я подарю тебе эти два специальных билета.",
    ["我有些大胆的想法，为何不尝试更强烈的用色？"] = "У меня есть смелые идеи, почему бы не попробовать более яркие цвета?",
    ["我有些想念那群老家伙们……阿德莱德怎么样了？那个家伙笑起来还是那么吵吗？"] = "Я скучаю по этим старикам... Как Аделаида? Этот парень все еще такой же шумный, когда смеется?",
    ["我有所预感"] = "у меня есть предчувствие",
    ["我有新杯子了！下个月拿了工钱，我要喝整整一大杯汽水！"] = "У меня новая чашка! Когда я получу зарплату в следующем месяце, я выпью целую большую чашку газировки!",
    ["我有非凡材料需要出售，尤里卡说你这里有门路……"] = "У меня есть материал Потусторонний на продажу. Эврика сказала, что у тебя здесь есть связи...",
    ["我有非凡材料需要出售，尤里卡说你这里有门路。"] = "У меня есть материалы по Потусторонний, которые я хочу продать; Эврика сказала, что у тебя здесь есть связи.",
    ["我正在努力。"] = "Я стараюсь.",
    ["我正在执行任务，碰巧需要来廷根。"] = "Я сейчас на задании, и мне как раз нужно было прибыть в Тинген.",
