    ["我赌赢了，十便士，占卜家先生也会有占卜失误的时候呢。"] = "Я выиграл пари, десять пенсов. Даже у мистера Сира бывают случаи, когда его гадание терпит неудачу.",
    ["我跟你说，他身上绝对有古怪。他来了东区之后，那儿就老出血案，没有尸体，只有一滩滩血。"] = "Позвольте мне сказать вам, в нем определенно есть что-то странное. С тех пор, как он прибыл в Восточный округ, там постоянно происходили кровавые инциденты — никаких тел, одни лужи крови.",
    ["我身体还不错，也没什么困扰，倒是你今天有些古怪。"] = "У меня хорошее здоровье, и у меня нет никаких проблем. А вот ты сегодня ведешь себя немного странно.",
    ["我身后？"] = "Позади меня?",
    ["我还不知道发生了什么，但乔纳尔医生是个好人，他没有骗我。"] = "Я до сих пор не знаю, что произошло, но доктор Джонар — хороший человек, он меня не обманывал.",
    ["我还会告诉你很多事，神奇的力量、甲板上的奇遇、五海的强者……去海上前，我会给你介绍这些事情。"] = "Я расскажу вам еще много всего: магические силы, приключения на палубе, электростанции Пяти морей... Прежде чем отправиться в море, я познакомлю вас с этими вещами.",
    ["我还有一个问题……封印物3-888是什么？"] = "У меня еще один вопрос... что такое Запечатанный Артефакт 3-888?",
    ["我还有事，先走了"] = "У меня есть другие дела, я ухожу первым.",
    ["我还真有点同情她了。"] = "На самом деле сейчас я испытываю к ней некоторую симпатию.",
    ["我还要继续寻找封印物3-888的去向，时间越久，它越危险。"] = "Мне все еще нужно продолжить поиски запечатанного артефакта 3-888; чем дольше это продолжается, тем опаснее это становится.",
    ["我还要走得更远……远到……传说中的东大陆、西大陆、远到地心、远到星空。"] = "Я должен идти дальше... далеко, к... легендарному Восточному континенту, Западному континенту, далеко к центру земли, далеко к звездному небу.",
    ["我还要赶回去做实验呢！你随便给我点什么吃的吧！"] = "Мне пора возвращаться, чтобы проводить эксперименты! Дай мне все, что хочешь съесть!",
    ["我这两天就会用剩余的功勋雇佣帮手，去获取迷雾树人的真实根茎和汁液，我很快就能完成交易。"] = "На днях я потрачу оставшиеся заслуги, чтобы нанять помощников и добыть настоящий корень и сок Туманного древочеловека. Совсем скоро я завершу эту сделку.",
    ["我这卖的都是好东西。"] = "Все, что я здесь продаю, — хорошие вещи.",
    ["我这合同一月一签，一周一付，一月一付也可以，水按人头付，煤气用多少付多少直接给燃气公司。"] = "Мой контракт подписывается ежемесячно и выплачивается еженедельно, хотя ежемесячная оплата тоже подойдет. Вода оплачивается на человека, а газ оплачивается непосредственно газовой компании в зависимости от потребления.",
    ["我这就去找食材和厨具。"] = "Я прямо сейчас пойду искать ингредиенты и посуду.",
    ["我这有不少神奇的药品。"] = "У меня здесь довольно много волшебных лекарств.",
    ["我这样的人……祈求没有厄运已经是最大的心愿。"] = "Для такого человека, как я... молить лишь об отсутствии несчастий — уже предел желаний.",
    ["我这的东西，都是市政专供。它们都是来自同一个供货商。"] = "Весь товар у меня — исключительно муниципальный спецзаказ. И все идет от одного поставщика.",
    ["我这种文史专业的学生，过得可是一眼望不到头的日子，毕业直接失业！"] = "Студенты, подобные мне, изучающие гуманитарные науки, живут жизнью, конца которой мы не видим, и к моменту окончания учебы мы остаемся безработными!",
    ["我这辈子最讨厌的就是鱼和蘑菇，还有耕种者途径的疯子！"] = "Больше всего в жизни я ненавижу рыбу, грибы и этих безумцев с Пути Плантаторов!",
    ["我这里出售各种咸鱼美食。要试试我新研发的咸鱼派吗？"] = "Я продаю всевозможные деликатесы из соленой рыбы. Не хотите попробовать мой новенький пирог с соленой рыбой?",
    ["我这里是廷根佣兵小队的活动中心，你需要的话我可以介绍其他的雇佣兵小队给你认识。"] = "Это центр деятельности отрядов наёмников Тингена. Если нужно, я могу представить вам другие отряды наемников.",
    ["我这里还有一些特别的药剂，能让你变得理智，或是疯狂……想试试吗？"] = "У меня есть несколько особых зелий, которые могут сделать тебя разумным или безумным... хочешь попробовать?",
    ["我迫不及待地接下了扩充航道的工作，我要亲身渡海，我要亲眼看到世界另一面的模样，我要亲手绘制南大陆的地图。"] = "Мне не терпелось взяться за расширение морских путей. Я хочу сам пересечь море, хочу увидеть другую сторону света своими глазами и хочу нарисовать карту Южного континента своими руками.",
    ["我都不愿回想，都怪那群该死的弗萨克人！"] = "Мне даже вспоминать об этом тошно, во всем виноваты эти чертовы фейсакцы!",
    ["我都跟他学习了三年了！放在别的咖啡店早就是独当一面的咖啡师了，而我，现在还是个学徒……"] = "Я учусь у него уже три года! В любом другом кафе я был бы бариста, способным работать один, но я всё равно ученик...",
    ["我都问过了，他们跟公爵府的人一样，什么都不肯说。"] = "Я спросил их всех. Как и люди в резиденции герцога, они отказываются что-либо говорить.",
    ["我随便逛逛"] = "Просто бродил вокруг",
    ["我需要你帮个忙：带我去见你们组织里所有去过廷根湖的人。"] = "Мне нужно, чтобы вы оказали мне услугу: отвезли меня к каждому из вашей организации, кто был на озере Тинген.",
    ["我需要做得更好、更稳妥一些……能代替卡萝，能做得像她一样好。"] = "Мне нужно добиться большего, быть более устойчивым... чтобы иметь возможность заменить Кару и добиться того же успеха, что и она.",
    ["我，我想攒些钱，等妈妈病好后继续回学校读书。"] = "Я, я хочу накопить немного денег, чтобы вернуться в школу после того, как болезнь моей матери поправится.",
    ["我，我没有，我只是……仰慕她。"] = "Я нет, я просто... восхищаюсь ею.",
    ["我？"] = "Мне?",
    ["我？我宁愿做一只狼鱼罐头。"] = "Мне? Я бы предпочел быть банкой с рыбой-волком.",
    ["我？！"] = "Мне?!",
    ["或许你们该换副新牌，这些牌的花色已经看不清了。"] = "Возможно, вам стоит приобрести новую колоду, масти на этих картах уже плохо видны.",
    ["或许你可以先带走蛋糕，明天来我这，以工抵钱。"] = "Возможно, ты сначала возьмешь торт, завтра придешь ко мне и поработаешь, чтобы расплатиться с ним.",
    ["或许你可以尝试看看。"] = "Возможно, вы могли бы попробовать посмотреть.",
    ["或许你该取个更好听的名字。"] = "Возможно, вам стоит придумать имя получше.",
    ["或许你说得对。但这次……还是请你为我转达吧。就当做一个太少和亲人相处的老人的请求。"] = "Возможно, вы правы. Но на этот раз... пожалуйста, передай мне это. Просто считайте это просьбой старика, у которого слишком мало времени, чтобы проводить время со своими близкими.",
    ["或许和皇室有关系，或许是一位拉斯廷伯爵的崇拜者，你觉得呢？"] = "Возможно, это как-то связано с королевской семьей или, возможно, с поклонником графа Ластингса, как вы думаете?",
    ["或许她已经想好要回来了，为了给你一个惊喜？"] = "Возможно, она уже решила вернуться, чтобы преподнести вам сюрприз?",
    ["或许它能带给你一些不一样的惊喜。"] = "Возможно, это преподнесет тебе приятный сюрприз.",
    ["或许您可以进来喝杯茶，他应该很快就会回家。"] = "Быть может, зайдете выпить чашку чая? Он должен скоро вернуться домой.",
    ["或许是来源于当地的一个古老的童话——讲的是一个被大地母神赐予了生命的小木偶。"] = "Возможно, оно взято из древней местной сказки — в ней рассказывается о деревянной кукле, подаренной Матерью-Землей.",
    ["或许是那个人的肉味呢？你能不能让我咬一口？"] = "Может быть, это запах тела этого человека? Можете ли вы дать мне перекусить?",
    ["或许还需要一点时间，但没什么可担心的了。"] = "Возможно, потребуется еще немного времени, но беспокоиться больше не о чем.",
    ["或许这就是犯人盯上他们的理由。"] = "Возможно, именно поэтому преступник напал на них.",
    ["或许，下一次应该邀请你和我在训练场演练？"] = "Возможно, в следующий раз мне стоит пригласить тебя потренироваться со мной на Тренировочной площадке?",
    ["或许，下次去拉斐尔墓园看望邓恩队长他们时，我会记得把这些咖啡豆带给他。"] = "Возможно, в следующий раз, когда я навещу капитана Данна и остальных на кладбище Рафаэля, я не забуду принести ему эти кофейные зерна.",
    ["或许，我们应该先去看望一下小阿诺德？"] = "Быть может, нам стоит сначала навестить маленького Арнольда?",
    ["战争。"] = "Война.",
    ["战争后，很多教会里的大人物都离开了，我们再也不能像以前那样传教了。"] = "После войны многие крупные деятели церкви ушли, и мы больше не можем проповедовать так, как раньше.",
    ["战斗状态下5秒戳一发，是否确认选择这项能力？选择后其他2个会消失"] = "В бою совершает выстрел каждые 5 секунд. Подтвердить выбор этой способности? При выборе две другие исчезнут.",
    ["戴上它们，就算是在贝克兰德的社交场合中，您也会是足够耀眼的一位。"] = "Надев их даже на светские мероприятия в Баклунде, вы будете ослепительны.",
    ["戴莉·西蒙妮，你愿意接受这个任务吗？"] = "Дейли Саймон, ты готов принять эту миссию?",
    ["戴莉跟我一起，不用担心，我会带阿诺德回去的。"] = "Дэйли пойдёт со мной. Не волнуйся, я верну Арнольда.",
    ["戴莉，你……"] = "Дэйли, ты...",
    ["戴莉，你怎么会在这里？"] = "Дэйли, почему ты здесь?",
    ["戴莉？"] = "Дейли?",
    ["房子是市政拨款修建的，它代表的是政府的脸面，住在里边的人就不是了！"] = "Здание было построено на средства муниципалитета; оно представляет собой лицо правительства, но люди, живущие внутри, таковыми не являются!",
    ["所以……你想来试试？"] = "Итак... хочешь попробовать?",
    ["所以……我想请你先看看小黛西，再做决定。"] = "Итак... Я хотел бы попросить вас сначала увидеть Малышку Дейзи, прежде чем принимать решение.",
    ["所以你待会问什么？……诶，镜子背后的眼睛好像正在看着你？"] = "Так что ты собираешься спросить позже?...Эх, кажется, глаз за зеркалом смотрит на тебя?",
    ["所以你有什么事？没事的话别来打扰我。成为合格学徒的第一步是学着自己使用熔炉。"] = "Так чего же ты хочешь? Если ничего нет, не беспокойте меня. Первый шаг к тому, чтобы стать квалифицированным учеником, — научиться пользоваться печью самостоятельно.",
    ["所以占卜怎么说？"] = "И что же показало гадание?",
    ["所以我从来不让人拖欠房租，兴许你早上出门好好的，晚上就躺在墓地里了。"] = "Вот почему я никогда не позволяю людям задерживать арендную плату. Возможно, утром вы спокойно выходите из дома, а ночью лежите на кладбище.",
    ["所以我决定换一种方式，我要打败第一名的弗朗切斯科！"] = "Поэтому я решил изменить свой подход; Я собираюсь победить Франческо, занявшего первое место!",
    ["所以我建议你们不要进去，毕竟这么做有不小的风险。"] = "Поэтому я предлагаю вам не заходить; в конце концов, это сопряжено со значительными рисками.",
    ["所以我想回来看看，有没有可以协助处理的事情？"] = "Поэтому я хотел вернуться и посмотреть, могу ли я чем-нибудь помочь?",
    ["所以最好不要轻易尝试，还是来一本《第二纪十大未解之谜》吧，这可是《我与格尔曼斯帕罗二三事》作者的最新力作！"] = "Так что лучше не пробовать легкомысленно. Лучше приобрести экземпляр «Десяти неразгаданных тайн второй эпохи». Это последний шедевр автора «Вещи между мной и Германом Воробьем»!",
    ["所以要找到最近来过这的人，排查他们的状态？"] = "Значит, нам нужно найти людей, которые были здесь недавно, и проверить их состояние?",
    ["所以这是我们所有人的生日，我身为国王，一定会带他们回家过。"] = "Итак, это день рождения каждого. Как король, я обязательно заберу их домой, чтобы отпраздновать это событие.",
    ["所以，他会理解的……我相信他会理解的。"] = "Значит, он поймет... Я думаю, он поймет.",
    ["所以，你们不眠者的糟糕记性，连死后也无法摆脱？"] = "Значит, ты, Неспящий, даже после смерти не можешь избавиться от своих ужасных воспоминаний?",
    ["所以，你听得到它们说话？"] = "Итак, вы слышите, как они разговаривают?",
    ["所以，你是他们的国王？"] = "Так ты их король?",
    ["所以，你是来看病的。"] = "Итак, вы пришли к врачу.",
    ["所以，要来点美味的香料吗？"] = "Итак, хотите вкусных специй?",
    ["所以，请您……放过我。"] = "Итак, пожалуйста... отпусти меня.",
    ["所有的问题似乎都围绕黛丝死亡的真实原因……我很好奇，你为什么执着于得到这个真相？"] = "Кажется, все вопросы вращаются вокруг настоящей причины смерти Дейзи... Мне любопытно, почему ты так одержим идеей узнать эту правду?",
    ["所有规则都处在不断完善和修正的过程之中。这个过程需要每个人的参与，而我会不遗余力地帮助你们。"] = "Все правила находятся в процессе постоянного улучшения и пересмотра. Этот процесс требует участия каждого, и я приложу все усилия, чтобы помочь вам всем.",
    ["所有鲁恩风格的珠宝，都是由来自首都的大师级工匠亲手打造。"] = "Все украшения в стиле Лоен изготавливаются вручную столичными мастерами.",
    ["手动触发一次朗基努斯之枪降低棋局1秒CD，是否确认选择这项能力？选择后其他2个会消失"] = "Вручную активируйте Копье Лонгиния, чтобы сократить время восстановления «Гамбита веков» на 1 секунду. Подтвердить эту способность? Выбор этого приведет к исчезновению двух других.",
    ["手帕、蜡烛、肥皂，家用杂货，来海达这里看一看！"] = "Платки, свечи, мыло, товары для дома, приходите заглянуть к Хеде!",
    ["打一架"] = "Подраться",
    ["打听乐谱的故事"] = "Спросите об истории создания партитуры",
    ["打听折扣"] = "Спросите о скидках",
    ["打听皮特"] = "Спросить о Пите",
    ["打听皮特1111"] = "Спросить о Пите 1111",
    ["打工是不可能打工的。"] = "Работать невозможно, я никогда не буду работать.",
    ["打开狼鱼罐头给她"] = "Откройте для нее консервы из рыбы-волка.",
    ["打感情牌"] = "Сыграть на чувствах",
    ["打扰了。"] = "Прошу прощения.",
    ["打扰了，你们看起来很忙……看来我来得不是时候。"] = "Извините, что беспокою, вы выглядите очень занятым... кажется, я пришел не вовремя.",
    ["打扰您了，我去那边看看。"] = "Извините, что беспокою, я пойду проверю там.",
    ["打扰，请问是蒸汽与机械系的同学吗？"] = "Простите, вы студент факультета пара и машин?",
    ["打架输了，东西被抢了，肚子饿了，每天都鸡飞狗跳的。"] = "Проигранные драки, кражи вещей, голодание — каждый день — это чистый хаос.",
    ["扛？再扛下去，我怕我这肚子真要炸了。算了，我还是去碰碰运气吧，大不了赊账。"] = "Перетерпеть? Если я продолжу терпеть, боюсь, мой желудок действительно взорвется. Забудь, пойду попытать счастья, на худой конец попрошу кредит.",
    ["执念？"] = "Одержимость?",
    ["扫兴的家伙，趁今天没什么任务，你最好出去散散心，晚饭前记得回来就行。"] = "Какая убийственность. Поскольку миссий сегодня нет, вам лучше выйти и прочистить голову. Просто вернись до ужина.",
    ["扫地啊，妻子不愿意让我在家里做家务，我只能出来做义工了。"] = "Подметаем пол. Моя жена не хочет, чтобы я занимался домашними делами, поэтому я могу выходить только на волонтерскую работу.",
    ["扮演结束了……看来是因为戴莉女士的信使，我才能重历他们的过去。"] = "Актерство закончилось... Кажется, именно благодаря посыльному мисс Дейли мне удалось пережить их прошлое.",
    ["扮演？"] = "Действуя?",
    ["找人？我是专业的！"] = "Найти человека? Да я в этом деле профи!",
    ["找佣人的话，来我们帮助家庭仆人协会就对了。"] = "Если вы ищете прислугу, то обращение в нашу Ассоциацию домашней прислуги — правильный выбор.",
    ["找值夜者的话从后面这条小巷进去，左手边就是，洛耀女士经常会在门口透气。"] = "Если вы ищете «Ночных ястребов», идите в переулок позади этого, он находится с левой стороны. Г-жа Ло Яо часто подходит к двери, чтобы подышать воздухом.",
    ["找到您了，邓恩先生！"] = "Нашёл вас, мистер Данн!",
    ["找墓地的话不要去找小科勒，找我就好。"] = "Если вы ищете место для захоронения, не ходите в «Маленький Колер»; просто приди ко мне.",
    ["找错人了，劳维斯是那边那位，他这段时间正伤心着呢。"] = "Вы ошиблись человеком: Ловис — вон тот господин, он сейчас сам не свой от горя.",
    ["找队长"] = "Найдите капитана",
    ["把东西交出来。"] = "Сдать вещи.",
    ["把你这该死的夜香草拿走，把我的钱还给我！"] = "Уберите свою чертову ночную траву и верните мне мои деньги!",
    ["把松软面包给她"] = "Дайте ей мягкий хлеб",
