    ["斯维因不仅借钱收利息，还要收取这里所有摊位收益的二十分之一！真是一门赚钱的生意。"] = "Суэйн не только дает деньги взаймы под проценты, но и забирает одну двадцатую часть доходов со всех здешних ларьков! Это действительно прибыльный бизнес.",
    ["新sequence已经在重新拍摄中，目前是旧sequence，可以直接跳过，表现非正式"] = "Переснимается новый эпизод; в настоящее время это старая последовательность, которую можно сразу пропустить, поскольку она неформальна.",
    ["新乘客的票我不卖，你都没买过我怎么敢卖给你？"] = "Я не продаю билеты новым пассажирам; ты никогда у меня не покупал, как я посмею продать тебе?",
    ["新人？我是洛耀·莱汀，幸会。"] = "Новичок? Я Ло Яо Лайтин, приятно познакомиться.",
    ["新管家？库尔斯先生呢？我们是警官。"] = "Новый дворецкий? А как насчет мистера Курса? Мы сотрудники полиции.",
    ["新面孔？你好！"] = "Новое лицо? Привет!",
    ["新面孔？那我建议你最好别碰朗齐，在它面前，很多啤酒只能算是饮料。"] = "Новое лицо? Тогда я предлагаю вам не трогать Лангзи. Перед этим многие сорта пива можно считать только напитками.",
    ["新骰子，也许能带来新运气！"] = "Новые кости, может, принесут новую удачу!",
    ["新鲜出炉的仰望绯月派！瞧这诱人的色泽、独特的造型……这位客人，要尝尝吗？"] = "Свежеиспеченный пирог «Взгляд на багровую луну»! Посмотрите на этот соблазнительный цвет и уникальную форму... не хотите ли попробовать, гость?",
    ["新鲜出炉的柠檬蛋糕口味最佳，你可以先买一小块尝尝看。"] = "Свежеиспеченный лимонный пирог вкуснее всего; вы можете купить небольшой кусочек, чтобы попробовать сначала.",
    ["新鲜牛排，来自沃克牧场，肉质紧实多汁，炭烤或慢炖都能锁住风味！"] = "Свежий стейк от Walker Ranch, мясо плотное и сочное. Приготовление на углях или медленное тушение помогут сохранить вкус блюда!",
    ["新鲜的黑猪肉！詹妮女士，给您留了最完整的肋排！"] = "Свежая черная свинина! Мисс Дженни, я оставил вам самые целые ребрышки!",
    ["无"] = "Никто",
    ["无奈地摇头"] = "Беспомощно покачать головой",
    ["无知！那你就去给那个愚蠢的占卜师陪葬吧！"] = "Невежда! Тогда ступай в могилу вслед за тем глупым гадателем!",
    ["无论你是否听过这句告诫，我都要再次提醒：“小心观众”。"] = "Независимо от того, слышали ли вы это предупреждение, я должен напомнить вам еще раз: «Остерегайтесь зрителей».",
    ["无论你来自何处，永远记得，你可以回到这里。"] = "Откуда бы ты ни был родом, всегда помни: ты можешь вернуться сюда.",
    ["无论在哪儿，平民的生活都是平凡的。至于能不能把日子过成美酒——年轻人，还得看你们自己的本事。"] = "Где бы вы ни находились, жизнь простолюдина обычна. Что касается того, сможете ли вы превратить жизнь в хорошее вино, молодой человек, это зависит от ваших способностей.",
    ["无论如何，我先入梦调查。"] = "В любом случае, я сначала войду в сон, чтобы провести расследование.",
    ["无论正确与否，现在可以验证一下这个猜想了。"] = "Верна она или нет, но теперь можно проверить эту гипотезу.",
    ["无辜的人在非凡事件中遇难，总是令人惋惜，但事情已经无法挽回。"] = "Всегда прискорбно, когда невинные люди терпят катастрофу в результате инцидентов в Потустороннем, но то, что сделано, не может быть отменено.",
    ["无需多言，让我找找，水银、黄金、红宝石、黄铁矿，不，这都不与你崎岖的命运匹配。"] = "Ни слова больше. Дай-ка поглядеть: ртуть, золото, рубин, пирит... Нет, ничто из этого не подходит твоей тернистой судьбе.",
    ["无非是让他们没日没夜的工作、鞭打、不给饭吃……毕竟他们没有父母。"] = "Не что иное, как заставлять их работать день и ночь, бить их, не кормить... ведь у них нет родителей.",
    ["既然《大冒险家》巡演难得来廷根一次，还是买票吧。"] = "Поскольку тур «Великий авантюрист» редко приезжает в Тинген, мне следует купить билет.",
    ["既然是免费，尝尝！"] = "Поскольку это бесплатно, я попробую!",
    ["既然泽维尔先生鼓足勇气才第一次发出正式邀请，或许会选择更有特色的……"] = "Поскольку мистер Ксавьер набрался смелости и сделал свое первое официальное приглашение, возможно, он выберет что-нибудь более необычное...",
    ["旧友"] = "Старый друг",
    ["旧地"] = "Старое место",
    ["旧物"] = "Старые предметы",
    ["早就预订好了，今晚我们去老维尔餐厅，听说那边的老板很热情，一把年纪了还站在门口招待客人，我今天刚发了工资，这顿我请！"] = "Оно уже забронировано. Сегодня вечером мы идем в ресторан Олд Уилла. Я слышал, что босс там полон энтузиазма; он довольно старый, но все еще стоит у двери и приветствует гостей. Я только сегодня получил зарплату, так что еда за мой счет!",
    ["时尚是一个轮回，总要有人怀念过去……祝您拥有愉快的一天。"] = "Мода циклична, и кто-то всегда будет тосковать по прошлому... Приятного вам дня.",
    ["时间到了第二天中午……"] = "Время приближалось к полудню следующего дня...",
    ["时间可过得真快，眨眼间都1358年了，总感觉战争才刚刚结束。"] = "Время действительно летит; В мгновение ока на дворе 1358 год. Такое ощущение, что война только что закончилась.",
    ["时间可过得真快，眨眼间都1358年，总感觉战争才刚刚结束。"] = "Время летит так быстро. В мгновение ока на дворе 1358 год. Такое ощущение, что война только что закончилась.",
    ["时间见证友谊"] = "Время свидетельствует о дружбе",
    ["时间过得可真快，眨眼间都1354年了，总感觉战争才刚刚结束。"] = "Как же быстро летит время: глазом моргнуть не успели, а уже 1354 год. Кажется, будто война только вчера закончилась.",
    ["明天下午。还有其他货的话，尽快送过来。"] = "Завтра днем. Если у вас есть другие товары, отправьте их как можно скорее.",
    ["明天会有一些新的材料，可以到时候再来看看。"] = "Завтра будут новые материалы; потом можешь вернуться и посмотреть.",
    ["明天，我感觉我明天的牌运会特别好！"] = "Завтра, я чувствую, что моя удача в картах завтра будет особенно хорошей!",
    ["明明今天截止！这不是重点，你是不是写书的时候又喝酒了？"] = "Крайний срок сегодня! Дело не в этом. Ты снова пил, пока писал?",
    ["明明我家里有她最喜欢的童话绘本，还有甜甜的小饼干啊……"] = "У меня дома наверняка есть ее любимая книжка со сказками и милое печенье...",
    ["明白了，我来同幸存者交涉。"] = "Понял, я сам поговорю с выжившим.",
    ["明白什么……"] = "Поймите, что...",
    ["昨天晚上又闷又热，那架风车居然在转动，奇怪吧？明明一丝风都没有。"] = "Вчера вечером было душно и жарко, а ветряная мельница даже вращалась, странно, правда? Хотя дуновения ветра не было.",
    ["是"] = "Да",
    ["是……乔纳尔医生，他来为我治疗高烧。他让所有人都出去，说有一种特殊的办法，可以让我梦见艾德蒙。我同意他的提议，将食指伸进那个环里……"] = "Это... доктор Джонар, он приходил сбить мне сильный жар. Он велел всем выйти, сказав, что есть особый способ, который позволит мне увидеть Эдмунда во сне. Я согласилась и просунула указательный палец в то кольцо...",
    ["是。"] = "Да.",
    ["是个不错的选择。"] = "Это хороший выбор.",
    ["是九百三十七便士……"] = "Это девятьсот тридцать семь пенсов...",
    ["是什么？"] = "Что это такое?",
    ["是他逝去的未婚妻的发丝，那个勇敢的姑娘在弗萨克战争中去世了，我的客户先生寻找了她很多年。"] = "Это локон волос его покойной невесты: та отважная девушка погибла на войне с Фейсаком, и мой наниматель искал ее долгие годы.",
    ["是你们啊……想要夺走家人……坏蛋……"] = "Это ты... хочешь забрать мою семью... плохих людей...",
    ["是你呀！终于有人能来和我聊天了！"] = "Это ты! Наконец-то кто-то может прийти и пообщаться со мной!",
    ["是你杀了贾斯汀！"] = "Ты убил Джастина!",
    ["是你，我找到了一些线索，可能廷根湖那居住的人来到了这附近。"] = "Это ты. Я нашел некоторые подсказки; возможно, что люди, живущие на озере Тинген, пришли в эти окрестности.",
    ["是你？为什么冲着我吐痰？"] = "Это ты? Почему ты плюешь на меня?",
    ["是卡萝队长的遗物，它怎么会在这里……这就是你的任务？"] = "Это реликвия капитана Кэрол. Как оно могло быть здесь... Это твой квест?",
    ["是吗，你可以准备好在未来付出对等的的代价了……呵呵，我开玩笑的。"] = "Это так? Вы можете быть готовы заплатить аналогичную цену в будущем... хе-хе, я просто шучу.",
    ["是吗？我也从来不劈人。"] = "Это так? Я также никогда не поражаю людей молнией.",
    ["是吗？我的确很同情黛西小姐的遭遇。"] = "Это так? Я сочувствую тяжелому положению мисс Дейзи.",
    ["是吗？谢谢，谢谢，我这就去看看小姐。"] = "Действительно? Спасибо, спасибо, я сейчас пойду навестить девушку.",
    ["是吗？这样啊……你的家人来接你了……我做错事了对吗？我不知道，没有人告诉过我……"] = "Правда? Вот как... Твоя семья пришла забрать тебя... Я поступил неправильно, да? Я не знал, мне никто никогда не говорил...",
    ["是否确认选择这项能力？选择后其他2个会消失"] = "Вы уверены, что хотите выбрать эту возможность? Остальные 2 исчезнут после выбора",
    ["是呀！不景气，股市也跟着大跌，我先生的收入也锐减了，现在只能雇一下临时仆人了。"] = "И не говорите! Спад в экономике, фондовый рынок рухнул, доходы моего мужа сильно сократились, так что теперь мы можем позволить себе только подённую прислугу.",
    ["是呀，特别是我的好朋友们都开启各自的生活后，准确的说，是从学校毕业后，梅丽莎去了贝克兰德，伊丽莎白在廷根大学……"] = "Да, особенно после того, как мои хорошие друзья начали свою собственную жизнь. Если быть точным, после окончания школы Мелисса уехала в Бэкланд, а Элизабет учится в Тингенском университете...",
    ["是呢，所以自从认识了这些好朋友以后，芙拉再也没有感觉到孤单过！"] = "Да, с тех пор, как я встретил этих хороших друзей, Фула больше никогда не чувствовал себя одиноким!",
    ["是哈罗德。"] = "Это Гарольд.",
    ["是啊……正像您看到的这样。\n不过也别太难过，也许有一天会好的，是吗？也许有一天我能跑步呢。"] = "Да... как видите. \nНо не расстраивайся слишком сильно, может быть, однажды все станет лучше, верно? Может быть, однажды я смогу сбежать.",
    ["是啊是啊，我们说这个演讲啊，它呢不是讲演，也不是背书，那么它是什么呢？哎，这个演讲本身啊就是需要注意，哎，真的是，我跟你说啊，我有以下六点要说……"] = "Да-да, когда мы говорим об этом ораторском искусстве, это не чтение лекций и не декламация, так что же это такое? Эй, это ораторское искусство само по себе требует внимания, эй, правда, позвольте мне сказать вам, у меня есть следующие шесть пунктов...",
    ["是啊，不用什么秘方，靠四十年的习惯，再加上一点温柔，就足够成就一间好面包店。"] = "Да, вам не нужен какой-то секретный рецепт. Чтобы сделать хорошую пекарню, достаточно положиться на сорокалетний опыт и немного нежности.",
    ["是啊，他们说你是个很好的孩子。"] = "Да, они сказали, что ты очень хороший ребенок.",
    ["是啊，仿佛就在昨天一样。"] = "Да, такое ощущение, будто это было только вчера.",
    ["是啊，你看那边的演讲家一直在宣传女神，我听了很开心，咱们队伍又要壮大了！"] = "Да, посмотрите на оратора, который продолжает пропагандировать Богиню; Я был очень рад, слушая это, наша команда снова растет!",
    ["是啊，你瞧这张。"] = "Да, посмотри на это.",
    ["是啊，你都不知道值班有多无聊，我必须一直在这里守着查尼斯门……"] = "Да, вы даже не представляете, как скучно дежурить. Мне приходится все время оставаться здесь, охраняя Врат Чаниса...",
    ["是啊，大概人总得找个办法活下去，靠这样的抱团取暖努力生活着也是一条出路。"] = "Да, я полагаю, людям всегда приходится находить способ выжить. Рассчитывать на то, что вот так сбившись в кучу, чтобы жить тяжело, — это тоже выход.",
    ["是啊，它们对我可好呢，想晒太阳了大海就让我到太阳最好的地方去，想休息了沙滩就让我去乘凉。"] = "Да, они так добры ко мне. Когда я хочу загорать, Оушен позволяет мне пойти в место с лучшим солнцем, а когда я хочу отдохнуть, Пляж позволяет мне уйти в тень.",
    ["是啊，年轻人，我也这样想着。我年轻的时候，总是被要求什么好的都让给弟弟，再后来是让给儿子。"] = "Да, юноша, я тоже так думаю. В молодости от меня всегда требовали уступать всё самое лучшее младшему брату, а позже — сыну.",
    ["是啊，广场上都在讨论赞美女神的诗歌，我听了感觉很激动。"] = "Да, на площади все обсуждают стихи, восхваляющие Богиню, и я был глубоко растроган, слушая их.",
    ["是啊，当然要快快吸收养分，才能快点开出我自己的花来。"] = "Да, конечно, мне нужно быстро усваивать питательные вещества, чтобы поскорее распустить свои цветы.",
    ["是啊，我也觉得这事儿有点蹊跷。这汤闻着是挺香，可是……谁知道里面有没有什么猫腻？这年头，哪有白给的好处！"] = "Да, мне тоже кажется, что это немного подозрительно. Суп пахнет ароматно, но... кто знает, есть ли в нем какая-то хитрость? В наши дни бесплатного обеда не существует!",
    ["是啊，我们总在和未知的危险对抗……"] = "Да, мы всегда боремся с неведомыми опасностями...",
    ["是啊，最近廷根的餐厅都在开发新菜品，我们也不能落伍。"] = "Да, в последнее время все рестораны Тингена разрабатывают новые блюда, и нам нельзя отставать.",
    ["是啊，煤炭曾带来辉煌，放在几年前，拥有煤炭，就等同于拥有了潮水般的金镑。"] = "Действительно, уголь когда-то приносил славу. Несколько лет назад владение углем было равносильно приливной волне фунтов золота.",
    ["是啊，这对我们的新品牌有很大帮助，城市之间的时尚差异也是个很值得讨论的命题。"] = "Действительно, это будет большим подспорьем нашему новому бренду. Различия в моде между городами также являются темой, заслуживающей обсуждения.",
    ["是因为小阿诺德被卷进了这起事件吗？"] = "Не потому ли, что в этом инциденте был замешан маленький Арнольд?",
    ["是因为过去的生活很好吗？"] = "Это потому, что твоя прошлая жизнь была очень хорошей?",
    ["是姐姐教我的，我不会跟她走。但说不定，她会买下我一朵玫瑰呢！"] = "Сестра меня научила: я с ней никуда не пойду. Но вдруг она купит у меня розочку!",
    ["是它自己消失的！"] = "Оно исчезло само собой!",
    ["是我。"] = "Это я.",
    ["是我在说话。"] = "Это я говорил.",
    ["是我找到了真相，但我不会给你去伤害其他人的机会。"] = "Я нашел правду, но я не дам тебе шанса причинить вред кому-либо еще.",
    ["是我新研制的黑胡椒咖啡！听说其他地区的青椒咖啡卖得不错，我学习一下……"] = "Это мой новый рецепт: кофе с черным перцем! Слышал, в других краях кофе с зеленым перцем расходится на ура, вот и решил перенять опыт...",
    ["是我鲁莽了。"] = "Я был безрассуден.",
    ["是死亡的味道……"] = "Это запах смерти...",
    ["是熟人介绍的吗？"] = "Это представил знакомый?",
