    ["是的。"] = "Да.",
    ["是的。<P_Heart>（微笑）</>或许这就是为什么我父亲总让我别窝在自己的世界，多和别人相处。"] = "Да. <P_Heart> (Улыбается) </> Возможно, именно поэтому мой отец всегда говорил мне не замыкаться в своем собственном мире и проводить больше времени с другими.",
    ["是的。丽贝卡让我去了解更多，我以警官身份进行调查，也发现封印物的印记。"] = "Да. Ребекка попросила меня узнать больше. Я как офицер полиции провел расследование и также нашел след запечатанного объекта.",
    ["是的！"] = "Да!",
    ["是的，27个人。"] = "Да, 27 человек.",
    ["是的，{{先生|女士}}。你是有什么问题想问我吗？"] = "Да, {{ Mr. | Ms. } }. Есть ли у вас какие-либо вопросы, которые вы хотели бы мне задать?",
    ["是的，{{先生|女士}}。总有人出于嫉妒或是什么，对其他竞争者出言诋毁，这很常见。"] = "Да, {{Mr.|Ms.}}. Всегда находятся люди, которые из зависти или чего-то другого унижают других конкурентов; это очень распространено.",
    ["是的，{{先生|女士}}，在这里，饿死几个流浪汉不是新鲜事儿。只不过……"] = "Да, {{Mr.|Ms.}}, здесь несколько бездомных, умирающих от голода, не являются чем-то новым. Просто это...",
    ["是的，{{先生|女士}}，您看，这是她妈妈给她的火柴盒，原本这个火柴盒是她妈妈用来装工资条的。"] = "Да, {{Mr.|Ms.}}, смотри, это спичечный коробок, который подарила ей мать. Первоначально ее мать использовала этот спичечный коробок для хранения квитанций о зарплате.",
    ["是的，不用担心，好好休息吧。"] = "Да, не волнуйтесь. Хорошо отдохните.",
    ["是的，不过和以前比，数量并不算多。"] = "Да, но по сравнению с тем, что было раньше, это число не так уж и велико.",
    ["是的，也可以用来展示大场景…..."] = "Да, его также можно использовать для показа больших сцен...",
    ["是的，他一直是。"] = "Да, он всегда был таким.",
    ["是的，他们以纺织相关的物品做名字，只有他们的首领有一个像样的名字，叫做亨特。"] = "Да, они используют в качестве названий предметы, связанные с текстилем. Только у их лидера приличное имя по имени Хантер.",
    ["是的，他和莫雷蒂先生算是同期加入俱乐部的，如今也成了廷根小有名气的占卜家了，他们挺熟的。"] = "Да, он и мистер Моретти присоединились к клубу примерно в одно и то же время, и теперь он стал известным Провидцем в Тингене. Они довольно близки.",
    ["是的，他很和蔼，给我父亲的感觉，但不知道为什么，以前我总会有点怕他。"] = "Да, он был очень добрым, чувствовал себя для меня отцом, но не знаю почему, раньше я его немного боялся.",
    ["是的，但谁能确定灾祸不会降临到自己头上？"] = "Да, но кто может быть уверен, что на них не обрушится беда?",
    ["是的，你也是来看望他们的？"] = "Да, ты тоже здесь, чтобы навестить их?",
    ["是的，你看这边。"] = "Да, посмотрите сюда.",
    ["是的，例如这种对着我的脸推进的镜头，通常用来表达震惊的情绪。"] = "Да, например, эта камера, направленная к моему лицу, обычно используется для выражения шока.",
    ["是的，先生。"] = "Да, сэр.",
    ["是的，听说还是他曾经的梦想。不知道有没有画家这条非凡途径？一定很适合弗莱队长。"] = "Да, говорят, он когда-то даже мечтал об этом. Интересно, существует ли Путь Художника? Он бы точно подошел капитану Фраю.",
    ["是的，和家人团聚……是我们在这个世界活下去的意义。"] = "Да, воссоединение с семьей... это смысл нашего существования в этом мире.",
    ["是的，女士。一点点咖啡并不会影响睡眠。"] = "Да, мэм. Немного кофе не повлияет на сон.",
    ["是的，她是我们的女儿，被那辆马车压断了脊柱。"] = "Да, она наша дочь, и ей раздробил позвоночник та коляска.",
    ["是的，小家伙还好吗？感谢你一直以来对他的照顾。"] = "Да, с малышом все в порядке? Спасибо, что заботились о нем все это время.",
    ["是的，您坐到贝克兰德的火车就会路过那处花海。"] = "Да, вы проедете мимо этого моря цветов, когда сядете на поезд до Баклунда.",
    ["是的，我们不仅有浪漫主义，也谈论了生活的难处。这越发让我觉得我应该有男子汉的担当。"] = "Да, у нас не только романтика, но и разговоры о трудностях жизни. Это заставляет меня еще больше чувствовать, что я должен нести ответственность мужчины.",
    ["是的，我们也可以进入小黛西的循环空间，和她团聚。"] = "Да, мы также можем войти в пространство петли Маленькой Дейзи и воссоединиться с ней.",
    ["是的，我住在东区，周末都会过来照顾一下花园。"] = "Да, я живу в Восточном районе и по выходным прихожу сюда присмотреть за садом.",
    ["是的，我和她有过一些交情。"] = "Да, я был с ней знаком.",
    ["是的，我姐姐叫罗莎琳，她是<P_Yellow>尼根公爵府的女仆</>。但她却在不久前失踪了，我到处都找不到她。只能在这里一边卖花一边继续找她。"] = "Да, мою сестру зовут Розалинда. Она <P_Yellow> горничная</> особняка герцога Нигана. Но она недавно исчезла, и я не могу ее нигде найти. Я могу только продолжать ее искать, продавая здесь цветы.",
    ["是的，我是管家库尔斯。请问您是？"] = "Да, я дворецкий, Кур. Могу я спросить, кто вы?",
    ["是的，我来是来这里参观的。这里的环境很不错。"] = "Да, я здесь в гостях. Обстановка здесь довольно хорошая.",
    ["是的，我的父亲、邓恩队长与戴莉女士他们，都在那里。"] = "Да, мой отец, капитан Данн и леди Дейли все здесь.",
    ["是的，我闻到了。雏菊开得很好，香气也十分浓郁。"] = "Да, я почувствовал этот запах. Ромашки красиво цвели, и аромат был очень насыщенным.",
    ["是的，有人看到在码头附近，有个小孩很像我的小巴特，这次我一定能找到他！"] = "Да, кто-то видел возле Дока ребенка, очень похожего на моего маленького Барта. На этот раз я обязательно его найду!",
    ["是的，有什么线索吗？"] = "Да, у тебя есть какие-нибудь подсказки?",
    ["是的，灵界生物的习性各异，我路过的正是一个热爱品酒的生物聚落。"] = "Да, привычки существ из Мира Духов различаются. То, мимо чего я прошел, представляло собой скопление существ, любящих вино.",
    ["是的，真是漂亮的房子……"] = "Да, это действительно красивый дом...",
    ["是的，编辑器还支持根据文本调用动作和语音资源。"] = "Да, редактор также поддерживает вызов действий и голосовых ресурсов на основе текста.",
    ["是的，莫雷蒂先生是位让人倍感亲切的人，他帮助过很多来这里寻求帮助的人，要是感兴趣的话，你可以西格拉斯先生聊聊。"] = "Да, мистер Моретти был человеком, который заставлял людей чувствовать себя очень добрыми. Он помог многим людям, пришедшим сюда за помощью. Если вам интересно, вы можете пообщаться с мистером Сиглассом.",
    ["是的，虫子，成群结队的、吞吃一切“谜团”的虫子，而书籍正是谜团的尸骸。"] = "Да, жуки, стаи жуков, пожирающие все «тайны», а книги — это трупы тайн.",
    ["是的，衷心且真诚的感谢。"] = "Да, моя самая искренняя и сердечная благодарность.",
    ["是的，让贵族们从人群中脱颖而出，这不是简单堆叠花边可以实现的……需要特殊的创新点。谢谢您。"] = "Да, выделить аристократов из толпы невозможно, просто надев кружева... Это требует особого новаторства. Спасибо.",
    ["是的，这些对成年人来说，总是很稀缺。"] = "Да, взрослым этого вечно не хватает.",
    ["是的，这对你的任务、你的职责……都没有影响。"] = "Да, это не влияет на вашу миссию, ваш долг...",
    ["是的，阿曼达女士。咖啡可以提神，一点点甜有益于思考。"] = "Да, мисс Аманда. Кофе может освежить разум, а немного сладости полезно для размышлений.",
    ["是神明驱逐了灾难……还是灾难驱逐了神明呢……"] = "Боги изгнали катастрофу... или катастрофа изгнала богов...",
    ["是笛声！我在阿诺德的梦中听到过，尤朵拉可能就在附近！"] = "Это звук флейты! Я слышал его во сне Арнольда. Юдора может быть где-то поблизости!",
    ["是罗塞尔大帝。"] = "Это Император Розель.",
    ["是被邓恩叔叔吓跑了吗？"] = "Их спугнул дядя Данн?",
    ["是谁？"] = "Кто это?",
    ["是这样啊。那小芙拉，你为什么想要变成一朵花呢？"] = "Это так. Тогда маленькая Фула, почему ты хочешь стать цветком?",
    ["是这样的……"] = "Это вот так...",
    ["是这样的，我今早去巡逻时，发现我们的王国被封锁了。我尝试钻空子，但还是没能返回基地。"] = "Дело вот в чём: отправившись утром на патрулирование, я обнаружил, что наше королевство заблокировано. Я пытался найти лазейку, но так и не смог вернуться на базу.",
    ["是那种可以动来动去的镜头，对吧。"] = "Это такая линза, которая может двигаться, верно.",
    ["是错觉吗？"] = "Это иллюзия?",
    ["是鞋泥！皮革和泥土的芬芳，多么令人陶醉啊……"] = "Это обувная грязь! Аромат кожи и земли, как опьяняет...",
    ["是，但留在这里的只是一具躯壳，她的灵躲起来了。"] = "Да, но здесь осталась лишь оболочка; ее дух спрятался.",
    ["是，灵界之上的伟大存在。"] = "Да, великое существование над Миром Духов.",
    ["显而易见，我不属于这里！没有人会害怕自己熟悉的地方。"] = "Очевидно, мне здесь не место! Никто не будет бояться места, которое ему знакомо.",
    ["显而易见，排队！"] = "Очевидно же — очередь!",
    ["晋升失败"] = "Продвижение не удалось",
    ["晚上九点，卡拉去给小姐<P_Yellow>擦手</>，却忽然昏倒在地，没多久呼吸和心跳都消失了。我们先让女仆艾琳接手照顾小姐，没想到她也以同样的方式去世了。"] = "В девять часов вечера Кара пошла <P_Yellow>обтереть руки</> барышне, как вдруг без чувств рухнула на пол, и вскоре дыхание и пульс у нее пропали. Сначала мы поручили уход за барышней горничной Айрин, но та неожиданно скончалась точно так же.",
    ["晚上好，我正在找你。"] = "Добрый вечер, я ищу вас.",
    ["晚上好，邓恩叔叔！"] = "Добрый вечер, дядя Дэн!",
    ["晚上打烊的时候，老维尔还会把没卖完的食物留给住在后门的流浪汉。"] = "Закрываясь на ночь, Старый Уилл также оставляет непроданную еду для бездомных у задней двери.",
    ["晚安。"] = "Спокойной ночи.",
    ["普通款式的服饰，我这都能做，你给我大概讲一下款式要求就好，太过高档的服饰，我就不太擅长了。"] = "Я могу шить обычную одежду. Просто скажите мне общие требования к стилю; Я не очень хорошо разбираюсь в дорогой одежде.",
    ["暂时不用，我也没什么头绪。"] = "Пока нет, у меня тоже нет никаких зацепок.",
    ["暂时放弃"] = "Сдавайся пока",
    ["暂时没有什么想买的。"] = "Пока ничего не хочу купить.",
    ["暂时没有想问的"] = "Не о чем просить сейчас",
    ["暂时没有更多了，可以去和其他非凡者交易试试。"] = "Больше пока ничего нет. Вы можете попробовать торговать с другими Потусторонними.",
    ["暂时没有，但我会帮你留意的。"] = "Не сейчас, но я присмотрю за тобой.",
    ["暂时离开"] = "Временно уйти",
    ["暂时算了吧。"] = "Забудь об этом на данный момент.",
    ["暴力拆锁！"] = "Насильно сломайте замок!",
    ["更何况鲁恩已经出台法律禁止了这些事情。"] = "Тем более что в Лоэне уже приняты законы, запрещающие подобные вещи.",
    ["更何况，黑夜教会每月都会给我们一大笔养育资金。说真的，我们都觉得这对养育一个孩子来说有些太多了……"] = "Более того, Церковь Вечной Ночи каждый месяц выделяет нам крупную сумму денег на его воспитание. Честно говоря, мы все считаем, что это слишком много для воспитания одного ребенка...",
    ["更加工整了。"] = "Более аккуратный.",
    ["更离谱的是，有人说，连续三次投中，就能够回家……"] = "Еще более возмутительно то, что некоторые говорят, что если поразить цель три раза подряд, то можно идти домой...",
    ["更重要的工作？啊我明白了，放心吧亲爱的布莱特，报酬从来不是问题，我也能付得起重要的价码。"] = "Более важная работа? Ах, я понимаю. Не волнуйтесь, дорогой Брайт, награда никогда не будет проблемой, и я могу позволить себе значительную цену.",
    ["曼妮莎小姐已经在这等了很久了……从她的描述来看泽维尔先生并不会真的如此无礼，睡过了约会时间，一定是在别的地方……"] = "Мисс Маниша уже давно ждет здесь... Судя по ее описанию, мистер Ксавьер не был бы настолько груб, чтобы спать после назначенного времени. Он, должно быть, где-то еще...",
    ["曼妮莎小姐，我有个大胆的猜测，或许你该去老维尔餐厅找一找，我相信若泽维尔先生没有失约，那他应该还在那儿痴痴等候呢。"] = "Мисс Маниша, у меня есть смелое предположение. Возможно, вам стоит пойти в ресторан Old Will и посмотреть. Я считаю, что если мистер Ксавьер не нарушил своего обещания, ему все равно следует глупо ждать там.",
    ["曾有人说，死而复生便是奇迹。你觉得什么才是真正的奇迹？ "] = "Кто-то однажды сказал, что воскресение – это чудо. Что вы считаете настоящим чудом?",
    ["曾经也是值夜者？你是说……"] = "Тоже когда-то был Ночным Ястребом? Ты имеешь в виду...",
    ["曾经只有贵族才能定义优秀的设计，哪怕那些都太过累赘单调——大量的黄金、珍珠、珊瑚……昂贵材料的手工堆砌。"] = "Когда-то только дворяне могли определить отличный дизайн, даже если он был слишком громоздким и однообразным — ручное складывание большого количества золота, жемчуга и кораллов… дорогих материалов.",
    ["曾经我也是个逃避训练的战士，直到……"] = "Раньше я был Воином, который избегал тренировок, пока...",
    ["曾经有些小插曲，不过这是我的私事。为了流浪王国的未来，外交大臣我跟你一起去找他们谈判。"] = "Были небольшие эпизоды, но это мое личное дело. Ради будущего Странствующего Королевства, как министр иностранных дел, я пойду с вами вести с ними переговоры.",
    ["曾经？"] = "Один раз?",
    ["最受欢迎的是简妮斯，对于情感方面的……嗯，你懂的，她对这方面就很擅长，不管是男方还是女方。"] = "Самая популярная — Дженис. Что касается дел сердечных... ну, вы понимаете, она в этом настоящая искусница, будь то с мужчинами или с женщинами.",
    ["最后那个可怜的女人死的时候，也没见到吉瑞尔。吉瑞尔回来看了一眼墓碑，就又去海上了。真是冷血。"] = "В конце концов, когда эта бедная женщина умерла, Гиреля даже не было рядом. Он вернулся, чтобы взглянуть на надгробие, а затем вернулся в море. Действительно хладнокровный.",
    ["最好的朋友！"] = "Лучший друг!",
    ["最爱你的，罗莎琳"] = "Люблю тебя больше всего, Розалинда",
    ["最终要的是，我们的会员可以自由地在俱乐部帮人占卜，并自己确定价格，我们只抽取很低比例的费用，您可以看看其他会员的介绍和定价。"] = "И самое главное: члены нашего клуба вольны гадать другим посетителям и сами назначать цены. Мы удерживаем лишь крошечный процент в качестве комиссии. Вы можете взглянуть на анкеты и расценки других участников клуба.",
    ["最经典吃法，就连富人区老爷们的女仆都常来光顾呢！{{先生|女士}}来一块吗？"] = "Самый классический способ его употребления; даже служанки господ из богатого района часто приходят к нам покровительствовать! {{ Mr. | Ms. } }, хотите кусочек?",
    ["最起码在文史方面，我们是全方位碾压廷根大学的，这一点毋庸置疑。"] = "По крайней мере, в плане литературы и истории мы полностью разгромим Тингенский университет. В этом нет никаких сомнений.",
    ["最近事情太多，可以慢慢告诉她。对了，乔纳尔医生住哪里？"] = "В последнее время произошло слишком много всего; Я могу сказать ей медленно. Кстати, где живет доктор Джонар?",
    ["最近你有没有发现什么奇怪的事情？"] = "Вы заметили что-нибудь странное в последнее время?",
    ["最近大家想尝尝不同的口味，所以弗莱队长派我来探索新的餐厅，丰富大家的伙食种类。"] = "В последнее время всем хочется попробовать разные вкусы, поэтому капитан Фрай отправил меня исследовать новые рестораны, чтобы разнообразить наш выбор блюд.",
    ["最近弗莱队长看起来压力很大，像有什么要发生似的，搞得我们也很紧张。"] = "Капитан Фрай в последнее время выглядит очень напряженным, как будто что-то вот-вот произойдет, что заставило нас всех очень нервничать.",
    ["最近我从塔罗学派获得很多指引和帮助——“正义”女士、“星星”先生……"] = "Недавно я получил много советов и помощи от Клуба Таро. Справедливость, мистер Стар...",
    ["最近我的记性是不是更差了。"] = "Ухудшилась ли моя память в последнее время?",
