    ["检查手臂"] = "Контрольный рычаг",
    ["检查脉搏"] = "Проверить пульс",
    ["检查黛西小姐的手腕——摸到了隐隐跳动的脉搏！"] = "Проверяем запястье мисс Дейзи — она почувствовала слабо бьющийся пульс!",
    ["检查鼻息"] = "Проверить дыхание",
    ["楼下那两个傻瓜，不知道在图书室要安静吗？"] = "Те двое дурней внизу не знают, что в библиотеке нужно соблюдать тишину?",
    ["模糊的阴影与预兆，你接触某些仪式太过深入了。"] = "Размыты тени и предзнаменования, вы слишком глубоко углубились в некоторые ритуалы.",
    ["欢迎下次光临，期待与您再次相逢。"] = "Добро пожаловать к нам в следующий раз и с нетерпением ждем встречи с вами снова.",
    ["欢迎你，孩子！"] = "Добро пожаловать, дитя!",
    ["欢迎光临服装店，很抱歉，如您所见……我现在不是很能脱开身，您可以先自己随便看看。"] = "Добро пожаловать в магазин одежды. Мне очень жаль, как ты видишь... Я сейчас не очень свободен, ты можешь сначала осмотреться сам.",
    ["欢迎光临珠宝店，随便看看。"] = "Добро пожаловать в ювелирный магазин, смело осмотритесь.",
    ["欢迎光临街角咖啡厅，{{先生|女士}}，您需要什么吗？"] = "Добро пожаловать в кафе на углу улицы, {{ Mr. | Ms. }}. Есть ли что-нибудь, что вам нужно?",
    ["欢迎光临！"] = "Добро пожаловать!",
    ["欢迎光临！不用四处张望，我就是这家店的老板。"] = "Добро пожаловать! Не нужно оглядываться, я владелец этого магазина.",
    ["欢迎光顾，请随意挑选，{{先生|女士}}。"] = "Добро пожаловать, пожалуйста, просматривайте, {{Mr.|Ms.}}.",
    ["欢迎您下次光临。"] = "Будем рады видеть вас снова.",
