    ["欢迎来到占卜家协会！"] = "Добро пожаловать в Клуб провидцев!",
    ["欢迎来到占卜家协会，您是想占卜，还是加入我们俱乐部？"] = "Добро пожаловать в клуб гадания. Желаете погадать или желаете вступить в наш клуб?",
    ["欢迎来到哈罗德百货，最近又来了不少新品，要来看看吗！"] = "Добро пожаловать в универмаг Гарольда. В последнее время у нас появилось довольно много новинок. Хотите взглянуть?",
    ["欢迎来到塔罗试炼，你准备好了吗？"] = "Добро пожаловать на Испытание Таро. Вы готовы?",
    ["欢迎来到我的地盘！"] = "Добро пожаловать на мою территорию!",
    ["欢迎来到我的裁缝铺，需要定制衣服吗？"] = "Добро пожаловать в мою ателье. Вам нужна одежда на заказ?",
    ["欢迎来到波拿巴餐厅！"] = "Добро пожаловать в ресторан Бонапарт!",
    ["欢迎来到银冠餐厅。"] = "Добро пожаловать в ресторан «Серебряная корона».",
    ["欢迎来海岸线餐厅品尝南方海洋的味道。"] = "Добро пожаловать в ресторан Coastline, чтобы попробовать ароматы южного океана.",
    ["款式也是，下装流行收束的裤脚，更方便行动。"] = "Стиль тоже другой; Для брюк популярны зауженные штанины, более удобные для движения.",
    ["歌声？说起来卡萝队长也是不眠者序列，而且擅长唱歌。"] = "Пение? Если подумать, капитан Карро тоже принадлежала к Пути Неспящих и хорошо пела.",
    ["歌颂者途径导师"] = "Наставник Пути Барда",
    ["正在进入塔罗学派。"] = "Вступление в Клуб Таро.",
    ["正常生活，远离一些怪异的事情，有事没事多去教堂祷告。"] = "Живите обычной жизнью, держитесь подальше от всяких странностей и почаще ходите в церковь молиться.",
    ["正是因为这样，3-888的危险等级暂时只是3级。"] = "Именно из-за этого уровень опасности 3-888 на данный момент является только уровнем 3.",
    ["正面。"] = "Головы.",
    ["此后，他将再也不会畏惧海水的冰冷，\n和枪炮的轰鸣。"] = "С тех пор он больше никогда не убоится ни холода морских глубин,\nни грохота орудий.",
    ["武力威胁"] = "Угрожать силой",
    ["死而复活？"] = "Воскрешение?",
    ["殿、殿下。"] = "Ваше, Ваше Высочество.",
    ["殿下……我不想伤害您……我不想伤害您……"] = "Ваше Высочество... Я не хочу вас обидеть... Я не хочу вас обидеть...",
    ["殿下一定能带我去比霍纳奇斯山脉更东，比迷雾海更西的地方！"] = "Ваше Высочество наверняка сможет отвезти меня куда-нибудь дальше на восток, чем горный хребет Хорнацис, и дальше на запад, чем Туманное море!",
    ["母亲？！"] = "Мать?!",
    ["母神啊……我愿发誓，我的菜若是从其他菜贩手中购入，等我的生命凋零，我将不会坠入大地，永远无法回归母亲的怀抱。"] = "Мать-Земля... Клянусь, если бы мои овощи были куплены у других торговцев, то, когда моя жизнь завянет, я не упаду в землю и никогда не смогу вернуться в объятия Матери.",
    ["每一场战争都有由来，而我，为你们打开通往它们的大门。"] = "У каждой войны есть свои истоки, и именно я открываю вам дверь, чтобы добраться до них.",
    ["每个人的命运属于他们自己，只有“你”才是答案，我们开始吧。"] = "Судьба каждого принадлежит ему самому; только «ты» — ответ. Начнем.",
    ["每个季度我会把这些单子整理好交给弗莱队长，他会拿去圣堂报销并申请下一季度的单费。"] = "Ежеквартально я собираю эти счета и передаю их капитану Фраю. Он отвезет их в Святой собор для возмещения ущерба и подачи заявления на получение средств на следующий квартал.",
    ["每天出门买菜，和你说说闲话，是我最高兴的时候。"] = "Каждый день ходить за продуктами и болтать с тобой — это самое счастливое время для меня.",
    ["每天对着窗户外的马车愁眉苦脸……她肯定在幻想一次郊游呢。"] = "Каждый день с хмурым лицом смотрю на карету за окном... Должно быть, она мечтает о прогулке.",
    ["每天搬着砖，啃着黑面包……哎！说这个干什么，{{先生|女士}}，感谢您听我唠叨。"] = "Таскать кирпичи и есть черный хлеб каждый день... Эй! О чем вы говорите, {{Г-н|Мисс.}}, спасибо, что выслушали меня.",
    ["每天来一杯咖啡，能让人精神抖擞呢！"] = "Чашка кофе каждый день поднимает настроение!",
    ["每天都这么难受，这些烧煤产生的烟雾已经把我们的皮肤和牙齿熏得发黄了，不知道还会熏成什么样。"] = "Это так грустно каждый день. Дым от горящего угля уже окрасил нашу кожу и зубы в желтый цвет. Я не знаю, во что еще это их испачкает.",
    ["每条面包的重量在0.5磅左右，不过也会有一些不可避免的误差，你可以按需购买。"] = "Каждая буханка хлеба весит около 0,5 фунта, но будут неизбежные ошибки, поэтому покупать можно по мере необходимости.",
    ["比如什么呢？捡垃圾比赛？还是谁能在工厂里干更多的活？"] = "Как что? Соревнования по сбору мусора? Или кто может выполнять больше работы на заводе?",
    ["比如伦纳德，一个不像诗人的午夜诗人，他作诗的水平比邓恩还糟糕，让人很担心他要怎么从午夜诗人晋升。"] = "Например, Леонард, Полуночный поэт, который не ведет себя как поэт. Его поэтические навыки даже хуже, чем у Данна, что заставляет беспокоиться о том, как он продвинется из «Полуночного поэта».",
    ["比如农夫暴毙，凶手是一只鸭子。"] = "Например, внезапно умер фермер, а убийцей оказалась утка.",
    ["比如呢？"] = "Например?",
    ["比如该拧希罗多德的左耳朵，还是右耳朵？"] = "Например, следует ли мне крутить Геродоту левое или правое ухо?",
    ["比如，“离开对未来生活的憧憬，公民将与咸鱼无异”，“人不读书和咸鱼有什么区别”。"] = "Например, «Без тоски о будущей жизни граждане ничем не будут отличаться от соленой рыбы», «Чем отличаются люди, которые не учатся, от соленой рыбы».",
    ["比赛结束后，酒吧仍然很热闹。"] = "После окончания соревнований в баре все еще было очень оживленно.",
    ["毕竟3-116是廷根值夜者前任队长卡萝·比舍普的“遗物”，由我这个曾追随她的队员去回收，是最好的选择。"] = "В конце концов, номер 3-116 – это «реликвия» бывшего капитана «Тинген Найтхокс» Карро Бишопа. Для меня, члена команды, который когда-то следовал за ней, это лучший выбор, чтобы вернуть его.",
    ["毕竟在逼仄的生活中，我们要先享受灵魂的自由。"] = "Ведь в этой тесной жизни мы должны прежде всего насладиться свободой души.",
    ["毕竟查尼斯门后面什么都有……"] = "Ведь за воротами Чанис есть все...",
    ["毕竟这是我们廷根值夜者的重点关注区域。"] = "В конце концов, это ключевая проблема для наших «Ночных ястребов Тингена».",
    ["毕竟，我们的未来取决于图书馆、阅读和白日梦。"] = "В конце концов, наше будущее зависит от библиотек, чтения и мечтаний.",
    ["气体实验中的偏差质量是混入了杂质！"] = "Отклонение массы в газовом эксперименте связано с примесями примесей!",
    ["气息即将消散，您忠诚的谦卑的阿罗德斯等待着再次为您效劳。（挥手简笔画）"] = "Аура вот-вот рассеется. Ваш верный и скромный Аррод снова ждёт, чтобы служить вам. (машет фигуркой)",
    ["永远爱你的，罗莎琳"] = "Всегда люблю тебя, Розалинда",
    ["永远都这样脏兮兮，破破烂烂，灰扑扑的……"] = "Вечно тут так грязно, убого и серо...",
    ["汉特夫妇的帽子实惠又耐用，他们靠一针一线地缝帽子，把孩子送去了贝克兰德技术学校。"] = "Шляпы Охотников были доступными и прочными. Они сшили их стежок за стежком и отправили детей в Баклундскую техническую школу.",
    ["汉特的店发生什么了？"] = "Что случилось с магазином Ханта?",
    ["汪嘻嘻嘻……"] = "Гав-хи-хи-хи...",
    ["汪汪汪汪汪！汪！"] = "Гав-гав-гав-гав-гав! Гав!",
    ["汪！"] = "Гав!",
    ["汪！汪汪！汪汪汪！"] = "Гав! Гав-гав! Гав-гав-гав!",
    ["沃特先生的服饰店、桑加小姐的咖啡厅、我的老房子……水仙花街的一切都让人怀念。"] = "Магазин одежды мистера Уотта, кафе мисс Санги, мой старый дом... все на Даффодил-стрит вызывает ностальгию.",
    ["沉入梦境……灵感有所预兆"] = "Падение во сне... есть признаки вдохновения",
    ["没、没关系，先买吧。一顿不吃不会饿死，但末场不看，我会遗憾而死！"] = "Это, не важно, сначала купите. Пропуск одного приема пищи меня не убьет, но если я не увижу финальное шоу, я умру с сожалением!",
    ["没事。那我就先走了，我们待会见。"] = "Ничего. Я сейчас пойду, увидимся позже.",
    ["没事了"] = "сейчас все в порядке",
    ["没事了。"] = "Неважно.",
    ["没事了，谢谢"] = "Все в порядке, спасибо",
    ["没事的，好好休息吧。"] = "Все в порядке, отдохни хорошенько.",
    ["没事，下次不要迟到就好。"] = "Ничего страшного, только не опаздывайте в следующий раз.",
    ["没人在家吗，真不巧。"] = "Никого нет дома? Какая досада.",
    ["没什么了"] = "Ничего больше.",
    ["没什么，只是想到了之前的一些事情。"] = "Ничего, просто думаю о некоторых вещах из прошлого.",
    ["没什么，我先前遇见了一个自称财政大臣的孩子，他向我要了一些钱，他也是你的臣民？"] = "Ничего, я раньше встречал ребенка, который утверждал, что он министр финансов, он попросил у меня денег, он тоже ваш подданный?",
    ["没什么，最近一切还顺利吗？"] = "Ничего особенного. Все ли шло гладко в последнее время?",
    ["没什么，这小子来买学术期刊。"] = "Ничего, этот парень здесь, чтобы покупать научные журналы.",
    ["没任务不能来廷根吗？虽然这里的咖啡比不上贝克兰德，但是女仆……咳咳，还是不错的。"] = "Разве я не могу приехать в Тинген без поручения? Хоть местный кофе и уступает бэкландскому, но горничные... кхм-кхм, очень даже ничего.",
    ["没关系{{先生|女士}}，感谢您的热心。"] = "Все в порядке, {{ Mr. | Ms. }}, спасибо за доброту.",
    ["没关系，你很努力，坚强的女孩，愿女神庇佑你。"] = "Ничего страшного, ты очень трудолюбивая, сильная девочка. Пусть Богиня благословит вас.",
    ["没关系，卡萝队长会帮我的。"] = "Все в порядке, капитан Кэрил мне поможет.",
    ["没关系，反正现在那都一样，活人可比死人难缠多了。回归女神的怀抱，说不定才是最好的选择。"] = "Это не имеет значения, сейчас всё равно. Живые доставляют гораздо больше хлопот, чем мертвые. Возвращение в объятия Богини может быть лучшим выбором.",
    ["没关系，如果想念母亲，就回家看看吧。"] = "Все нормально. Если ты скучаешь по матери, пойди домой и навести ее.",
    ["没关系，我来付钱，你选喜欢的就好。"] = "Не беда, я заплачу, а вы можете выбрать то, что вам нравится.",
    ["没关系，这个就已经足够了。"] = "Все в порядке, этого достаточно.",
    ["没关系，这附近没什么别的人，不会被听到的。"] = "Ничего страшного, поблизости никого нет, нас никто не услышит.",
    ["没听清吗？我是说，我是乞丐。"] = "Разве ты не слышал ясно? Я сказал: я нищий.",
    ["没喝酒怎么会醉呢？也许醉了就好了……"] = "Как я мог быть пьяным, не выпивая? Может быть, было бы лучше, если бы я был пьян...",
    ["没想到只用了两根。"] = "Я не ожидал, что буду использовать только два.",
    ["没想到在这也遇见了你。你是有了什么新发现吗？"] = "Я тоже не ожидал встретить тебя здесь. Были ли у вас новые открытия?",
    ["没效果？那包草药需要空腹服用，你用之前没吃东西吧？"] = "Нет эффекта? Эту пачку трав нужно принимать натощак. Ты же ничего не ел перед тем, как его использовать, верно?",
    ["没有万能的灵药，但是有对症的药方。"] = "Панацеи не существует, но есть рецепты от конкретных симптомов.",
    ["没有了"] = "Больше нет",
    ["没有了……没有了……\n哪怕往前一步的方向，都没有了……"] = "Ничего не осталось... Ничего не осталось...\nБольше нет даже направления, чтобы сделать хотя бы шаг вперёд...",
    ["没有别的问题"] = "Никаких других вопросов",
    ["没有啊。我既没有吃面包也没有吃炖菜，我只喝了点牛奶，吃了一口香蕉！"] = "Нет. Я не ел ни хлеба, ни тушеного мяса, я только выпил немного молока и съел кусочек банана!",
    ["没有啊，他说要做有文化的屠夫，回家编写《雌性家猪的产后生理调护》去啦！"] = "Нет, он сказал, что хочет стать культурным мясником, и пошел домой писать «Послеродовой физиологический уход за домашними свиньями»!",
    ["没有小伙伴愿意和我玩……他们都说我很奇怪，但花花草草不一样，它们都是我的好朋友。"] = "Никто из ребят не хочет со мной играть... Все говорят, что я странный. Но цветы и травы другие, они мои лучшие друзья.",
    ["没有感觉吗？这可是天降甘霖！在烈日的树荫下，神灵的赐福……"] = "Разве вы этого не чувствуете? Это дождь с небес! Под сенью палящего солнца благословение Божие...",
    ["没有朱莉鼓励我，我连出门都很害怕。她对我很好，我不知道该怎么报答她……"] = "Без поддержки Джули мне было бы слишком страшно выходить из дома. Она очень добра ко мне, и я не знаю, чем ей отплатить...",
    ["没有鼻息，也没有脉搏，的确很符合死亡的标准。"] = "Нет дыхания, нет пульса; это определенно соответствует критериям смерти.",
    ["没有，你们不能被假象迷惑"] = "Нет, внешность не обманет",
    ["没有，你画得很好。"] = "Нет, ты очень хорошо это нарисовал.",
    ["没有，我从来不流鼻涕。"] = "Нет, у меня никогда не бывает насморка.",
    ["没有，我去看看"] = "Нет, я пойду посмотрю",
    ["没有，我对传统草药很感兴趣，能和我说说吗？"] = "Нет, меня очень интересует традиционная медицина с использованием трав. Можете ли вы рассказать мне об этом?",
    ["没有，我当时只是个旁观者"] = "Нет, я был просто свидетелем в тот момент",
    ["没错。只要循环还在继续，符号就会发出流光，而黛西小姐也不会真正死去。"] = "Это верно. Пока цикл продолжается, символ будет излучать струящийся свет, и мисс Дейзи не умрет по-настоящему.",
    ["没错！上面记载了罗塞尔大帝创造的神秘符文，里面藏着神秘的力量！"] = "Это верно! В нем записаны таинственные руны, созданные императором Розеллой, которые содержат в себе таинственную силу!",
    ["没错！价格实惠，数量有限，先到先得！"] = "Это верно! Доступные цены, количество ограничено, в порядке очереди!",
    ["没错，你的问题我已经听到了。湖畔封锁前我们都盯着，帽子帮的亨特和下街牵马的老马丁都去过。警察封锁湖畔后，就再没人了。"] = "Верно, я слышал твой вопрос. До того как берег озера оцепили, мы приглядывали за ним: туда наведывались Хантер из банды Шляпников и старый Мартин с Нижней улицы, что водит лошадей. А как полиция все перекрыла, там больше ни души.",
    ["没错，和这个一模一样。我看见它就有些眩晕……"] = "Верно, точь-в-точь такое же. Стоит мне взглянуть на него, как кружится голова...",
    ["没错，因蒂斯的最西边是迷雾海。"] = "Правильно, крайний запад Интиса — это Туманное море.",
    ["没错，我是一朵正在生长的小花。"] = "Верно, я растущий цветочек.",
    ["没错，这是廷根的老牌餐厅了，不少周围的邻居都常常过来。走这儿也挺方便的。"] = "Правильно, это давний ресторан в Тингене, сюда часто приходят многие соседи. Ходить таким образом довольно удобно.",
    ["没问题"] = "Без проблем",
    ["没问题。"] = "Без проблем.",
    ["没问题，交给我吧。"] = "Без проблем, доверься мне.",
    ["没问题，包在我身上。"] = "Никаких проблем, положитесь на меня.",
    ["没问题，喜欢您再来！"] = "Нет проблем, приходите еще, если хотите!",
    ["没问题，弗莱队长，我们现在就出发吧！"] = "Нет проблем, капитан Фрай, отправляемся прямо сейчас!",
    ["没问题，我找找。"] = "Нет проблем, дай мне посмотреть.",
    ["波特总是喜欢躲起来唱歌。"] = "Портеру всегда нравится прятаться и петь.",
    ["注意，它有点跛足，身上可能带着一股酒味。"] = "Обратите внимание: он немного хромает и может пахнуть алкоголем.",
    ["洛络塔？！"] = "Лолита?!",
    ["洛罗每次表演完都要吐到后半夜，边吐边说：“下次会吃下更多的。”"] = "Каждый раз, когда Лоро заканчивает представление, его рвет до середины ночи, и во время рвоты он говорит: «В следующий раз я съем больше».",
    ["洛耀他们又把斗邪恶的纸牌带出了娱乐室！"] = "Ло Яо и остальные снова вынесли карты борьбы со злом из комнаты отдыха!",
    ["活着就不错了！"] = "Просто быть живым достаточно хорошо!",
    ["活着的时候它们能够游经王都，一路进入苏尼亚海浅水区繁衍生存……当然，这些朋友现在肯定不会那么有活力了，哈哈。"] = "При жизни они могли проплывать через столицу и добираться до мелководья моря Соня, чтобы плодиться и жить... Конечно, сейчас эти ребята уже далеко не так резвы, ха-ха.",
    ["流浪王国？真是个好名字！我想以国王的名义，邀请你加入流浪王国。"] = "Странствующее королевство? Какое великолепное имя! Я хотел бы предложить вам присоединиться к Странствующему Королевству во имя Короля.",
    ["测试剧情表现用资产"] = "Ресурсы для тестирования производительности графика",
    ["济贫院可不是什么好地方。"] = "Ночлежка — не самое лучшее место.",
    ["济贫院可是有名额限制的，想来的话，先报名，你前边还有200多位。"] = "В богадельне есть квота. Если вы хотите прийти, сначала запишитесь. Перед вами более 200 человек.",
    ["济贫院的房子光鲜亮丽，却不能去救济更多需要帮助的人？"] = "Здание богадельни яркое и красивое, но оно не может помочь большему количеству нуждающихся людей?",
    ["浮动环绕选项测试"] = "Тест плавающего кругового опциона",
    ["海上有什么新消息？"] = "Есть какие-нибудь новости с моря?",
    ["海精灵？那是什么？哦……是那个小东西啊，我见过"] = "Морской эльф? Что это такое? Ох... это такая мелочь, я ее уже видел",
    ["海纳斯.凡森特。"] = "Ханас Винсент.",
    ["海默教授沉思着离开了\n他的身影虽然孤独，但依旧坚毅……"] = "Профессор Хеймер ушел в глубокой задумчивости \n Хотя его фигура была одинокой, он все еще был полон решимости...",
    ["海默教授跟着你一起去了学术诚信办公室，并对自己的所作所为供认不讳。\n学术诚信办公室的人无比震惊，声称他们会谨慎地考虑处理方式。"] = "Профессор Хеммер последовал за вами в Управление академической честности и признался в содеянном. \nЛюди из Управления академической честности были крайне шокированы и заявили, что тщательно обдумают, как с этим поступить.",
    ["消失了……"] = "Исчезнувший...",
    ["深眠花、夜香草，对失眠有奇效。金手柑加点薄荷，能让最辛苦的工人再坚持大半天！"] = "Цветы глубокого сна и ароматные ночные травы оказывают чудесное воздействие на бессонницу. Бергамот с небольшим количеством мяты поможет даже самым трудолюбивым работникам продержаться еще полдня!",
    ["温弗是谁？"] = "Кто такой Винфр?",
    ["温弗里德！那个拿了罗塞尔文学奖，养活了无数剧院的剧作家！"] = "Уинифред! Драматург, получивший литературную премию «Розель» и сохранивший работу бесчисленного количества театров!",
    ["温柔地安抚她"] = "Аккуратно успокойте ее",
    ["温蒂是个懂事的孩子，我失业后，她主动帮我妻子在家糊制火柴盒，再也没去周日学校了，但我知道那孩子很喜欢读书的……"] = "Венди разумный ребенок. После того, как я потерял работу, она взяла на себя инициативу помогать моей жене делать дома спичечные коробки и больше не ходила в воскресную школу, но я знаю, что ребенок любит читать...",
    ["漂亮的狸花猫，眼睛像晴朗的夜空一样纯粹。"] = "Красивая полосатая кошка с глазами чистыми, как ясное ночное небо.",
    ["漂亮的鸟儿们，会来给我唱好听的歌，把我叫醒……今天约好要介绍尤朵拉认识它们，但鸟儿们没有来。"] = "Красивые птички прилетят, чтобы спеть мне красивые песни и разбудить... Сегодня у меня была назначена встреча, чтобы познакомить их с Йодорой, но птицы не прилетели.",
    ["演出诚可贵，健康价更高，这笔钱你还是留着买食物吧。"] = "Результативность драгоценна, но здоровье дороже. Вам следует отложить эти деньги, чтобы купить еду.",
    ["火柴？您去旁边的杂货摊问问吧。"] = "Матчи? Сходите спросите в продуктовом ларьке по соседству.",
    ["火柴？没有。新鲜的牛肉，买两块吧？"] = "Спички? Нету. А вот свежая говядина — не желаете взять пару кусочков?",
    ["火蛇在焚烧炉之中狂舞，将不祥的舞鞋吞得一干二净，一缕黑烟从火炉中消散而出。"] = "Огненные змеи танцуют внутри мусоросжигателя, полностью поглощая зловещие танцующие туфли, а из печи вырывается клубок черного дыма.",
    ["灯光再次熄灭，演出停止。"] = "Свет вновь гаснет, представление прекращается.",
    ["灯光熄灭，演出再次停止，台下出现填词的句子。"] = "Свет гаснет, представление снова останавливается, и под сценой появляются слова песни.",
    ["灯光突然熄灭，其他演员们一动不动。"] = "Свет внезапно погас, а остальные актеры остались неподвижными.",
    ["灵性的直觉告诉我，她是被我吸引过来的。"] = "Моя духовная интуиция подсказывает мне, что я ее привлек.",
    ["灵界信使？小戴莉现在序列几？"] = "Посланник духовного мира? В какой последовательности сейчас маленький Дейли?",
    ["灵？"] = "Духи?",
    ["灾难？什么灾难？"] = "Катастрофа? Какая катастрофа?",
    ["炼金室"] = "Алхимическая комната",
    ["烈日？树荫？"] = "Палящее солнце? Оттенок?",
    ["烈朗齐能让我想起暴风肆虐的日子，但我现在已经是一个老家伙了。"] = "Лантис воскрешает в памяти бурные штормовые деньки, но теперь я уже старик.",
    ["烈朗齐能让我想起暴风肆虐的日子，可我现在已经是一个老家伙了。"] = "Леланж напоминает мне дни, когда бушевали бури, но теперь я старик.",
    ["烟草是男人桌面上的武器，听说贝克兰德雪茄馆的生意不错，要不我也开一家？"] = "Табак — это оружие мужчины на его столе. Я слышал, что у сигарного магазина Баклунда дела идут хорошо; может, мне тоже открыть?",
    ["烟草生意终究还是害人的，所以，您需要一位优秀体面的管家吗？"] = "Табачный бизнес все-таки вреден, так нужна ли вам хорошая и порядочная домработница?",
    ["烦透了！你看看，这卖的都是什么边角料？要香味没香味，要样子没样子……"] = "Мне это так надоело! Посмотрите, а что это за обрезки продаются? Ни запаха, ни внешнего вида...",
    ["然后他们就能说“嘿，这就是你妈妈二十年前最喜欢的味道！”“爸爸当年也是吃着小松饼长大的！”"] = "А потом они смогут сказать: «Эй, именно этот вкус твоя мама любила больше всего двадцать лет назад!» и «Папа в своё время тоже вырос на этих кексиках!»",
    ["然后是……"] = "А затем...",
    ["照片里的很多人已经牺牲了，这张照片也是我们偶然找到的，这已经足够幸运了。"] = "Многие из тех, кто на этой фотографии, уже погибли. Мы нашли её совершенно случайно, и это само по себе огромная удача.",
    ["照顾照顾小女孩的生意吧。"] = "Купите что-нибудь у маленькой девочки.",
    ["煮沸……加入纯牛奶150毫升……搅拌……"] = "Вскипятить... добавить 150мл цельного молока... перемешать...",
    ["爱德华·斯蒂夫是有很天赋的占卜家，擅长塔罗牌占卜，扑克占卜。每次收费3便士。"] = "Эдвард Стив — очень талантливый предсказатель, хорошо умеет гадать на картах Таро и в покере. За каждый раз взимайте 3 пенса.",
    ["爸爸——啊——"] = "Папа... ах-",
    ["爸爸……妈妈……救救我……我再也不任性了……"] = "Папа... мама... спаси меня... Я больше не буду своенравной...",
    ["爸爸妈妈都生病了，幸好我还能帮忙卖东西。"] = "Папа и мама заболели, к счастью, я могу помогать торговать.",
    ["爸爸被工厂辞退后，每天喝酒买醉，我不得不从教会的周日学校辍学，帮妈妈给人洗衣服，可妈妈现在也生病了，我不得不……"] = "После того как папу уволили с фабрики, он начал каждый день пропивать свое горе. Мне пришлось бросить церковную воскресную школу, чтобы помогать маме стирать одежду для других, но теперь мама тоже больна, и мне приходится...",
    ["爸爸，刚刚那是什么？那个恐怖的怪物……是我带来的吗？"] = "Папа, что это было только что? Это Ужасающее Монстр... я принес его сюда?",
    ["爸爸，别这么说！您不是常告诉我，迟到总比不到好吗？这可是您说的！"] = "Папа, не говори так! Разве ты не часто говорил мне, что лучше поздно, чем никогда? Ты сам это сказал!",
    ["爸爸？你、你回来了！仪式……生效了？"] = "Папа? Ты, ты вернулся! Ритуал... сработал?",
    ["爸！您怎么还在和弗雷尔叔叔较量谁蹲得更久！还看报纸，您看得进去吗！"] = "Папа! Почему ты до сих пор соревнуешься с дядей Фрейром, кто сможет приседать дольше! А читая газету, можете ли вы вообще сосредоточиться на ней!",
    ["爽快答应"] = "Охотно согласиться",
    ["片刻之后……"] = "Мгновение спустя...",
    ["片刻后……"] = "Мгновение спустя...",
    ["牌局很长，长得就像那个连输了十五把的男人流泻而出的悲伤。"] = "Карточная игра длинна, до тех пор, пока грусть изливается из того человека, который проиграл пятнадцать игр подряд.",
    ["牌面是……死神？"] = "Карта... Смерть?",
    ["牛肉，羊肉，新鲜的肉……"] = "Говядина, баранина, свежее мясо...",
    ["特邀嘉宾——{{PlayerName}}——请注意您的身份，您无权干预演出的正常进行。"] = "Специальный гость — {{PlayerName}} — пожалуйста, помните о своем статусе. Вы не имеете права вмешиваться в нормальный ход выступления.",
    ["犯人很狡猾，除了诡异的笛声外，没留下任何线索。"] = "Преступник очень хитрый. Кроме жуткого звука флейты, они не оставили никаких улик.",
    ["犯罪现场那堆杂物里伸出来的绝对是人手，它们还在动！"] = "Это определенно была человеческая рука, торчащая из кучи обломков на месте преступления, и она все еще двигалась!",
    ["状况怎样，还不是一样，普通人的世界外一切都是乱糟糟的。"] = "Какова ситуация? Это то же самое, что и всегда; все за пределами мира обычных людей — это бардак.",
    ["狂暴海航线的开启，对这片大陆的人到底意味着什么？对我到底意味着什么？"] = "Что на самом деле означает открытие Морского пути Берсерка для жителей этого континента? Что это значит для меня?",
    ["狗屎！什、什么因蒂斯女郎！"] = "Чушь собачья! Ч-что за леди Интис!",
    ["狗生来就是要叫的……你输了老兄，不要把照看婴儿的怒气撒在狗身上。"] = "Собаки рождены, чтобы лаять... Ты проиграл, приятель, не расстраивайся из-за того, что присматриваешь за собакой.",
    ["王国新闻？内务大臣今天生日，算吗？"] = "Новости Царства? У министра внутренних дел сегодня день рождения, это считается?",
    ["玛丽阿姨就住我们隔壁！我看着他们长大的，现在我已经是大孩子，可以照顾他们啦。"] = "Тетя Мэри живет рядом с нами! Я видел, как они росли, и теперь я большой ребенок, поэтому могу о них позаботиться.",
    ["玛莎，带着他的这份力量活下去，继续寻找你的家人，完成你们未竟的梦想。"] = "Марта, живи дальше, используя эту его силу, продолжай искать свою семью и осуществи свою неоконченную мечту.",
    ["玛蒂尔德在看一条价值我五年工资的项链，我根本不可能买下……"] = "Матильда смотрит на ожерелье, которое стоит пять лет моего жалованья; у меня нет возможности его купить...",
    ["玩家与恶灵战斗，击杀恶灵，任务成功。"] = "Игрок сражается со Злым Духом, убивает его, и квест завершается успешно.",
    ["现在……向我提问……"] = "Теперь... задайте мне вопрос...",
    ["现在就算没什么特别的事，我也喜欢过来坐一坐，点杯喝的，看会儿报纸。"] = "Даже если ничего особенного не происходит, я люблю прийти, посидеть немного, заказать выпивку и почитать газету.",
    ["现在市面上的花价跌得厉害，那些工厂女工都去买人造花了，谁还愿意花大价钱买真花？"] = "Цены на цветы на рынке сейчас сильно упали: фабричные работницы покупают искусственные цветы, кто теперь станет отдавать бешеные деньги за живые?",
    ["现在年轻人，都不爱结婚了，我觉得这是一个很严重的问题！"] = "Молодые люди в наши дни не любят жениться; Я считаю, что это очень серьезная проблема!",
    ["现在总算没人再让我来等一等了，可好像很多东西……我都已经错过了。"] = "Теперь меня наконец никто больше не заставляет ждать, но кажется, что многое... я уже пропустил.",
    ["现在我弄明白了，你就得把那些手脚发软，脸色发白的东西放在上面晾一会儿，别老让他们妨碍公共建设事业。"] = "Теперь я это понял; вам просто нужно оставить этих слабых, бледнолицых тварей там на некоторое время, чтобы они проветрились, и не позволять им продолжать мешать общественным строительным проектам.",
    ["现在是什么时候，看来我又喝多了，昨天我看到老特勒了，那该死的混蛋居然想要抢我的酒。"] = "Сколько сейчас времени? Кажется, я снова слишком много выпил. Вчера я видел Старого Трелля. Этот чертов ублюдок действительно хотел украсть мое вино.",
    ["现在最重要的，是唤醒黛西小姐，避免类似的事情再次发生。"] = "Самое главное сейчас — разбудить мисс Дейзи и не допустить повторения подобного.",
    ["现在每次来学派，我都会找一个人磨练棋艺。以后若是还能和我父亲对局，一定——按你们的说法——杀得他片甲不留。"] = "Теперь каждый раз, приходя в школу, я нахожу кого-то, кто оттачивает мои шахматные навыки. Если мне удастся в будущем еще раз сыграть против отца, то я обязательно, как вы говорите, оставлю его без единой фигуры.",
    ["现在的人为了利益，指不定要干出什么违背良心的事。愿大地母神庇佑你健康，{{先生|女士}}。"] = "Люди в наши дни ради прибыли кто знает, какие вещи они сделают против своей совести. Да благословит вас Мать-Земля здоровьем, господин/госпожа. {{|}}.",
    ["现在的廷根，怪事越来越多了。真不知道，我们这些小市民要如何生存。"] = "В Тингене в наши дни происходит все больше и больше странных вещей. Я действительно не знаю, как мы, простые граждане, выживем.",
    ["现在的非凡者也更容易晋升，失控，风险和机遇并存。"] = "Потусторонние теперь также легче продвигаться, но есть риск потерять контроль. Риски и возможности сосуществуют.",
    ["现在看来，这个决定是正确的。"] = "Сейчас кажется, что это решение было правильным.",
    ["现在能在廷根码头搬运货物，对我来说已经很不错了。"] = "Возможность теперь перемещать грузы в доках Тингена уже очень хороша для меня.",
    ["现在还没法确定其中的含义……需要了解更多情况。"] = "Значение пока определить невозможно... Мне нужно узнать больше о ситуации.",
    ["现在，光就在我面前，可能熄灭，也可能燃烧——这取决于我们所有人的选择。"] = "Теперь свет прямо передо мной; он может погаснуть или сгореть — это зависит от выбора каждого из нас.",
    ["现实里有诡异的能量溢出，你的能力也一起爆发。我担心梦境里出了什么事，就进来看看。"] = "В реальности переполняется странная энергия, и вместе с ней прорываются ваши способности. Я волновалась, что что-то произошло во сне, поэтому зашла проверить.",
    ["珂赛特！别看了，你妈妈要着急了！"] = "Козетта! Хватит читать, твоя мама будет волноваться!",
    ["珍妮不渴也不饿，珍妮只是想要一根火柴。"] = "Дженни не голодна и не хочет пить... Дженни просто хочет спичку.",
    ["珍妮消失了……"] = "Дженни исчезла...",
    ["珍妮，你在这里等等，我会帮你找到火柴的。"] = "Дженни, подожди здесь, я обязательно найду для тебя спички.",
    ["琳达，加油！"] = "Линда, действуй!",
    ["瑞安娜女士是我们这的常驻占卜大师，擅长塔罗占卜，梦境占卜，星盘占卜。每次1苏勒。"] = "Г-жа Рианна — наш постоянный мастер гадания, специализирующийся на гадании Таро, гадании во сне и гадании по астролябии. 1 подошва каждый раз.",
    ["甜冰茶、烤薄饼、土豆面包……咦，这似乎是南方的食物风格？让人想起炸蔬菜和烤肉，或者猪肉香肠……"] = "Сладкий чай со льдом, блинчики, картофельный хлеб... Хм, похоже на южную кухню? Сразу вспоминаются жареные овощи, жареное мясо или свиные колбаски...",
    ["甜柠檬鸡尾酒好了。风暴在上，这让我想起那些在奥拉维岛的日子。"] = "Сладкий лимонный коктейль готов. Буря наверху, это напоминает мне те дни на острове Орави.",
    ["甜苹果汁，很好的选择。让我们继续往里面加点什么。"] = "Сладкий яблочный сок, отличный выбор. Давайте продолжим что-нибудь добавлять к этому.",
    ["生日快乐！"] = "С днем ​​рождения!",
    ["生日礼物的话……"] = "Что касается подарка на день рождения...",
    ["生日聚会……偶尔放松一下也不错。"] = "День рождения... приятно иногда расслабиться.",
    ["生日除了蛋糕……还需要邀请臣民和准备惊喜礼物。"] = "Помимо торта... нам еще нужно пригласить испытуемых и подготовить подарки-сюрпризы ко дню рождения.",
    ["生日？"] = "День рождения?",
    ["生死边缘？你连阳台都没出过！赶紧回来，不然我过去把你推下去！"] = "Грань жизни и смерти? Ты даже с балкона не сошел! Возвращайся сейчас же, или я приду и столкну тебя!",
    ["生活总是充满了各种不幸，希望他能够再次站起来不要被苦难所打到。"] = "Жизнь полна всяческих невзгод. Надеюсь, он сумеет вновь подняться на ноги и невзгоды не сломят его.",
    ["生病了吗？我来给你开上一副传统草药。"] = "Заболели? Я выпишу вам традиционные травы.",
    ["用不着。"] = "Незачем.",
    ["用什么钓鱼？我好像没有看到钓竿。"] = "Что вы используете для ловли рыбы? Кажется, я не вижу удочки.",
    ["用来自南大陆的果实压榨萃取，然后加入糖与奶，形成特殊的固体……"] = "Извлекается из фруктов с Южного континента, затем смешивается с сахаром и молоком, образуя особое твердое вещество...",
    ["用爱！"] = "С любовью!",
    ["用罗塞尔大帝的话说，他有小偷的心，没有小偷的胆量。"] = "По словам императора Розеллы, у него воровское сердце, но нет воровской храбрости.",
    ["由于你没有签署保密协议，我没法对你说太多。"] = "Поскольку вы не подписали соглашение о конфиденциальности, я не могу вам сказать слишком много.",
    ["画画。"] = "Рисовать.",
    ["疯女工听见了年轻女工的声音，面露惊恐，转身向雾中逃去。"] = "Сумасшедшая работница слышит голос молодой работницы, ее лицо наполнено ужасом, и она поворачивается, чтобы бежать в туман.",
    ["疯子真是越来越多了！"] = "Сумасшедших действительно становится все больше и больше!",
    ["疯狂冒险家格尔曼·斯帕罗！他就是以五海为猎场的赏金猎人、海盗将军与王的终结者！纵横海洋的噩梦与美梦！"] = "Безумный искатель приключений Герман Воробей! Он охотник за головами, пиратский адмирал и король терминаторов, который использует Пять морей в качестве своих охотничьих угодий! Кошмар и сладкий сон, пересекающий океан!",
    ["疯癫的？"] = "Сумасшедшие?",
    ["白银城的居民曾在神弃之地的永夜中坚守千年，我们以信念驱散阴翳，依靠着彼此度过长夜漫漫。"] = "Жители Серебряного Города когда-то тысячу лет удерживали свои позиции в вечной ночи Заброшенной Земли Богов. Мы развеиваем мрак своей верой и полагаемся друг на друга, чтобы пережить долгую ночь.",
    ["的确常有女仆把女主人的项链拿出来卖，可没几个人敢收啊。"] = "Правда, служанки часто уносят на продажу ожерелья своей хозяйки, но не многие осмеливаются их принять.",
    ["的确，暂时还没有明显恢复的迹象。"] = "Действительно, на данный момент явных признаков выздоровления нет.",
    ["皮埃尔，我有空还会回来看你的。等我们的女帽店开门，你来给莉亚拿一顶帽子！"] = "Пьер, я вернусь к тебе, когда у меня будет время. Когда откроется наш магазин шляп, ты обязательно придешь и выберешь шляпку для Лии!",
    ["皮特"] = "Пит",
    ["皮特的身体逐渐消散，原地只留下一株鸢尾花……"] = "Тело Пита постепенно рассеялось, оставив на месте лишь цветок ириса...",
    ["皮特逐渐彻底异化，变成一个树人怪物。"] = "Пит постепенно полностью отошел от него, превратившись в монстра-деревочеловека.",
    ["盒饭出现什么问题了？"] = "Что не так с упакованным ланчем?",
    ["目前已知线索比较少，需要前往报案地点进行调查。"] = "На данный момент известных улик немного, и нам нужно отправиться в указанное место и провести расследование.",
    ["目前已经进行过三轮选择，每次提问后答案都会出现在截然不同的地方，这似乎不是随机的……"] = "На данный момент сделано три раунда выбора, и ответы появляются в совершенно разных местах после каждого вопроса. Это не кажется случайным...",
    ["目前最紧要的，就是为我们今晚找个落脚处。外交大臣，你熟悉廷根市场这片区域，你有什么好点子吗？"] = "Сейчас важнее всего найти ночлег на сегодняшнюю ночь. Министр иностранных дел, вы хорошо знаете район Тингенского рынка — есть какие-нибудь мысли?",
    ["目前还不知道，所以需要你出面侦查。"] = "Я пока не знаю, поэтому мне нужно, чтобы вы пошли и расследовали.",
    ["直到尖叫渐息，她在一片寂静中狼狈爬起。"] = "Пока крик не утих, она в беспорядке ползает в тишине.",
    ["直到现在，邓恩他一直对您非常地感激与……愧疚。"] = "Даже сейчас Данн всегда был очень благодарен и... виноват перед тобой.",
    ["直接拧他的鼻子，就没有左右的问题了！"] = "Просто крутите ему нос прямо, и тогда не будет проблем с левым или правым!",
    ["直觉告诉我，他的遗骨能唤起我过去的记忆。"] = "Моя интуиция подсказывает мне, что его останки могут пробудить мои воспоминания о прошлом.",
    ["相信我，之后我会跟你解释。"] = "Поверь мне, позже я все объясню.",
    ["相信我，只需要一口，就能胜过千万口。买一份浓缩咸鱼汤，带回去能让一家人喝上一周。"] = "Поверьте, один укус стоит тысячи. Купите порцию концентрированной соленой ухи, и ее хватит семье на целую неделю, если взять ее домой.",
    ["相信我，如果结果你不喜欢，就再抛几次，至少会让你心情好起来！"] = "Поверьте, если вам не понравится результат, просто переверните его еще несколько раз; по крайней мере, это заставит вас чувствовать себя лучше!",
    ["相信我，文献室太可口了，如果不尽快将那些逃窜的小家伙们捉出来，这知识的宝库很快就会变成密密麻麻的虫巢！"] = "Поверьте, архивы — это слишком вкусно. Если мы в ближайшее время не поймаем этих убегающих малышей, эта сокровищница знаний вскоре превратится в густое гнездо жуков!",
    ["相信我，这杯酒会让你在特里尔被所有酒吧轰出去的。"] = "Поверьте, за этот напиток вас выгонят из каждого бара Трира.",
    ["相信本书作者与文献室管理员希罗多德先生都会感谢你。"] = "Я думаю, что автор этой книги и администратор комнаты документов г-н Геродот будут вам благодарны.",
    ["相信经过了这场拳赛，会有更多的人因为琳达光顾恶龙酒吧，真是幸福的烦恼。"] = "Я верю, что после этого боксерского поединка больше людей будут посещать бар ««Злой Дракон»» из-за Линды. Это действительно радостная проблема.",
    ["相当划算的价格，煮汤应该不错。"] = "Очень разумная цена, должно быть хорошо для приготовления супа.",
    ["相比起贝克兰德，作为“大学之城”的廷根在服饰的流行风向上，似乎有一些微妙的差异。"] = "По сравнению с Баклундом, Тинген, как «город университетов», похоже, имеет некоторые тонкие различия в модных тенденциях.",
    ["相较于柔顺光亮的缎面材质，我觉得硬挺的刺绣和蕾丝的运用在这里更加常见。"] = "По сравнению с мягким сияющим атласом, жесткая вышивка и кружева встречаются здесь куда чаще.",
    ["看上去好香！回见！"] = "Как аппетитно пахнет! Еще увидимся!",
    ["看你徘徊许久了，需要一瓶“安曼达”纯露吗？"] = "Я вижу, ты долго бродил. Вам нужна бутылка цветочной воды «Аманда»?",
    ["看到了"] = "Видел это",
    ["看到了。"] = "Я вижу его.",
    ["看到琳达获得冠军，我实在太兴奋了，今晚可能都睡不着了，不如留下来再找找乐子。"] = "Видя, как Линда выиграла чемпионат, я слишком взволнован. Возможно, сегодня я не смогу заснуть. Почему бы не остаться и не найти себе еще развлечений?",
    ["看在你帮我排除一个错误答案的份上，这次不追究你的鲁莽。"] = "Учитывая, что вы помогли мне исключить неправильный ответ, на этот раз я не буду обвинять вас в вашем безрассудстве.",
    ["看来你喜欢将命运掌握在自己手中，虽然缺乏一些刺激，但是个稳妥的选择。"] = "Похоже, вам нравится держать судьбу в собственных руках. Пусть в этом и мало азарта, зато выбор надёжный.",
    ["看来你来的正是时候。"] = "Кажется, вы пришли в нужное время.",
    ["看来你的品味也不过如此。"] = "Похоже, твой вкус оставляет желать лучшего.",
    ["看来你知道的不少！"] = "Кажется, ты знаешь довольно много!",
    ["看来你讨厌他"] = "Похоже, ты его терпеть не можешь",
    ["看来你误会了什么，他只是走了，离开廷根而已。该死的，我每个月还要上交大半收入给他。"] = "Кажется, вы что-то неправильно поняли. Он просто ушел, ушел из Тингена, вот и все. Черт побери, мне все еще приходится каждый месяц отдавать ему большую часть своего дохода.",
    ["看来您已经从事这个行业很久了。"] = "Кажется, вы уже давно в этой отрасли.",
    ["看来您是一位和合格的女仆，相信很快就会有雇主来找您的。"] = "Кажется, вы квалифицированная горничная. Я верю, что работодатель скоро придет искать тебя.",
    ["看来您是个明白人。"] = "Похоже, вы разумный человек.",
    ["看来您误会了，这是尼尔先生的花园，他已经去世了。"] = "Кажется, вы неправильно поняли, это сад мистера Нила, он уже умер.",
    ["看来您运气不错，老特勒已经死了，晚上的时候最好还是找个安全的地方，为了您的安全。"] = "Кажется, вам повезло. Старый Трелль уже мертв. Лучше всего найти безопасное место ночью для вашей собственной безопасности.",
    ["看来是躲到了书中……或许那是她认为最安全的地方。"] = "Кажется, она спряталась в книге... возможно, это место она считает самым безопасным.",
    ["看来还不错，我再想想！"] = "Вроде неплохо, подумаю!",
    ["看来这不是一个轻松的任务。"] = "Кажется, это не простой квест.",
    ["看来魔法师也比不上邓肯。"] = "Кажется, даже волшебник не сможет сравниться с Дунканом.",
    ["看来，和你有关？"] = "Кажется, это имеет к вам какое-то отношение?",
    ["看看猪肉——卷耳短毛猪，还是那个什么短耳卷毛猪，新品种！都来看看！"] = "Взгляните на свинину! Короткошёрстная вислоухая или как её там, кудрявая короткоухая — новая порода! Подходите, посмотрите!",
    ["看看罗塞尔的子嗣情况"] = "Посмотрите на ситуацию с потомством Розеллы.",
    ["看看罗塞尔的辉煌事迹"] = "Посмотрите на славные дела Розеллы",
    ["看看菜单"] = "Посмотрите меню",
    ["看起来詹姆斯不是安东尼的对手。"] = "Похоже, Джеймс не ровня Энтони.",
    ["看起来这里都是些普通的生活用品，还算整齐干净，主人应该刚离开不久。"] = "Похоже, это обычные предметы первой необходимости, и все довольно аккуратно и чисто. Хозяин, должно быть, не так давно уехал.",
    ["看起来，你已经做好充分准备了！"] = "Похоже, ты отлично подготовился!",
    ["看，那两个小朋友很可爱吧。那是玛丽阿姨的小孩哦。"] = "Смотри, эти двое малышей милые, не так ли? Это дети тети Мэри.",
    ["真厉害。"] = "Это впечатляет.",
    ["真可惜呀，那我就只能将就用你填填肚子了！"] = "Как жаль, тогда мне придется довольствоваться тобою желудок!",
    ["真复杂"] = "Так сложно",
    ["真好心啊……"] = "Такой добрый...",
    ["真好，我也想认识认识这些朋友！"] = "Это здорово, я тоже хочу познакомиться с этими друзьями!",
    ["真实造物主……"] = "Истинный Творец...",
    ["真实造物主的追随者？那群疯子什么都干的出来。哼，真应该把他们丢进墓穴里，用腐肉塞满他们的每一个孔隙。"] = "Последователи Истинного Создателя? Эти безумцы способны на все. Хм, их действительно следует бросить в могилу и набить каждую пору гниющей плотью.",
    ["真希望我们带了自己的咖啡桌。"] = "Мне бы очень хотелось, чтобы мы взяли с собой собственный журнальный столик.",
    ["真怀念在巴伐特银行做见习生的日子。"] = "Я очень скучаю по тем временам, когда я был стажером в банке «Баварт».",
    ["真想念贝克兰德的克拉格俱乐部，布置的都是些有品位的花。"] = "Я очень скучаю по клубу Cragg Club в Баклунде, он украшен изысканными цветами.",
    ["真是一位好人，愿女神庇佑她。"] = "Какой добрый человек, пусть Богиня защитит ее.",
    ["真是一场精彩的比赛……"] = "Какой чудесный матч...",
    ["真是可怕的尝试，看起来像苹果潘趣酒变质了。"] = "Какая ужасная попытка, похоже, Apple Punch испортился.",
    ["真是可笑，这些蠢货还在发印着肖像画的通缉令。"] = "Это смешно, эти идиоты до сих пор раздают плакаты о розыске с портретами.",
    ["真是太感谢了，请稍等，果子汤煮好后分给你。"] = "Большое спасибо. Пожалуйста, подождите немного; Я поделюсь с тобой фруктовым супом, как только он будет готов.",
    ["真是奇怪，目前毫无线索，只遇上了几个互称大臣的小孩。"] = "Как странно, никаких зацепок вообще нет, просто встретились несколько ребят, называющих друг друга министрами.",
    ["真是小甜心。"] = "Какая лапочка.",
    ["真是没素质！好端端的花圃都被污染了！"] = "Как нецивилизованно! Испорчена идеальная клумба!",
    ["真是麻烦，现在来这的病人越来越多了！"] = "Это такая нервотрепка, сюда сейчас приезжает все больше и больше пациентов!",
    ["真正的店主？"] = "Настоящий лавочник?",
    ["真的吗，{{大哥哥|大姐姐}}，我在这儿好久了，你是第一个愿意这么说我的人。"] = "Правда, {{братишка|сестричка}}? Я здесь уже очень давно, и ты первый, кто сказал мне такое.",
    ["真的吗？"] = "Правда?",
    ["真的吗？对，我好像有点印象……他是说了那家餐厅的名字吗？他应该说了……！"] = "Действительно? Да, кажется, у меня смутная память... Он сказал название того ресторана? Должно быть, он это сказал...!",
    ["真的很抱歉。"] = "Мне действительно очень жаль.",
    ["真的要放在这里吗？会不会有点奇怪？"] = "Нам действительно нужно разместить это здесь? Не будет ли это немного странно?",
    ["真的？"] = "Действительно?",
    ["真的？无论如何，先谢谢你。"] = "Действительно? В любом случае, прежде всего спасибо.",
    ["真相总会浮出水面，恐惧会蒙蔽我们的双眼，库尔斯先生。"] = "Истина всегда всплывет на поверхность; страх ослепит наши глаза, г-н Курс.",
    ["真相比性命重要？"] = "Правда важнее жизни?",
    ["真羡慕你有这种手艺，从技术学院出来直接就能就业。"] = "Я действительно завидую вам за такое ремесло; устроиться на работу можно сразу после окончания технического колледжа.",
    ["真贴心！"] = "Такой вдумчивый!",
    ["真高兴看到一位对咸鱼充满兴趣的人！"] = "Так приятно видеть человека, интересующегося соленой рыбой!",
    ["真高兴看到像您这样优秀的年轻人，铁十字街可能稍微乱了点儿……但总是生机勃勃的，不是吗？"] = "Очень приятно видеть такого замечательного молодого человека, как ты. Улица Айрон-Кросс, возможно, немного хаотична... но она всегда полна жизненной энергии, не так ли?",
    ["眼前一大片雏菊花田，黛西在里面蹦蹦跳跳，十分快乐。\n小黛西微笑着看了一眼这边，就继续跑到几个地方去摘雏菊花。"] = "Перед глазами простирается бескрайнее поле маргариток, по которому весело резвится Дейзи.\nМалышка Дейзи с улыбкой бросает взгляд в вашу сторону и снова убегает собирать маргаритки.",
    ["睡前喝咖啡是年轻人的特权——给，你的迪西咖啡，早点睡，亲爱的。"] = "Пить кофе перед сном — привилегия для молодых людей — вот, твой кофе «Дези», спи пораньше, дорогая.",
    ["瞧瞧我这花，今早刚浇了从南大陆商人那里买的花肥，开得比教堂的彩窗还鲜艳！"] = "Посмотрите на мои цветы, я только сегодня утром полила их удобрением, купленным у торговца с Южного континента, они цветут ярче церковных витражей!",
    ["瞬间，二人瘫倒在地上。"] = "В то же мгновение они оба без сил рухнули на землю.",
    ["知识光芒落到贝尔纳黛手中，她静静地看着那知识光芒，直到它暗淡，消散……良久，她垂下了眼睛。"] = "Свет знаний попадает в руки Бернадетты. Она спокойно наблюдает за светом знаний, пока он не тускнеет и не рассеивается... Она надолго опускает глаза.",
    ["知识给予了你回应，你想要知道什么？"] = "Знание дало тебе ответ. Что ты хочешь узнать?",
    ["知识逐人的冷却时间降低三秒，是否确认选择这项能力？选择后其他2个会消失"] = "Время восстановления «Охотника за знаниями» сокращается на три секунды. Вы уверены, что выбрали эту способность? Остальные 2 исчезнут после выбора",
    ["知识逐人给额外1次长枪，是否确认选择这项能力？选择后其他2个会消失"] = "«Знание преследует человека» дает 1 дополнительное копье. Подтвердить выбор этой способности? После выбора остальные 2 исчезнут.",
    ["知道吗，我长大后会嫁给这条街跳舞最好的男孩！"] = "Знаешь, когда я вырасту, я выйду замуж за мальчика, который лучше всех танцует на этой улице!",
    ["知道的越多，越危险。"] = "Чем больше знаешь, тем опаснее.",
    ["知道，这个符号是<P_Yellow>封印物3-888</>留下的印记。"] = "Знаю: этот символ — знак, оставленный <P_Yellow>Запечатанным Артефактом 3-888</>.",
    ["短期工也行！零工也行！求求您……我没脸回家了。"] = "Краткосрочная работа - это хорошо! Случайные подработки тоже хороши! Пожалуйста... Мне некуда идти домой.",
    ["码头又送来一批货，我今天得干到什么时候才能下班？"] = "Очередная партия прибыла в док. Как долго мне сегодня придется работать, прежде чем я смогу уйти с работы?",
    ["研究？"] = "Исследовать?",
    ["砰！"] = "Хлопнуть!",
    ["破碎的梦境，有被污染的气息……"] = "Фрагментированные мечты, с запахом Искажения...",
    ["硬币占卜！你也想试试吗？我可以把这枚铜便士借你用一下！"] = "Гадание на монетах! Хотите тоже попробовать? Я могу одолжить тебе эту медную копейку!",
    ["确实。"] = "Действительно.",
    ["确实如此，只有最顶尖的那部分人决定历史的走向，他们又是为了各自的目的，普通人只是被迫随波逐流罢了。"] = "Действительно. Только люди высшего звена решают направление истории, и делают они это в своих собственных целях; обычные люди просто вынуждены плыть по течению.",
    ["确实很适合，特别是一个人的时候。"] = "Это действительно очень удобно, особенно когда ты один.",
    ["确实！"] = "Действительно!",
    ["确实，我们的营生有些小众，但我们都是体面人。"] = "Да, наше ремесло довольно специфично, но мы все приличные люди.",
    ["礼貌询问"] = "Вежливый запрос",
    ["祂……那个“隐匿贤者”，在我头痛的时候，说……因蒂斯的最西边是迷雾海。"] = "Он... тот \"Скрытый мудрец\", когда у меня заболела голова, сказал... Дальний запад Интиса - это Туманное Море.",
    ["祂是统治天空的王者，主宰大海的皇帝，伟大的风暴之神！"] = "Он Король, правящий небом, Император, властвующий над морем, великий Бог Штормов!",
    ["祂的灌输结束了，我们离开这里。"] = "Его идеологическая обработка закончилась, давайте покинем это место.",
    ["祝你今天的前途也无比灿烂！就当是一个陌生人的小小祝愿。"] = "Желаю вам блестящего будущего уже сегодня! Просто маленькое пожелание от незнакомца.",
    ["祝你好运"] = "Удачи",
    ["祝你成功！"] = "Желаю вам успехов!",
    ["祝你的战斗一切顺利。"] = "Желаю, чтобы ваша битва прошла гладко.",
    ["祝您好运，警官。"] = "Удачи, офицер.",
    ["祝您度过一个美妙的夜晚。"] = "Желаю вам чудесного вечера.",
    ["祝您生活愉快"] = "Приятной жизни",
    ["祝贺您太太！但要我说，您看下这条五磅重的塔索克鱼，可是难得一见的稀罕东西，往常在港口就被餐厅抢购一空了。"] = "Поздравляю, мэм! Но на твоем месте я бы взглянул на эту пятифунтовую рыбу-Кусок. Это редкая находка; обычно его раскупают в ресторанах в гавани.",
    ["神明？是邪神吧！"] = "Божество? Скорее уж злой бог!",
    ["神秘的符号"] = "Таинственные символы",
    ["福利"] = "Бонусы",
    ["离奇的案子？"] = "Странные случаи?",
    ["离开"] = "Оставлять",
    ["离开这个空间会留下一些副作用……希望命运庇佑你，让你有机会做我的观众。"] = "Выход из этого пространства будет иметь некоторые побочные эффекты... Надеюсь, судьба защитит тебя и даст тебе шанс стать моим зрителем.",
    ["离我远点，别想从我这套话！"] = "Держитесь от меня подальше, не пытайтесь вытянуть из меня информацию!",
    ["私生子又如何？"] = "А что, если ты внебрачный ребенок?",
    ["私生子？"] = "Незаконнорожденный ребенок?",
    ["科恩黎，麻烦回公司通知大家这起非凡事件。"] = "Кенли, будь добр, вернись в компанию и предупреди всех об этом потустороннем происшествии.",
    ["科林导师似乎是所有导师中最特殊的一位。"] = "Инструктор Колин кажется самым особенным среди всех инструкторов.",
    ["科里就很擅长找东西，可以是一些日常物品，也能是各种动物，比如帮人找猫，找狗。"] = "Кори очень хорошо умеет находить вещи, будь то предметы повседневного обихода или различных животных, например, помогает людям находить кошек или собак.",
    ["租客，当然就是普通的廷根人了，不算富裕的铁十字街居民。"] = "Арендаторы, конечно же, обычные тингены, а не богатые жители Айрон-Кросс-стрит.",
    ["称赞名气"] = "Похвалить известность",
    ["称赞年轻"] = "Комплимент молодости",
    ["称赞珠宝店"] = "Сделайте комплимент ювелирному магазину",
    ["移动有走路和跑步两种方式，而且可以自由选择路径。"] = "Движение имеет два режима: ходьба и бег, причем вы можете свободно выбирать путь.",
    ["稍等一下。"] = "Подождите минутку.",
    ["稍等片刻，美味正在制作。"] = "Подождите, вкусная еда готовится.",
    ["稍等，我先把这里修好……"] = "Подождите, позвольте мне сначала это исправить...",
    ["穴位？什么是穴位？风暴在上，难道我的后背有很多洞吗？"] = "Акупунктурные точки? Что такое акупунктурные точки? Буря наверху, у меня в спине много дыр?",
    ["究竟是怎么回事"] = "Что именно происходит",
    ["空镜头"] = "Пустой выстрел",
    ["突然有种被工作掏空灵魂的感觉……"] = "Внезапно я чувствую, что моя душа опустошена работой...",
    ["站在命运的风口上，没人知道自己做的选择是否正确。"] = "Стоя на распутье судьбы, никто не знает, правильный ли сделанный выбор.",
    ["站起"] = "Вставать",
    ["竟然敢骗我！不，竟然，敢欺骗命运！"] = "Как ты смеешь лгать мне! Нет, как ты смеешь, смеешь обманывать судьбу!",
    ["端着这杯酒，过去请她喝一杯，我保证你所有的担忧都会一扫而空！"] = "Возьми этот бокал, подойди и угости её выпивкой — гарантирую, от всех твоих тревог не останется и следа!",
    ["笑话？不够虔诚的人才是那个笑话！"] = "Шутка? Те, кто недостаточно благочестивы, — это шутка!",
    ["笔记"] = "Примечание",
    ["笛子？什么笛子，我从没见过尤朵拉吹笛子。"] = "Флейта? Какая флейта? Я никогда не видел, чтобы Йодора играл на флейте.",
    ["第二声枪响消散于半空，\n带来一场永远的别离。"] = "Второй выстрел рассеялся в воздухе, положив начало вечному прощанию.",
    ["第二天……"] = "На следующий день...",
    ["第二天一早，女仆卡拉发现小姐高烧退了，却怎么都喊不醒。我们猜想大概是退烧后的嗜睡，所以打算先观察一下。"] = "На следующее утро горничная Кара обнаружила, что лихорадка девушки спала, но разбудить ее не удалось. Мы предположили, что это, вероятно, была сонливость после того, как лихорадка спадала, поэтому мы планировали сначала понаблюдать некоторое время.",
    ["第二天晚上……"] = "На следующий вечер...",
    ["第二次？"] = "Второй раз?",
    ["等一下，{{PlayerName}}！"] = "Постой, {{PlayerName}}!",
    ["等你到我这个年纪的时候，就会发现身体康健，没有心事，坐在长椅上看一份报纸，是多么舒服的事情。"] = "Когда ты достигнешь моего возраста, ты поймешь, как приятно быть здоровым, не беспокоиться и сидеть на лавочке с газетой.",
    ["等待，等待下一位小姐的回眸。"] = "Ждать, ждать, пока следующая дама оглянется.",
    ["等我成为了像大名鼎鼎的佛尔思·沃尔一样的小说家，这个班就给你上。"] = "Как только я стану таким же известным писателем, как Форс Уолл, я позволю тебе пойти на этот курс.",
    ["等我站上舞台那天，会邀请你来观演的，一定要来哦！"] = "В тот день, когда я выйду на сцену, я приглашу вас посмотреть спектакль, вы должны прийти!",
    ["等着瞧！不让我种菜，我偏要种！"] = "Просто подожди! Если мне не дадут выращивать овощи, я все равно их буду выращивать!",
    ["等等……新面孔？"] = "Подожди... новое лицо?",
    ["等等！"] = "Ждать!",
    ["等等，你为什么不跟我一起去？"] = "Подожди, почему ты не идешь со мной?",
    ["等等，你们仔细看看。"] = "Подождите, посмотрите внимательно все.",
    ["等等，你放了什么？"] = "Подожди, а что ты вставил?",
    ["等等，女士，你手里的针为什么这么长？"] = "Подождите, мадам, почему иглы в вашей руке такие длинные?",
    ["等等，灵感提醒我，这里有危险……很古怪。"] = "Подождите, мое вдохновение предупреждает меня, что здесь есть опасность... это очень странно.",
    ["答对了！以后你有什么想知道的，可以来我这问问。"] = "Верно! Если захочешь узнать что-нибудь в будущем, приходи ко мне с расспросами.",
    ["答对了，{{小伙子|小姑娘}}。我年轻的时候住在南方，这些对我来说是家乡的食物。"] = "В самую точку, {{парень|девушка}}. В молодости я жил на юге, так что для меня это родные блюда.",
    ["答错了！那么是任务，还是惩罚？"] = "Неправильный ответ! Так это задание или наказание?",
    ["策划说都在做了，再催把肝吐你脸上。"] = "Геймдизайнеры говорят, что уже делают. Если будете торопить — выплюнут свою печень вам в лицо.",
    ["简单的指引"] = "Простое руководство",
    ["简直哪里都比廷根好！那毕竟是鲁恩的首都，繁华富饶的希望之地啊！您说，我怎么才能留住我的小甜心？"] = "Это просто лучше Тингена во всех отношениях! В конце концов, это столица Лоена, процветающей и богатой страны надежды! Скажи мне, как мне сохранить свою маленькую возлюбленную?",
    ["简直？"] = "Просто?",
    ["算了！等我说服她陪我办戏剧俱乐部，你可以来进修一下！"] = "Забудь это! Когда я уговорю ее пойти со мной руководить драматическим кружком, ты сможешь прийти и пройти курсы повышения квалификации!",
    ["算了，先买票吧，至于活着，我再想想办法。"] = "Забудь об этом, я сначала куплю билет. Что касается того, чтобы остаться в живых, я подумаю о другом способе.",
    ["算了，待会还是问问贝茜吧……"] = "Забудь об этом, я спрошу у Бесси позже...",
    ["算了，我还是去排队吧。"] = "Забудь об этом, я пойду в очередь.",
    ["算是吧，一个杂草坛子，被我仔细锄了一遍，种了一圈水灵灵的卷心菜。"] = "Вы могли бы так сказать. Это был участок сорняков, который я тщательно прополал и засадил кругом пышной капусты.",
    ["算是吧，他帮过了，或许吧……"] = "Наверное, да, он мне помог, возможно...",
    ["算是有一点烦恼吧。"] = "Полагаю, у меня небольшие проблемы.",
    ["管他的，快跑！"] = "К чёрту, беги!",
    ["管家会告诉你一切的。我还有些问题，不得不向你询问。"] = "Дворецкий вам все расскажет. У меня есть несколько вопросов, которые я должен вам задать.",
    ["精神问题的根源是什么，抛开遗传、压力和性格，最主要的还是来自邪恶的污染。"] = "Какова основная причина психических проблем? Помимо генетики, стресса и личности, основным источником является порча зла.",
    ["糟糕！小阿诺德呢？他刚才还跟我在一起！"] = "О, нет! А как насчет маленького Арнольда? Он был только со мной!",
    ["累？你听错了，我是说，这腰带有点勒。能够摸到那么精密又完美的机械是我的幸运。"] = "Усталый? Вы ослышались неправильно. Я сказал, что этот ремень немного туговат. Мне повезло иметь возможность прикоснуться к такому точному и совершенному механизму.",
    ["红手套"] = "Красная перчатка",
    ["红手套……和伦纳德一样。"] = "Красная Перчатка... прямо как Леонард.",
    ["红手套代表了什么？"] = "Что символизируют красные перчатки?",
    ["红手套可以不受限制地追踪和抓捕罪犯和被关注的邪恶者。"] = "Red Gloves может отслеживать и арестовывать преступников и злодеев, находящихся под наблюдением, без ограничений.",
    ["红手套是没有固定辖区的，伦纳德总是喜欢回来这里，我也偶尔来看看。"] = "У «Красных перчаток» нет фиксированной юрисдикции. Леонарду всегда нравится сюда возвращаться, и я тоже иногда захожу.",
    ["红桃还是黑桃？"] = "Червы или пики?",
    ["红色的油漆？"] = "Красная краска?",
    ["红色的纹路"] = "Красные узоры",
    ["约翰是我的邻居，他的父母生下来以后就没再管过他，我一直关照着他，像……像对弟弟那样。"] = "Джон мой сосед. Его родители не заботились о нем с самого рождения, поэтому я всегда присматривал за ним, как... как за младшим братом.",
    ["纺织厂如同教堂一般静谧，你的灵性却如琴键起伏不定，你向灵性预警方向看去。\n隐约看见一只手在黑雾中挣扎着，在地面刻出五道血痕，\n疯女工的惨叫再次从黑雾中传来， 她被拖进黑雾之中，再没有一点动静……"] = "На ткацкой фабрике царила могильная тишина, словно в соборе, однако ваша духовная интуиция тревожно металась, как клавиши рояля. Вы взглянули в сторону источника опасности:\nв чёрном тумане смутно билась чья-то рука, оставляя на полу пять кровавых полос.\nИз мглы вновь донёсся истошный вопль безумной работницы: её рывком уволокло в непроглядную тьму, и всё затихло...",
    ["线索显示，这个人很可能是{{Time}}在{{Place}}发生的{{Crime}}罪的凶手，找他聊聊。"] = "Улики указывают на то, что этот человек, вероятно, является виновником преступления {{Crime}}, совершенного {{Time}} в {{Place}}. Иди поговори с ним.",
    ["细细密密的，越来越多。"] = "Плотные и многочисленные, всё больше и больше.",
    ["经典款式？塔罗学派很多年轻人都有这样的喜好。"] = "Классический стиль? Такие предпочтения есть у многих молодых людей в Клубе Таро.",
    ["经查证，这些金币来自一名资本家洛克，含有非凡力量，不能让普通市民接触，会带来不可预料的危险。"] = "После проверки эти золотые монеты были получены от капиталиста по имени Локк и содержат силу Потустороннего. Их нельзя допускать до обычных граждан, поскольку они принесут непредсказуемые опасности.",
    ["经过我的研究，结合了鲁恩人的饮食偏好，我发明出了这道菜品——将咸鱼头依次放在派上烤！"] = "После моих исследований, в сочетании с диетическими предпочтениями народа лоен, я изобрел это блюдо — выложить на пирог головы соленой рыбы и запечь их по порядку!",
    ["结束了……这一切终于结束了。"] = "Все кончено... наконец-то все кончено.",
    ["结束至【50199999】"] = "Конец на [50199999]",
    ["结束至【60001999】"] = "Завершить до 【60001999】",
    ["结束至【90010000】"] = "Окончание на [90010000]",
    ["结束观察"] = "Окончание наблюдения",
    ["结果一周后我开始每天做噩梦，被砖块压住，被沙土埋起来之类的。"] = "В результате через неделю мне каждый день стали сниться кошмары: меня раздавили кирпичами, засыпали песком и так далее.",
    ["结果最后也没找到老维尔餐厅的替代品啊。"] = "В итоге замену ресторану Old Will's мы не нашли.",
    ["结果照镜子时发现还是我自己的脸，今天还是要工作，可怕得很！"] = "Но когда я посмотрел в зеркало, я обнаружил, что это все еще мое собственное лицо. Мне еще сегодня работать, это ужасно!",
    ["绘画不是你的工作吗？"] = "Разве рисование не твоя работа?",
    ["给她看警察徽章"] = "Покажи ей полицейский значок",
    ["给您献上我在拾荒老人那里买的花！如果今天能通过，我就把她所有的花全都买下来……"] = "Вот цветы, которые я купил для тебя у старика-мусорщика! Если я пройду сегодня, я куплю ей все цветы...",
    ["给我一块，谢谢。"] = "Дай мне кусочек, спасибо.",
    ["给我挑两磅嫩豌豆和四个土豆、一个洋葱，今晚要回去做嫩豌豆炖羔羊肉，庆祝小乔治亚通过了政府雇员考试。"] = "Возьми мне два фунта нежного горошка, четыре картофелины и луковицу. Сегодня вечером я собираюсь снова приготовить нежное рагу из горошка и баранины, чтобы отпраздновать сдачу маленькой Джорджией экзамена на государственного служащего.",
    ["给点提示"] = "Дайте подсказку",
    ["给，你的热牛奶，希望它能让你做个好梦。"] = "Вот твое горячее молоко. Надеюсь, это поможет вам увидеть хороший сон.",
    ["给，甜冰茶有浓郁的鲁恩南部风情，它一定能让你做个清爽的梦。"] = "Здесь сладкий холодный чай имеет богатый вкус южного Лоена; это наверняка позволит вам увидеть освежающий сон.",
    ["绝不是从哪个高地王族的墓里挖出来的，也不是哪具木乃伊身上的！"] = "Он определенно не выкопан из какой-то королевской гробницы Хайленда и не из какой-либо мумии!",
    ["统治这里的是分裂的拜朗帝国，航道开辟后，越来越多的北大陆舰队驶来，争抢着这里的土地、物产和人，把这里搅成一滩浑水。"] = "Им управляет разделенная Империя Балам. После того, как были открыты морские пути, сюда приплывало все больше и больше флотов Северного континента, сражаясь за землю, ресурсы и людей, превращая это место в грязный беспорядок.",
    ["继续劝说"] = "Продолжайте убеждать",
    ["继续检查"] = "Продолжить проверку",
    ["继续询问"] = "Продолжайте спрашивать",
    ["继续！应该是……"] = "Продолжать идти! Это должно быть...",
    ["绿叶菜是大地的恩赐！您瞧，它们的颜色鲜亮得好像在发光。这才是“从农场到餐桌”的真正新鲜！"] = "Листовая зелень – подарок Земли! Посмотрите, их цвета настолько яркие, что кажется, что они светятся. Это настоящая свежесть «от фермы к столу»!",
    ["罗伊斯，这次案子办得漂亮，你准备准备，给大家开个讲座，传授一下经验。"] = "Ройс, ты прекрасно справился с этим делом. Приготовьтесь, прочитайте всем лекцию и поделитесь своим опытом.",
    ["罗塞尔大帝有句名言，来都来了。"] = "У императора Розеллы есть знаменитая поговорка: раз мы уже здесь.",
    ["罗塞尔大帝的笔记？"] = "Записки императора Розеллы?",
    ["罗森死了！我是他可怜的学生，不仅赚不到钱，还要每月给他上缴……"] = "Лоусон мертв! Я его бедный ученик. Я не только не могу заработать денег, но мне еще и приходится платить ему каждый месяц...",
    ["罗珊，你确定？"] = "Розанна, ты уверена?",
    ["罗珊，好久不见啊。平时多谢你们安保公司照顾生意，来，尝尝我们的新菜。"] = "Розанна, давно не виделись. Спасибо за покровительство вашей охранной компании. Приходите, попробуйте наше новое блюдо.",
    ["罗珊，没想到你还有做美食评论家的天赋呢。"] = "Розанна, я не знала, что у тебя есть талант кулинарного критика.",
    ["罗珊？"] = "Розанна?",
    ["美味的咸鱼，便宜的咸鱼，罗塞尔最爱的咸鱼，改良新鲁恩口味咸鱼，霍夫曼家的咸鱼！"] = "Вкусная соленая рыба, дешевая соленая рыба, любимая соленая рыба Розеля, соленая рыба с новым улучшенным лоэнским вкусом, рыба семейства Хоффман!",
    ["美好的东西……我试试。首先想到的是……"] = "Прекрасное... Сейчас попробую. Первое, что приходит на ум...",
    ["美好的休息时间，斯卡纳女士却忙得焦头烂额。"] = "Во время прекрасного отдыха г-жа Скана занята и взволнована.",
    ["美好的谎言"] = "Красивая ложь",
    ["美梦"] = "Сладкий сон",
    ["羔羊肉就一两块！这不纯骗人吗？"] = "Есть только один или два куска баранины! Разве это не просто мошенничество?",
    ["羔羊肉怎么样？相当鲜美，非常适合用来做嫩豌豆炖羔羊肉这道菜！"] = "Как ягненок? Это очень вкусно, очень подходит для приготовления блюда из нежного горошка, тушенного с бараниной!",
    ["翻到第二页"] = "Перелистнуть на вторую страницу",
    ["翻开书籍"] = "Откройте книгу",
    ["翻窗户？"] = "Залезть в окно?",
    ["翻阅"] = "Пролистнуть",
    ["老伙计，这几天怎么没见你？不会是又被你那该死的风湿病缠上了吧？"] = "Старый приятель, почему я не видел тебя последние несколько дней? Только не говори мне, что тебя снова мучает этот проклятый ревматизм?",
    ["老兄，下次“狗抓老鼠”比赛你一定要押豪斯，我听说它有着凛冬郡猎犬的血脉，肯定能抓到最多的老鼠！"] = "Приятель, ты должен сделать ставку на Хауса в следующей гонке «Собака ловит мышь». Я слышал, что у нее есть родословная гончей округа Уинтер; он определенно поймает больше всего мышей!",
    ["老兄，下次“狗抓老鼠”比赛你想好要在谁身上押注了吗？"] = "Чувак, ты уже придумал, на кого сделать ставку в следующей игре в «собаки-мышки»?",
    ["老尼尔，麻烦过来一下。"] = "Старина Нил, пожалуйста, подойди сюда на минутку.",
    ["老尼尔？"] = "Старина Нил?",
    ["老板，你上次给我的助眠草药好像没有效果啊？"] = "Босс, снотворные травы, которые вы дали мне в прошлый раз, похоже, не оказали никакого эффекта?",
    ["老板，我想要一点那个。"] = "Босс, я хочу немного этого.",
    ["老爷都一把年纪了，去贝克兰德上议院当个议员不好吗，非要竞选廷根市长。"] = "Старый господин уже в таком возрасте; не лучше ли быть членом Палаты лордов в Баклунде? Почему он должен баллотироваться на пост мэра Тингена?",
    ["老特勒从墓地里爬出来了，该死的，小科勒又把这个墓地卖给别人了。"] = "Старый Трелль выполз с кладбища. Черт возьми, Маленький Колер снова продал этот участок кому-то другому.",
    ["老特勒呀，就是个住在村里的混蛋罢了，前几天死了。"] = "Старый Туллер, он просто ублюдок, живший в деревне, он умер несколько дней назад.",
    ["老特勒是谁？"] = "Кто такой Старый Трелль?",
    ["老特勒活着的时候是个老混蛋，死了以后也不让人消停，死了还出来蹦跶，还没有找到。"] = "При жизни старый Колер был старым мерзавцем, и после смерти не даёт никому покоя: до сих пор бродит и пакостит, а мы его так и не нашли.",
    ["老特勒，没啥好说的，他就是个混蛋罢了，住在这村子里。"] = "Старый Туллер, ничего не скажешь, он просто ублюдок, жил в этой деревне.",
    ["老特勒？看起来很有名的样子。"] = "Старый Туллер? Кажется, он довольно знаменит.",
    ["老维尔先生，<P_Heart>（有些局促）</>没想到你们也参加了这次活动。"] = "Мистер Старый Уилл, <P_Heart>(Немного неловко)</> Я не ожидал, что вы тоже примете участие в этом мероприятии.",
    ["老维尔先生，你记得我喜欢香草？"] = "Мистер Старый Уилл, вы помните, я люблю травы?",
    ["考虑一下"] = "Подумайте об этом",
    ["而且……说不定我们还来得及去参加你今晚的生日聚会。"] = "И... возможно, мы еще успеем сегодня вечером на твой день рождения.",
    ["而且你们在黛西小姐身上的尝试，害死两位仆人和一位管家……"] = "А ваши покушения на мисс Дейзи стали причиной гибели двух слуг и дворецкого...",
    ["而且在我饿的时候，还拿出面包跟我分享！"] = "А когда я был голоден, ты даже доставал Хлеб, чтобы поделиться со мной!",
    ["而且她看起来很是纤弱。或许是文职人员？"] = "И она выглядит очень хрупкой. Может быть, канцелярский работник?",
    ["而且弗莱队长他们刚才被突发任务叫走了，现在只剩我们继续这件庞大的工作。{{PlayerName}}……或许你刚好有时间帮帮我？"] = "А капитан Фрай и остальные только что были отозваны из-за внезапной миссии, так что только нам остается продолжить эту масштабную задачу. {{PlayerName}}... может быть, у тебя найдется время мне помочь?",
    ["而且我相信，我们会在黑夜的国度里，再次相聚……"] = "И я верю, что мы воссоединимся в Царстве Вечной Ночи...",
    ["而且这副牌已经用了很多年，我想他们会更习惯这些“老朋友”。"] = "И этой колодой пользуются уже много лет, думаю, они больше привыкли к этим \"старым друзьям\".",
    ["而且，你的状态并不稳定，我需要尽快将你带回贝克兰德教会重新封印。"] = "И ваше состояние не стабильно. Мне нужно как можно скорее отвезти тебя обратно в церковь Баклунда, чтобы тебя снова запечатали.",
    ["而且，我的小阿诺德很像我，我相信他。"] = "К тому же мой маленький Арнольд очень похож на меня. Я верю в него.",
    ["而且，那边的孩子手里不就是《大冒险家》？"] = "И разве этот ребенок не держит в руках «Великого искателя приключений»?",
    ["而她绝对不会允许我在家里碰一根烟叶，你懂吗？"] = "И она ни за что не позволит мне притронуться к табаку дома, понимаешь?",
    ["而它的对手，那只黑白大狗看着就很愚蠢，有几次它甚至兴奋地和耗子玩了起来！"] = "А его противник, этот большой черно-белый пес, выглядит таким глупым. Несколько раз он даже азартно начинал играть с мышами!",
    ["而封锁前，帽子帮的亨特和下街牵马的老马丁也来过湖畔。"] = "А перед блокадой к озеру приезжали еще Охотник из Шляпной банды и старый Мартин, который водит лошадей на Нижней улице.",
    ["而就算侥幸赢得了大笔财富，又会很快变成整日流连在“红剧场”中的蛆虫，哦——“红剧场”就是那儿最大的妓院名字。"] = "И даже если вам повезет выиграть большое состояние, вы быстро превратитесь в личинку, торчащую весь день в «Красном театре» — о, «Красный театр» — это название самого большого там борделя.",
    ["而我以为您是想进行一场正经的学术讨论，看来是我弄错了。"] = "И я думал, вы хотите провести серьезную академическую дискуссию. Кажется, я ошибся.",
    ["而我们，每天能盼到的最好的事情，就是你这样的人肯把手伸进口袋，丢给我们一点什么，叫我们帮忙拎行李或者牵马、送信。"] = "А для нас лучшее, на что мы можем надеяться каждый день, — это то, что кто-то вроде вас захочет полезть в карман и бросить нам что-нибудь, попросив помочь нести багаж, вести лошадь или доставить письмо.",
    ["而我已经在这个世界，找到生命中最珍贵的东西——亲人之间的感情。小黛西的纯真快乐，乔纳尔的善良温柔感染着我，我才逐渐融入和接纳这个世界。"] = "И я обрел самое дорогое в жизни в этом мире — привязанность между родственниками. Невинность и радость маленькой Дейзи, а также доброта и нежность Джонара заразили меня, и я постепенно интегрировался и принял этот мир.",
    ["而我相信，每一位顾客都拥有明亮的眼睛。"] = "И я верю, что у каждого покупателя наметанный глаз.",
    ["聊天？"] = "Чат?",
    ["联排别墅呢？"] = "А как насчет таунхаусов?",
    ["联排别墅的话，看你需要多大的面积和预算了。"] = "Для таунхаусов это зависит от того, сколько места вам нужно и вашего бюджета.",
