    ["询问笛子"] = "Спроси про флейту",
    ["该死的厂长已经拖欠了一个月的薪水，他的老婆才得病去世没多久，小女儿又因为没钱吃饭，活活饿死了。"] = "Проклятый управляющий фабрикой задерживает жалованье уже целый месяц. Жена его недавно умерла от болезни, а младшая дочь умерла от голода, потому что не на что было купить еды.",
    ["该死的弗萨克人，他们在四年前偷袭贝克兰德引起的战争。赞美女神，我们还是赢了。"] = "Чертовы Фейнапоттеры, четыре года назад они начали тайное нападение на Бэкланд, вызвав войну. Слава Богине, мы все равно победили.",
    ["该死的税金小偷！就在刚才！它还在追杀我！"] = "Чертовы сборщики налогов! Только что! Оно еще гналось за мной!",
    ["该死的，他以为这条街上的住客都是绵羊吗？不揍一顿根本不会老实！"] = "Черт побери, он что, думает, что все жители этой улицы — овцы? Без побоев они не будут послушны!",
    ["该死！你又把午餐弄不见了？！"] = "Блин! Ты снова заставил свой обед исчезнуть?!",
    ["该死！我们都该死！"] = "Блин! Мы все умрем!",
    ["该死，再这样我们就分手吧！"] = "Проклятье, если так пойдет дальше — давай расстанемся!",
    ["该死，我最终心软了，哪只耳朵也没有拧。"] = "Черт возьми, я в итоге смягчил свое сердце и не покрутил ни одного уха.",
    ["说"] = "Рассказывать",
    ["说到这里，希望你想起来的时候替我提醒戴里克两句，叫他合理安排饮食和睡眠。"] = "Кстати говоря, я надеюсь, что вы сможете напомнить мне Деррику, когда подумаете об этом, и попросите его наладить свою диету и разумный сон.",
    ["说唱歌手？也许只是生活给我安排的韵脚太过密集。"] = "Рэпер? Возможно, жизнь просто слишком плотно расставила для меня рифмы.",
    ["说回正题，需要我帮你去做些什么呢？关于你的执念，队长还有什么线索吗？"] = "Возвращаясь к главному: что мне нужно для вас сделать? Что касается вашей одержимости, есть ли у капитана какие-нибудь еще подсказки?",
    ["说实话……我甚至不知道它们躲在哪里。"] = "Честно говоря... Я даже не знаю, где они прячутся.",
    ["说实话，我不相信你。"] = "Сказать по правде, я вам не верю.",
    ["说得好，但你怎么能预设我一定用不完呢。"] = "Хорошо сказано, но как можно предположить, что я его точно не дочитаю?",
    ["说是她丈夫做生意败光了钱。"] = "Говорят, ее муж потерял все свои деньги в бизнесе.",
    ["说来话长，我们先去找到阿诺德吧。"] = "Это долгая история. Давай сначала найдём Арнольда.",
    ["说真的，我只是不想去接放学的儿子，哈哈。"] = "Честно говоря, я просто не хочу забирать сына из школы, хаха.",
    ["说真的，艾瑞克，我实在无法理解你们这些咖啡爱好者。茶可是鲁恩王国的灵魂。"] = "Серьезно, Эрик, я просто не могу понять вас, любителей кофе. Чай – душа Королевства Лоен.",
    ["说起来在刚才的梦中，我似乎也听到了诡异的声音……"] = "Кстати говоря, только что во сне я, кажется, тоже услышал странный звук...",
    ["说起来，从你入队开始，你们两个就很亲近，而且你提及邓恩的次数多到让我忍不住想……"] = "Если подумать, с того момента, как вы присоединились к команде, вы были очень близки, и вы так часто упоминали Данна, что я не мог не захотеть...",
    ["说起来，你在这里做什么？"] = "Кстати, а что ты здесь делаешь?",
    ["说起来，前两天艾尔萨小姐和雅克先生两位设计师在廷根采风的时候，来我们店转了一圈，还说有机会想和我们建立合作呢。他们要做一个新品牌，你听说过吗？"] = "Кстати, два дня назад дизайнеры Мисс Эльза и мистер Жак пришли в наш магазин, когда были в Тингене, за вдохновением, и даже сказали, что хотели бы установить с нами партнерство, если бы была возможность. Они собираются создать новый бренд; ты слышал об этом?",
    ["说起来，我刚刚好像听到一个小孩的声音，说着火柴、火柴什么的，你们听到了吗？"] = "Если подумать, я только что услышал детский голос, говорящий «совпадение, совпадение» или что-то в этом роде, ты слышал?",
    ["说起来，最早我还是廷根舞蹈团的团长，可后来家里人都让我以照顾孩子为重，爱好就等孩子长大了再搞。"] = "А ведь когда-то я возглавляла танцевальную труппу Тингена... Но потом родные настояли, что главное — растить детей, а к увлечениям можно вернуться, когда они подрастут.",
    ["诶……那是神明要干的事情，疯人院的意义，更多的是避免这些患者给社会造成新的隐患。治疗他们是神明才能完成的事情。"] = "Эх... это дело богов. Значение приюта больше в том, чтобы не допустить, чтобы эти пациенты создавали новую скрытую опасность для общества. Вылечить их – это то, что могут сделать только Боги.",
    ["诶？队长？我不擅长照顾孩子啊……"] = "Э? Капитан? Я не умею заботиться о детях...",
    ["诶？队长？老尼尔？我真的不擅长照顾孩子啊……"] = "Э? Капитан? Старина Нил? Я совсем не умею заботиться о детях...",
    ["请不要小看我，女士"] = "Пожалуйста, не смотрите на меня свысока, мадам.",
    ["请不要这么说，阿诺德懂事又聪明，我们早把他当成自己的孩子来抚养。"] = "Пожалуйста, не говори так. Арнольд разумен и умен. Мы долгое время относились к нему как к собственному ребенку, которого нужно воспитывать.",
    ["请伸出你的手，让直觉引导你选择那张牌。"] = "Пожалуйста, протяните руку и позвольте своей интуиции помочь вам выбрать эту карту.",
    ["请你，至少让我们一家人……最后团聚。"] = "Прошу вас... позвольте нашей семье хотя бы напоследок воссоединиться.",
    ["请保持距离——啊，{{PlayerName}}。"] = "Пожалуйста, держитесь на расстоянии — ах, {{PlayerName}}.",
    ["请努力听我的声音。"] = "Пожалуйста, постарайтесь прислушаться к моему голосу.",
    ["请小猫动手"] = "Попросить котенка помочь",
    ["请开始你的表演吧，艾登先生。"] = "Пожалуйста, начните выступление, мистер Эйден.",
    ["请忍耐一下。"] = "Пожалуйста, подождите немного.",
    ["请您原谅，我其实不太擅长做饭。"] = "Пожалуйста, простите меня, я не очень хорошо готовлю.",
    ["请您原谅，能不能让我再看一下黛西小姐的情况？"] = "Пожалуйста, простите меня, не могли бы вы позволить мне еще раз взглянуть на состояние мисс Дейзи?",
    ["请您放心，我一定做出最完美的果子汤。"] = "Будьте уверены, я обязательно приготовлю самый идеальный фруктовый суп.",
    ["请把选票给我，我要成为市长，进行一系列的改革，改变廷根的颓势。"] = "Пожалуйста, дайте мне свой голос. Я хочу стать мэром и провести ряд реформ, чтобы изменить упадок Тингена.",
    ["请直接告诉我"] = "Пожалуйста, скажите мне прямо",
    ["请看——"] = "Пожалуйста, взгляните —",
    ["请稍等，我去把花放下。"] = "Пожалуйста, подожди минутку, я пойду положу цветы.",
    ["请进，不必拘束，老爷吩咐过，家里要保持少爷还在时的样子。"] = "Пожалуйста, входите, не будьте формальными. Хозяин распорядился сохранить дом таким, каким он был, когда здесь еще жил молодой господин.",
    ["请问——"] = "Прошу прощения-",
    ["请问……"] = "Могу я спросить...",
    ["请问……您是肉摊的……"] = "Простите... вы из мясного ларька...",
    ["请问乔的“那些”药剂都有什么效果？"] = "Могу я спросить, какой эффект имеют «эти» зелья Джо?",
    ["请问您有什么事吗？"] = "Могу я спросить, что вам нужно?",
    ["请问有没有火柴？一根就好。"] = "У вас есть спички? Достаточно одного.",
    ["请问需要红茶还是咖啡？"] = "Хотите черный чай или кофе?",
    ["请问，两位来这里有什么事吗？"] = "Прошу прощения, какое у вас двоих здесь дело?",
    ["请随便坐。晚上八点之后营业酒水。\n我在研究新的菜谱，您喜欢芜菁还是土豆炖汤？"] = "Присаживайтесь куда угодно. Выпивку подаём после восьми вечера.\nЯ тут колдую над новым рецептом: вам больше по душе похлёбка из репы или картофельная?",
    ["请随便看看。"] = "Пожалуйста, не стесняйтесь осмотреться.",
    ["请随我来，一起欣赏这首美妙的音乐。"] = "Пожалуйста, следуйте за мной и наслаждайтесь этой чудесной музыкой вместе.",
    ["谁会想尝这种东西？"] = "Кому захочется попробовать такое?",
    ["谁会讨厌壁炉呢？"] = "Кто будет ненавидеть камин?",
    ["谁在外面嚷嚷！"] = "Кто кричит снаружи!",
    ["谁在说话！好多声音……脑袋要裂开了……"] = "Кто это говорит! Столько голосов... голова вот-вот расколется...",
    ["谁在说话？！"] = "Кто это говорит?!",
    ["谁是世界上最美丽的人？"] = "Кто самый красивый человек в мире?",
    ["谁来救救我啊，总不能因为这点小事去找会长帮助吧……我又不认识什么人，唉，我就不该这么早尝试召唤信使，啊啊啊……"] = "Кто может спасти меня? Я не могу обратиться к президенту за помощью по такому пустяковому вопросу... Я никого не знаю. Увы, не надо было так рано вызывать гонца, ай ай ай...",
    ["谁知道呢，就当是做些善事，听一听我这可怜人的牢骚吧。流浪的人那么多，就连济贫院都要排队进，只为从门缝里获得一丝怜悯。"] = "Кто знает? Просто считайте это добрым делом и выслушайте жалобы такого бедняка, как я. Странников так много, что даже в богадельне стоит очередь, чтобы получить кусочек жалости через дверную щель.",
    ["谁能告诉我怎样挑选一个合适的护身符？"] = "Может кто-нибудь подсказать, как выбрать подходящий амулет?",
    ["谁能帮我写论文！"] = "Кто может помочь мне написать дипломную работу!",
    ["谁问你这个了？"] = "Кто тебя об этом спрашивал?",
    ["谜虫身上的绒毛开始剧烈摆动——"] = "Пух Таинственного Насекомого начал сильно раскачиваться…",
    ["谜题的难度和类型，和受害者的潜意识有关。"] = "Сложность и тип головоломок связаны с подсознанием жертвы.",
    ["谢谢你。"] = "Спасибо.",
    ["谢谢你带我们回家。"] = "Спасибо, что отвезли нас домой.",
    ["谢谢你支持我！等我赢了回来一定请你吃饭！"] = "Спасибо, что поддержали меня! Когда выиграю и вернусь, обязательно угощу вас!",
    ["谢谢你的夸奖。"] = "Спасибо за комплимент.",
    ["谢谢你的赞美，喜欢的话我可以送给你。"] = "Спасибо за комплимент. Если оно тебе понравится, я могу его тебе подарить.",
    ["谢谢你！我的新朋友，你还有什么想问的吗？"] = "Спасибо тебе! Мой новый друг, хочешь спросить о чем-нибудь еще?",
    ["谢谢你，{{先生|女士}}。愿女神保佑你。如果你在铁十字街见到我的父亲贝尔曼先生，请帮我瞒着他，他还在一直找小艾琳……"] = "Спасибо, господин/госпожа. {{|}}. Пусть Богиня благословит вас. Если вы увидите моего отца, мистера Беллмана, на Айрон-Кросс-стрит, пожалуйста, помогите мне скрыть это от него; он все еще ищет маленькую Ирэн...",
    ["谢谢你，也请多多支持我的朋友们！"] = "Спасибо и, пожалуйста, продолжайте поддерживать моих друзей!",
    ["谢谢你，你已经帮助我很多了，就让其他人来继续提问吧。我们刚刚又排除了一个错误选项，真相似乎已经近在眼前了……"] = "Спасибо, вы мне уже очень помогли. Пусть другие продолжают задавать вопросы. Мы только что исключили еще один неправильный вариант, и истина, кажется, прямо перед нами...",
    ["谢谢你，保护臣民是我的责任……却把你卷进来了，抱歉。"] = "Спасибо. Защищать подданных — мой долг... Прости, что втянул тебя в это.",
    ["谢谢你，我会注意的。"] = "Спасибо, буду следить.",
    ["谢谢你，新朋友！"] = "Спасибо, новый друг!",
    ["谢谢你，玛莎。"] = "Спасибо, Марта.",
    ["谢谢你，玛莎。希望他也能像你一样坚强！"] = "Спасибо, Марта. Я надеюсь, что он сможет быть таким же сильным, как ты!",
    ["谢谢你，玛莎。我和小巴特分开之前，他也是这样轻轻地拥抱我。"] = "Спасибо тебе, Марта. Перед тем как мы расстались с маленьким Бартом, он тоже так нежно обнял меня.",
    ["谢谢你，能将这些故事告诉我。"] = "Спасибо, что можете рассказать мне эти истории.",
    ["谢谢你，艾登！"] = "Спасибо, Эйден!",
    ["谢谢你，这对我们来说，已经是足够的善意。"] = "Спасибо; для нас это уже достаточно доброта.",
    ["谢谢你，陌生人。我会考虑的。"] = "Спасибо, незнакомец. Я подумаю об этом.",
    ["谢谢你，黛西小姐。你需要休息，我去喊管家进来。"] = "Спасибо, мисс Дейзи. Вам нужно отдохнуть; Я позову дворецкого.",
    ["谢谢您……"] = "Спасибо...",
    ["谢谢您……朱莉也总是这么对我说。"] = "Спасибо... Джули мне тоже всегда это говорит.",
    ["谢谢您的善意，会长女士。"] = "Спасибо за вашу доброту, госпожа Президент.",
    ["谢谢您！您真是个好人！"] = "Спасибо! Ты действительно хороший человек!",
    ["谢谢您，下次再聊。"] = "Спасибо, увидимся в следующий раз.",
    ["谢谢您，会长女士，那丽埃娜……"] = "Спасибо, госпожа президент, тогда Лиана...",
    ["谢谢您，会长女士，那丽埃娜和封印物3-888……"] = "Спасибо, госпожа президент, затем Лиана и запечатанный артефакт 3-888...",
    ["谢谢您，告诉我这些。"] = "Спасибо, что рассказали мне это.",
    ["谢谢您，如果以后有幸在贝克兰德相遇，我会用最鲜艳的颜料为您作上一副完美的肖像画。"] = "Спасибо. Если нам посчастливится встретиться в Баклунде в будущем, я нарисую для вас идеальный портрет в самых ярких красках.",
    ["谢谢您，我会向朱莉看齐的。"] = "Спасибо, я последую примеру Джулии.",
    ["谢谢您，我明白了。让我再想想。"] = "Спасибо, я понимаю. Дайте мне подумать об этом еще раз.",
    ["谢谢您，约翰也经常这么说我。"] = "Спасибо, Джон тоже часто мне это говорит.",
    ["谢谢队长。"] = "Спасибо, капитан.",
    ["谢谢！"] = "Спасибо!",
    ["谢谢！你爸爸布彻先生呢？怎么就你一个在守摊子？你还没台子高呢！"] = "Спасибо! Где ваш отец, мистер Мясник? Почему ты единственный, кто смотрит за прилавком? Ты даже не такой высокий, как прилавок!",
    ["谢谢！谢谢你愿意祝福詹森。你和小莉迪一样，都是好孩子。"] = "Спасибо! Спасибо, что согласились поздравить Дженсена с днем ​​рождения. Ты хороший ребенок, совсем как маленькая Лидди.",
    ["谢谢，多亏了小罗珊带来的杂志。"] = "Спасибо, спасибо журналу, который принесла маленькая Розанна.",
    ["谢谢，它看上去真不错。"] = "Спасибо, выглядит просто замечательно.",
    ["谢谢，我暂时还没这方面的需求。"] = "Спасибо, но у меня пока нет никаких потребностей в этом отношении.",
    ["谢谢，我替他们向你表示感谢。"] = "Спасибо, я благодарю вас от их имени.",
    ["谢谢，我知道了。"] = "Спасибо, я понимаю.",
    ["谢谢，我自己去看看。"] = "Спасибо, пойду гляну сам.",
    ["谢谢，或许有一天你会在报纸上看到我最新的作品。"] = "Спасибо, возможно, однажды вы увидите мою последнюю работу в газете.",
    ["谢谢，期望您到时候的选票。"] = "Благодарю, надеюсь на ваш голос на выборах.",
    ["谢谢，汉娜女士，再见。"] = "Спасибо, мисс Ханна, до свидания.",
    ["谢谢，突然没食欲了。"] = "Спасибо, у меня внезапно пропал аппетит.",
    ["谢谢，老希罗多德非常愉快！"] = "Спасибо, старик Геродот очень рад!",
    ["谨慎地迈出了稳健的左脚，离狩猎目标近了一步。"] = "Осторожно сделав уверенный шаг левой ногой, вы стали на шаг ближе к цели охоты.",
    ["豌豆也指不定是放了多少天的，又瘪又老，难吃。"] = "Горох тоже невесть сколько дней пролежал: сморщенный, старый, гадость несусветная.",
    ["贝克兰德、拜亚姆、班西港……不过今天只有一艘前往拜亚姆的航班。"] = "Бэкланд, Баям, Банси-Харбор... но сегодня в Баям есть только один рейс.",
    ["贝克兰德有什么好？除了大点，简直……简直……"] = "Что хорошего в Бэкланде? Кроме размеров, он просто... просто...",
    ["贝克兰德的天气总是阴沉、起雾、连绵不断的雨，能够在这样的好天气遇见您，我很愉快。嗯，也祝您快乐。"] = "Погода в Баклунде всегда пасмурная, туманная и дождливая; Я очень рад встрече с вами в такую ​​хорошую погоду. Что ж, я тебе тоже желаю счастья.",
    ["贝克兰德的斯内克大主教，人称“神之歌者”，一首《风暴之心》据说能让整个贝克兰德港的海水为之共鸣！而你们连调都找不到，唉！"] = "Архиепископ Снейк из Баклунда, известный как «Певец Бога», утверждает, что песня «Сердца бури» способна заставить морскую воду всего порта Баклунда резонировать! А вы, ребята, даже ключ не можете найти, вздох!",
    ["贝尔纳黛·古斯塔夫"] = "Бернадетт Густав",
    ["财富的堆砌已经过时了，它们应该好好待在保险柜里，以后，工艺才是流行风尚，而爱丽丝小姐在这方面的嗅觉一向敏锐。"] = "Накопление богатства устарело; он должен оставаться в безопасности в хранилище. Отныне в моде мастерство, и мисс Алиса всегда отличалась острым нюхом на это.",
    ["账本？最近的生意出了什么问题吗？"] = "Леджер? Были ли в последнее время проблемы с бизнесом?",
    ["质问原因"] = "Задайте вопрос о причине",
    ["购买报纸"] = "Купить газету",
    ["费内波特境内有大片的平原，盛产着咖啡、可可、烟草和各种粮食，费内波特面相当好吃，哦！大地母神的恩赐。"] = "В Фейнапоттере раскинулись бескрайние равнины, богатые кофе, какао, табаком и всевозможными зерновыми. А фейнапоттерская лапша невероятно вкусна — о да, истинный дар Земной Матери!",
    ["费内波特王国是北大陆南部的大国，信仰着大地母神教会，这里温暖、潮湿，空气中洋溢着海风和费内波特琴曲的声音。"] = "Королевство Фейнапоттер — крупная держава на юге Северного континента, верящая в Церковь Матери-Земли. Здесь тепло и влажно, а воздух наполнен звуками морских бризов и музыкой Фейнапоттеров.",
    ["费尔默咖啡产自星星高原附近帕斯河谷，密实轻盈，回味久远，是不错的选择。"] = "Кофе Филмер производят недалеко от Звездного плато в долине Паз. Он плотный и легкий, с длительным послевкусием; это хороший выбор.",
    ["资料明明记载，3-888是在意外中失踪的，怎么在你们这里？"] = "В документах чётко указано, что 3-888 был утерян в результате несчастного случая. Откуда же он у вас?",
    ["赌……他们说，赌徒应有尽有，我……我什么都有……地上那不是我的钱吗？"] = "Азартные игры... говорят, у Игрока есть все, у меня... у меня есть все... Разве это не мои деньги на земле?",
    ["赌场？拜亚姆不是出产香料的地方吗？"] = "Казино? Разве Баям не место, где производят специи?",
    ["赔偿桌子"] = "Компенсация за стол",
    ["赛弗拉，你听！约会……！泽维尔一说这词，我心里砰砰直跳，我什么也不记得了，连他说在哪个餐厅门口见面也不记得！"] = "Сефра, послушай! Свидание...! Каждый раз, когда Ксавье произносит это слово, мое сердце бешено бьется. Я ничего не помню, даже у какого входа в ресторан он сказал встретиться!",
    ["赛弗拉，我这就去……！哦，不行，我一想到就脸滚烫，我，我有点迈不开步子……"] = "Сефра, я ухожу...! О, нет, у меня лицо горит, когда я думаю об этом. Я, кажется, не могу сделать ни шагу...",
    ["赞美大帝！"] = "Слава Императору!",
    ["赞美天气"] = "Хвалите погоду",
    ["赞美女神！"] = "Слава Богине!",
    ["赞美女神！您真是位好心人，我们全家人都会感谢您的！"] = "Слава Леди! Вы действительно добрый человек; вся наша семья будет вам благодарна!",
    ["赞美女神，赞美您。"] = "Слава Богине, слава тебе.",
    ["赞美风暴！如果有家庭事务相关的咨询可以来找我。"] = "Слава Шторму! Если у вас есть консультации по семейным вопросам, вы можете прийти ко мне.",
    ["赞美黑夜，赞美女神！"] = "Слава Вечной Ночи, слава Вечной Богине!",
    ["走出了下午镇，没想到却在贝克兰德迷路了。"] = "Я вышел из Тингена, но не ожидал, что заблудюсь в Баклунде.",
    ["走吧，我带你们去找他。"] = "Пойдем, я возьму тебя на его поиски.",
    ["走开走开！别害我被找到了！"] = "Уходи, уходи! Не дай мне найтись!",
    ["走得真快……"] = "Как быстро ушли...",
    ["走，去试试。"] = "Давай попробуем.",
    ["赶紧抓住谜虫"] = "Быстро поймайте таинственного червя",
    ["趁着记忆还清晰，我得出发去唤醒黛西小姐了。"] = "Пока моя память еще ясна, я должен отправиться будить мисс Дейзи.",
    ["超字数厚葬"] = "Превышено ограничение на количество персонажей. Грандиозные похороны.",
    ["越来越？你是这家的常客吗？"] = "Хуже и хуже? Вы здесь завсегдатай?",
    ["跃跃欲试"] = "Очень хочу попробовать",
    ["跟上去看看。"] = "Следуйте за ними и увидите.",
    ["跟卡萝解释了一切。"] = "Все объяснил Кэрол.",
    ["跟我来吧。"] = "Подписывайтесь на меня.",
    ["跟我走。"] = "Подписывайтесь на меня.",
    ["跟我走吧，我知道后巷有个安静的地方，比这儿可舒服多了！"] = "Пойдем со мной, я знаю тихое место в глухом переулке, там гораздо уютнее, чем здесь!",
    ["跟我走，我有办法追踪到阿诺德现在的位置。"] = "Следуйте за мной, у меня есть способ отследить текущее местоположение Арнольда.",
    ["跟随苏茜走下长长的楼梯后，你们来到了试炼场……"] = "Спустившись вслед за Сьюзи по длинной лестнице, вы вышли к арене испытаний...",
    ["车厢里的气味实在太糟糕了。"] = "Запах в вагоне действительно ужасный.",
    ["转动的齿轮，喷薄的蒸汽，一切都是那么完美。"] = "Вращающиеся шестеренки, шипящий пар — все так идеально.",
    ["转学？"] = "Перевести школы?",
    ["软弱的怜悯只会让人丧失斗志。风暴之主教导我们，人要像海燕一样在风暴中搏击，而不是等待施舍！"] = "Слабое милосердие приводит лишь к потере боевого духа. Повелитель Бурь учит нас, что в буре надо бороться, как буревестник, а не ждать подачек!",
    ["轻轻触碰"] = "Аккуратно прикоснитесь",
    ["输了多少次？赢了多少次？没人记得了，你们似乎厮杀到了世界的末日、宇宙的尽头。"] = "Сколько раз вы проиграли? Сколько раз вы выиграли? Никто не помнит; ты словно сражался до конца света, края вселенной.",
    ["过了一段时间……"] = "Спустя некоторое время...",
    ["过了很久……很久"] = "Прошло много... очень много времени",
    ["过了很久，很久……"] = "Прошло много-много времени...",
    ["过去皆成历史，历史无疑是伟大的，我们想要从中汲取营养，给予警示，避免悲剧再次重演。"] = "Прошлое стало историей, а история, несомненно, велика. Мы хотим черпать из этого пищу, предупреждать и не допускать повторения трагедий.",
    ["过去，我只当这是父亲发明的益智游戏，现在看来，更像是微缩的桌上战争。很有魅力的游戏，不是吗？<P_Heart>（微笑）</>"] = "Раньше я думал об этом только как об игре-головоломке, изобретенной моим отцом. Теперь это больше похоже на миниатюрную настольную войну. Очень очаровательная игра, не правда ли? <P_Heart> (Улыбается) </>",
    ["过期的报纸？为什么不卖当天的呢？"] = "Просроченные газеты? Почему бы не продать его в тот же день?",
    ["迈出了微微颤抖的右脚——你和谜虫都害怕惊吓到对方。"] = "Сделал слегка дрожащий правильный шаг — и вы, и Таинственное насекомое боялись напугать друг друга.",
    ["迈出右脚"] = "Шагнуть с правой ноги",
    ["迈出左脚"] = "Шагнуть левой ногой",
    ["运气好的时候能捡到只啃了一口的面包！还有很多他们不要的旧衣服啦，盘子啦，可以卖不少便士！"] = "_\n\nЕсли вам повезет, вы можете найти только пережеванный хлеб! А еще там много старой одежды и ненужной им посуды, которую можно продать за большие гроши!",
    ["运气爆棚？"] = "Переполняющая удача?",
    ["近几个月来也没有出现过偷窃、行骗和拐卖的案件，您可以照常前往。"] = "За последние несколько месяцев не было случаев воровства, мошенничества или похищения людей, так что можете идти как обычно.",
    ["近日，廷根市有位<P_Yellow>黛西小姐</>忽然昏睡不醒，照顾她的两位女仆接连死亡，家中管家已经报案。<P_Yellow>丽埃娜</>上报了这起案子，怀疑有非凡因素的影响。"] = "Недавно мисс <P_Yellow>Daisy</> из Тингена внезапно впала в кому. Две служанки, присматривавшие за ней, умерли одна за другой, о чем сообщил дворецкий дома. <P_Yellow>Liana</> сообщила об этом случае, подозревая влияние чрезвычайных факторов.",
    ["还不太确定……"] = "Пока не уверен...",
    ["还会医治一些城市顽疾。"] = "Я также лечу некоторые городские недуги.",
    ["还会教导你如何靠自己去验证祂的话是否可信，因为世界上的一切都是证据。"] = "Оно также научит вас, как самостоятельно проверить достоверность Его слов, ведь все в мире является доказательством.",
    ["还好，谢谢你今天救我，国王说你变成我们的朋友了。"] = "Все в порядке, спасибо, что спас меня сегодня. Король сказал, что ты стал нашим другом.",
    ["还是下次吧"] = "Лучше в следующий раз",
    ["还是先离开吧，别打扰专心找东西的人。"] = "Лучше пока уйти и не мешать тому, кто так сосредоточенно что-то ищет.",
    ["还是我应该说“请”呢？伟大的非凡者？"] = "Или мне следует сказать «пожалуйста»? Великий Потусторонний?",
    ["还是无法交流……"] = "Все еще не могу общаться...",
    ["还是算了。"] = "Неважно.",
    ["还有一杯！还有一杯！想尝尝吗？"] = "Есть еще одна чашка! Еще одна чашка! Хотите попробовать?",
    ["还有什么办法呢？"] = "Какой еще способ?",
    ["还有什么想问的吗？"] = "Есть ли что-нибудь еще, что вы хотели бы спросить?",
    ["还有什么需要的吗？"] = "Есть ли что-нибудь еще, что вам нужно?",
    ["还有你的小……兔子？熊？呃，鸭子？总之，无论是什么，奶奶都帮你修好了，和之前一模一样。"] = "А твой маленький... кролик? Медведь? Э, утка? В любом случае, что бы это ни было, бабушка все для тебя починила, как и было раньше.",
    ["还有你，看什么看？你对我的嗓音有意见？"] = "И ты тоже, чего уставился? Есть претензии к моему голосу?!",
    ["还有先生女士们容貌与气味的专项疾病……"] = "И специализированные заболевания, связанные с внешним видом и запахом дам и господ...",
    ["还有其他的吗？"] = "Что-нибудь еще?",
    ["还有别的事，先走了。"] = "Есть другие дела, сейчас ухожу.",
    ["还有办生日派对的闲情，看来他们应该过得不错。"] = "Еще есть свободное время, чтобы устроить вечеринку по случаю дня рождения; кажется, у них дела идут хорошо.",
    ["还有最近加入值夜者小队的克莱恩，害羞青涩的样子招人喜欢，但总被卷进非凡事件，是个倒霉的小家伙。"] = "И Клейн, который недавно присоединился к команде «Ночные ястребы». Его застенчивая и наивная внешность очаровывает, но он всегда вмешивается в происшествия в Потустороннем. Он неудачливый маленький парень.",
    ["还有表情和口型，生动的剧情表演需要多模块的配合。"] = "Есть также выражения лица и синхронизация губ; яркие сюжетные представления требуют взаимодействия нескольких модулей.",
    ["还有警察在湖畔巡逻，你要怎么带他们回家？"] = "Озеро все еще патрулирует полиция, как вы собираетесь отвезти их домой?",
    ["还有谁？"] = "Кто еще?",
    ["还有这么多门道？"] = "Есть так много способов сделать что-то?",
    ["还有，“咸鱼翻身”也是大帝用过的比喻，形容一个身处底层的人突然结交了好运，变成了大人物。"] = "А ещё «солёная рыба перевернулась» — это выражение, которое использовал сам Император: так говорят о человеке со дна жизни, которому внезапно улыбнулась удача, и он стал важной персоной.",
    ["还有，如果是紧急情况，马上向你信仰的那位存在祈祷，要相信你的伙伴，也要相信伟大存在的作用。"] = "Кроме того, если это чрезвычайная ситуация, немедленно помолитесь существованию, в которое вы верите. Вы должны доверять своим партнерам, а также доверять роли Великого Существования.",
    ["还有，角落卡座里的那个男人，也神神秘秘的。"] = "Кроме того, тот мужчина в угловой кабинке тоже ведет себя загадочно.",
    ["还能成本价购买午餐、晚餐、酒类饮料和一些占卜教材、占卜材料。"] = "Вы также можете приобрести обед, ужин, алкогольные напитки, а также некоторые учебники и материалы по гаданию по себестоимости.",
    ["还能自我控制不伤害别人的人，就不用来这里，就像阿德米索那样的，工厂区的那个疯子。"] = "Тем, кто еще может контролировать себя и не причинять вреда другим, сюда не надо приезжать, как тому парню Адемису, сумасшедшему из фабричного района.",
    ["还要再来一杯吗？"] = "Хотите еще чашку?",
    ["这……10镑，最低了！"] = "Это... 10 фунтов, это самый низкий показатель!",
    ["这……是……一……种……修……行……"] = "Это... это... форма... культивирования...",
    ["这……这是我家的油漆桶。昨天阿尔伯特把它借走了。"] = "Это... это ведро с краской моей семьи. Альберт одолжил его вчера.",
    ["这……这没什么，害怕虫子是人之常情……"] = "Это... это пустяки, бояться жуков - это человеческая природа...",
    ["这一刻！"] = "Этот момент!",
    ["这不是我要找的那个小孩吗？"] = "Разве это не тот ребенок, которого я ищу?",
    ["这不能怪他，看看我，我偶尔也会为自己着迷！"] = "Я не могу его винить. Посмотри на меня; даже я иногда восхищаюсь собой!",
    ["这东西要多少钱？"] = "Сколько за это?",
    ["这个……我也不太清楚。"] = "Это... Я тоже не слишком уверен.",
    ["这个世界……似乎到此为止了。"] = "Этот мир... кажется, достиг своего конца.",
    ["这个人似乎喝醉了，把这里当成了马桶？"] = "Кажется, этот человек пьян... Он что, принял это место за туалет?",
    ["这个口风琴和乐谱，是他留在这个世上最后的痕迹了……"] = "Эта гармошка и ноты — последние следы, которые он оставил в этом мире…",
    ["这个味道，是说谎的味道！"] = "Этот запах, это запах лжи!",
    ["这个很实用！"] = "Это очень практично!",
    ["这个手包是纯正的鱼人鳞片制成，每一片都闪着不同的光泽。是我叔叔从南大陆远航带回来的。"] = "Эта сумочка изготовлена ​​из настоящей чешуи русаля; каждый переливается разным блеском. Мой дядя привез его из долгого путешествия на Южный континент.",
    ["这个承载着爱与希望的口风琴和乐谱，是他留给你的祝福。"] = "Эта губная гармоника и ноты, хранящие любовь и надежду, — его благословение тебе.",
    ["这个盒子……你从哪里找到它的？你要拿它来做什么？"] = "Эта коробка... Где ты ее нашел? Что ты собираешься с этим делать?",
    ["这个盒子，是她准备送给邓恩的生日礼物吗？"] = "Является ли эта коробка подарком на день рождения, который она планирует подарить Данну?",
    ["这个蠢货！希望他看人的眼神能比看狗好一点，不然在这里可混不下去。"] = "Какой идиот! Надеюсь, он лучше разбирается в людях, чем в собаках, иначе он здесь долго не продержится.",
    ["这个要2苏勒……还有更便宜的吗？"] = "Это 2 сола... есть ли что-нибудь дешевле?",
    ["这个距离足以让你与它肢足上所有的绒毛拥吻。"] = "Этого расстояния вам хватит, чтобы расцеловать весь пух на его конечностях.",
    ["这个问题我也问过，她说她觉得我很特别，和她之前见过的男士都不一样，给她一种疏离感。"] = "Я тоже задавал этот вопрос, она сказала, что чувствует, что я особенный, отличаюсь от мужчин, которых она встречала раньше, что дает ей чувство отстраненности.",
    ["这个问题，你要问军情大臣，他在那边的木桶上例行巡视。"] = "Этот вопрос вам следует задать министру военной разведки, он обычно патрулирует вон ту деревянную бочку.",
    ["这么大的俱乐部，只有安洁莉卡的咖啡还是熟悉的味道。"] = "В таком большом клубе только кофе Анжелики имеет привычный вкус.",
    ["这么大的俱乐部，就找不到个能信任的占卜家吗？"] = "В таком большом клубе ты не можешь найти надежного Провидца?",
    ["这么快就到了？看来贝克兰德教区的那群家伙也没有那么古板。"] = "Здесь так скоро? Кажется, ребята из Баклундской епархии не такие уж и строгие.",
    ["这么快就看完了？没问题，老希罗多德批准你的归还。"] = "Так быстро закончили читать? Нет проблем, старый Геродот одобряет ваше возвращение.",
    ["这么快？你一定没有撒谎，对吧？"] = "Так быстро? Ты не лжешь, да?",
    ["这么神奇！"] = "Как волшебно!",
    ["这么说，事情已经查清楚了？"] = "Значит, дело прояснилось?",
    ["这么说，你还有别的打算？"] = "Итак, у тебя есть другие планы?",
    ["这么高的佣金可不常见，他犯什么事了？"] = "Такая высокая комиссия встречается редко. Во что он вляпался?",
    ["这也是女神喜爱的植物，祝福您。"] = "Это тоже растение, любимое Богиней. Будьте здоровы.",
    ["这也是艾登最希望看到的。"] = "Это также то, что Эйден больше всего надеется увидеть.",
    ["这五年来，非凡事件越来越高频，但多亏了大家，廷根市民每晚依旧可以安心入睡。"] = "За последние пять лет потусторонние инциденты происходят всё чаще, но благодаря вам жители Тингена могут каждую ночь спать спокойно.",
    ["这些信中提到了一些你姐姐曾经去过的地方、见过的人。罗塞尔大帝曾说过，凡走过，必留下痕迹。"] = "В этих письмах упоминаются некоторые места, которые посетила ваша сестра, и люди, которых она встретила. Император Розель однажды сказал: «Все, по чему ходят, оставляет след».",
    ["这些合同里也规定了吗？"] = "Это также указано в этих контрактах?",
    ["这些孩子，有一个共同点……"] = "У этих детей есть одна общая черта...",
    ["这些月亮花开得真茂盛！"] = "Эти лунные цветы так пышно цветут!",
    ["这些花是哪里来的？"] = "Откуда взялись эти цветы?",
    ["这些花都是我们从廷根东南边的一处村子附近挖来的，那里有一片很大的花海。"] = "Эти цветы мы выкопали недалеко от деревни к юго-востоку от Тингена, где большое море цветов.",
    ["这些蔬菜都是我亲手栽种的，口感很好，要来点吗？"] = "Все эти овощи были выращены мной; они имеют прекрасный вкус. Хотите немного?",
    ["这些陈词滥调，只是运气好受欢迎罢了。"] = "Эти клише популярны только благодаря удаче.",
    ["这件事情需要尽快处理，这次我与你同行。"] = "Этот вопрос необходимо решить как можно скорее. На этот раз я буду сопровождать тебя.",
    ["这件事涉及的隐秘，连我都不一定能承受。"] = "Даже я, возможно, не смогу вынести секретности, связанной с этим вопросом.",
    ["这件护身符多少钱？"] = "Сколько стоит этот амулет?",
    ["这件衣服看起来还不错。"] = "Этот предмет одежды выглядит очень хорошо.",
    ["这件雕刻着天使羽毛的银质护身符还不错，用来避免厄运足够了。"] = "Этот серебряный амулет с гравировкой в виде ангельского пера весьма недурён — чтобы отвести беду, его вполне хватит.",
    ["这份报纸给你。"] = "Эта газета для вас.",
    ["这份牵挂，化作了未竟的旋律，一直盘旋不愿离去，引领我找到你。"] = "Эта привязанность превратилась в незавершенную мелодию, задерживающуюся и не желающую уходить, побуждающую меня найти тебя.",
    ["这份资料就在<P_Yellow>角落的保管箱</>里。不过，虽然会长已经赋予你特别权限……"] = "Этот документ находится в ящике для хранения <P_Yellow> в углу </>. Однако, хотя Президент дал вам особое разрешение...",
    ["这位{{先生|女士}}，您穿得很有意思。我和艾尔萨小姐在做设计采风。"] = "Этот {{Mr.|Ms.}}, ты очень интересно одет. Мы с мисс Эльзой проводим исследование дизайна.",
    ["这位{{先生|女士}}，您说，作为医生怎么能不出诊呢？"] = "Послушайте, {{господин|госпожа}}, скажите, как врач может отказываться от вызова на дом?",
    ["这位{{先生|女士}}，来看看知识雕塑的纪念品吧！"] = "Это {{sir|madam}}, приходите посмотреть сувениры Скульптуры Знаний!",
    ["这位{{先生|小姐}}，您看，我们的曼妮莎从今天下午溜出门开始，就一直这么着急忙慌的。"] = "Видите ли, эта {{Mr.|Ms.}}, наша Маниша так спешила с тех пор, как ускользнула сегодня днем.",
    ["这位{{先生|小姐}}，或许您能帮帮曼妮莎……哦，可是您也并不知情呀！"] = "Уважаемый {{сэр|мисс}}, быть может, вы поможете Манише?.. Ах, но ведь вы тоже ничего об этом не знаете!",
    ["这位……"] = "Этот...",
    ["这位仁慈的{{先生|女士}}，您为珍妮找到火柴了吗？"] = "Добрый {{Mr.|Ms.}}, вы нашли совпадения для Дженни?",
    ["这位先生给村民开颠茄制剂来治疗病痛，结果超量服用颠茄的患者声称自己变成了狼，值夜者赶到的时候，半个村庄的人都患上了“临床变狼妄想症”。"] = "Этот господин прописывал деревенским настойку белладонны от болей. В итоге пациенты с передозировкой начали утверждать, что превратились в волков, а к моменту прибытия Ночных Ястребов половина деревни уже страдала «клинической ликантропией».",
    ["这位先生，您在大街上，马路边……抽烟？"] = "Сэр, вы... курите на улице, у дороги?",
    ["这位塔罗学派成员，回答我一个问题，如果你撒谎或回答不出，将接受我安排的任务或者被惩罚。根据对等原则，那之后你可以问我问题。"] = "Член Клуба Таро, ответьте мне на вопрос. Если вы солгаете или не сможете ответить, вы примете задание, которое я организую, или будете наказаны. По принципу взаимности вы можете задать мне вопрос после этого.",
    ["这位夫人，这株玫瑰正称您的美丽，您愿意带它回家吗？"] = "Моя леди, эта роза соответствует вашей красоте. Хотите забрать его домой?",
    ["这位女士……"] = "Эта леди...",
    ["这位女士，你怎么了？"] = "Эта леди, что с тобой не так?",
    ["这位客人，要不要参与我们今天的试餐活动？"] = "Гость, хотели бы вы принять участие в нашей сегодняшней дегустации?",
    ["这位小姐，您这样粗糙的涂改，实在有碍市容……"] = "Мисс, такие грубые изменения действительно бельмо на глазу города...",
    ["这位慷慨仁慈的{{先生|女士}}，珍妮希望能够与您一同分享这份喜悦，您愿意帮我划亮火柴吗？"] = "Эта щедрая и добрая Дженни {{ Mr. | Ms. }} надеется разделить эту радость с вами. Не могли бы вы помочь мне зажечь спичку?",
    ["这位是{{PlayerName}}警官，负责调查真相。"] = "Это офицер {{PlayerName}}, отвечающий за расследование истины.",
    ["这位美丽的小姐，我能为你写一首诗吗？"] = "Прекрасная дама, можно я напишу для вас стихотворение?",
    ["这便是保持爱情新鲜度的窍门。你还太年轻呢。"] = "В этом секрет сохранения любви. Вы еще слишком молоды.",
    ["这俱乐部里是要花钱的！我们家有一个浪费钱的蠢货就够了！"] = "Посещение этого клуба стоит денег! Хватит иметь в нашей семье одного идиота, тратящего деньги!",
    ["这儿成天有人来，有人走的，我可不知道你说的是谁了。"] = "Здесь целый день народ снует туда-сюда, откуда мне знать, о ком именно ты говоришь.",
    ["这几年我还会时不时想起他，今天不知怎么就走到这里了。"] = "Я до сих пор думаю о нем время от времени на протяжении всех этих лет, и сегодня я случайно прогуливался здесь.",
    ["这几年最火爆的小说你都不知道？我和你无话可说。去、去、排队去后面，别打扰我。"] = "Вы даже не знаете самый популярный роман последних нескольких лет? Мне нечего вам сказать. Иди, иди, встань в очередь сзади, не мешай мне.",
    ["这几年见到行长的次数渐渐少了，也许他已经放心把银行托付给希伯特少爷了。"] = "В последние несколько лет я видел менеджера банка все реже и реже. Возможно, он уже почувствовал себя спокойно, доверив банк молодому господину Хибберту.",
    ["这到底……"] = "Да что же это такое...",
    ["这只乌鸦在干什么？"] = "Что делает эта ворона?",
    ["这只是我从家里随便拿的一本杂志。"] = "Это просто журнал, который я принес из дома.",
    ["这可不是我想出来的呀！是它们自己告诉我的，我面前的这一簇花叫大海，左边这棵高一点的树叫沙滩，右边矮一点的小树叫小精灵。"] = "Это не я придумал! Они сами мне сказали, этот букет цветов передо мной называется Океан, более высокое дерево слева называется Пляж, а более низкое деревце справа называется Эльф.",
    ["这可是全廷根最高档的百货商店，关门期间也有不少人盯着它！"] = "Это самый элитный универмаг во всем Тингене, и многие присматриваются к нему, даже когда он закрыт!",
    ["这可是各大酒馆里的招牌项目！"] = "Это же коронная забава во всех тавернах!",
    ["这可是在鲁恩买不到的货呢，3金镑便宜你了。"] = "Это товары, которые нельзя купить в Лоэне; 8 фунта — это выгодная сделка для вас.",
    ["这可是廷根最大的百货商店。"] = "Это крупнейший универмаг в Тингене.",
    ["这可是真正的神迹！没想到如此高层次的事物就这样摆在最显眼的地方。"] = "Это настоящее чудо! Я не ожидал, что столь высокоуровневая вещь будет размещена на самом видном месте.",
    ["这和教会有什么关系？"] = "Какое это имеет отношение к Церкви?",
    ["这和百货商店的联系是什么？"] = "Какая связь между этим и универмагом?",
    ["这嫩豌豆炖羔羊肉越来越难吃了！"] = "Это рагу из баранины с нежным горошком становится все хуже и хуже!",
    ["这家餐厅以前可从没免费送过汤，最近怎么突然这么大方？"] = "Этот ресторан никогда раньше не раздавал бесплатный суп, почему они вдруг стали такими щедрыми?",
    ["这对你们有什么影响吗？"] = "Оказывает ли это какое-либо влияние на вас?",
    ["这小子，他偷我的火腿！"] = "Этот парень, он украл мою ветчину!",
    ["这小破酒馆没有赏金猎人也不举办娱乐活动，愿意来两杯黑麦啤酒还是烈朗齐都随你的便。"] = "В этом маленьком дайв-баре нет охотников за головами и нет развлечений, так что смело заходите на стакан ржаного пива или Тей-Ланг-Чи, когда захотите.",
    ["这就是常说的经济不景气吧！"] = "Это то, что часто называют экономическим спадом, верно!",
    ["这就是现实。而且，真正的穷人，从来不会出现在济贫院里。"] = "Это реальность. Кроме того, по-настоящему бедные никогда не появляются в богадельне.",
    ["这就是那份报告，有黛西小姐的<P_Yellow>住址</>，你看看。"] = "Вот тот самый отчет, в нем указан <P_Yellow>адрес</> мисс Дейзи, взгляни.",
    ["这就是，我们牺牲一切、坚持至今的意义。"] = "В этом смысл всего, чем мы жертвовали и ради чего упорствовали до сих пор.",
    ["这就算是对外大使送给流浪王国的第一份礼物吧。"] = "Это может быть первый подарок посла иностранных дел Странствующему королевству.",
    ["这已经持续了至少十年了，阁下，一到阴雨天，我的膝盖就疼痛无比，而廷根的阴雨天占了大多数！"] = "Это продолжается уже по меньшей мере десять лет, сэр. Каждый раз, когда выпадает пасмурный или дождливый день, у меня ужасно болят колени, а в Тингене большую часть времени пасмурно и идет дождь!",
    ["这已经是我们最近住过环境最好的地方了，为此外交大臣和帽子帮谈判了很久。"] = "Это лучшее место, где мы останавливались за последнее время. Ради него министру иностранных дел пришлось долго вести переговоры с Бандой Шляпников.",
    ["这年头金融官司可不好打！"] = "Финансовые иски в наши дни трудно выиграть!",
    ["这并非不可能。但作为医生，我从没有在判断生死上犯过错。"] = "Это не невозможно. Но как врач я ни разу не ошибся в суждениях о жизни и смерти.",
    ["这建议太奢侈了。"] = "Это предложение слишком экстравагантно.",
    ["这当然也是我想要从政的重要原因之一，这时代变化很快，有人能跟上，有人也许会掉队。"] = "И это, разумеется, одна из главных причин, почему я хочу пойти в политику. Эпоха стремительно меняется: одни поспевают за ней, а другие рискуют остаться на обочине.",
    ["这很有帮助，谢谢队长的关心。"] = "Это очень полезно, спасибо за заботу, капитан.",
    ["这必须尽快处理，你回基地包扎一下吧。"] = "Это необходимо лечить как можно скорее. Вернитесь на базу и перевяжите его.",
    ["这快赶上一整袋面粉的价钱了吧？"] = "Разве это не цена целого мешка муки?",
    ["这怪不了别人，库尔斯完全是被自己的好奇心害死的。"] = "В этом нет чьей-либо вины; Курса полностью убило собственное любопытство.",
    ["这总让我想起莫雷蒂一家——那是我当年的邻居，那家的大哥参加了当年的第一届政府雇员考试，如今，他们已经搬到贝克兰德去了。"] = "Это всегда напоминает мне о семье Моретти — тогда они были моими соседями. В том же году старший сын этой семьи сдал первый экзамен на государственного служащего, и теперь они переехали в Бэкланд.",
    ["这才对嘛！咱们一起加油，今天绝不迟到……明天！"] = "Это больше похоже на это! Давайте поработаем вместе, сегодня точно не поздно... завтра!",
    ["这日子真是没法过了……听说附近有个草药店，要不要去看看？"] = "Эта жизнь действительно невыносима... Я слышал, что неподалеку есть магазин трав, может, сходим заглянем?",
    ["这是……"] = "Это...",
    ["这是……我写给小巴特的曲子。"] = "Это... песня, которую я написал для маленького Барта.",
    ["这是一个妈妈对孩子的承诺。"] = "Это обещание матери своему ребенку.",
    ["这是一众神灵行走世间的纪元，直到现在也有很多人热衷于挖掘第四纪元的历史……"] = "Это эпоха, когда по миру ходит множество богов. Даже сейчас многие люди увлечены раскопками истории Четвертой Эпохи...",
    ["这是一本介绍女巫与黑魔法的书籍，不过这本书的上一位主人按照它调配魔法药剂，据说差点毁了一座村庄的平静生活。"] = "В этой книге рассказывается о ведьмах и чёрной магии. Впрочем, поговаривают, что прежний владелец книги, следуя описанным в ней рецептам зелий, чуть не разрушил мирную жизнь целой деревни.",
    ["这是一片落后的大陆，人们信奉着死神，最寻常的交通工具不是马车，是棺。"] = "Это отсталый континент. Люди верят в Бога Смерти. Самым распространенным средством передвижения является не карета, а гроб.",
    ["这是一首送战士出征的歌，战神信仰感染着这里的一切。"] = "Это песня для воинов, отправляющихся на войну. Вера в Бога Битвы заражает здесь все.",
    ["这是不是你临时想出来的借口？如果你是因为这种原因而不消散，那么请安息吧，卡萝队长。"] = "Это оправдание, которое ты придумал тут же? Если это причина, по которой вы не рассеялись, то, пожалуйста, покойся с миром, капитан Кара.",
    ["这是个惬意的地方，不过我当时的邻居们大多都搬走了，很遗憾……"] = "Это уютное место, но большинство моих соседей тогда уехали, очень жаль...",
    ["这是人生的终点站，每次从这里搭车离开，总会让我有不一样的感觉。"] = "Это конечная остановка жизни. Каждый раз, когда я уезжаю отсюда на карете, у меня всегда возникают новые ощущения.",
    ["这是什么东西？"] = "Что это?",
    ["这是什么，小猫，摸一下。"] = "Что это, котенок? Позвольте мне погладить вас.",
    ["这是从恩马特港暴风雨夜捕鱼的故事里汲取的灵感，据说，鱼群从暴风雨中向空中跃起，宛如要从大海涌向辽远的红月。"] = "Это было вдохновлено историей о рыбалке в штормовую ночь в порту Энмат. Говорят, что стаи рыб прыгают из шторма в воздух, как будто хотят прыгнуть из моря к далекой красной луне.",
    ["这是从我师父那里突然接手的药草店，他走得很突然，很多药方我还没学会，神奇的药方。"] = "Эту травяную лавку я неожиданно унаследовал от своего наставника. Он ушёл слишком внезапно, и многим рецептам я так и не успел обучиться... Чудесным рецептам.",
    ["这是他的日记，一本他已经渐渐看不懂的发明笔记。"] = "Это его дневник, блокнот изобретений, который он больше не может понять.",
    ["这是你的猫吗？真可爱。"] = "Это твой кот? Как мило.",
    ["这是你的荣幸，年轻的非凡者。"] = "Это твоя честь, молодой Потусторонний.",
    ["这是刚刚的那盒火柴……"] = "Это коробок спичек, который я только что купил...",
    ["这是可以说的吗？老天啊，你们什么也没说！我什么也没听见！咱们赶紧结束这个话题吧……"] = "Мы можем об этом поговорить? Боже мой, ты ничего не сказал! Я ничего не слышал! Давайте поскорее закончим эту тему...",
    ["这是命运馈赠的礼物。"] = "Это подарок судьбы.",
    ["这是她最后一张工资条，上面有她留给我和小珍妮的话，你可以打开看看——如果你想的话。"] = "Это ее последняя квитанция о зарплате, там записаны слова, которые она оставила мне и маленькой Дженни. Вы можете открыть его и посмотреть — если хотите.",
    ["这是宁静药剂，你服下之后，只要努力听我的声音，其他的什么都不要想。"] = "Это зелье спокойствия. После того, как возьмешь, просто постарайся слушать мой голос и не думать ни о чем другом.",
    ["这是尤朵拉的资料。"] = "Это информация Йодоры.",
    ["这是常态，每个时段我们身边都会有不同的人陪伴。"] = "Это вполне естественно: на каждом этапе жизни рядом с нами оказываются разные люди.",
    ["这是当今世界所处的纪元，四国统治着北大陆。"] = "Это эпоха, в которую пребывает нынешний мир: четыре великих державы правят Северным континентом.",
    ["这是当然的，不过对于工薪阶层来说，花2便士喝上一杯还是他们为数不多能够承受的起的消遣。"] = "Это, конечно, так, но для рабочего класса потратить 2 пенсов на выпивку — одно из немногих развлечений, которые они могут себе позволить.",
    ["这是怎么了？"] = "Что случилось?",
    ["这是您的花园吗，很漂亮。"] = "Это ваш сад? Это очень красиво.",
    ["这是新白银城的特产，黑面酒，可以帮我带给首席吗？"] = "Это местная диковинка Нового Города Серебра — вино из чернотрава. Можешь передать его Главе?",
    ["这是用夜香草、深眠花、洋甘菊混合蒸馏萃取的纯露，有位女士命名为“安曼达”，在赫密斯语里是宁静的意思。"] = "Это цветочная вода, дистиллированная из смеси ароматной ночной травы, цветов глубокого сна и ромашки. Женщина назвала его «Аманта», что по Гермесу означает спокойствие.",
    ["这是第一句。"] = "Это первое предложение.",
    ["这是第三句。"] = "Это третье предложение.",
    ["这是第二句。"] = "Это второе предложение.",
    ["这是身为国王应尽的责任，不能让别人代劳。"] = "Это обязанность, которую должен выполнить Король, я не могу позволить другим делать это за меня.",
    ["这是阿诺德·比舍普，他可能被卷进了最近的儿童失踪案。"] = "Это Арнольд Бишоп. Возможно, он замешан в недавних делах об исчезновении детей.",
    ["这是鲁恩什么地方的口味……"] = "Что это за лоенский вкус...",
    ["这是黑荆棘安保公司，有什么能为您服务的吗？"] = "Это охранная компания Чёрный Чертополох. Могу ли я что-нибудь сделать для тебя?",
    ["这是，这是奶茶！你不是要教我配睡眠药剂的吗？"] = "Это чай с молоком! Разве ты не должен был научить меня готовить снотворное?",
    ["这条街的人是穷，但了解世界的心和其他人的没有差别。"] = "Люди на этой улице бедны, но их понимание мира ничем не отличается от других людей.",
    ["这株黄水仙和他一样，来自因蒂斯，那是一个浪漫的国度，令人向往。"] = "Этот желтый нарцисс, как и он, родом из Интиса. Это романтическая страна, по-настоящему тоскующая.",
    ["这样也是可以的吗……"] = "Это действительно нормально...",
    ["这样啊……那看来没办法了，有时间的话，我们会去店里用餐的。"] = "Понятно... тогда ничего не поделаешь. Если у нас будет время, мы придем в магазин пообедать.",
    ["这样啊，我还在休假，工作的事以后再谈。"] = "Я понимаю. Я все еще в отпуске; мы можем поговорить о работе позже.",
    ["这样我会没法把你带回家的！"] = "Иначе я не смогу отвезти тебя домой!",
    ["这次好像不一样了？"] = "Кажется, на этот раз все по-другому?",
    ["这次没看上，还有下次。您以后想要新鲜鱼，跟我打声招呼就行。"] = "Если вы ничего не нашли в этот раз, всегда есть следующий раз. Просто дайте мне знать, если захотите в будущем свежую рыбу.",
    ["这正是我需要的信息，谢谢你。"] = "Это именно та информация, которая мне нужна, спасибо.",
    ["这没什么，不过臣民是指旁边这个小男孩吗？"] = "Ничего. Но под предметами вы имеете в виду этого маленького мальчика рядом с вами?",
    ["这煎肉闻起来真好，有一种让人怀念的味道……也许是因为香草吧。我们这就尝尝！"] = "Это обжаренное мясо пахнет так приятно, у него ностальгический аромат... может, дело в травах. Давайте попробуем!",
    ["这片历史孔隙……为什么被点亮了？我不曾……"] = "Этот пробел в истории... зачем его засветили? Я никогда...",
    ["这真不像小孩说的话。"] = "Это действительно не похоже на то, что сказал бы ребенок.",
    ["这码头的每艘船都挂着我家旗帜，尽管去让人事开了我——"] = "Каждый корабль в этом доке плавает под флагом моей семьи, так что давайте, пусть отдел кадров меня уволит…",
    ["这种不属于模板中的对象，都需要通过新增镜头轨来实现哦。"] = "Подобные объекты, которых нет в шаблоне, необходимо реализовать путем добавления новой дорожки камеры.",
    ["这种时候，我好想回到因蒂斯……"] = "В такие моменты очень хочется вернуться в Интис...",
    ["这种药剂真的有效吗？或许我需要去准备些鸟饲料先拉近距离……"] = "Действительно ли это зелье эффективно? Возможно, мне нужно сначала приготовить корм для птиц, чтобы преодолеть расстояние...",
    ["这种风格的珠宝会大量运用曲线，材料的组合也往往足够绚丽，彩色宝石的价格都因此被炒高了。"] = "В этом стиле ювелирных изделий используется множество изгибов, а сочетание материалов часто бывает просто великолепным, что привело к росту цен на цветные драгоценные камни.",
    ["这笔钱会用来干什么呢？"] = "И на что же пойдут эти деньги?",
    ["这类镜头不属于模板内容，需要根据具体需求，由策划来手k出来。一般来说，k的越细，效果越好。"] = "Этот тип камеры не относится к шаблонам, дизайнеру необходимо вручную расставлять ключи анимации под конкретные нужды. Как правило, чем детальнее расставлены ключи, тем лучше результат.",
    ["这群小家伙吵吵闹闹地要给你办生日派对。对了，我也赌你会忘记自己的生日，感谢配合。来吧克莱恩，十便士。"] = "Эти малыши суетились из-за того, что устроили тебе вечеринку по случаю дня рождения. Кстати, я тоже готов поспорить, что ты забудешь свой день рождения. Спасибо за сотрудничество. Давай, Клейн, десять пенсов.",
    ["这肉都臭了，还能卖？不怕吃出问题吗？"] = "Это мясо уже протухло, можно ли его еще продать? Не боитесь вызвать проблемы со здоровьем?",
    ["这街上又人来人往的了，真棒啊，你说是不是？"] = "Улица снова кипит людьми, это здорово, вам не кажется?",
    ["这角度真是令人耳目一新。若是让您去给集市上的驴子做个批注，怕是能出一本厚厚的专著。"] = "Этот ракурс действительно освежает. Если бы вам разрешили комментировать ослов на рынке, боюсь, вы могли бы написать толстую монографию.",
    ["这该死的小混蛋，还敢躲！现在被我抓到了吧，看我不宰了你！"] = "Ты, чертов маленький паршивец, посмеешь спрятаться! Теперь, когда я поймал тебя, посмотрим, не убью ли я тебя!",
    ["这该死的济贫院规定，将大人和孩子分开安置，害我白天的时候都找不到你。"] = "Это проклятое правило ночлежки разделять взрослых и детей не позволяет мне найти тебя в течение дня.",
    ["这起儿童失踪案，可能没那么简单。"] = "Дело о похищении ребенка может быть не таким простым.",
    ["这跟佛尔思的《大冒险家》有什么关系？"] = "Какое это имеет отношение к «Великому искателю приключений» Форса?",
    ["这边的摊位，统统免费品尝！"] = "Все киоски здесь можно попробовать бесплатно!",
    ["这道罗勒牛尾汤，可以预订送餐到我们公司吗？在佐特兰街36号，2楼。"] = "Можно ли заказать суп из бычьих хвостов с базиликом с доставкой в ​​нашу компанию? По адресу улица Зотланд-стрит, 36, 2-й этаж.",
    ["这道菜可以加入我们的餐食改良计划。"] = "Это блюдо можно было бы добавить в наш план улучшения питания.",
    ["这都是我找来的二手报纸。有钱人家的门廊、佐兰特街的垃圾桶、花园的躺椅，各种各样的地方。"] = "Это все подержанные газеты, которые я нашел. Подъезды богатых домов, мусорные баки на улице Золат, шезлонги в садах — да куда угодно.",
    ["这里……环境的确很糟糕。"] = "Эта... окружающая среда действительно очень плохая.",
    ["这里交通很便利，稍微走几步就能到圣赛琳娜教堂，有轨马车也有站点，去其他教堂和火车站也很方便。"] = "Транспорт здесь очень удобен. Короткая прогулка приведет вас к собору Святой Селены. Также есть трамвайная остановка, очень удобно добираться до других церквей и вокзала.",
    ["这里以前是菜园？"] = "Раньше здесь был огород?",
    ["这里到处都是发狂的秘偶，真是太可怕了，但也只有这里，能搞到最多最好的秘偶精粹，喂，看你衣兜鼓囊囊的，想必这一路捡了不少吧？"] = "Это место кишит обезумевшими марионетками. Это действительно ужасно, но это также единственное место, где можно получить самую лучшую и самую лучшую эссенцию марионеток. Эй, судя по твоим оттопыренным карманам, ты, должно быть, немало набрался по дороге, верно?",
    ["这里实在有些糟糕，我可以帮你们安排其他地方过生日。"] = "Здесь действительно немного ужасно. Я могу помочь вам организовать другое место для празднования вашего дня рождения.",
    ["这里应该就是<P_Yellow>黛西小姐</>的家。"] = "Это должен быть дом <P_Yellow> Мисс Дейзи </>.",
    ["这里是亨利侦探事务所！有能为您效劳的地方吗？"] = "Это детективное агентство Генри! Могу ли я что-нибудь сделать для тебя?",
    ["这里是你们的流浪王国。"] = "Это ваше странствующее королевство.",
    ["这里是风暴教会的池子，干净得很，哪有什么鱼？"] = "Это пруд Церкви Бурь, он очень чистый, где бы там была рыба?",
    ["这里有一只迷路的小羔羊。"] = "Здесь заблудившийся ягненок.",
    ["这里有各种咖啡，红茶，还有专为小孩子准备的甜冰茶，小蛋糕和水果塔等等，保证让每位客人度过美好的时光。"] = "У нас есть все виды кофе, черного чая и сладкого чая со льдом, специально приготовленные для детей, небольшие пирожные, фруктовые пироги и т. д., чтобы каждый гость прекрасно провел время.",
    ["这里有没有售卖一种，呃……小孩子会喜欢的面包？"] = "Вы продаете какой-нибудь... хлеб, который понравится детям?",
    ["这里有许多不同尺寸的雕像。"] = "Здесь много статуй разного размера.",
    ["这里流传着一句谚语“撒谎者长长鼻子”。"] = "Здесь есть пословица: «У лжецов длинные носы».",
    ["这里的人是绝对不会这么做的！大家都只管自己的死活……"] = "Люди здесь никогда бы этого не сделали! Каждый заботится только о своем выживании...",
    ["这里的每杯酒都来自恶龙的馈赠……如果你点的这杯也算作酒的话。尽享美味吧，{{先生|女士}}。"] = "Каждый бокал вина здесь — подарок дракона… если заказанный вами бокал считается вином. Приятного аппетита, {{Сэр | Мадам}}.",
    ["这里的每杯酒都来自恶龙的馈赠。尽享美味吧，{{先生|女士}}。"] = "Каждый напиток здесь исходит от дара дракона. Наслаждайтесь вкусом, {{sir|madam}}.",
    ["这里的环境总让人有些犯困，你不觉得吗？要是不叫“学派”而叫“沙龙”，一定会有趣得多。"] = "Здешняя обстановка всегда заставляет людей чувствовать себя немного сонными, тебе не кажется? Если бы это называлось не «школой», а «салоном», то однозначно было бы гораздо интереснее.",
    ["这里的生活真好……"] = "Жизнь здесь так хороша...",
    ["这里确实有不少有趣的东西。"] = "Здесь действительно немало интересного.",
    ["这里虽然条件艰苦，但至少能给那些无家可归的人一个遮风挡雨的地方。"] = "Хотя условия здесь тяжелые, по крайней мере здесь можно найти приют для бездомных.",
    ["这里难道就是基地……"] = "Это база?..",
    ["这附近没有厨房，厨具该怎么办呢？"] = "Рядом нет кухни; что мне делать с посудой?",
    ["这首未完的乐曲，我一定会把它完成。当你再次听到这段旋律，就是我们相聚的那天。"] = "Я обязательно закончу это незавершенное музыкальное произведение. Когда ты снова услышишь эту мелодию, это будет день, когда мы воссоединимся.",
    ["进一步了解"] = "Узнать больше",
    ["进去吧伙计。希望我过一会看见你的时候，你是竖着出来的。"] = "Заходи, приятель. Я надеюсь, что когда я увижу тебя через некоторое время, ты выйдешь на своих двоих.",
    ["远离危险"] = "Держитесь подальше от опасности",
    ["连灵使都无法完全隔绝这种影响吗？"] = "Неужели даже Духовный Медиум не может полностью изолировать это влияние?",
    ["迪西馅饼？豌豆炖羊羔肉？……要不还是红焖达格亚牛小排？"] = "Дикси пирог? Тушеная баранина с горошком? …Как насчет тушеных коротких ребрышек из говядины дагоя?",
    ["迷途的灵魂啊，请驻足聆听命运的低语。随着每个黎明到来，我将获得为你揭示神秘的契机。"] = "Заблудшая душа, пожалуйста, остановись и прислушайся к шепоту судьбы. С каждым рассветом я получу возможность открыть тебе тайны.",
    ["追上去"] = "Догнать",
    ["追到金黄的大河，就喝干河水……"] = "Преследовать его до золотой реки, а затем пить реку досуха...",
    ["追捕失控非凡者。目标叫卡尔·埃德加，窥秘人途径序列7，失控后四处游荡，伤害了很多人。"] = "Выслеживание Потустороннего, потерявшего контроль. Цель зовут Карл Эдгар, загадочный Прайер из седьмой серии. Потеряв контроль, он бродил вокруг и ранил множество людей.",
    ["追随灵性的气息"] = "Следуйте за ароматом духовности",
    ["送您一把迷迭香，下次再来！"] = "Вот тебе пучок розмарина, приходи еще!",
    ["适度的合作能够事半功倍，过度的依赖则是一种软弱，迟早会在危机下成为致命的缺陷。"] = "Умеренное сотрудничество позволяет добиться двойного результата, прилагая вдвое меньше усилий, но чрезмерная зависимость — это слабость, которая рано или поздно станет фатальным недостатком в условиях кризиса.",
    ["适当增加就业，努力稳定物价，积极刺激消费。我有很多工厂，很清楚工人们当下的真实诉求。"] = "Соответствующим образом повышать занятость, стремиться стабилизировать цены и активно стимулировать потребление. У меня много фабрик, и я очень хорошо знаю истинные текущие потребности рабочих.",
    ["选项环"] = "Кольцо выбора",
    ["透明的灵之虫"] = "Прозрачный червь духа",
    ["通常来说，世界的历史分为五个纪元，分别是……"] = "Как правило, история этого мира делится на пять эпох, а именно...",
    ["造物主从混沌中醒来，打破了幽暗，制造了第一缕光，自己则彻底融入宇宙，化身为万物……"] = "Создатель проснулся от хаоса, разогнал тьму, создал первый луч света, а затем полностью слился со вселенной, став всем сущим...",
    ["遇上点小麻烦，我弟弟的午餐又不见了。"] = "Попал в небольшую неприятность, обед моего брата снова пропал.",
    ["遇到了一些考验，但运气还算不错，谜题都解开了。"] = "Я столкнулся с некоторыми испытаниями, но мне повезло, и все головоломки были решены.",
    ["遇到麻烦去占卜一下，是廷根人的习惯。"] = "У жителей Тингена есть привычка прибегать к гаданию, когда они сталкиваются с неприятностями.",
    ["遇到麻烦的话，我们习惯去占卜俱乐部，你知道的，遇到麻烦去占卜一下，是廷根人的习惯。"] = "В случае неприятностей мы обычно идем в клуб гаданий. Сам знаешь, гадать при любых невзгодах — давняя привычка жителей Тингена.",
    ["道恩……道恩也牺牲了，我们将她葬在了拉斐尔墓园，就在你附近、一个阳光可以照耀到的地方。"] = "Рассвет... Дон тоже пожертвовала собой. Мы похоронили ее на кладбище Рафаэля, прямо рядом с вами, в месте, где светит солнце.",
    ["遵循平等是什么意思？"] = "Что означает соблюдение равенства?",
    ["邓恩……祝你生日快乐……其实我……"] = "Дэнн... с днем рождения... На самом деле я...",
    ["邓恩与戴莉简单说明廷根儿童失踪案与阿诺德的事情。"] = "Данн и Дейли кратко объяснили дело о похищении детей Тингена и дело Арнольда.",
    ["邓恩先生、戴莉女士……"] = "Мистер Данн, леди Дейли...",
    ["邓恩先生的孩子喜欢这种蛋糕吗，但我记得你还是单身？"] = "Ребёнку мистера Данна нравится этот торт? Но я помню, ты все еще одинок?",
    ["邓恩先生，好久不见。"] = "Мистер Данн, давно не виделись.",
    ["邓恩先生，您是来看望阿诺德的吗？"] = "Мистер Данн, вы пришли проведать Арнольда?",
    ["邓恩先生，我们接到了消息，儿童失踪案已经转为非凡事件，我们会配合您这边的一切行动。"] = "Мистер Дэнн, мы получили распоряжение: дело о пропаже детей признано потусторонним инцидентом. Мы окажем любое содействие вашим действиям.",
    ["邓恩先生，邓恩先生！"] = "Мистер Данн, мистер Данн!",
    ["邓恩叔叔，您看到我妈妈了吗？"] = "Дядя Данн, ты видел мою мать?",
    ["邓恩听不见我的声音吗？这太可惜了。"] = "Неужели Данн не слышит мой голос? Очень жаль.",
    ["邓恩说的没错，吹响我吧！"] = "Данн прав, взорви меня!",
    ["邓恩队长……"] = "Капитан Данн...",
    ["邓恩队长……我听说过他，一个很可靠的人。"] = "Капитан Данн... Я слышал о нем, очень надежный человек.",
    ["邓恩队长和克莱恩……几年前的事情了，没想到你都还记得。"] = "Капитан Данн и Клейн... это было много лет назад, я не ожидал, что вы еще помните.",
    ["邓恩，你的语气太像审问了。"] = "Данн, твой тон слишком похож на допрос.",
    ["邓恩，听到了吗？"] = "Данн, ты это слышал?",
    ["邓恩？他看起来成熟了好多……"] = "Данн? Он выглядит намного взрослее...",
    ["那{{大哥哥|大姐姐}}，等你有空的时候再来看我吧，说不定那时候我已经开出花啦。"] = "Тогда {{ big brother | big sister }}, приходи ко мне снова, когда будет время. Может быть, к тому времени я расцвету.",
    ["那……就去把她的灵接出来吧，就当做晚间训练。"] = "Тогда... иди и выведи ее дух, считай это вечерней тренировкой.",
    ["那……爸爸，你能教我操控风的方法吗？我、我真的很想和你去海上。"] = "Тогда... Папа, ты можешь научить меня управлять ветром? Я, я очень хочу поехать с тобой на море.",
    ["那、那我该怎么报答您呢？"] = "Т-тогда как мне отплатить тебе?",
    ["那一刻，艾登就像光，让我不再害怕夜晚。\n只是，光也会有暗淡的时候……"] = "В тот миг Эйден был подобен лучу света, избавившему меня от страха перед тьмой ночи.\nВот только и свет порою угасает...",
    ["那下次吧。"] = "Тогда в следующий раз.",
    ["那两位女仆，因为触碰黛西小姐手腕的符号，进入循环空间、没解开谜题而死？"] = "Неужели эти две служанки погибли из-за того, что коснулись символа на запястье мисс Дейзи, вошли в пространство петли и не смогли решить головоломку?",
    ["那个人、那个男人说，只要这么做，我们就可以一起回家……家，我要回家……"] = "Тот человек... тот мужчина сказал, что если я сделаю это, мы сможем вместе вернуться домой... Домой... Я хочу домой...",
    ["那个人好奇怪啊，从刚才到现在，怎么一直在那边自言自语？"] = "Этот человек такой странный, почему они с этого момента разговаривают сами с собой?",
    ["那个？"] = "Вон то?",
    ["那为什么会酗酒呢？"] = "Тогда почему он стал алкоголиком?",
    ["那么我们对半分。"] = "Тогда мы разделим их пополам.",
    ["那么等会我们就在廷根湖的王国集合！"] = "Тогда мы встретимся позже в Королевстве у озера Тинген!",
    ["那么请问行政大臣，廷根湖畔的杯子和火柴都是国库里的东西？"] = "Тогда позвольте мне спросить, министр администрации, являются ли чашки и спички с озера Тинген предметами национальной казны?",
    ["那么，{{PlayerName}}，那时你闻到雏菊的清香了吗？\n<P_Yellow>（注意：不同的选择将让故事走向不同的结局。）</>"] = "Тогда, {{PlayerName}}, ты тогда почувствовал слабый аромат ромашки?\n<P_Yellow> (Примечание: разные варианты приведут историю к разным концам.)</>",
    ["那么，我该何时找您订购香水呢？"] = "Тогда когда мне прийти к вам, чтобы заказать духи?",
    ["那么，我这边还有一些工作要处理，先走一步了。"] = "Что ж, мне ещё нужно разобраться с кое-какой работой, так что я пойду.",
    ["那么，拿着这瓶醒神花露，它能帮黛西小姐恢复意识。"] = "Затем возьмите эту бутылку Пробуждающейся Цветочной Росы; это может помочь мисс Дейзи прийти в сознание.",
    ["那些人贩子——哔——我要是还活着——哔——"] = "Эти торговцы людьми — гудок — если бы я был еще жив — гудок —",
    ["那些坐在马车里的老爷？他们的日子可好过多了！"] = "Эти господа сидят в каретах? Их жизнь стала намного проще!",
    ["那些失踪的孩子们，还有我的小阿诺德就拜托你们了。毕竟我现在这副模样，似乎也做不了什么。"] = "Этих пропавших детей и моего маленького Арнольда я оставлю тебе. В конце концов, в моем нынешнем состоянии я, похоже, мало что смогу сделать.",
    ["那些是邓恩队长的，或许你听过他的事情，他是一个很好的人。"] = "Это капитана Данна. Возможно, вы слышали о нем; он был очень хорошим человеком.",
    ["那些老爷太太们……应该一辈子都没吃过这种苦吧。"] = "Эти хозяева и хозяйки... они, наверное, никогда в жизни так не страдали.",
    ["那些该死的野生非凡者，以为会变几个戏法就能逃脱法律的制裁？这次我绝不会让他们得逞，不允许发生任何意外！"] = "Эти чертовы дикие Потусторонние думают, что смогут избежать юридических санкций, просто зная несколько трюков? На этот раз я никогда не позволю им добиться успеха и не допущу никаких случайностей!",
    ["那他多半是个骗子。"] = "Тогда он, вероятно, мошенник.",
    ["那件案子对你来说并不算危险。或许可以交给你，作为一次学习和历练。"] = "Этот случай для вас не опасен. Возможно, я могу оставить это вам в качестве учебного опыта.",
    ["那位夫人难道是退伍的女兵吗？但即使是黑夜女神的信徒，也很少有被征召入伍的情况……"] = "Может ли эта женщина быть отставным солдатом? Но даже среди верующих в Богиню Вечной Ночи в армию призывают редко...",
    ["那位小女孩，是您的……"] = "Эта маленькая девочка, она твоя...",
    ["那位？"] = "Тот?",
    ["那你出现在这里的原因是……"] = "Тогда причина, по которой вы здесь...",
    ["那你呢？"] = "А вы?",
    ["那你或许可以尝试一下占卜，说不定可以给你带来新的解决办法。"] = "Тогда, возможно, вы сможете попробовать гадание; это может принести вам новое решение.",
    ["那你打算单干吗？"] = "Тогда ты планируешь выступать соло?",
    ["那你还是先吃饭？"] = "Тогда стоит ли сначала поесть?",
    ["那你还跑？"] = "Тогда зачем ты бежишь?",
    ["那又怎么样？我是一只饿了很久的可怜小猫咪！"] = "Ну и что? Я бедный котёнок, который давно голоден!",
    ["那可不是随随便便就能操控的，刚入塔罗学派的学生我都不推荐，毕竟那需要控制好冰和火的力量。"] = "Это не то, что вы можете контролировать случайно. Я не рекомендую его студентам, которые только что присоединились к Клубу Таро; в конце концов, это требует хорошего контроля над силами льда и огня.",
    ["那可不能错过！"] = "Тогда я не могу это пропустить!",
    ["那可以看看文德尔街的公寓房，很适合您这样的单身精英人士，就在豪尔斯街的北侧，也是在富裕的北区。"] = "Тогда вы можете посмотреть квартиру на Уэнделл-стрит. Это очень подходит для такой одинокой элиты, как вы. Он находится на северной стороне Хаулс-стрит, также в богатом Северном районе.",
    ["那可太多了，如果你拿了冠军，你会成为这一带的知名人物，上报纸头条，获得数之不尽的财富！"] = "Можно так много выиграть! Если вы выиграете чемпионат, вы станете известной фигурой в этой области, попадете в заголовки газет и получите бесконечное богатство!",
    ["那可是不小的一笔钱，说不定我还可以给爸爸妈妈寄去一些。"] = "Это довольно большая сумма. Может быть, я даже смогу отправить немного маме и папе.",
    ["那可要努力了，那里住的都是有钱人。"] = "Это потребует некоторых усилий, там живут только богатые люди.",
    ["那块怀表，我猜一定和他一起下葬了。"] = "Эти карманные часы, я уверен, были похоронены вместе с ним.",
    ["那外表斯文有礼，行动却疯狂的冒险家，有着令四王七将都恐惧的名字——格尔曼！没错，就是他，大冒险家，疯狂的海盗猎人，格尔曼·斯帕罗！"] = "Тот самый искатель приключений, безупречно вежливый снаружи, но безумный в действиях, носит имя, перед которым трепещут Четыре Короля и Семь Адмиралов — Герман! Да, это он, великий авантюрист, безумный охотник на пиратов — Герман Спэрроу!",
    ["那天晚上，小姐发起了高烧，我们就请乔纳尔医生过来治疗。小姐服药后就睡着了，所以我们整晚都没去打扰。"] = "В тот вечер у барышни поднялся сильный жар, и мы пригласили доктора Джонара. Приняв лекарство, барышня уснула, поэтому всю ночь мы ее не тревожили.",
    ["那太好了，希望您一辈子不用来罗森民俗草药店。"] = "Это здорово, надеюсь, вам никогда до конца жизни не придется приходить в лавку народных трав «Розен».",
    ["那太遗憾了，我听说那是全大陆最繁华的城市，您以后有空可以去观光。"] = "Очень жаль, я слышал, это самый процветающий город на всем континенте. Будет время — обязательно съездите туда.",
    ["那家伙在楼上站了半天了，不知道到底在干嘛？"] = "Этот парень уже давно стоит наверху, интересно, что он на самом деле делает?",
    ["那家伙很神秘……酒保亚历克斯告诉我，他是最近才出现在恶龙酒吧的，每次都是一个人坐在角落喃喃自语，有时候还会露出古怪的笑容。"] = "Этот парень очень загадочный... Бармен Алекс рассказал мне, что он появился в баре ««Злой Дракон»» совсем недавно. Каждый раз он сидит один в углу и что-то бормочет про себя, а иногда даже показывает странную улыбку.",
    ["那就……让我看看你最近的成长吧！"] = "Тогда... покажи мне, чему ты научился за последнее время!",
    ["那就别做白日梦了，即使有好运，也不会砸到我们头上。"] = "Тогда не мечтай. Даже если будет удача, она не свалится нам на голову.",
    ["那就动手吧，爱管闲事的好心人。"] = "Тогда приступай к работе, назойливый добросердечный человек.",
    ["那就看看谁会赢吧！"] = "Тогда посмотрим, кто победит!",
    ["那就这些吧，给你零钱。"] = "Вот и все, вот перемена.",
    ["那当然！"] = "Конечно!",
    ["那当然，我总结了一本《阿罗德斯问答攻略大全》，这可是一次次试出来的。资料证明，魔镜不会太过为难学员的。"] = "Конечно, я составил «Полное руководство по вопросам и ответам на Арродес», которое проверялось снова и снова. Данные доказывают, что волшебное зеркало не усложнит задачу ученикам.",
    ["那很好。"] = "Замечательно.",
    ["那很辛苦吧？"] = "Это должно быть очень тяжело, да?",
    ["那您在这里钓鱼的意图是？"] = "Тогда каковы ваши намерения ловить рыбу здесь?",
    ["那我们开始吧！"] = "Тогда начнем!",
    ["那我们还等什么？"] = "Тогда чего мы ждем?",
    ["那我先去看看，谢谢队长。"] = "Тогда я пойду посмотреть, спасибо, капитан.",
    ["那我再看看。"] = "Тогда я посмотрю.",
    ["那我可得好好想想，等我写完了我会送你一本的，谢谢你！"] = "Тогда мне придется хорошенько об этом подумать. Когда я закончу писать, я пришлю вам копию. Спасибо!",
    ["那我就做对外大使吧。"] = "Тогда я буду послом иностранных дел.",
    ["那我希望听到这首乐曲的人，都能与失散的家人团聚。"] = "Тогда я надеюсь, что каждый, кто услышит эту мелодию, сможет воссоединиться со своими потерянными близкими.",
    ["那我换成四个二？"] = "Тогда мне следует обменять его на четыре двойки?",
    ["那我推荐水仙花街北段的住宅，这里靠近北区和金梧桐区，房价也合适。"] = "Тогда рекомендую резиденции в северной части улицы Даффодил. Он находится недалеко от Северного округа и района Золотого Инда, а цены на жилье также разумные.",
    ["那我更要写信邀请她，就像以前一样！"] = "Тогда я должен написать письмо, чтобы пригласить ее, как и раньше!",
    ["那我留在这里，等黛西小姐醒来，或许可以问到有用的线索。"] = "Тогда я останусь здесь и подожду, пока мисс Дейзи проснется; возможно, я могу попросить некоторые полезные подсказки.",
    ["那接下来的事，就交给你了。"] = "Тогда остальное оставляю на вас.",
    ["那提前祝你生日快乐！"] = "Тогда заранее с Днем Рождения!",
    ["那时候我还没有柜台高呢，哈哈……"] = "Тогда я был даже не таким высоким, как прилавок, хаха...",
    ["那时的我已经流浪了很久，能感觉到的只有……平淡。"] = "К тому времени я уже долго бродил и чувствовал только... пустоту.",
    ["那是……一种未知的谜题吗？"] = "Это... какая-то неизвестная загадка?",
    ["那是……小黛西？"] = "Это... Маленькая Дейзи?",
    ["那是一个连杀了五位少女的血腥屠夫……"] = "Это был кровавый мясник, убивший подряд пять молодых девушек...",
    ["那是一种天真、纯净，无忧无虑和永远快乐的味道。"] = "Это был аромат невинности, чистоты, беззаботности и вечного счастья.",
    ["那是个顽劣的孩子，说谎使他的鼻子长得能当撬棍。大地母神包容了它，引导它成长为乖孩子。"] = "Это был непослушный ребенок, чей нос вырастал настолько, что можно было превратить его в лом, когда он лгал. Мать-Земля терпела это и помогала ему вырасти хорошим ребенком.",
    ["那是安慰你的话，亲爱的。老板可不会这么想，他只会觉得我是个懒汉，说不定连这份工作都保不住。"] = "Это было просто для того, чтобы утешить тебя, моя дорогая. Босс так не подумает. Он подумает, что я ленивый бездельник, и я могу даже потерять эту работу.",
    ["那是自然，这可是全廷根最有名的莴苣与肉类市场！不过摊子一多，一些不良的竞争也就多了。"] = "Само собой разумеется; это самый известный рынок салата и мяса во всем Тингене! Однако при таком большом количестве прилавков обязательно будет некоторая недобросовестная конкуренция.",
    ["那是被风吹落的树叶。"] = "Это листья, сдутые ветром.",
    ["那是队长的爱好吗？"] = "Это хобби капитана?",
    ["那柄斧头几乎两三下碰撞就能制造出一道伤害性很强的闪电。"] = "Этот топор от двух-трех ударов способен породить сокрушительную молнию.",
    ["那点可怜的午休时间，也只有这家的出餐速度能赶上了。"] = "В этот жалкий обеденный перерыв это единственное место, где обслуживание достаточно быстрое, чтобы успеть вернуться вовремя.",
    ["那爸爸给他们各捐一栋楼好了，这样我的宝贝有更多选择的余地。"] = "Потом папа подарит каждому из них по зданию, чтобы у моего сокровища было больше места для выбора.",
    ["那看来你还有机会继续学习他的神奇配方。"] = "Тогда, похоже, у тебя еще есть шанс продолжить изучение его магических формул.",
    ["那真可惜，劳拉可是刚从贝克兰德最好的礼仪学校毕业，她的用餐礼仪比某些南大陆暴发户好多了。"] = "Какая жалость. Лора ведь только что окончила лучшую школу этикета в Бэкланде, и её манеры за столом куда лучше, чем у иных нуворишей с Южного континента.",
    ["那真是太可惜了。"] = "Очень жаль.",
    ["那真是太好了！你马上就能跟孩子团聚了！"] = "Это замечательно! Вы скоро воссоединитесь со своим ребенком!",
    ["那种堕落的、被污染的气息我曾见过，在海纳斯·凡森特的梦中。而根据我们的调查，他的梦指向了邪神——真实造物主。"] = "Я уже сталкивался с такой падшей, испорченной аурой во сне Хейнса Винсента. И согласно нашему расследованию, его сон указывал на злого бога — Истинного Творца.",
    ["那种果酸味，每一口都能让身体暖暖的。"] = "Этот кисловато-фруктовый привкус... каждый кусочек разливался теплом по телу.",
    ["那群不需要睡眠的值夜者经常连夜打牌，钢铁的牌也禁不住这么用。"] = "Те «Ночные Ястребы», которым не нужен сон, часто всю ночь играют в карты; даже стальные карты не выдержали такого использования.",
    ["那股诡异的能量估计就是他造成的。"] = "Эта странная энергия, вероятно, вызвана им.",
    ["那肯定，不赌怎么翻盘？"] = "Само собой! Как еще отыграться, если не делать ставки?",
    ["那起意外和我们无关！这是通过地下市场买来的，请你相信。"] = "Эта авария не имеет к нам никакого отношения! Это было куплено на подпольном рынке, поверьте мне.",
    ["那边两位先生……似乎在很激烈地辩论？"] = "Эти два джентльмена... кажется, очень интенсивно спорят?",
    ["那边的牌子上写着“绯月派”，听起来是一道特别的料理。"] = "На вывеске вон там написано «Пирог Алой Луны», звучит как необычное блюдо.",
    ["那边的芬利叔叔今天为他的哥哥庆生，我有热情送上祝福哦。"] = "Дядя Финли сегодня празднует день рождения своего брата, и я с энтузиазмом передаю ему свои благословения.",
    ["那边那个人是……"] = "Тот человек там...",
    ["那这样的观察，让你获得了什么灵感？"] = "Итак, какое вдохновение дало вам это наблюдение?",
    ["那道香草白酱煎肉真不错，{{PlayerName}}下次来黑荆棘，我们一起吃饭吧。"] = "Обжаренное мясо с белым соусом из трав было действительно вкусным, {{PlayerName}}, давай поедим вместе, когда в следующий раз приедешь в Чёрный Чертополох.",
    ["那里有一些报销单。"] = "Там есть формы для возмещения.",
    ["邪恶的仪式魔法？！"] = "Зловещая ритуальная магия?!",
    ["邪神事件也越来越多了，普通人也被更广泛的影响了。"] = "Происшествий с участием злых богов происходит все больше и больше, и обычные люди страдают от них сильнее.",
    ["邪神！那是邪神！格调要高，别局限于这些小事。"] = "Злой бог! Это злой бог! Стиль должен быть высоким; не ограничивайтесь этими мелочами.",
    ["邻居家的太太讲的睡前故事里，主角是一个住在梦幻岛上，用蘑菇当烟囱，和仙子、人鱼生活在一起，永远都不会长大的小男孩……"] = "В сказке на ночь, которую рассказывала соседка, главным героем был вечно юный мальчик, живущий на Острове Грез; его дымоходом служил гриб, а делил он свой дом с феями и русалками...",
    ["郊外一处遗迹附近。有人举报在这里多次看见邪教仪式。"] = "Рядом с какими-то руинами в пригороде. Кто-то сообщил, что видел здесь несколько раз культовые ритуалы.",
    ["都别吵了，偏差的质量是惰性气体。"] = "Хватит спорить, ребята. Отклоненная масса представляет собой инертный газ.",
    ["都很好，我们顺利完成了那次任务，救了很多人……你是唯一的牺牲者。"] = "Все в порядке. Мы успешно выполнили то задание и спасли многих... Ты был единственным, кто погиб.",
    ["都搞清楚了，住在那的是一群流浪儿，我已经用灵视检查过了，他们没有问题。"] = "Все ясно. Там живет группа сирот. Я уже проверил их духовным зрением, и у них нет проблем.",
    ["都搬去了哪里？"] = "Куда они все переехали?",
    ["都是为了大家嘛。"] = "Это все ради всех.",
    ["都是些过期的报纸，可以用物品交换，也可以随便给几便士。"] = "Это все просроченные газеты; вы можете обменять их на предметы или просто отдать несколько пенсов.",
    ["都是今天早上新鲜出炉的面包，您要来点吗？"] = "Это весь хлеб, свежеиспеченный сегодня утром. Хотите немного?",
    ["都是可怜的人啊，被无常的命运反复捉弄。我常跟丈夫说，如果我们当年也投资无烟煤，也不会在这卖香料了。"] = "Все они жалкие люди, с которыми неоднократно играла переменчивая судьба. Я часто говорю мужу, что если бы мы тогда вложили деньги в антрацит, мы бы сейчас здесь не торговали специями.",
    ["都有什么效果？"] = "Каковы последствия?",
    ["都给你！发完这些蛋糕我就可以下班啦！"] = "Возьмите их всех! Я могу уйти с работы после того, как раздам ​​эти пирожные!",
    ["都说了租房子找我同事弗里斯！他热爱，他积极！"] = "Я уже сказал, найди моего коллегу Фрайса, чтобы снять дом! Он страстный, он активный!",
    ["都说了这里没有你要找的人！快走快走！"] = "Я уже говорил тебе, человека, которого ты ищешь, здесь нет! Уходи, уходи!",
    ["酒友？"] = "Собутыльники?",
    ["酸柠檬汁，很好的选择。让我们继续往里面加点什么。"] = "Кислый лимонный сок, отличный выбор. Давайте продолжим что-нибудь добавлять к этому.",
    ["释放光之折射后恢复自身最大生命值30%的血量，是否确认选择这项能力？选择后其他2个会消失"] = "После устранения преломления света вы восстановите 30% своего максимального здоровья. Вы уверены, что выбрали эту способность? Остальные 2 исчезнут после выбора",
    ["释放压力，这有助于维持精神稳定。你知道的，精神稳定在这个混乱的时代有多重要。"] = "Снятие стресса помогает сохранить психическую стабильность. Вы знаете, насколько важна психическая стабильность в эту хаотичную эпоху.",
    ["释放星沙后触发星穹裁决，是否确认选择这项能力？选择后其他2个会消失"] = "Вызывает срабатывание «Правосудия Звездного купола» после высвобождения Звездного песка. Подтвердить эту способность? Выбор этого приведет к исчезновению двух других.",
    ["释放知识逐人后获得护盾，是否确认选择这项能力？选择后其他2个会消失"] = "Получите Щит после отпуска «Погоня за знаниями». Подтвердить эту способность? Выбор этого приведет к исчезновению двух других.",
    ["重返青春，焕然一新！怎么样，不管用不用得上都能买点哦。"] = "Возвращает молодость, освежает тело и душу! Ну как? Даже если прямо сейчас не нужно, всё равно стоит прикупить немного.",
    ["金色的，很薄……形状难以描述，我的文法课成绩一直不好。"] = "Золотистая, очень тонкая... форму трудно описать; мои оценки по грамматике всегда были плохими.",
    ["金钱诱惑"] = "Искушение деньгами",
    ["钓鱼。"] = "Рыбалка.",
    ["铁十字街还有其他好吃的东西吗？"] = "На улице Железного Креста есть еще что-нибудь вкусное?",
    ["银冠餐厅，罗勒牛尾汤？听起来不错。"] = "Ресторан «Серебряная Корона», Суп из бычьих хвостов с базиликом? Это звучит неплохо.",
    ["镜头一般是在剧情块中的，所以这里的镜头取的是相对位置吧？"] = "Камера обычно находится в сюжетном блоке, поэтому здесь камера занимает относительное положение, верно?",
    ["镜头外，或者新增对象，实现方式有很多。"] = "За кадром или добавление нового объекта; Есть много способов добиться этого.",
    ["长了就割，割完又长。"] = "Их собирают, когда они растут, и они вырастают снова после сбора.",
    ["长官！长官……"] = "Сэр! Сэр...",
    ["长时间昏睡后醒来，明亮的灯光会很刺眼，我先把近处的灯光调暗了些。"] = "После пробуждения от долгой комы яркий свет может ослепить, поэтому сначала я приглушу ближайший свет.",
    ["门口似乎有两位先生在等您。"] = "Кажется, у двери вас ждут два джентльмена.",
    ["门口的那位女士，看着不讲理，但我也挺理解她的。"] = "Дама у двери выглядит неразумной, но я могу ее понять.",
    ["闭嘴，达蒙。别再乱猜了！"] = "Заткнись, Дэймон. Хватит гадать дико!",
    ["闭嘴，阿罗，咱俩的冰淇淋是同一个供货商。"] = "Заткнись, Арло, мы оба пользуемся услугами одного и того же поставщика мороженого.",
    ["问题的答案"] = "Ответ на вопрос",
    ["闲聊"] = "Чат",
    ["阁下，可能过段时间……或是下周，或是明天，我可能就会消失……"] = "Ваша Светлость, возможно, через некоторое время... на следующей неделе или уже завтра, я просто исчезну...",
    ["队长、卡萝队长，这副模样……你一直在封印物里？"] = "Капитан, капитан Кэрол, это появление... Вы все это время находились внутри Запечатанного Артефакта?",
    ["队长你冷静一点……"] = "Капитан, успокойтесь...",
    ["队长回来啦，可我们还没布置好公司……"] = "Капитан вернулся, но мы еще не закончили создание компании...",
    ["队长熟悉的地方……黑荆棘安保公司，或者圣赛琳娜教堂？"] = "Места, которые были знакомы капитану… Охранная компания «Чёрный Чертополох» или собор Святой Селены?",
    ["队长的素描画得相当好，我建议过他把画挂在大厅，但他不好意思。"] = "Эскизы Капитана весьма хороши. Я предложил ему повесить картины в зале, но он постеснялся.",
    ["队长，你平时有什么爱好吗？"] = "Капитан, у вас есть хобби?",
    ["队长，叫我来有什么事？"] = "Капитан, зачем вы меня сюда позвали?",
    ["队长，对不起把你吵醒了……我们应该更小心些的。"] = "Капитан, извините, что разбудил вас... Нам следовало быть осторожнее.",
    ["队长，我来啦。"] = "Капитан, вот и я.",
    ["队长，我跟你一起去！毕竟是我弄丢了阿诺德……"] = "Капитан, я пойду с вами! В конце концов, это я упустил Арнольда...",
    ["队长，有什么事吗……你的眼神好可怕。"] = "Капитан, что-то не так... у вас ужасные глаза.",
    ["队长，有什么事吗？"] = "Капитан, что-то случилось?",
    ["队长，这次又是什么委托？"] = "Капитан, какая комиссия на этот раз?",
    ["队长？请放心，今天没有什么紧急的任务。"] = "Капитан? Будьте уверены, сегодня нет срочных миссий.",
    ["阳光、鲜花、小甜品！祝你有一个美好的午后！"] = "Солнце, цветы и маленькие десерты! Желаю вам чудесного дня!",
    ["阿尔伯特在街角的风车那边搞了一些恶作剧，乱涂红漆、挂鱼线，还在半夜转动风车。"] = "Альберт разыгрывал ветряную мельницу на углу улицы, размазывал красную краску, развешивал лески и крутил мельницу посреди ночи.",
    ["阿尔伯特家在哪里？"] = "Где дом Альберта?",
    ["阿尔伯特平时在后院干什么？"] = "Что Альберт обычно делает на заднем дворе?",
    ["阿尔伯特的父亲怎么了？"] = "Что случилось с отцом Альберта?",
    ["阿尔伯特被丢给了姑妈玛里琳照顾，八九岁，正是爱恶作剧的年纪，玛里琳也很头痛吧。"] = "За Альбертом присматривала его тетя Мэрилин. В восемь или девять лет наступает возраст озорства; У Мэрилин, должно быть, тоже болит голова.",
    ["阿尔伯特这么想去海上，我却不了解他这个愿望……我也该承担起父亲的职责了。"] = "Альберт так хочет в море, но я не поняла его желания... Я тоже должен взять на себя обязанности отца.",
    ["阿尔伯特！"] = "Альберт!",
    ["阿尔伯特？噢，那个疯子水手吉瑞尔的孩子！哈，这个鱼线应该也是他家的。"] = "Альберт? О, дитя этого сумасшедшего матроса Гиреля! Ха, эта леска, должно быть, тоже из его дома.",
    ["阿德莱德牺牲在一次任务中，就在你死后不久。"] = "Аделаида пожертвовала собой во время квеста вскоре после вашей смерти.",
    ["阿曼达女士，你有难以抉择的事情吗？"] = "Мадам Аманда, есть ли у вас вещи, между которыми сложно сделать выбор?",
    ["阿曼达女士，你有难以选择的事情吗？"] = "Мадам Аманда, есть ли у вас вещи, между которыми сложно выбрать?",
    ["阿曼达女士，请给我一杯……"] = "Мисс Аманда, пожалуйста, дайте мне...",
    ["阿罗德斯，<P_Heart>（描述符号形状）</>您知道它代表什么吗？"] = "Арродес, <P_Heart> (опишите форму символа) </>, вы знаете, что он обозначает?",
    ["阿诺德……<P_Yellow>卡萝</>队长的儿子，我不会忘记的。"] = "Арнольд... сын капитана <P_Yellow>Кэрол</>, я этого не забуду.",
    ["阿诺德之前没有受到笛子的影响，但这次却被引诱了……"] = "Арнольд раньше не находился под влиянием флейты, но на этот раз он соблазнился...",
    ["阿诺德拜托给你了，我需要去尽快调查案件。"] = "Поручаю Арнольда тебе, мне нужно как можно скорее заняться расследованием дела.",
    ["阿诺德提到过会有鸟儿找他玩，或许真的是因为夜莺银哨影响到了廷根的鸟儿们，让它们去保护阿诺德。"] = "Арнольд упомянул, что птицы придут поиграть с ним. Возможно, это действительно потому, что свисток Серебряного соловья воздействует на птиц в Тингене, заставляя их защищать Арнольда.",
    ["阿诺德的妈妈曾经也是值夜者，他对这里很熟悉，不用拘谨。"] = "Мать Арнольда тоже когда-то была Ночным Ястребом, так что он здесь как дома — не стесняйся.",
    ["阿诺德，你的妈妈……"] = "Арнольд, твоя мать...",
    ["阿诺德，我们不是一样的吗？没有家人、孤零零地活着……"] = "Арнольд, разве мы не одинаковы? Без семьи, в полном одиночестве...",
    ["阿诺德，这件事很重要，你必须好好回想起来。"] = "Арнольд, это важная вещь, и ты должен хорошенько об этом подумать.",
    ["陌生的？每天都会有陌生气息出现，这里可是墓园，笨蛋，好笨的人类！"] = "Странный? Странные ауры появляются каждый день. Это кладбище, идиот, какой глупый человек!",
    ["除了一种淡淡的果酸味。"] = "За исключением слабого фруктового кисловатого аромата.",
    ["除了值班和外出处理事件，弗莱队长会一直在办公室里。"] = "Капитан Фрай всегда будет в офисе, за исключением дежурств и выездов для устранения происшествий.",
    ["除了基本的周薪之外，我们还有保密和风险补贴。"] = "Помимо основной еженедельной зарплаты, у нас также есть субсидии на конфиденциальность и риск.",
    ["除了奥利安娜太太以外，你是第二个欣赏这本杂志的人！相当有品味！"] = "После миссис Олианны вы второй человек, оценивший этот журнал! У вас превосходный вкус!",
    ["除了挑剔的房东，应该还有其他不便利的因素吧。"] = "Кроме придирчивого хозяина должны быть и другие неудобные факторы, верно?",
    ["除你们以外，最近还有人去过廷根湖畔吗？"] = "Кроме вас, кто-нибудь еще был недавно на берегу озера Тинген?",
    ["随你降临的命运，将你引领至此的命运。"] = "Судьба, которая сошла с тобой, судьба, которая привела тебя сюда.",
    ["随便来点好的。"] = "Просто дай мне что-нибудь хорошее.",
    ["随便看看吧。虽然没什么客人，我也不会像那边那个懒货一样把摊子扔在这儿不管。"] = "Не стесняйтесь осмотреться вокруг. Хотя клиентов не так много, я не брошу свой ларек, как тот ленивый бездельник.",
    ["随意触碰一位淑女并不是礼貌的行为，如果你感到消沉，我可以为你提供专业的心理诊疗。"] = "Бесцеремонно прикасаться к леди невежливо. Если вы чувствуете подавленность, я могу предложить профессиональную психологическую консультацию.",
    ["随着资历的提升，薪水会逐步增长。"] = "По мере увеличения стажа зарплата будет постепенно расти.",
    ["难以相信，三次都是拼图，还都是雏菊的图案……"] = "Трудно поверить, все три раза это была головоломка, и все были ромашки...",
    ["难怪，黛西小姐会被困在那段最美好、烂漫的记忆中。"] = "Неудивительно, что мисс Дейзи оказалась в ловушке этого самого прекрасного и романтического воспоминания.",
    ["难道……"] = "Может быть...",
    ["难道你改变了自己的看法？关于“活着”和“死亡”的看法？"] = "Может быть, вы изменили свое мнение? Ваш взгляд на «жизнь» и «смерть»?",
    ["难道你是……"] = "Можешь ли ты быть...",
    ["难道是我最近熬夜太多了？"] = "Может быть, я в последнее время слишком поздно ложился спать?",
    ["难道是诊金不够吗？"] = "Может быть, платы за консультацию недостаточно?",
    ["难道是走丢后，被当做流浪犬卖到这里了，真可怜。"] = "Может быть, он заблудился и был продан сюда как бродячая собака? Как жалко.",
    ["难道，黛西小姐的灵魂被封禁在了某段情景的循环中，所以她的身体才会出现死亡特征？"] = "Может ли быть так, что душа мисс Дейзи заперта в петле какой-то сцены, поэтому на ее теле появляются признаки смерти?",
    ["雏菊让我想到很多。比如天真、纯洁、无忧无虑，和永远快乐。"] = "Ромашки заставляют меня думать о многом. Например, невинность, чистота, беззаботность и вечное счастье.",
    ["雪山茶树新叶12片……"] = "12 новых листьев чайного дерева Снежная Гора...",
    ["雪莉娅的面包很不错，不过霍夫曼的咸鱼摊的东西就不太行了。"] = "Хлеб у Шелии неплохой, но в ларьке с соленой рыбой у Хоффмана не очень вкусный.",
    ["雪莉想帮你"] = "Шерри хочет помочь вам",
    ["雾气……更浓重了。"] = "Туман... стал еще гуще.",
    ["雾气？"] = "Туман?",
    ["需要其他人协助吗？"] = "Вам нужна помощь других?",
    ["需要增加就业！"] = "Нужно повышать занятость!",
    ["需要帮忙调查吗？"] = "Вам нужна помощь в расследовании?",
    ["需要帮您提行李吗？我对这边很熟悉的。"] = "Помочь вам с багажом? Я здесь каждый уголок знаю.",
    ["需要我为你提供一些帮助吗，女士。"] = "Вам нужна моя помощь, мэм?",
    ["需要我帮忙吗？"] = "Вам нужна моя помощь?",
    ["霍森医生的医术比我家里的私人医生要高多了！但他一心坐诊，还说什么“许多来到这里的病人都是怀着最后的希望……我不能让他们失望”之类的。"] = "Медицинские навыки доктора Хоссена намного выше, чем у личного врача моей семьи! Но он сосредоточился на приеме пациентов и сказал что-то вроде: «Многие пациенты, которые приходят сюда, имеют последнюю надежду… Я не могу их подвести».",
    ["露娜女士会将蕴含灵性的材料视为食物，只需要取下一点点粉末，我们就会知道这笔交易是否诚实。"] = "Г-жа Луна относится к материалам, содержащим духовность, как к еде. Нам достаточно взять совсем немного порошка, и мы узнаем, честна ли сделка.",
    ["露娜？那只走来走去的猫？"] = "Луна? Этот кот гуляет?",
    ["非凡世界中，没有一定会成功的事。我们开始吧！"] = "В мире Потусторонних ни в чем нельзя быть уверенным наверняка. Давайте начнем!",
    ["非凡者，祝你好运。"] = "Beyonder, good luck.",
    ["非凡领域对普通人严格保密，警官徽章还在吗？"] = "Царство Потусторонний строго конфиденциально для обычных людей. Ваш полицейский значок еще с вами?",
    ["非常感谢，你们的效率令人赞叹。"] = "Большое спасибо, ваша оперативность достойна восхищения.",
    ["非常感谢，我之后会去尝试一下的！"] = "Спасибо большое, позже попробую!",
    ["非常抱歉，{{PlayerName}}，我没有单独借阅《谜题破解法》的权限。"] = "Мне очень жаль, {{PlayerName}}, но у меня нет разрешения выдавать «Методы разгадывания головоломок» на руки.",
    ["非常诚实且自信的回答。要是我也能流鼻涕的话……"] = "Очень честный и уверенный ответ. Если бы у меня только был насморк...",
    ["靠你们才对，现在的超凡事件越来越多了，搞得我们这群老家伙心惊胆战的，特别是那件事情之后。"] = "Это зависит от вас всех. В последнее время происходит все больше и больше инцидентов с Потусторонним, заставляя нас, стариков, чувствовать себя в ужасе, особенно после этого инцидента.",
    ["靠近一些"] = "Подойди ближе",
    ["韦尔奇的朋友"] = "друг Уэлча",
    ["音乐安抚"] = "Умиротворение с помощью музыки",
    ["顺着占卜结果向前走吧。"] = "Идите вперед, следуя результатам гадания.",
    ["顺着这条路一直向北走，遇到路口往东。"] = "Следуйте по этой дороге на север и на перекрестке поверните на восток.",
    ["额……客人，如果你有其他需求，可以去码头碰碰运气，听说那边有个黑市。"] = "Э... гость, если у тебя есть другие нужды, ты можешь попытать счастья на пристани. Я слышал, что там есть черный рынок.",
    ["额外经费？"] = "Дополнительные средства?",
    ["额，确实，下街在往南边走就是贫民窟和工厂区了。"] = "Да, действительно, если пойти дальше на юг от Лоуэр-стрит, это трущобы и фабричный район.",
    ["风暴之主啊，您是统治天空的王者，主宰大海的皇帝。"] = "Повелитель Штормов, Ты Король, правящий небом, Император, властвующий над морем.",
    ["风暴信徒啊……"] = "Верующий в шторм, да...",
    ["风暴在上！卢莎，你这话说得活像个诗人。"] = "Буря выше! Луша, ты говоришь как поэт.",
    ["风暴在上！我丈夫刚告诉我一个惊喜，他要把那条海蓝宝石的项链作为我的生日礼物！"] = "Буря выше! Мой муж только что преподнес мне сюрприз; он собирается подарить мне это аквамариновое ожерелье в качестве подарка на день рождения!",
    ["风暴在上，你可别吓我！吓我遭雷劈！"] = "Клянусь Бурей, не пугай меня так! Разрази меня гром!",
    ["风暴在上，廷根越来越不消停了。"] = "Наверху бури, Тинген становится все менее и менее мирным.",
    ["风暴在上，您听说过风暴的启示吗？"] = "Шторм выше; слышали ли вы об откровении Шторма?",
    ["风暴在上，我建议他在礼拜日去教堂做祈祷，最近别再出海，小心有命赚钱没命花。"] = "Буря всемогущая! Советую ему в воскресенье пойти в церковь помолиться и на время забыть про море. А то заработать-то заработает, да потратить не успеет.",
    ["风暴在上，水是风暴信徒永远的家！如同回到初生之时，沐浴在蔚蓝的海水之间……"] = "Шторм наверху, вода – вечный дом последователей Шторма! Как возвращение в момент рождения, купание в голубой морской воде...",
    ["风暴在上，这次保证没问题！"] = "Наверху буря, я гарантирую, что на этот раз проблем не будет!",
    ["风车……风车！之前阿尔伯特在那边不是恶作剧，而是仪式魔法的演练！"] = "Ветряная мельница... Ветряная мельница! Альберт раньше там не шалил; это была практика Ритуальной Магии!",
    ["风车旁边的“血迹”，似乎是红色的油漆。"] = "«Пятна крови» рядом с ветряной мельницей кажутся красной краской.",
    ["风车？……我得找他谈谈。"] = "Ветряная мельница?...Мне нужно с ним поговорить.",
    ["风险总是伴随着机遇，不是吗？"] = "Риск всегда сопровождается возможностью, не так ли?",
    ["饮品并不免费。没关系，很多新人都有这样的误解。"] = "Напитки платные. Ничего страшного, многие новички совершают ту же ошибку.",
    ["饱受这个念头的折磨后，他最终无法控制自己，伸手触碰黛西小姐的手腕……"] = "Терзаемый этой мыслью, он наконец не смог совладать с собой и потянулся, чтобы коснуться запястья мисс Дейзи...",
    ["饿死了……"] = "Умер от голода...",
    ["首先得找到食材和厨具。"] = "Сначала нужно найти продукты и кухонную утварь.",
    ["首先，从我们的国家因蒂斯开始……"] = "Во-первых, давайте начнем с нашей страны, Интиса...",
    ["首席……是以前在神弃之地时的称呼。即使现在我在拜亚姆的新白银城接任了首席的职务，仍然改不掉过去的习惯。"] = "Шеф... так называли его в Забытой Земле Богов. Несмотря на то, что я сейчас занял должность вождя Нью-Сильвер-Сити в Баяме, я все еще не могу избавиться от старой привычки.",
    ["首都贝克兰德被称作“希望之城”，风气却比因蒂斯要保守得多，婚外情会成为惊人的八卦。"] = "Столицу Бэкланд называют «Городом надежды», но ее социальная атмосфера гораздо более консервативна, чем в Интисе; внебрачные связи стали бы шокирующими сплетнями.",
    ["香料将带给生活更多滋味，欢迎下次光临，{{先生|女士}}。"] = "Пряности придают жизни больше вкуса. Заходите к нам ещё, {{господин|госпожа}}.",
    ["马上马上！"] = "Сразу, сразу!",
    ["马车行驶一段距离后停了下来。"] = "Карета остановилась, проехав некоторое расстояние.",
    ["马车路过玩家正前方时，一阵颠簸，黛西小姐被颠起，手中的雏菊掉落在地。\n男士趁机搂住、扶稳黛西小姐，马车恢复平静，二人相视大笑。\n马车走远后消失，街上的行人一个个消失，只剩下地上的雏菊。"] = "Когда карета проезжала прямо перед игроком, раздался удар. Мисс Дейзи ударилась, и маргаритка в ее руке упала на землю. \nМужчина воспользовался возможностью, чтобы обнять и крепко держать мисс Дейзи. Карета успокоилась, и они посмотрели друг на друга и рассмеялись. \nКарета исчезла после исчезновения, а пешеходы на улице исчезли один за другим, оставив на земле только ромашки.",
    ["马车还没来吗……这天真让人受不了。"] = "Неужели карета еще не прибыла... Погода действительно невыносимая.",
    ["骂醒杰德"] = "Просыпайся, Джед",
    ["骗子……彻头彻尾的骗子……我丢了半副身家！……女神啊……"] = "Лжец... полный лжец... Я потерял половину своих сбережений!...О, Богиня...",
    ["高于生活！"] = "Выше жизни!",
    ["高品质的红酒是因蒂斯的美食名片，搭配浓厚的酱汁与香醇的牛肉，绝对能带来极致的味觉享受。"] = "Высококачественное красное вино – изысканная визитная карточка Интис. В сочетании с насыщенным соусом и нежной говядиной он обязательно доставит максимальное чувственное наслаждение.",
    ["鱼人鳞片算什么，我的袖钉可是去间海郡度假时买的海妖之石，听说整个鲁恩都找不出第二对！"] = "Что такое мерманская шкала? Мои запонки — это Siren Stones, купленные во время отпуска в Мидсишире. Я слышал, во всем Лоэне второй пары не найти!",
    ["鲁比？不，他不是非凡者，只是个爱赌博酗酒又怕老婆的普通人。"] = "Руби? Нет, он не Потусторонний. Он обычный человек, который любит азартные игры и выпивку и боится своей жены.",
    ["鸟儿的歌很像妈妈的摇篮曲，肯定是妈妈教它们的，是妈妈想在梦中与我见面了。"] = "Песни птиц очень похожи на мамину колыбельную. Должно быть, мама их научила; Мама хочет встретиться со мной во сне.",
    ["鸟儿落下来了……"] = "Птица опустилась на землю...",
    ["鸟儿？"] = "Птица?",
    ["鸟就是鸟！鸟就是它自己！"] = "Птица есть птица! Птица сама по себе!",
    ["鸽子也能卖报纸？"] = "Голуби тоже умеют продавать газеты?",
    ["鸽子小姐……哈哈！我是个和鸽子说话的疯子……"] = "Мисс Голубь... хаха! Я сумасшедший, который разговаривает с голубями...",
    ["麻烦你们去调查一个叫做尤朵拉的人，或许会与案件有关联。"] = "Пожалуйста, расследуйте человека по имени Йодора; это может быть связано с делом.",
    ["黄水仙枯萎了，而他也不告而别，我们从未见面，却已灵魂相融……"] = "Нарциссы завяли, и он ушел, не попрощавшись. Мы никогда не встречались, но наши души уже слились...",
    ["黑夜女神教会，风暴之主教会都在廷根拥有自己的教堂。"] = "И Церковь Богини Вечной Ночи, и Церковь Повелителя Бурь имеют собственные соборы в Тингене.",
    ["黑夜给人带来宁静。"] = "Ночь приносит покой людям.",
    ["黑屏白字"] = "Белый текст на черном экране",
    ["黑荆棘安保公司？妈妈工作过的地方……"] = "Охранная компания Чёрный Чертополох? Место, где раньше работала мама...",
    ["黑荆棘就是一支正式的雇佣兵小队，你们经常去出一些非官方的任务。嗯，能赚点外快，又能帮助人们解决困难，双赢。"] = "Чёрный Чертополох — формальный отряд наёмников. Вы часто выходите выполнять неофициальные квесты. Хм, ты можешь подзаработать и помочь людям решить трудности; это беспроигрышный вариант.",
    ["黑荆棘是距离最近的值夜小队，所以由我们派人援助。"] = "Чёрный Чертополох — ближайшая команда Ночного Ястреба, поэтому мы посылаем людей на помощь.",
    ["黑荆棘门外的街道消失了，变成了廷根中央广场。\n玩家抬头，廷根的夜空被涌动的知识洪流所替代。\n知识的流光注入一位少女的大脑中，原本正常的人砰地一声——变成了一股洪流消散。"] = "Улица за воротами «Черного терновника» исчезла, сменившись центральной площадью Тингена.\nИгрок поднял взгляд: ночное небо Тингена заслонил бурлящий Поток Знаний.\nСияющий поток знаний хлынул в разум девушки, и еще мгновение назад обычный человек с громким хлопком рассеялся бурным потоком.",
    ["黑荆棘，伪装成安保公司的廷根值夜者小队。"] = "Чёрный Чертополох, отряд Тинген Найтхокс, замаскированный под охранную компанию.",
    ["黑雾将工厂笼罩，雾中隐约传来野兽的嘶吼。"] = "Черный туман окутал завод, и в нем смутно слышался рев зверей.",
    ["黑麦啤酒1便士一杯，恩马特啤酒2便士，南威尔啤酒4便士，或者你想来一杯纯麦芽酿的朗齐？"] = "Ржаное пиво — 1 пенс за стакан, пиво «Энмат» — 2 пенсов, пиво «Саутвелл» — 4 пенсов, или вы хотите стаканчик чистого солодового Рончи?",
    ["黑麦啤酒25便士一杯，恩马特啤酒50便士，南威尔啤酒100便士，或者你想来一杯纯麦芽酿的朗齐？"] = "Rye beer is 25 pence a glass, Enmat beer is 50 pence, South Will beer is 100 pence, or would you like a glass of pure malt Lanqi?",
    ["黑麦啤酒25便士一杯，恩马特啤酒50便士，南威尔啤酒100便士，或者你想来点不一样的？"] = "Ржаное пиво стоит 25 пенсов за стакан, пиво Enmat — 50 пенсов, пиво Southwell — 100 пенсов, или вы хотите что-то другое?",
    ["黑麦面包、廷根饼、柠檬蛋糕……嗯，看起来都是廷根的传统食物，听说您这儿的廷根饼在附近可是最好的。"] = "Ржаной хлеб, печенье Тинген, лимонный пирог... хм, кажется, все это традиционная еда Тингена. Я слышал, что твое печенье Тинген лучшее в округе.",
